//! Independent read-back of the shared receipt and MRP snapshot.
//! A missing isolated database is recorded and is not a pass.

use erp_domain::manufacturing::{
    BomItem, DatedDemand, Execution, MaterialMove, MaterialMoveKind, MrpItem, OperationReport,
    ReceiptStatus, RoutingStep, WorkOrderStatus,
};
use erp_domain::quantity::{ScaledQty, parse_qty};
use erp_domain::receipt::ReceiptError;
use erp_repo::shared_contract::{GridQueryInput, GridSelectionInput, SharedContractRepo, SharedWrite};
use erp_types::TenantId;

#[path = "shared_contract_receipt_actor.rs"]
mod shared_contract_receipt_actor;

#[path = "shared_contract_workflow.rs"]
mod shared_contract_workflow;

fn isolated_database_url() -> Option<String> {
    std::env::var("ERP_GRID_TEST_DATABASE_URL")
        .ok()
        .filter(|value| !value.trim().is_empty())
}

fn protected_database_options(url: &str) -> anyhow::Result<sqlx::postgres::PgConnectOptions> {
    let options: sqlx::postgres::PgConnectOptions = url.parse()
        .map_err(|_| anyhow::anyhow!("invalid isolated database configuration"))?;
    if options.get_host() != "127.0.0.1"
        || options.get_port() != 15438
        || options.get_database() != Some("erp_shared_contract_test")
        || options.get_username() != "erp_grid_test"
    {
        anyhow::bail!("refusing a database outside the protected QA identity");
    }
    Ok(options)
}

#[test]
fn shared_contract_database_address_is_rejected_before_connecting() {
    assert!(protected_database_options(
        "postgresql://erp_grid_test@127.0.0.1:15438/erp_shared_contract_test"
    ).is_ok());
    for url in [
        "postgresql://erp_grid_test@127.0.0.1:5432/erp_shared_contract_test",
        "postgresql://erp_grid_test@production.example:15438/erp_shared_contract_test",
        "postgresql://erp_grid_test@localhost:15438/erp_shared_contract_test",
        "postgresql://erp_grid_test@127.0.0.1:15438/erp",
        "postgresql://postgres@127.0.0.1:15438/erp_shared_contract_test",
        "invalid database url",
    ] {
        assert!(protected_database_options(url).is_err());
    }
}

