async fn scan_intent_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let exception = repo
        .record_scan_exception(tenant, "i06g-bad", "i06g-bad", "BAD-I06G")
        .await
        .expect("exception")
        .expect("admit exception");
    assert!(matches!(exception, SharedWrite::Stored(_)));
    let verified = repo
        .record_scan(tenant, "i06g-scan", "i06g-scan", "ITEM-I06G", "ITEM", "user-i06g")
        .await
        .expect("scan")
        .expect("admit scan");
    assert!(matches!(verified.0, SharedWrite::Stored(_)));
    let held = repo
        .hold_repeat_scan(tenant, "i06g-hold", "i06g-hold", "ITEM-I06G", "ITEM")
        .await
        .expect("hold")
        .expect("admit hold");
    assert!(matches!(held, SharedWrite::Stored(_)));
    let documents: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and effect_id like 'DOC-%'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("documents");
    assert_eq!(documents, 0);
    let jobs: i64 = sqlx::query_scalar(
        "select count(*) from print_jobs where tenant_id = $1",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_optional(&pool)
    .await
    .unwrap_or(Some(0))
    .unwrap_or(0);
    assert_eq!(jobs, 0);
    let scans: (i64, i64) = sqlx::query_as(
        "select count(*) filter (where status = 'EXCEPTION'), count(*) filter (where status = 'VERIFIED') from shared_scans where tenant_id = $1",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("scans");
    assert_eq!(scans, (1, 1));
    let holds: i64 = sqlx::query_scalar(
        "select count(*) from shared_scan_holds where tenant_id = $1 and decision = 'HELD'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("holds");
    assert_eq!(holds, 1);
}

#[test]
fn allocation_choice_race_read_back() {
    std::thread::Builder::new()
        .name("allocation-choice".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(allocation_choice_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("allocation choice thread");
}

async fn allocation_choice_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let lots = vec![
        erp_domain::trade::AllocationLot {
            batch_code: "LOT-B".into(), location_code: "A-1".into(), available: 400_000,
            sort_date: "2026-10-01".into(), stock_version: 3, frozen: false, expired: false,
        },
        erp_domain::trade::AllocationLot {
            batch_code: "LOT-A".into(), location_code: "A-2".into(), available: 400_000,
            sort_date: "2026-10-01".into(), stock_version: 3, frozen: false, expired: false,
        },
    ];
    let (suggested, ids) = repo
        .save_allocation_suggestion(tenant, "i08d-suggest", "i08d-suggest", "FEFO", "pick-i08d", 600_000, &lots)
        .await
        .expect("suggest")
        .expect("admit suggestion");
    assert!(matches!(suggested, SharedWrite::Stored(_)));
    let suggestion_id = ids[0];
    let choose = |request: &'static str| {
        let repo = repo.clone();
        async move {
            repo.choose_allocation_manually(
                tenant, request, request, suggestion_id, "LOT-B", "buyer asked for LOT-B",
            )
            .await
        }
    };
    let (choice_a, choice_b) = tokio::join!(choose("i08d-a"), choose("i08d-b"));
    let choices = [choice_a, choice_b]
        .into_iter()
        .filter(|item| matches!(item, Ok(Ok(SharedWrite::Stored(_)))))
        .count();
    assert_eq!(choices, 1, "two choices of one suggestion store one manual choice");
    let choice_row: (String, String, String) = sqlx::query_as(
        "select chosen_batch, decision, reason from shared_allocation_choices where tenant_id = $1 and suggestion_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(suggestion_id)
    .fetch_one(&pool)
    .await
    .expect("one choice row");
    assert_eq!(choice_row, ("LOT-B".into(), "MANUAL".into(), "buyer asked for LOT-B".into()));
    let suggested_batch: String = sqlx::query_scalar(
        "select batch_code from shared_allocation_suggestions where tenant_id = $1 and suggestion_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(suggestion_id)
    .fetch_one(&pool)
    .await
    .expect("suggested batch");
    assert_eq!(suggested_batch, "LOT-A");
    let choice_receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('i08d-a','i08d-b')",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("choice receipts");
    assert_eq!(choice_receipts, 1);
    let issues: i64 = sqlx::query_scalar(
        "select count(*) from shared_allocation_issues where tenant_id = $1",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("issues");
    assert_eq!(issues, 0);
}

