async fn freeze_inspection_and_block_release(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let width = erp_domain::manufacturing::FrozenInspectionLine {
        item_code: "width".into(),
        required: true,
        min_micros: 900_000,
        max_micros: 1_100_000,
        sample_count: 2,
    };
    let length = erp_domain::manufacturing::FrozenInspectionLine {
        item_code: "length".into(),
        required: true,
        min_micros: 0,
        max_micros: 2_000_000,
        sample_count: 1,
    };
    let (saved, template_id, version) = repo
        .save_inspection_template(tenant, "q01-tpl", "q01-tpl", "STD-Q01", "INCOMING", &[width.clone(), length.clone()])
        .await
        .expect("template")
        .expect("admit template");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let replay = repo
        .save_inspection_template(tenant, "q01-tpl", "q01-tpl", "STD-Q01", "INCOMING", &[width.clone(), length.clone()])
        .await
        .expect("template replay")
        .expect("same template");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, template_id);
    let wider = erp_domain::manufacturing::FrozenInspectionLine {
        item_code: "width".into(),
        required: true,
        min_micros: 0,
        max_micros: 9_000_000,
        sample_count: 2,
    };
    let revised = repo
        .save_inspection_template(tenant, "q01-tpl2", "q01-tpl2", "STD-Q01", "INCOMING", &[wider, length.clone()])
        .await
        .expect("revised template")
        .expect("admit revised");
    assert!(matches!(revised.0, SharedWrite::Stored(_)));
    assert_eq!(revised.2, 2);

    let order = repo
        .save_work_order(tenant, "q01-wo", "q01-wo", "WO-Q01", "FG-Q01", None, qty_text("2"))
        .await
        .expect("order")
        .expect("admit order");
    let SharedWrite::Stored(order) = order else {
        panic!("order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&order.effect_id).expect("order id");
    repo.transition_saved_work_order(tenant, "q01-rel", "q01-rel", work_order_id, "release")
        .await
        .expect("release")
        .expect("admit release");
    let frozen = repo
        .freeze_inspection_template(
            tenant, "q01-frz", "q01-frz", template_id, "WORK_ORDER", work_order_id, "FG-Q01", "BATCH-Q01",
        )
        .await
        .expect("freeze")
        .expect("admit freeze");
    let SharedWrite::Stored(frozen) = frozen else {
        panic!("freeze stores");
    };
    let freeze_id = uuid::Uuid::parse_str(&frozen.effect_id).expect("freeze id");
    let freeze_replay = repo
        .freeze_inspection_template(
            tenant, "q01-frz", "q01-frz", template_id, "WORK_ORDER", work_order_id, "FG-Q01", "BATCH-Q01",
        )
        .await
        .expect("freeze replay")
        .expect("same freeze");
    assert!(matches!(freeze_replay, SharedWrite::Replay(_)));

    let blocked_issue = repo
        .issue_work_order_material(
            tenant, "q01-iss", "q01-iss", work_order_id, warehouse, uuid::Uuid::new_v4(), sku, "BATCH-Q01",
            1_000_000, "ISSUE", "",
        )
        .await;
    assert!(blocked_issue.expect_err("open freeze blocks issue").to_string().contains("incomplete"));
    let missing = repo
        .save_frozen_inspection_reading(tenant, "q01-miss", "q01-miss", freeze_id, "width", None, "inspector-q01", "reviewer-q01")
        .await;
    assert!(missing.expect_err("missing required reading").to_string().contains("missing"));
    let zero_is_not_missing = repo
        .save_frozen_inspection_reading(tenant, "q01-zero", "q01-zero", freeze_id, "length", Some(0), "inspector-q01", "reviewer-q01")
        .await
        .expect("zero reading")
        .expect("admit zero");
    assert!(matches!(zero_is_not_missing, SharedWrite::Stored(_)));
    let still_blocked = repo
        .issue_work_order_material(
            tenant, "q01-iss2", "q01-iss2", work_order_id, warehouse, uuid::Uuid::new_v4(), sku, "BATCH-Q01",
            1_000_000, "ISSUE", "",
        )
        .await;
    assert!(still_blocked.expect_err("one open item still blocks").to_string().contains("incomplete"));
    let out_of_frozen = repo
        .save_frozen_inspection_reading(
            tenant, "q01-wide", "q01-wide", freeze_id, "width", Some(2_000_000), "inspector-q01", "reviewer-q01",
        )
        .await;
    assert!(out_of_frozen.expect_err("later template range is not used").to_string().contains("InvalidText"));
    let failed = repo
        .save_frozen_inspection_reading(
            tenant, "q01-bad", "q01-bad", freeze_id, "width", Some(800_000), "inspector-q01", "reviewer-q01",
        )
        .await;
    assert!(failed.expect_err("failed reading").to_string().contains("InvalidText"));
    let passed = repo
        .save_frozen_inspection_reading(
            tenant, "q01-ok", "q01-ok", freeze_id, "width", Some(1_000_000), "inspector-q01", "reviewer-q01",
        )
        .await
        .expect("passed reading")
        .expect("admit passed");
    assert!(matches!(passed, SharedWrite::Stored(_)));
    let no_review = repo
        .save_frozen_inspection_reading(tenant, "q01-norev", "q01-norev", freeze_id, "width", Some(1_000_000), "inspector-q01", " ")
        .await;
    assert!(no_review.is_err(), "a reading needs a reviewer");

    let report = OperationReport {
        operation: "inspect".into(),
        good: qty_text("1"),
        rejected: ScaledQty::ZERO,
        rework: ScaledQty::ZERO,
        minutes: 4,
        operator_id: "worker-q01".into(),
        session_user_id: "login-q01".into(),
        session_id: "session-q01".into(),
        crew_code: String::new(),
        started_at: String::new(),
        ended_at: String::new(),
        reverses_report_id: None,
    };
    let (stored_report, _) = repo
        .save_operation_report(tenant, "q01-rpt", "q01-rpt", work_order_id, qty_text("2"), &report)
        .await
        .expect("report")
        .expect("admit report");
    let SharedWrite::Stored(stored_report) = stored_report else {
        panic!("report stores");
    };
    let report_id = uuid::Uuid::parse_str(&stored_report.effect_id).expect("report id");
    let (held, _, _) = repo
        .save_production_receipt(
            tenant, "q01-hold", "q01-hold", work_order_id, qty_text("1"), ReceiptStatus::Hold, report_id,
            "BATCH-Q01", uuid::Uuid::new_v4(), warehouse, sku,
        )
        .await
        .expect("hold")
        .expect("admit hold");
    assert!(matches!(held, SharedWrite::Stored(_)));
    let available = repo
        .save_production_receipt(
            tenant, "q01-avail", "q01-avail", work_order_id, qty_text("1"), ReceiptStatus::Released, report_id,
            "BATCH-Q01", uuid::Uuid::new_v4(), warehouse, sku,
        )
        .await;
    assert!(available.is_err(), "an unread required item cannot become available");

    let sales = erp_domain::trade::SalesLine {
        line_no: 1,
        item_code: "FG-Q01".into(),
        qty_micros: 1_000_000,
        price_cent: 100,
        discount_cent: 0,
        tax_cent: 0,
        due_date: "2026-10-20".into(),
        address: "Gate-Q".into(),
        source: "RESALE".into(),
    };
    let so_id = uuid::Uuid::new_v4();
    repo.save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "q01-so", payload_hash: "q01-so", so_id: Some(so_id), customer_code: "C-Q01", expected_version: None, action: "SUBMIT", lines: &[sales.clone()] })
        .await
        .expect("sales")
        .expect("admit sales");
    repo.save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "q01-go", payload_hash: "q01-go", so_id: Some(so_id), customer_code: "C-Q01", expected_version: Some(1), action: "FULFILL", lines: &[sales] })
        .await
        .expect("fulfill")
        .expect("admit fulfill");
    let ship_freeze = repo
        .freeze_inspection_template(tenant, "q01-ship-frz", "q01-ship-frz", template_id, "SALES_ORDER", so_id, "FG-Q01", "BATCH-SHIP")
        .await
        .expect("ship freeze")
        .expect("admit ship freeze");
    assert!(matches!(ship_freeze, SharedWrite::Stored(_)));
    let location = uuid::Uuid::new_v4();
    repo.append_stock_ledger(tenant, "q01-stock", "q01-stock", warehouse, location, sku, "BATCH-SHIP", "GOOD", "ON_HAND", 1_000_000)
        .await
        .expect("stock")
        .expect("admit stock");
    let source = format!("{so_id}:1");
    repo.reserve_stock_line(tenant, "q01-rsv", "q01-rsv", warehouse, location, sku, "BATCH-SHIP", "GOOD", &source, 1_000_000)
        .await
        .expect("reserve")
        .expect("admit reserve");
    let (planned, delivery_id) = repo
        .plan_sales_delivery(erp_repo::shared_contract::SalesDeliveryPlanInput { tenant_id: tenant, request_id: "q01-plan", payload_hash: "q01-plan", so_id, line_no: 1, expected_version: 2, qty_micros: 1_000_000 })
        .await
        .expect("plan")
        .expect("admit plan");
    assert!(matches!(planned, SharedWrite::Stored(_)));
    for (request_id, action) in [("q01-dres", "RESERVE"), ("q01-pick", "PICK"), ("q01-rev", "REVIEW"), ("q01-out", "ISSUE")] {
        repo.advance_sales_delivery(erp_repo::shared_contract::SalesDeliveryAdvanceInput { tenant_id: tenant, request_id, payload_hash: request_id, delivery_id, action, carrier_ref: "", warehouse_id: warehouse, location_id: location, sku_id: sku, batch_code: "BATCH-SHIP" })
            .await
            .expect(action)
            .expect("admit stage");
    }
    let blocked_ship = repo
        .advance_sales_delivery(erp_repo::shared_contract::SalesDeliveryAdvanceInput { tenant_id: tenant, request_id: "q01-ship", payload_hash: "q01-ship", delivery_id, action: "SHIP", carrier_ref: "WB-Q01", warehouse_id: warehouse, location_id: location, sku_id: sku, batch_code: "BATCH-SHIP" })
        .await;
    assert!(blocked_ship.expect_err("open ship inspection blocks shipment").to_string().contains("incomplete"));

    let width_row: (i64, i64) = sqlx::query_as(
        "select min_micros, max_micros from shared_inspection_freeze_lines where tenant_id = $1 and freeze_id = $2 and item_code = 'width'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(freeze_id)
    .fetch_one(pool)
    .await
    .expect("frozen width");
    assert_eq!(width_row, (900_000, 1_100_000));
    let revised_row: (i64, i64) = sqlx::query_as(
        "select min_micros, max_micros from shared_inspection_template_lines where tenant_id = $1 and template_id = $2 and item_code = 'width'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(revised.1)
    .fetch_one(pool)
    .await
    .expect("revised width");
    assert_eq!(revised_row, (0, 9_000_000));
}

async fn dispose_cited_hold(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let order = repo
        .save_work_order(tenant, "q02-wo", "q02-wo", "WO-Q02", "FG-Q02", None, qty_text("10"))
        .await
        .expect("order")
        .expect("admit order");
    let SharedWrite::Stored(order) = order else {
        panic!("order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&order.effect_id).expect("order id");
    let hold = repo
        .save_quality_hold(tenant, "q02-hold", "q02-hold", work_order_id, "BATCH-Q02", qty_text("10"))
        .await
        .expect("hold")
        .expect("admit hold");
    let SharedWrite::Stored(hold) = hold else {
        panic!("hold stores");
    };
    let inspection_id = uuid::Uuid::parse_str(&hold.effect_id).expect("inspection id");
    let location = uuid::Uuid::new_v4();
    let missing = repo
        .save_cited_quality_disposition(
            tenant, "q02-miss", "q02-miss", uuid::Uuid::new_v4(), location, warehouse, sku,
            "ACCEPT", qty_text("1"), "", "", "",
        )
        .await;
    assert!(missing.is_err(), "a disposition must cite a saved inspection");
    let (accepted, left, version) = repo
        .save_cited_quality_disposition(
            tenant, "q02-ok", "q02-ok", inspection_id, location, warehouse, sku,
            "ACCEPT", qty_text("8"), "", "", "",
        )
        .await
        .expect("accept")
        .expect("admit accept");
    assert!(matches!(accepted, SharedWrite::Stored(_)));
    assert_eq!(left, qty_text("2").as_micros());
    assert_eq!(version, 1);
    let replay = repo
        .save_cited_quality_disposition(
            tenant, "q02-ok", "q02-ok", inspection_id, location, warehouse, sku,
            "ACCEPT", qty_text("8"), "", "", "",
        )
        .await
        .expect("replay")
        .expect("same accept");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, qty_text("2").as_micros());
    let over = repo
        .save_cited_quality_disposition(
            tenant, "q02-over", "q02-over", inspection_id, location, warehouse, sku,
            "SCRAP", qty_text("3"), "too much", "", "",
        )
        .await;
    assert!(over.expect_err("cannot exceed the remaining hold").to_string().contains("InvalidText"));
    let no_reason = repo
        .save_cited_quality_disposition(
            tenant, "q02-noreason", "q02-noreason", inspection_id, location, warehouse, sku,
            "ISOLATE", qty_text("1"), " ", "", "",
        )
        .await;
    assert!(no_reason.expect_err("isolate needs a reason").to_string().contains("reason"));
    let (isolated, isolated_left, isolated_version) = repo
        .save_cited_quality_disposition(
            tenant, "q02-bad", "q02-bad", inspection_id, location, warehouse, sku,
            "ISOLATE", qty_text("2"), "defect", "", "",
        )
        .await
        .expect("isolate")
        .expect("admit isolate");
    assert!(matches!(isolated, SharedWrite::Stored(_)));
    assert_eq!(isolated_left, 0);
    assert_eq!(isolated_version, 2);
    let row: (String, i32, i64, uuid::Uuid) = sqlx::query_as(
        r#"
        select quality_status, version_no, qty_micros, location_id
        from mfg_quality_dispositions
        where tenant_id = $1 and inspection_id = $2 and kind = 'ISOLATE'
        "#,
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(inspection_id)
    .fetch_one(pool)
    .await
    .expect("isolate row");
    assert_eq!(row.0, "ISOLATED");
    assert_eq!(row.1, 2);
    assert_eq!(row.2, qty_text("2").as_micros());
    assert_eq!(row.3, location);
    let ledger: (String, i64) = sqlx::query_as(
        r#"
        select quality_status, sum(delta_micros)::bigint
        from shared_stock_ledgers
        where tenant_id = $1 and batch_code = 'BATCH-Q02' and quality_status = 'ISOLATED'
        group by quality_status
        "#,
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("isolated ledger");
    assert_eq!(ledger, ("ISOLATED".into(), qty_text("2").as_micros()));
}

async fn trace_serial_pages_without_dropping_customers(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
) {
    let planned = repo
        .save_genealogy_edge(
            tenant, "q03-plan", "q03-plan", "PLANNED_BOM", "RAW-Q03", "FG-Q03", qty_text("1"), "WO-Q03", "FG-Q03", "",
        )
        .await;
    assert!(planned.expect_err("planned bom is not actual input").to_string().contains("planned BOM"));
    let (consume, consume_id) = repo
        .save_genealogy_edge(
            tenant, "q03-use", "q03-use", "CONSUME", "SER-Q03", "FG-Q03A", qty_text("2"), "WO-Q03", "BATCH-Q03A", "",
        )
        .await
        .expect("consume")
        .expect("admit consume");
    assert!(matches!(consume, SharedWrite::Stored(_)));
    let replay = repo
        .save_genealogy_edge(
            tenant, "q03-use", "q03-use", "CONSUME", "SER-Q03", "FG-Q03A", qty_text("2"), "WO-Q03", "BATCH-Q03A", "",
        )
        .await
        .expect("replay")
        .expect("same consume");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, consume_id);
    repo.save_genealogy_edge(
        tenant, "q03-out", "q03-out", "OUTPUT", "SER-Q03", "FG-Q03B", qty_text("1"), "WO-Q03", "BATCH-Q03B", "",
    )
    .await
    .expect("output")
    .expect("admit output");
    for (request, batch, customer, qty) in [
        ("q03-c1", "BATCH-Q03A", "CUST-Q1", "1"),
        ("q03-c2", "BATCH-Q03A", "CUST-Q2", "1"),
        ("q03-c3", "BATCH-Q03B", "CUST-Q3", "1"),
    ] {
        repo.save_genealogy_edge(tenant, request, request, "DELIVER", "SER-Q03", batch, qty_text(qty), "WO-Q03", batch, customer)
            .await
            .expect(request)
            .expect("admit delivery");
    }
    repo.save_genealogy_edge(
        tenant, "q03-ret", "q03-ret", "RETURN", "BATCH-Q03A", "BATCH-Q03A", qty_text("1"), "WO-Q03", "BATCH-Q03A", "CUST-Q1",
    )
    .await
    .expect("return")
    .expect("admit return");
    repo.save_genealogy_edge(
        tenant, "q03-rev", "q03-rev", "DELIVER_REVERSAL", "SER-Q03", "BATCH-Q03B",
        ScaledQty::from_micros(-1_000_000), "WO-Q03", "BATCH-Q03B", "CUST-Q3",
    )
    .await
    .expect("reversal")
    .expect("admit reversal");

    let first = repo
        .read_genealogy_keyset(tenant, "input", "SER-Q03", None, 2, 64)
        .await
        .expect("first page");
    assert!(first.incomplete, "a short page is not the full customer range");
    assert_eq!(first.edges.len(), 2);
    let cursor = uuid::Uuid::parse_str(first.next_edge_id.as_deref().expect("cursor")).expect("edge cursor");
    let second = repo
        .read_genealogy_keyset(tenant, "input", "SER-Q03", Some(cursor), 10, 64)
        .await
        .expect("second page");
    assert!(!second.incomplete);
    let mut customers: Vec<&str> = first
        .edges
        .iter()
        .chain(second.edges.iter())
        .map(|edge| edge.customer.as_str())
        .filter(|customer| !customer.is_empty())
        .collect();
    customers.sort();
    customers.dedup();
    assert_eq!(customers, vec!["CUST-Q1", "CUST-Q2", "CUST-Q3"]);
    let capped = repo
        .read_genealogy_keyset(tenant, "input", "SER-Q03", None, 10, 1)
        .await
        .expect("capped page");
    assert!(capped.incomplete, "a node cap must not look like every customer was loaded");
    assert!(capped.edges.len() <= 1, "the node cap must limit the returned page");
    assert!(capped.loaded <= 1);
    let backward = repo
        .read_genealogy_keyset(tenant, "output", "BATCH-Q03A", None, 10, 64)
        .await
        .expect("backward");
    assert!(backward.edges.iter().any(|edge| edge.source_action == "CONSUME" && edge.input_code == "SER-Q03"));
    assert!(backward.edges.iter().any(|edge| edge.source_action == "RETURN" && edge.customer == "CUST-Q1"));
    assert!(backward.edges.iter().all(|edge| edge.source_action != "PLANNED_BOM"));
    let stored: i64 = sqlx::query_scalar(
        "select count(*) from mfg_genealogy_edges where tenant_id = $1 and work_order_no = 'WO-Q03'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("stored edges");
    assert_eq!(stored, 7);
}

async fn recall_two_products_and_three_customers(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let location = uuid::Uuid::new_v4();
    let published = repo
        .save_sampling_rule(tenant, "q04-rule", "q04-rule", "AQL-Q04", 1, 20, 1)
        .await
        .expect("rule")
        .expect("admit rule");
    assert!(matches!(published.0, SharedWrite::Stored(_)));
    assert_eq!(published.1, 1);
    let revised = repo
        .save_sampling_rule(tenant, "q04-rule2", "q04-rule2", "AQL-Q04", 2, 20, 3)
        .await
        .expect("rule version 2")
        .expect("admit later rule");
    assert_eq!(revised.1, 2);
    let accepted = repo
        .save_cited_sampling_decision(tenant, "q04-pass", "q04-pass", "AQL-Q04", 1, "2026-09", 1)
        .await
        .expect("sample pass")
        .expect("admit cited sample");
    assert!(matches!(accepted.0, SharedWrite::Stored(_)));
    assert!(accepted.1);
    assert_eq!(accepted.2, 50_000);
    let rejected = repo
        .save_cited_sampling_decision(tenant, "q04-fail", "q04-fail", "AQL-Q04", 1, "2026-10", 2)
        .await
        .expect("sample fail")
        .expect("admit cited rejection");
    assert!(!rejected.1);
    assert_eq!(rejected.2, 100_000);
    let replay = repo
        .save_cited_sampling_decision(tenant, "q04-fail", "q04-fail", "AQL-Q04", 1, "2026-10", 2)
        .await
        .expect("sample replay")
        .expect("same sample");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    let rewrite = repo
        .save_cited_sampling_decision(tenant, "q04-rewrite", "q04-rewrite", "AQL-Q04", 1, "2026-09", 0)
        .await;
    assert!(rewrite.expect_err("period").to_string().contains("sampling period"));
    let missing_rule = repo
        .save_cited_sampling_decision(tenant, "q04-norule", "q04-norule", "AQL-NONE", 1, "2026-09", 0)
        .await;
    assert!(missing_rule.expect_err("rule").to_string().contains("not found"));
    let over = repo
        .save_cited_sampling_decision(tenant, "q04-over", "q04-over", "AQL-Q04", 1, "2026-11", 21)
        .await;
    assert!(over.expect_err("defects").to_string().contains("sampling rejected"));

    for (request, action, input, output, qty, batch, customer) in [
        ("q04-use", "CONSUME", "RAW-Q04", "FG-Q04A", "2", "BATCH-Q04A", ""),
        ("q04-out", "OUTPUT", "RAW-Q04", "FG-Q04B", "1", "BATCH-Q04B", ""),
        ("q04-c1", "DELIVER", "BATCH-Q04A", "BATCH-Q04A", "1", "BATCH-Q04A", "CUST-Q4A"),
        ("q04-c2", "DELIVER", "BATCH-Q04A", "BATCH-Q04A", "1", "BATCH-Q04A", "CUST-Q4B"),
        ("q04-c3", "DELIVER", "BATCH-Q04B", "BATCH-Q04B", "1", "BATCH-Q04B", "CUST-Q4C"),
    ] {
        repo.save_genealogy_edge(tenant, request, request, action, input, output, qty_text(qty), "WO-Q04", batch, customer)
            .await
            .expect(request)
            .expect("admit edge");
    }
    let capped = repo
        .save_scoped_recall(tenant, "q04-cap", "q04-cap", "RAW-Q04", "AQL-Q04", 1, qty_text("3"), 1)
        .await;
    assert!(capped.expect_err("node cap").to_string().contains("incomplete"));
    let opened = repo
        .save_scoped_recall(tenant, "q04-open", "q04-open", "RAW-Q04", "AQL-Q04", 1, qty_text("3"), 64)
        .await
        .expect("recall")
        .expect("admit recall");
    assert!(matches!(opened.0, SharedWrite::Stored(_)));
    assert!(!opened.3);
    assert_eq!(opened.2, 6);
    let recall_id = opened.1;
    let replay_recall = repo
        .save_scoped_recall(tenant, "q04-open", "q04-open", "RAW-Q04", "AQL-Q04", 1, qty_text("3"), 64)
        .await
        .expect("recall replay")
        .expect("same recall");
    assert!(matches!(replay_recall.0, SharedWrite::Replay(_)));
    assert_eq!(replay_recall.1, recall_id);
    let empty = repo
        .save_scoped_recall(tenant, "q04-empty", "q04-empty", "RAW-Q04-NONE", "AQL-Q04", 1, qty_text("1"), 64)
        .await;
    assert!(empty.expect_err("empty scope").to_string().contains("confirmed trace"));
    let uncited = repo
        .save_scoped_recall(tenant, "q04-uncited", "q04-uncited", "RAW-Q04", "AQL-NONE", 1, qty_text("1"), 64)
        .await;
    assert!(uncited.expect_err("uncited rule").to_string().contains("not found"));

    let frozen = repo
        .save_cited_recall_result(
            tenant, "q04-freeze", "q04-freeze", recall_id, "STOCK", "RAW-Q04", "freeze", "DONE",
            warehouse, location, sku,
        )
        .await
        .expect("freeze")
        .expect("admit freeze");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    let notice_failed = repo
        .save_cited_recall_result(
            tenant, "q04-notice-fail", "q04-notice-fail", recall_id, "CUSTOMER", "CUST-Q4B", "notice", "FAILED",
            warehouse, location, sku,
        )
        .await
        .expect("notice fail")
        .expect("admit notice failure");
    assert!(matches!(notice_failed, SharedWrite::Stored(_)));
    let recovered = repo
        .save_cited_recall_result(
            tenant, "q04-notice-ok", "q04-notice-ok", recall_id, "CUSTOMER", "CUST-Q4B", "notice", "DONE",
            warehouse, location, sku,
        )
        .await
        .expect("notice recover")
        .expect("admit notice recovery");
    assert!(matches!(recovered, SharedWrite::Stored(_)));
    let missing = repo
        .save_cited_recall_result(
            tenant, "q04-missing", "q04-missing", recall_id, "CUSTOMER", "CUST-Q9", "notice", "DONE",
            warehouse, location, sku,
        )
        .await;
    assert!(missing.expect_err("missing item").to_string().contains("not found"));

    let outputs: Vec<String> = sqlx::query_scalar(
        "select item_code from mfg_recall_items where tenant_id = $1 and recall_id = $2 and item_kind = 'OUTPUT' order by item_code",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(recall_id)
    .fetch_all(pool)
    .await
    .expect("outputs");
    assert_eq!(outputs, vec!["BATCH-Q04A", "BATCH-Q04B"]);
    let customers: Vec<String> = sqlx::query_scalar(
        "select item_code from mfg_recall_items where tenant_id = $1 and recall_id = $2 and item_kind = 'CUSTOMER' order by item_code",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(recall_id)
    .fetch_all(pool)
    .await
    .expect("customers");
    assert_eq!(customers, vec!["CUST-Q4A", "CUST-Q4B", "CUST-Q4C"]);
    let frozen_qty: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from shared_stock_ledgers where tenant_id = $1 and batch_code = 'RAW-Q04' and quality_status = 'FROZEN' and bucket = 'UNAVAILABLE'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("frozen ledger");
    assert_eq!(frozen_qty, 3_000_000);
    let other_notice: String = sqlx::query_scalar(
        "select notice_status from mfg_recall_items where tenant_id = $1 and recall_id = $2 and item_kind = 'CUSTOMER' and item_code = 'CUST-Q4A'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(recall_id)
    .fetch_one(pool)
    .await
    .expect("other notice");
    assert_eq!(other_notice, "PENDING");
    let version_one: i64 = sqlx::query_scalar(
        "select accept_number from shared_sampling_rules where tenant_id = $1 and rule_code = 'AQL-Q04' and rule_version = 1",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("version one");
    assert_eq!(version_one, 1);
}

async fn rebuild_confirmed_document_balances(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    customer: uuid::Uuid,
    supplier: uuid::Uuid,
    sku: uuid::Uuid,
    warehouse: uuid::Uuid,
) {
    let (draft, draft_id) = repo
        .save_draft_sale(tenant, "f01-draft", "f01-draft", customer, sku, 200, "CNY")
        .await
        .expect("draft")
        .expect("admit draft");
    assert!(matches!(draft, SharedWrite::Stored(_)));
    let refused = repo
        .confirm_document_balance(erp_repo::shared_contract::DocumentBalanceInput { tenant_id: tenant, request_id: "f01-draft-ar", payload_hash: "f01-draft-ar", document_id: draft_id, document_kind: "SALES", partner_code: "CUST-F01", currency: "CNY", due_date: "2026-10-31" })
        .await;
    assert!(refused.expect_err("draft").to_string().contains("rejected"));
    let (sale, closed) = repo
        .save_trade_sale(erp_repo::shared_contract::TradeSaleInput { tenant_id: tenant, request_id: "f01-sale", payload_hash: "f01-sale", customer_id: customer, sku_id: sku, purchased_qty: 10, unit_cost_cent: 2_000, sold_qty: 1, unit_price_cent: 200, returned_qty: 0, customer_paid_cent: 0, supplier_paid_cent: 0, partner_code: "CUST-F01", currency: "CNY", document_date: "2026-10-01", warehouse_id: warehouse })
        .await
        .expect("sale")
        .expect("admit sale");
    assert!(matches!(sale, SharedWrite::Stored(_)));
    assert_eq!(closed.receivable_cent, 200);
    let sale_id = uuid::Uuid::parse_str(&match sale { SharedWrite::Stored(receipt) => receipt.effect_id, SharedWrite::Replay(_) => unreachable!() }).expect("sale id");
    let (ar, ar_id, open) = repo
        .confirm_document_balance(erp_repo::shared_contract::DocumentBalanceInput { tenant_id: tenant, request_id: "f01-ar", payload_hash: "f01-ar", document_id: sale_id, document_kind: "SALES", partner_code: "CUST-F01", currency: "CNY", due_date: "2026-10-31" })
        .await
        .expect("ar")
        .expect("admit ar");
    assert!(matches!(ar, SharedWrite::Stored(_)));
    assert_eq!(open, 200);
    let again = repo
        .confirm_document_balance(erp_repo::shared_contract::DocumentBalanceInput { tenant_id: tenant, request_id: "f01-ar-again", payload_hash: "f01-ar-again", document_id: sale_id, document_kind: "SALES", partner_code: "CUST-F01", currency: "CNY", due_date: "2026-10-31" })
        .await;
    assert!(again.expect_err("second confirm").to_string().contains("already confirmed"));
    let (purchase, purchase_total) = repo
        .save_trade_purchase(erp_repo::shared_contract::TradePurchaseInput { tenant_id: tenant, request_id: "f01-po", payload_hash: "f01-po", supplier_id: supplier, warehouse_id: warehouse, sku_id: sku, qty: 15, price_cent: 2_000, partner_code: "SUP-F01", currency: "CNY", document_date: "2026-10-01" })
        .await
        .expect("purchase")
        .expect("admit purchase");
    assert_eq!(purchase_total, 30_000);
    let po_id = uuid::Uuid::parse_str(&match purchase { SharedWrite::Stored(receipt) => receipt.effect_id, SharedWrite::Replay(_) => unreachable!() }).expect("po id");
    let draft_ap = repo
        .confirm_document_balance(erp_repo::shared_contract::DocumentBalanceInput { tenant_id: tenant, request_id: "f01-po-draft", payload_hash: "f01-po-draft", document_id: po_id, document_kind: "PURCHASE", partner_code: "SUP-F01", currency: "CNY", due_date: "2026-11-15" })
        .await;
    assert!(draft_ap.expect_err("draft purchase").to_string().contains("rejected"));
    let confirmed = repo
        .confirm_trade_purchase(tenant, "f01-po-ok", "f01-po-ok", po_id)
        .await
        .expect("confirm purchase")
        .expect("admit confirm");
    assert!(matches!(confirmed, SharedWrite::Stored(_)));
    let (ap, _, ap_open) = repo
        .confirm_document_balance(erp_repo::shared_contract::DocumentBalanceInput { tenant_id: tenant, request_id: "f01-ap", payload_hash: "f01-ap", document_id: po_id, document_kind: "PURCHASE", partner_code: "SUP-F01", currency: "CNY", due_date: "2026-11-15" })
        .await
        .expect("ap")
        .expect("admit ap");
    assert!(matches!(ap, SharedWrite::Stored(_)));
    assert_eq!(ap_open, 30_000);
    let (opening, _) = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f01-open", payload_hash: "f01-open", kind: erp_domain::trade::PartnerBalanceKind::OpeningReceivable, partner_code: "CUST-F01", currency: "CNY", source_type: "OPENING", source_id: "2026-01-01", source_status: "CONFIRMED", amount_cent: 8_000, due_date: None })
        .await
        .expect("opening")
        .expect("admit opening");
    assert!(matches!(opening, SharedWrite::Stored(_)));
    let opening_again = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f01-open", payload_hash: "f01-open", kind: erp_domain::trade::PartnerBalanceKind::OpeningReceivable, partner_code: "CUST-F01", currency: "CNY", source_type: "OPENING", source_id: "2026-01-01", source_status: "CONFIRMED", amount_cent: 8_000, due_date: None })
        .await
        .expect("opening replay")
        .expect("same opening");
    assert!(matches!(opening_again.0, SharedWrite::Replay(_)));
    let (advance, _) = repo
        .save_advance_balance(erp_repo::shared_contract::AdvanceBalanceInput { tenant_id: tenant, request_id: "f01-adv", payload_hash: "f01-adv", kind: erp_domain::trade::PartnerBalanceKind::AdvanceReceipt, partner_code: "CUST-F01", currency: "CNY", source_id: "rc-f01", amount_cent: 5_000 })
        .await
        .expect("advance")
        .expect("admit advance");
    assert!(matches!(advance, SharedWrite::Stored(_)));
    let (settled, left) = repo
        .save_partner_settlement(tenant, "f01-pay", "f01-pay", ar_id, 50)
        .await
        .expect("settle")
        .expect("admit settle");
    assert!(matches!(settled, SharedWrite::Stored(_)));
    assert_eq!(left, 150);
    let rebuilt = repo
        .read_rebuilt_balances(tenant, &[sale_id.to_string().as_str(), po_id.to_string().as_str(), "2026-01-01", "rc-f01"])
        .await
        .expect("rebuild");
    let ar_row = rebuilt.iter().find(|row| row.source_id == sale_id.to_string()).expect("rebuilt ar");
    assert_eq!(ar_row.open_cent, 150);
    assert_eq!(ar_row.settled_cent, 50);
    let ap_row = rebuilt.iter().find(|row| row.source_id == po_id.to_string()).expect("rebuilt ap");
    assert_eq!(ap_row.open_cent, 30_000);
    assert!(rebuilt.iter().all(|row| row.kind != "ADVANCE_RECEIPT"));
    let advance_kind: String = sqlx::query_scalar(
        "select kind from partner_balances where tenant_id = $1 and source_id = 'rc-f01'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("advance row");
    assert_eq!(advance_kind, "ADVANCE_RECEIPT");
    let draft_rows: i64 = sqlx::query_scalar(
        "select count(*) from partner_balances where tenant_id = $1 and source_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(draft_id.to_string())
    .fetch_one(pool)
    .await
    .expect("draft rows");
    assert_eq!(draft_rows, 0);
}

async fn rebuild_cash_after_receipt_payment_and_return(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
) {
    let (_, ar_id) = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f02b-ar", payload_hash: "f02b-ar", kind: erp_domain::trade::PartnerBalanceKind::Receivable, partner_code: "CUST-F02", currency: "CNY", source_type: "SALES", source_id: "so-f02b", source_status: "CONFIRMED", amount_cent: 45_000, due_date: Some("2026-10-31") })
        .await
        .expect("ar")
        .expect("admit ar");
    let (_, ap_id) = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f02b-ap", payload_hash: "f02b-ap", kind: erp_domain::trade::PartnerBalanceKind::Payable, partner_code: "SUP-F02", currency: "CNY", source_type: "PURCHASE", source_id: "po-f02b", source_status: "CONFIRMED", amount_cent: 100_000, due_date: Some("2026-11-15") })
        .await
        .expect("ap")
        .expect("admit ap");
    let (receipt, _, left) = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f02b-400", payload_hash: "f02b-400", direction: "RECEIPT", partner_code: "CUST-F02", currency: "CNY", account_code: "CASH", amount_cent: 40_000, balance_id: Some(ar_id), reverses_settlement_id: None })
        .await
        .expect("receipt")
        .expect("admit receipt");
    assert!(matches!(receipt, SharedWrite::Stored(_)));
    assert_eq!(left, 5_000);
    let (payment, _, ap_left) = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f02b-700", payload_hash: "f02b-700", direction: "PAYMENT", partner_code: "SUP-F02", currency: "CNY", account_code: "BANK-BOOK", amount_cent: 70_000, balance_id: Some(ap_id), reverses_settlement_id: None })
        .await
        .expect("payment")
        .expect("admit payment");
    assert!(matches!(payment, SharedWrite::Stored(_)));
    assert_eq!(ap_left, 30_000);
    let (partial, settlement_id, after_partial) = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f02b-part", payload_hash: "f02b-part", direction: "RECEIPT", partner_code: "CUST-F02", currency: "CNY", account_code: "CASH", amount_cent: 2_000, balance_id: Some(ar_id), reverses_settlement_id: None })
        .await
        .expect("partial")
        .expect("admit partial");
    assert!(matches!(partial, SharedWrite::Stored(_)));
    assert_eq!(after_partial, 3_000);
    let (reversal, _, restored) = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f02b-rev", payload_hash: "f02b-rev", direction: "REVERSAL", partner_code: "CUST-F02", currency: "CNY", account_code: "CASH", amount_cent: -2_000, balance_id: Some(ar_id), reverses_settlement_id: Some(settlement_id) })
        .await
        .expect("reversal")
        .expect("admit reversal");
    assert!(matches!(reversal, SharedWrite::Stored(_)));
    assert_eq!(restored, 5_000);
    let (offset, open_after_return) = repo
        .save_return_cash_offset(erp_repo::shared_contract::ReturnCashOffsetInput { tenant_id: tenant, request_id: "f02b-ret5", payload_hash: "f02b-ret5", balance_id: ar_id, partner_code: "CUST-F02", currency: "CNY", account_code: "CASH", return_cent: 5_000 })
        .await
        .expect("return")
        .expect("admit return");
    assert!(matches!(offset, SharedWrite::Stored(_)));
    assert_eq!(open_after_return, 0);
    let marked = repo.read_rebuilt_cash_open(tenant, ar_id, true).await.expect("rebuild ar");
    assert_eq!(marked, (45_000, 0, false));
    let payable = repo.read_rebuilt_cash_open(tenant, ap_id, true).await.expect("rebuild ap");
    assert_eq!(payable, (70_000, 30_000, false));
    let cross = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f02b-usd", payload_hash: "f02b-usd", direction: "RECEIPT", partner_code: "CUST-F02", currency: "USD", account_code: "CASH", amount_cent: 1_000, balance_id: Some(ap_id), reverses_settlement_id: None })
        .await;
    assert!(cross.expect_err("currency").to_string().contains("rejected"));
    let over = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f02b-over", payload_hash: "f02b-over", direction: "PAYMENT", partner_code: "SUP-F02", currency: "CNY", account_code: "BANK-BOOK", amount_cent: 40_000, balance_id: Some(ap_id), reverses_settlement_id: None })
        .await;
    assert!(over.expect_err("over").to_string().contains("rejected"));
    let original_rows: i64 = sqlx::query_scalar(
        "select count(*) from partner_settlements where tenant_id = $1 and settlement_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(settlement_id)
    .fetch_one(pool)
    .await
    .expect("original settlement");
    assert_eq!(original_rows, 1);
    let bank_executed: bool = sqlx::query_scalar(
        "select bool_and(bank_executed) from cash_entries where tenant_id = $1 and partner_code = 'CUST-F02'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("bank flag");
    assert!(!bank_executed);
}

async fn allocate_confirmed_purchase_freight(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    supplier: uuid::Uuid,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let missing_rule = repo
        .save_cited_expense_allocation(erp_repo::shared_contract::CitedExpenseAllocationInput { tenant_id: tenant, request_id: "f03-norule", payload_hash: "f03-norule", category: "FREIGHT", partner_code: "SUP-F03", purchase_id: uuid::Uuid::new_v4(), currency: "CNY", gross_cent: 11_300, deductible_tax_cent: 1_300, weights: &[("SKU-A", 1), ("SKU-B", 1), ("SKU-C", 1)] })
        .await;
    assert!(missing_rule.expect_err("rule").to_string().contains("not found"));
    let (rule, tax_is_cost) = repo
        .save_tax_cost_rule(tenant, "f03-rule", "f03-rule", false)
        .await
        .expect("rule")
        .expect("admit rule");
    assert!(matches!(rule, SharedWrite::Stored(_)));
    assert!(!tax_is_cost);
    let (purchase, total) = repo
        .save_trade_purchase(erp_repo::shared_contract::TradePurchaseInput { tenant_id: tenant, request_id: "f03-po", payload_hash: "f03-po", supplier_id: supplier, warehouse_id: warehouse, sku_id: sku, qty: 10, price_cent: 1_000, partner_code: "SUP-F03", currency: "CNY", document_date: "2026-10-01" })
        .await
        .expect("purchase")
        .expect("admit purchase");
    assert_eq!(total, 10_000);
    let po_id = uuid::Uuid::parse_str(&match purchase {
        SharedWrite::Stored(receipt) => receipt.effect_id,
        SharedWrite::Replay(_) => unreachable!(),
    })
    .expect("po id");
    let draft = repo
        .save_cited_expense_allocation(erp_repo::shared_contract::CitedExpenseAllocationInput { tenant_id: tenant, request_id: "f03-draft", payload_hash: "f03-draft", category: "FREIGHT", partner_code: "SUP-F03", purchase_id: po_id, currency: "CNY", gross_cent: 11_300, deductible_tax_cent: 1_300, weights: &[("SKU-A", 1), ("SKU-B", 1), ("SKU-C", 1)] })
        .await;
    assert!(draft.expect_err("draft purchase").to_string().contains("rejected"));
    repo.confirm_trade_purchase(tenant, "f03-po-ok", "f03-po-ok", po_id)
        .await
        .expect("confirm")
        .expect("admit confirm");
    let (stored, expense_id, cost, used_tax) = repo
        .save_cited_expense_allocation(erp_repo::shared_contract::CitedExpenseAllocationInput { tenant_id: tenant, request_id: "f03-100", payload_hash: "f03-100", category: "FREIGHT", partner_code: "SUP-F03", purchase_id: po_id, currency: "CNY", gross_cent: 11_300, deductible_tax_cent: 1_300, weights: &[("SKU-A", 1), ("SKU-B", 1), ("SKU-C", 1)] })
        .await
        .expect("expense")
        .expect("admit expense");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert_eq!(cost, 10_000);
    assert!(!used_tax);
    let shares: Vec<(String, i64, bool)> = sqlx::query_as(
        "select target_code, amount_cent, residual from expense_allocations where tenant_id = $1 and expense_id = $2 order by line_no",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(expense_id)
    .fetch_all(pool)
    .await
    .expect("shares");
    assert_eq!(shares.iter().map(|row| row.1).sum::<i64>(), 10_000);
    assert_eq!(shares.last().map(|row| row.2), Some(true));
    let late = repo
        .save_expense_adjustment(tenant, "f03-late", "f03-late", expense_id, 2_000, "late freight")
        .await
        .expect("late")
        .expect("admit late");
    assert!(matches!(late, SharedWrite::Stored(_)));
    let returned = repo
        .save_expense_adjustment(tenant, "f03-ret", "f03-ret", expense_id, -1_000, "return freight")
        .await
        .expect("return")
        .expect("admit return");
    assert!(matches!(returned, SharedWrite::Stored(_)));
    let confirmed_cost: i64 = sqlx::query_scalar(
        "select cost_cent from expense_documents where tenant_id = $1 and expense_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(expense_id)
    .fetch_one(pool)
    .await
    .expect("confirmed cost");
    assert_eq!(confirmed_cost, 10_000);
    let source: String = sqlx::query_scalar(
        "select source_id from expense_documents where tenant_id = $1 and expense_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(expense_id)
    .fetch_one(pool)
    .await
    .expect("source");
    assert_eq!(source, po_id.to_string());
    let margin = repo.read_basic_margin(tenant, 45_000, Some(expense_id)).await.expect("margin");
    assert_eq!(margin, Some(35_000));
    let unknown = repo.read_basic_margin(tenant, 45_000, None).await.expect("unknown");
    assert_eq!(unknown, None);
}

async fn reconcile_posted_cost_facts(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    for (request, bucket, amount, source) in [
        ("f04-inv", "INVENTORY", 70_000_i64, "inv-f04"),
        ("f04-wip", "WIP", 4_000, "wip-f04"),
        ("f04-fg", "FINISHED", 49_000, "fg-f04"),
        ("f04-cogs", "COGS", 30_000, "cogs-f04"),
    ] {
        let stored = repo
            .save_cost_fact(erp_repo::shared_contract::CostFactInput { tenant_id: tenant, request_id: request, payload_hash: request, period_code: "2026-09-F04", bucket, amount_cent: amount, source_ref: source })
            .await
            .expect(request)
            .expect("admit fact");
        assert!(matches!(stored, SharedWrite::Stored(_)));
    }
    let books = [("INVENTORY", 70_000_i64), ("WIP", 4_000), ("FINISHED", 50_000), ("COGS", 30_000)];
    let (stored, reconciliation_id, difference) = repo
        .save_posted_cost_reconciliation(erp_repo::shared_contract::PostedCostReconciliationInput { tenant_id: tenant, request_id: "f04-recon", payload_hash: "f04-recon", period_code: "2026-09-F04", currency: "CNY", cutoff_at: "2026-09-30", books: &books })
        .await
        .expect("reconcile")
        .expect("admit reconcile");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert_eq!(difference, 1_000);
    let replay = repo
        .save_posted_cost_reconciliation(erp_repo::shared_contract::PostedCostReconciliationInput { tenant_id: tenant, request_id: "f04-recon", payload_hash: "f04-recon", period_code: "2026-09-F04", currency: "CNY", cutoff_at: "2026-09-30", books: &books })
        .await
        .expect("replay")
        .expect("same reconcile");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, reconciliation_id);
    let again = repo
        .save_posted_cost_reconciliation(erp_repo::shared_contract::PostedCostReconciliationInput { tenant_id: tenant, request_id: "f04-again", payload_hash: "f04-again", period_code: "2026-09-F04", currency: "CNY", cutoff_at: "2026-09-30", books: &books })
        .await;
    assert!(again.expect_err("second run").to_string().contains("already stored"));
    let again_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'f04-again'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("second receipt");
    assert_eq!(again_rows, 0);
    let fact_after: i64 = sqlx::query_scalar(
        "select amount_cent from shared_cost_facts where tenant_id = $1 and source_ref = 'fg-f04'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("fact");
    assert_eq!(fact_after, 49_000);
    let closed = repo
        .close_cost_period(tenant, "f04-close", "f04-close", "2026-09-F04")
        .await
        .expect("close")
        .expect("admit close");
    assert!(matches!(closed, SharedWrite::Stored(_)));
    let backdated = repo
        .save_period_adjustment(erp_repo::shared_contract::PeriodAdjustmentInput { tenant_id: tenant, request_id: "f04-back", payload_hash: "f04-back", period_code: "2026-09-F04", document_date: "2026-09-30", amount_cent: 500, reason: "late receipt" })
        .await;
    assert!(backdated.expect_err("closed date").to_string().contains("rejected"));
    let late = repo
        .save_period_adjustment(erp_repo::shared_contract::PeriodAdjustmentInput { tenant_id: tenant, request_id: "f04-late", payload_hash: "f04-late", period_code: "2026-09-F04", document_date: "2026-10-02", amount_cent: 500, reason: "late receipt" })
        .await
        .expect("late")
        .expect("admit late");
    assert!(matches!(late, SharedWrite::Stored(_)));
    let source: String = sqlx::query_scalar(
        "select source_ref from cost_reconciliations where tenant_id = $1 and reconciliation_id = $2 and bucket = 'FINISHED'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(reconciliation_id)
    .fetch_one(pool)
    .await
    .expect("source");
    assert_eq!(source, "fg-f04");
}

async fn record_cited_invoices_and_aging(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    use erp_domain::trade::PartnerBalanceKind;
    let (_, open_id) = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f05b-ar", payload_hash: "f05b-ar", kind: PartnerBalanceKind::Receivable, partner_code: "CUST-F05B", currency: "CNY", source_type: "SALES", source_id: "so-f05b", source_status: "CONFIRMED", amount_cent: 20_000, due_date: Some("2026-08-01") })
        .await
        .expect("f05b ar")
        .expect("admit f05b ar");
    let settled = repo
        .save_partner_settlement(tenant, "f05b-part", "f05b-part", open_id, 5_000)
        .await
        .expect("f05b settle")
        .expect("admit f05b settle");
    assert_eq!(settled.1, 15_000);
    let (_, credit_id) = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f05b-credit", payload_hash: "f05b-credit", kind: PartnerBalanceKind::Receivable, partner_code: "CUST-F05B", currency: "CNY", source_type: "CREDIT", source_id: "cn-f05b", source_status: "CONFIRMED", amount_cent: 3_000, due_date: Some("2026-09-20") })
        .await
        .expect("f05b credit")
        .expect("admit f05b credit");
    let credit_cash = repo
        .save_cash_entry(erp_repo::shared_contract::CashEntryInput { tenant_id: tenant, request_id: "f05b-credit-cash", payload_hash: "f05b-credit-cash", direction: "RECEIPT", partner_code: "CUST-F05B", currency: "CNY", account_code: "CASH", amount_cent: 3_000, balance_id: Some(credit_id), reverses_settlement_id: None })
        .await
        .expect("f05b credit cash")
        .expect("admit f05b credit cash");
    assert_eq!(credit_cash.2, 0);
    let (_, undated_id) = repo
        .save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "f05b-undated", payload_hash: "f05b-undated", kind: PartnerBalanceKind::Payable, partner_code: "SUP-F05B", currency: "CNY", source_type: "PURCHASE", source_id: "po-f05b", source_status: "CONFIRMED", amount_cent: 4_000, due_date: None })
        .await
        .expect("f05b undated")
        .expect("admit f05b undated");

    let settled_invoice = repo
        .save_cited_invoice(erp_repo::shared_contract::CitedInvoiceInput { tenant_id: tenant, request_id: "f05b-inv-settled", payload_hash: "f05b-inv-settled", number: "INV-F05B-SETTLED", issuer: "ISSUER-A", invoice_date: "2026-10-03", balance_id: credit_id, requested_official: true })
        .await;
    assert!(settled_invoice.expect_err("settled").to_string().contains("settled"));

    let (stored, invoice_id, official) = repo
        .save_cited_invoice(erp_repo::shared_contract::CitedInvoiceInput { tenant_id: tenant, request_id: "f05b-inv", payload_hash: "f05b-inv", number: "INV-F05B", issuer: "ISSUER-A", invoice_date: "2026-10-03", balance_id: open_id, requested_official: true })
        .await
        .expect("cited invoice")
        .expect("admit cited invoice");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert!(!official);
    let replay = repo
        .save_cited_invoice(erp_repo::shared_contract::CitedInvoiceInput { tenant_id: tenant, request_id: "f05b-inv", payload_hash: "f05b-inv", number: "INV-F05B", issuer: "ISSUER-A", invoice_date: "2026-10-03", balance_id: open_id, requested_official: true })
        .await
        .expect("cited replay")
        .expect("same cited invoice");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, invoice_id);
    assert!(!replay.2);
    let other_issuer = repo
        .save_cited_invoice(erp_repo::shared_contract::CitedInvoiceInput { tenant_id: tenant, request_id: "f05b-inv-b", payload_hash: "f05b-inv-b", number: "INV-F05B", issuer: "ISSUER-B", invoice_date: "2026-10-04", balance_id: undated_id, requested_official: false })
        .await
        .expect("other issuer")
        .expect("admit other issuer");
    assert!(matches!(other_issuer.0, SharedWrite::Stored(_)));
    assert!(!other_issuer.2);
    let duplicate = repo
        .save_cited_invoice(erp_repo::shared_contract::CitedInvoiceInput { tenant_id: tenant, request_id: "f05b-inv-dup", payload_hash: "f05b-inv-dup", number: "INV-F05B", issuer: "ISSUER-A", invoice_date: "2026-10-05", balance_id: undated_id, requested_official: false })
        .await;
    assert!(duplicate.expect_err("same issuer").to_string().contains("already exists"));
    let late = repo
        .save_invoice_record(erp_repo::shared_contract::InvoiceRecordInput { tenant_id: tenant, request_id: "f05b-late", payload_hash: "f05b-late", number: "INV-F05B-LATE", issuer: "ISSUER-A", invoice_date: "2026-10-06", currency: "CNY", gross_cent: -2_000, tax_cent: 0, source_type: "CREDIT", source_id: "cn-f05b-late", balance_id: None })
        .await
        .expect("late credit invoice")
        .expect("admit late credit invoice");
    assert!(matches!(late.0, SharedWrite::Stored(_)));
    let attached = repo
        .save_shared_attachment(
            tenant, "f05b-file", "f05b-file", &invoice_id.to_string(), "invoice-f05b.pdf",
            "sha256-f05b", 128, "operator-f05b",
        )
        .await
        .expect("attachment")
        .expect("admit attachment");
    assert!(matches!(attached.0, SharedWrite::Stored(_)));

    let (snapshot, snapshot_id, rows) = repo
        .save_cited_aging(tenant, "f05b-age", "f05b-age", "2026-10-01", &[open_id, credit_id, undated_id])
        .await
        .expect("aging")
        .expect("admit aging");
    assert!(matches!(snapshot, SharedWrite::Stored(_)));
    assert_eq!(rows, 2);
    let replay_age = repo
        .save_cited_aging(tenant, "f05b-age", "f05b-age", "2026-10-01", &[open_id, credit_id, undated_id])
        .await
        .expect("aging replay")
        .expect("same aging");
    assert!(matches!(replay_age.0, SharedWrite::Replay(_)));
    assert_eq!(replay_age.1, snapshot_id);
    assert_eq!(replay_age.2, 2);

    let partial: (String, i64) = sqlx::query_as(
        "select bucket, open_cent from aging_snapshots where tenant_id = $1 and snapshot_id = $2 and balance_id = $3",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(snapshot_id)
    .bind(open_id)
    .fetch_one(pool)
    .await
    .expect("partial bucket");
    assert_eq!(partial, ("61-90".to_string(), 15_000));
    let credit_rows: i64 = sqlx::query_scalar(
        "select count(*) from aging_snapshots where tenant_id = $1 and snapshot_id = $2 and balance_id = $3",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(snapshot_id)
    .bind(credit_id)
    .fetch_one(pool)
    .await
    .expect("credit absent");
    assert_eq!(credit_rows, 0);
    let undated: (String, i64) = sqlx::query_as(
        "select bucket, open_cent from aging_snapshots where tenant_id = $1 and snapshot_id = $2 and balance_id = $3",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(snapshot_id)
    .bind(undated_id)
    .fetch_one(pool)
    .await
    .expect("undated bucket");
    assert_eq!(undated, ("UNDATED".to_string(), 4_000));
    let stored_official: bool = sqlx::query_scalar(
        "select official_issued from invoice_records where tenant_id = $1 and invoice_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(invoice_id)
    .fetch_one(pool)
    .await
    .expect("official flag");
    assert!(!stored_official);
    let gross: i64 = sqlx::query_scalar(
        "select gross_cent from invoice_records where tenant_id = $1 and invoice_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(invoice_id)
    .fetch_one(pool)
    .await
    .expect("gross");
    assert_eq!(gross, 15_000);
}

async fn split_cited_cost_variance(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    let work_order_id = uuid::Uuid::new_v4();
    let (stored, standard_id, version) = repo
        .save_standard_cost_snapshot(
            tenant, "f06b-std", "f06b-std", work_order_id, 10_000_000, 3_000, 60, 200, 100,
        )
        .await
        .expect("standard")
        .expect("admit standard");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let replay = repo
        .save_standard_cost_snapshot(
            tenant, "f06b-std", "f06b-std", work_order_id, 10_000_000, 3_000, 60, 200, 100,
        )
        .await
        .expect("standard replay")
        .expect("same standard");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, standard_id);
    let negative = repo
        .save_standard_cost_snapshot(
            tenant, "f06b-neg", "f06b-neg", work_order_id, -1_000_000, 3_000, 60, 200, 100,
        )
        .await;
    assert!(negative.expect_err("negative qty").to_string().contains("rejected"));

    let (posted, variance_id, total, estimated) = repo
        .save_cited_cost_variance(
            tenant, "f06b-var", "f06b-var", standard_id, 5_000_000, 6_200, 50, 250, Some(6_500),
        )
        .await
        .expect("variance")
        .expect("admit variance");
    assert!(matches!(posted, SharedWrite::Stored(_)));
    assert_eq!(total, 2_000);
    assert!(!estimated);
    let missing = repo
        .save_cited_cost_variance(
            tenant, "f06b-missing", "f06b-missing", uuid::Uuid::new_v4(), 5_000_000, 6_200, 50, 250, Some(6_500),
        )
        .await;
    assert!(missing.expect_err("missing standard").to_string().contains("not found"));

    let (second, second_id, second_version) = repo
        .save_standard_cost_snapshot(
            tenant, "f06b-std2", "f06b-std2", work_order_id, 8_000_000, 3_000, 60, 200, 100,
        )
        .await
        .expect("second standard")
        .expect("admit second standard");
    assert!(matches!(second, SharedWrite::Stored(_)));
    assert_eq!(second_version, 2);
    assert_ne!(second_id, standard_id);
    let first_qty: i64 = sqlx::query_scalar(
        "select material_qty_micros from mfg_standard_cost_drivers where tenant_id = $1 and standard_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(standard_id)
    .fetch_one(pool)
    .await
    .expect("version 1 qty");
    assert_eq!(first_qty, 10_000_000);

    let (unknown, _, unknown_total, unknown_estimated) = repo
        .save_cited_cost_variance(
            tenant, "f06b-unknown", "f06b-unknown", second_id, 5_000_000, 6_200, 50, 250, None,
        )
        .await
        .expect("unknown overhead")
        .expect("admit unknown");
    assert!(matches!(unknown, SharedWrite::Stored(_)));
    assert!(unknown_estimated);
    assert_ne!(unknown_total, 2_000);

    let parts: Vec<(String, i64, i64, i64, bool)> = sqlx::query_as(
        "select kind, standard_cent, actual_cent, variance_cent, estimated from mfg_cost_variance_parts where tenant_id = $1 and variance_id = $2 order by kind",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(variance_id)
    .fetch_all(pool)
    .await
    .expect("parts");
    let part = |kind: &str| {
        parts
            .iter()
            .find(|row| row.0 == kind)
            .cloned()
            .unwrap_or_else(|| panic!("missing {kind}"))
    };
    assert_eq!(part("MATERIAL_PRICE"), ("MATERIAL_PRICE".to_string(), 30_000, 62_000, 32_000, false));
    assert_eq!(part("MATERIAL_USAGE"), ("MATERIAL_USAGE".to_string(), 62_000, 31_000, -31_000, false));
    assert_eq!(part("LABOR_RATE"), ("LABOR_RATE".to_string(), 12_000, 15_000, 3_000, false));
    assert_eq!(part("LABOR_EFFICIENCY"), ("LABOR_EFFICIENCY".to_string(), 15_000, 12_500, -2_500, false));
    assert_eq!(part("OVERHEAD"), ("OVERHEAD".to_string(), 6_000, 6_500, 500, false));
    assert!(!part("OVERHEAD").4);
    let material_standard = part("MATERIAL_PRICE").1;
    let labor_standard = part("LABOR_RATE").1;
    let overhead_standard = part("OVERHEAD").1;
    let material_actual = part("MATERIAL_USAGE").2;
    let labor_actual = part("LABOR_EFFICIENCY").2;
    let overhead_actual = part("OVERHEAD").2;
    assert_eq!(material_standard + labor_standard + overhead_standard, 48_000);
    assert_eq!(material_actual + labor_actual + overhead_actual, 50_000);
    let variance_sum: i64 = parts.iter().map(|row| row.3).sum();
    assert_eq!(variance_sum, 2_000);
    let version_rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_standard_cost_drivers where tenant_id = $1 and work_order_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(pool)
    .await
    .expect("versions");
    assert_eq!(version_rows, 2);
}

async fn report_cited_operating_range(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let supplier = uuid::Uuid::new_v4();
    let customer = uuid::Uuid::new_v4();
    let draft = repo
        .save_trade_purchase(erp_repo::shared_contract::TradePurchaseInput { tenant_id: tenant, request_id: "r01b-draft", payload_hash: "r01b-draft", supplier_id: supplier, warehouse_id: warehouse, sku_id: sku, qty: 9, price_cent: 1_000, partner_code: "SUP-R01B", currency: "CNY", document_date: "2026-10-03" })
        .await
        .expect("draft purchase")
        .expect("admit draft");
    assert!(matches!(draft.0, SharedWrite::Stored(_)));
    let confirmed = repo
        .save_trade_purchase(erp_repo::shared_contract::TradePurchaseInput { tenant_id: tenant, request_id: "r01b-po", payload_hash: "r01b-po", supplier_id: supplier, warehouse_id: warehouse, sku_id: sku, qty: 4, price_cent: 2_500, partner_code: "SUP-R01B", currency: "CNY", document_date: "2026-10-04" })
        .await
        .expect("purchase")
        .expect("admit purchase");
    assert_eq!(confirmed.1, 10_000);
    let po_id = sqlx::query_scalar::<_, uuid::Uuid>(
        "select effect_id::uuid from command_receipts where tenant_id = $1 and request_id = 'r01b-po'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("purchase id");
    repo.confirm_trade_purchase(tenant, "r01b-po-ok", "r01b-po-ok", po_id)
        .await
        .expect("confirm")
        .expect("admit confirm");
    let usd = repo
        .save_trade_purchase(erp_repo::shared_contract::TradePurchaseInput { tenant_id: tenant, request_id: "r01b-usd", payload_hash: "r01b-usd", supplier_id: supplier, warehouse_id: warehouse, sku_id: sku, qty: 2, price_cent: 1_500, partner_code: "SUP-R01B-USD", currency: "USD", document_date: "2026-10-05" })
        .await
        .expect("usd")
        .expect("admit usd");
    assert_eq!(usd.1, 3_000);
    let usd_id = sqlx::query_scalar::<_, uuid::Uuid>(
        "select effect_id::uuid from command_receipts where tenant_id = $1 and request_id = 'r01b-usd'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("usd id");
    repo.confirm_trade_purchase(tenant, "r01b-usd-ok", "r01b-usd-ok", usd_id)
        .await
        .expect("confirm usd")
        .expect("admit confirm usd");
    let sale = repo
        .save_trade_sale(erp_repo::shared_contract::TradeSaleInput { tenant_id: tenant, request_id: "r01b-so", payload_hash: "r01b-so", customer_id: customer, sku_id: sku, purchased_qty: 4, unit_cost_cent: 2_500, sold_qty: 3, unit_price_cent: 4_000, returned_qty: 1, customer_paid_cent: 2_000, supplier_paid_cent: 0, partner_code: "CUST-R01B", currency: "CNY", document_date: "2026-10-06", warehouse_id: warehouse })
        .await
        .expect("sale")
        .expect("admit sale");
    assert!(matches!(sale.0, SharedWrite::Stored(_)));
    let page = repo.refuse_page_operating_report(1, 4).await;
    assert!(page.expect_err("page").to_string().contains("authorized range"));

    let (stored, run_id, lines) = repo
        .save_operating_report(
            tenant, "r01b-rpt", "r01b-rpt", "2026-12-31", Some("2026-10-01"), Some("2026-12-31"), None, None,
        )
        .await
        .expect("report")
        .expect("admit report");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert!(lines >= 3);
    let replay = repo
        .save_operating_report(
            tenant, "r01b-rpt", "r01b-rpt", "2026-12-31", Some("2026-10-01"), Some("2026-12-31"), None, None,
        )
        .await
        .expect("replay")
        .expect("same report");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, run_id);

    let cny: (i64, i64) = sqlx::query_as(
        "select amount_cent, qty from operating_report_totals where tenant_id = $1 and run_id = $2 and metric = 'PURCHASE' and currency = 'CNY'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("cny purchase");
    let usd_total: (i64, i64) = sqlx::query_as(
        "select amount_cent, qty from operating_report_totals where tenant_id = $1 and run_id = $2 and metric = 'PURCHASE' and currency = 'USD'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("usd purchase");
    assert_ne!(cny.0, usd_total.0);
    let draft_lines: i64 = sqlx::query_scalar(
        "select count(*) from operating_report_lines where tenant_id = $1 and run_id = $2 and source_id = $3",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .bind(sqlx::query_scalar::<_, String>(
        "select effect_id from command_receipts where tenant_id = $1 and request_id = 'r01b-draft'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("draft id"))
    .fetch_one(pool)
    .await
    .expect("draft lines");
    assert_eq!(draft_lines, 0);
    let sale_line: (String, i64) = sqlx::query_as(
        "select source_id, amount_cent from operating_report_lines where tenant_id = $1 and run_id = $2 and metric = 'SALES' and partner_code = 'CUST-R01B'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("sale drill");
    assert_eq!(sale_line.0, "r01b-so");
    assert!(sale_line.1 > 0);
    let cutoff: String = sqlx::query_scalar(
        "select cutoff_at from operating_report_runs where tenant_id = $1 and run_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("cutoff");
    assert_eq!(cutoff, "2026-12-31");
}

async fn report_cited_manufacturing(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    use erp_domain::manufacturing::{MaterialMove, MaterialMoveKind, OperationReport, ReceiptStatus};
    use erp_domain::quantity::ScaledQty;
    let planned = repo
        .save_work_order(
            tenant, "r02b-wo", "r02b-wo", "WO-R02B", "FG-R02B", None, ScaledQty::from_micros(10_000_000),
        )
        .await
        .expect("work order")
        .expect("admit work order");
    assert!(matches!(planned, SharedWrite::Stored(_)));
    let work_order_id = sqlx::query_scalar::<_, uuid::Uuid>(
        "select effect_id::uuid from command_receipts where tenant_id = $1 and request_id = 'r02b-wo'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("work order id");
    sqlx::query("update mfg_work_orders set status = 'RELEASED' where tenant_id = $1 and work_order_id = $2")
        .bind(uuid::Uuid::from(tenant))
        .bind(work_order_id)
        .execute(pool)
        .await
        .expect("release status");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'r02b', 'R02B')")
        .bind(warehouse)
        .bind(uuid::Uuid::from(tenant))
        .execute(pool)
        .await
        .expect("r02b warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-R02B')")
        .bind(sku)
        .bind(uuid::Uuid::from(tenant))
        .execute(pool)
        .await
        .expect("r02b sku");
    let r02b_seed = repo
        .post_inventory_inbound(tenant, "r02b-in", "r02b-in", warehouse, sku, 4, Some("r02b".into()))
        .await
        .expect("r02b inbound")
        .expect("admit r02b inbound");
    assert!(matches!(r02b_seed, SharedWrite::Stored(_)));
    repo.reserve_manufacturing_stock(tenant, "r02b-rsv", "r02b-rsv", work_order_id, warehouse, sku, ScaledQty::from_micros(4_000_000))
        .await
        .expect("r02b reserve")
        .expect("admit r02b reserve");

    let issued = repo
        .save_material_move(
            tenant, "r02b-issue", "r02b-issue", work_order_id,
            MaterialMove { kind: MaterialMoveKind::Issue, qty: ScaledQty::from_micros(4_000_000), supplement_reason_required: false },
            None, Some(warehouse), Some(sku),
        )
        .await
        .expect("issue")
        .expect("admit issue");
    assert!(matches!(issued.0, SharedWrite::Stored(_)));
    let r02b_issue_id = match &issued.0 {
        SharedWrite::Stored(stored) => uuid::Uuid::parse_str(&stored.effect_id).expect("r02b issue id"),
        SharedWrite::Replay(_) => panic!("r02b issue must store"),
    };
    let consumed = repo
        .post_material_move(
            tenant, "r02b-consume", "r02b-consume",
            erp_repo::shared_contract::MaterialMoveInput {
                work_order_id, warehouse_id: warehouse, sku_id: sku, batch_id: None,
                original_issue_id: Some(r02b_issue_id),
                movement: MaterialMove { kind: MaterialMoveKind::Consume, qty: ScaledQty::from_micros(3_000_000), supplement_reason_required: false },
                reason: None,
            },
        )
        .await
        .expect("consume")
        .expect("admit consume");
    assert!(matches!(consumed.effect, SharedWrite::Stored(_)));
    let report = OperationReport {
        operation: "OP-R02B".into(),
        good: ScaledQty::from_micros(6_000_000),
        rejected: ScaledQty::from_micros(0),
        rework: ScaledQty::from_micros(0),
        minutes: 30,
        operator_id: "operator-r02b".into(),
        session_user_id: "session-r02b".into(),
        session_id: "sess-r02b".into(),
        crew_code: "crew-r02b".into(),
        started_at: "2026-10-06T08:00:00".into(),
        ended_at: "2026-10-06T08:30:00".into(),
        reverses_report_id: None,
    };
    let reported = repo
        .save_operation_report(tenant, "r02b-report", "r02b-report", work_order_id, ScaledQty::from_micros(10_000_000), &report)
        .await
        .expect("report")
        .expect("admit report");
    assert!(matches!(reported.0, SharedWrite::Stored(_)));
    let report_id = sqlx::query_scalar::<_, uuid::Uuid>(
        "select effect_id::uuid from command_receipts where tenant_id = $1 and request_id = 'r02b-report'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("report id");
    let receipt = repo
        .save_production_receipt(
            tenant, "r02b-receipt", "r02b-receipt", work_order_id, ScaledQty::from_micros(6_000_000),
            ReceiptStatus::Hold, report_id, "BATCH-R02B", uuid::Uuid::nil(), uuid::Uuid::nil(), uuid::Uuid::nil(),
        )
        .await
        .expect("receipt")
        .expect("admit receipt");
    assert!(matches!(receipt.0, SharedWrite::Stored(_)));
    let (variance, _, total, estimated) = repo
        .save_cost_variance(
            tenant, "r02b-cost", "r02b-cost", work_order_id, 30_000, 31_000, 12_000, 12_500, 6_000, None,
        )
        .await
        .expect("cost")
        .expect("admit cost");
    assert!(matches!(variance, SharedWrite::Stored(_)));
    assert!(estimated);
    assert_eq!(total, 1_500);

    let (stored, run_id, lines) = repo
        .save_manufacturing_report(tenant, "r02b-rpt", "r02b-rpt", "2026-10-31", Some(work_order_id))
        .await
        .expect("manufacturing report")
        .expect("admit manufacturing report");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert!(lines >= 5);
    let replay = repo
        .save_manufacturing_report(tenant, "r02b-rpt", "r02b-rpt", "2026-10-31", Some(work_order_id))
        .await
        .expect("replay")
        .expect("same report");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, run_id);

    let header: (String, Option<i32>, String) = sqlx::query_as(
        "select cutoff_at, cost_version, quality_status from mfg_report_runs where tenant_id = $1 and run_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("header");
    assert_eq!(header.0, "2026-10-31");
    assert_eq!(header.1, Some(1));
    assert_eq!(header.2, "HOLD");
    let plan: i64 = sqlx::query_scalar(
        "select qty_micros from mfg_report_lines where tenant_id = $1 and run_id = $2 and metric = 'PLAN' and source_id = $3",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .bind(work_order_id.to_string())
    .fetch_one(pool)
    .await
    .expect("plan");
    assert_eq!(plan, 10_000_000);
    let issue_source: String = sqlx::query_scalar(
        "select source_id from mfg_report_lines where tenant_id = $1 and run_id = $2 and metric = 'ISSUE'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("issue source");
    assert_ne!(issue_source, work_order_id.to_string());
    let consume_source: String = sqlx::query_scalar(
        "select source_id from mfg_report_lines where tenant_id = $1 and run_id = $2 and metric = 'CONSUME'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("consume source");
    assert_ne!(consume_source, issue_source);
    let report_source: String = sqlx::query_scalar(
        "select source_id from mfg_report_lines where tenant_id = $1 and run_id = $2 and metric = 'REPORT_GOOD'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("report source");
    assert_eq!(report_source, report_id.to_string());
    let partial: i64 = sqlx::query_scalar(
        "select count(*) from mfg_report_lines where tenant_id = $1 and run_id = $2 and metric = 'PARTIAL'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("partial");
    assert_eq!(partial, 1);
    let cost_estimated: bool = sqlx::query_scalar(
        "select estimated from mfg_report_lines where tenant_id = $1 and run_id = $2 and metric = 'COST_V1'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(run_id)
    .fetch_one(pool)
    .await
    .expect("estimated cost");
    assert!(cost_estimated);
}

async fn export_cited_snapshot(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    let sources = vec!["so-r03b".to_string(), "po-r03b".to_string(), "exclude-r03b".to_string()];
    let empty = repo
        .save_export_scope(
            tenant, "r03b-empty", "r03b-empty", "user-r03b", "SELECTED", "cutoff=2026-10-31", &[],
        )
        .await;
    assert!(empty.expect_err("empty").to_string().contains("rejected"));
    let bad_scope = repo
        .save_export_scope(
            tenant, "r03b-scope", "r03b-scope", "user-r03b", "PAGE", "cutoff=2026-10-31", &sources,
        )
        .await;
    assert!(bad_scope.expect_err("scope").to_string().contains("invalid"));
    let (frozen, snapshot_id, count) = repo
        .save_export_scope(
            tenant, "r03b-snap", "r03b-snap", "user-r03b", "SELECTED", "cutoff=2026-10-31", &sources,
        )
        .await
        .expect("snapshot")
        .expect("admit snapshot");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    assert_eq!(count, 3);
    let replay = repo
        .save_export_scope(
            tenant, "r03b-snap", "r03b-snap", "user-r03b", "SELECTED", "cutoff=2026-10-31", &sources,
        )
        .await
        .expect("snapshot replay")
        .expect("same snapshot");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, snapshot_id);

    let (stored, job_id, items) = repo
        .save_cited_export(
            tenant, "r03b-job", "r03b-job", snapshot_id, "csv-v1", &["exclude-r03b".to_string()],
            Some("po-r03b"), Some("added-r03b"),
        )
        .await
        .expect("export")
        .expect("admit export");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    assert_eq!(items, 2);
    let missing = repo
        .save_cited_export(
            tenant, "r03b-missing", "r03b-missing", uuid::Uuid::new_v4(), "csv-v1", &[], None, None,
        )
        .await;
    assert!(missing.expect_err("missing snapshot").to_string().contains("not found"));

    let (download, authorized, content) = repo
        .authorize_export_download(tenant, "r03b-down", "r03b-down", job_id, "user-r03b")
        .await
        .expect("download")
        .expect("admit download");
    assert!(matches!(download, SharedWrite::Stored(_)));
    assert!(authorized);
    assert!(content.contains("so-r03b"));
    assert!(!content.contains("po-r03b"));
    assert!(!content.contains("exclude-r03b"));
    assert!(!content.contains("added-r03b"));
    let other = repo
        .authorize_export_download(tenant, "r03b-other", "r03b-other", job_id, "user-other")
        .await;
    assert!(other.expect_err("other actor").to_string().contains("actor"));
    let cancelled = repo
        .cancel_export_read(tenant, "r03b-cancel", "r03b-cancel", job_id)
        .await
        .expect("cancel")
        .expect("admit cancel");
    assert!(matches!(cancelled, SharedWrite::Stored(_)));
    let after = repo
        .authorize_export_download(tenant, "r03b-after", "r03b-after", job_id, "user-r03b")
        .await
        .expect("after cancel")
        .expect("job remains");
    assert!(after.1);
    let still: i64 = sqlx::query_scalar(
        "select count(*) from export_snapshots where tenant_id = $1 and job_id = $2 and read_cancelled = true",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(job_id)
    .fetch_one(pool)
    .await
    .expect("cancelled flag");
    assert_eq!(still, 1);
    let file_rows: i64 = sqlx::query_scalar(
        "select count(*) from export_files where tenant_id = $1 and content_text like '%added-r03b%'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("extra absent");
    assert_eq!(file_rows, 0);
}

async fn retain_cited_task_effect(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    let object_id = "wo-r04b";
    let (opened, exception_id) = repo
        .save_task_exception(
            tenant, "r04b-fail", "r04b-fail", "TASK_FAILED", "WORK_ORDER", object_id, "cmd-r04b", 1,
            "worker stopped",
        )
        .await
        .expect("exception")
        .expect("admit exception");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    let banner = repo
        .save_task_effect(tenant, "r04b-banner", "r04b-banner", exception_id, "refresh ok", "refresh ok")
        .await;
    assert!(banner.expect_err("banner").to_string().contains("rejected"));
    let (stored, effect_id) = repo
        .save_task_effect(
            tenant, "r04b-effect", "r04b-effect", exception_id, "effect-r04b", "refresh ok",
        )
        .await
        .expect("effect")
        .expect("admit effect");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    let replay = repo
        .save_task_effect(
            tenant, "r04b-effect", "r04b-effect", exception_id, "effect-r04b", "refresh ok",
        )
        .await
        .expect("effect replay")
        .expect("same effect");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, effect_id);
    let missing = repo
        .save_task_effect(tenant, "r04b-missing", "r04b-missing", uuid::Uuid::new_v4(), "effect-r04b", "")
        .await;
    assert!(missing.expect_err("missing").to_string().contains("not found"));
    let read = repo
        .read_task_effect(tenant, object_id, "cmd-r04b", 1)
        .await
        .expect("read effect");
    assert_eq!(read, (effect_id, "effect-r04b".to_string()));
    let stale = repo.read_task_effect(tenant, object_id, "cmd-r04b", 2).await;
    assert!(stale.expect_err("stale").to_string().contains("stale"));
    let retried = repo
        .act_on_task_exception(tenant, "r04b-retry", "r04b-retry", exception_id, "cmd-r04b", 1, "RETRY", uuid::Uuid::nil())
        .await
        .expect("retry")
        .expect("admit retry");
    assert!(matches!(retried, SharedWrite::Stored(_)));
    let kept: String = sqlx::query_scalar(
        "select effect_text from task_effects where tenant_id = $1 and exception_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(exception_id)
    .fetch_one(pool)
    .await
    .expect("kept effect");
    assert_eq!(kept, "effect-r04b");
    let status: String = sqlx::query_scalar(
        "select status from task_exceptions where tenant_id = $1 and exception_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(exception_id)
    .fetch_one(pool)
    .await
    .expect("status");
    assert_eq!(status, "RETRIED");
}

async fn restore_cited_report_view(repo: &SharedContractRepo<'_>, pool: &sqlx::PgPool, tenant: TenantId) {
    let catalog = vec!["amount_cent".to_string(), "qty".to_string(), "document_date".to_string()];
    let saved_catalog = repo
        .save_report_field_catalog(tenant, "r05b-cat", "r05b-cat", "operating", &catalog)
        .await
        .expect("catalog")
        .expect("admit catalog");
    assert!(matches!(saved_catalog.0, SharedWrite::Stored(_)));
    assert_eq!(saved_catalog.1, 3);
    let view = personal_view("user-r05b", "month-sales-r05b");
    let (stored, view_id) = repo
        .save_report_view(tenant, "r05b-save", "r05b-save", &view)
        .await
        .expect("view")
        .expect("admit view");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    let other = TenantId(uuid::Uuid::new_v4());
    let other_view = personal_view("user-r05b", "month-sales-r05b");
    let other_saved = repo
        .save_report_view(other, "r05b-other", "r05b-other", &other_view)
        .await
        .expect("other tenant")
        .expect("admit other tenant");
    assert_ne!(other_saved.1, view_id);
    let restored = repo
        .restore_report_view(tenant, "user-r05b", view_id, "operating|2026-10-01|2026-10-31")
        .await
        .expect("restore");
    assert_eq!(restored.0, "bar");
    assert_eq!(restored.1, "sum(amount_cent)");
    let other_user = repo
        .restore_report_view(tenant, "user-other", view_id, "operating|2026-10-01|2026-10-31")
        .await;
    assert!(other_user.expect_err("other user").to_string().contains("another user"));
    let other_query = repo
        .restore_report_view(tenant, "user-r05b", view_id, "operating|2026-11-01|2026-11-30")
        .await;
    assert!(other_query.expect_err("other query").to_string().contains("saved query"));
    let caller_fields = vec!["partner".to_string(), "amount_cent".to_string()];
    let (marked, stale) = repo
        .mark_cited_report_stale(tenant, "r05b-stale", "r05b-stale", view_id, &caller_fields)
        .await
        .expect("stale")
        .expect("admit stale");
    assert!(matches!(marked, SharedWrite::Stored(_)));
    assert_eq!(stale, 1);
    let formula: String = sqlx::query_scalar(
        "select formula from saved_report_views where tenant_id = $1 and view_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(view_id)
    .fetch_one(pool)
    .await
    .expect("formula");
    assert_eq!(formula, "sum(amount_cent)");
    let stale_field: String = sqlx::query_scalar(
        "select field_name from saved_report_stale_fields where tenant_id = $1 and view_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(view_id)
    .fetch_one(pool)
    .await
    .expect("stale field");
    assert_eq!(stale_field, "partner");
    let other_rows: i64 = sqlx::query_scalar(
        "select count(*) from saved_report_views where tenant_id = $1 and name = 'month-sales-r05b'",
    )
    .bind(uuid::Uuid::from(other))
    .fetch_one(pool)
    .await
    .expect("other count");
    assert_eq!(other_rows, 1);
}

async fn commit_cited_issue_once(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    _warehouse: uuid::Uuid,
    _sku: uuid::Uuid,
) {
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'o01b', 'O01B')")
        .bind(warehouse)
        .bind(uuid::Uuid::from(tenant))
        .execute(pool)
        .await
        .expect("o01b warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-O01B')")
        .bind(sku)
        .bind(uuid::Uuid::from(tenant))
        .execute(pool)
        .await
        .expect("o01b sku");
    let o01b_seed = repo
        .post_inventory_inbound(tenant, "o01b-in", "o01b-in", warehouse, sku, 2, Some("o01b".into()))
        .await
        .expect("o01b inbound")
        .expect("admit o01b inbound");
    assert!(matches!(o01b_seed, SharedWrite::Stored(_)));
    use erp_domain::quantity::ScaledQty;
    let planned = repo
        .save_work_order(
            tenant, "o01b-wo", "o01b-wo", "WO-O01B", "FG-O01B", None, ScaledQty::from_micros(2_000_000),
        )
        .await
        .expect("work order")
        .expect("admit work order");
    assert!(matches!(planned, SharedWrite::Stored(_)));
    let work_order_id = sqlx::query_scalar::<_, uuid::Uuid>(
        "select effect_id::uuid from command_receipts where tenant_id = $1 and request_id = 'o01b-wo'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("work order id");
    let fractional = erp_domain::manufacturing::AtomicEffect {
        source_action: "ISSUE".into(),
        action_no: "act-o01b-frac".into(),
        qty: parse_qty("0.125").expect("qty"),
        amount_cent: 100,
    };
    let refused = repo
        .commit_atomic_effect(tenant, "o01b-frac", "o01b-frac", work_order_id, warehouse, sku, &fractional)
        .await;
    assert!(refused.expect_err("fraction").to_string().contains("rejected"));
    let effect = erp_domain::manufacturing::AtomicEffect {
        source_action: "ISSUE".into(),
        action_no: "act-o01b".into(),
        qty: parse_qty("1").expect("qty"),
        amount_cent: 2_500,
    };
    let (stored, document_id) = repo
        .commit_atomic_effect(tenant, "o01b-post", "o01b-post", work_order_id, warehouse, sku, &effect)
        .await
        .expect("post")
        .expect("admit post");
    assert!(matches!(stored, SharedWrite::Stored(_)));
    let replay = repo
        .commit_atomic_effect(tenant, "o01b-post", "o01b-post", work_order_id, warehouse, sku, &effect)
        .await
        .expect("replay")
        .expect("same post");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, document_id);
    let again = repo
        .commit_atomic_effect(tenant, "o01b-again", "o01b-again", work_order_id, warehouse, sku, &effect)
        .await;
    assert!(again.expect_err("second request").to_string().contains("already posted"));
    let docs: i64 = sqlx::query_scalar(
        "select count(*) from atomic_source_documents where tenant_id = $1 and source_action = 'ISSUE' and action_no = 'act-o01b'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("documents");
    assert_eq!(docs, 1);
    let moves: i64 = sqlx::query_scalar(
        "select count(*) from mfg_material_moves where tenant_id = $1 and work_order_id = $2 and reason = 'act-o01b'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(pool)
    .await
    .expect("moves");
    assert_eq!(moves, 1);
    let issued: i64 = sqlx::query_scalar(
        "select issued_micros from mfg_work_orders where tenant_id = $1 and work_order_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(pool)
    .await
    .expect("issued");
    assert_eq!(issued, 1_000_000);
    let events: (i64, String) = sqlx::query_as(
        "select amount_cent, posting_status from atomic_posting_events where tenant_id = $1 and action_no = 'act-o01b'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("event");
    assert_eq!(events, (2_500, "PENDING_POSTING".to_string()));
    let on_hand: i64 = sqlx::query_scalar(
        "select on_hand from inventory_balances where tenant_id = $1 and warehouse_id = $2 and sku_id = $3",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(warehouse)
    .bind(sku)
    .fetch_one(pool)
    .await
    .expect("balance");
    let move_id: String = sqlx::query_scalar(
        "select move_id::text from mfg_material_moves where tenant_id = $1 and reason = 'act-o01b'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("move");
    let ledger: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_on_hand), 0)::bigint from inventory_ledgers where tenant_id = $1 and reason_type = 'MFG_ISSUE' and ref_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(move_id)
    .fetch_one(pool)
    .await
    .expect("ledger");
    assert_eq!(ledger, -1);
    assert_eq!(on_hand, 1);
}

async fn lookup_cited_lost_command(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let (opened, session_id, _) = repo
        .open_browser_session(
            tenant, "o02b-session", "o02b-session", "user-o02b", "BEARER", false, false, "", "",
        )
        .await
        .expect("session")
        .expect("admit session");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    let missing = repo
        .open_command(tenant, "o02b-empty", "o02b-empty", "LEDGER", "", 1)
        .await;
    assert!(missing.expect_err("empty").to_string().contains("required"));
    let accepted = repo
        .open_command(tenant, "o02b-lost", "o02b-lost", "LEDGER", "ledger-o02b", 2)
        .await
        .expect("open")
        .expect("admit open");
    assert!(matches!(accepted, SharedWrite::Stored(_)));
    let accepted_status: String = sqlx::query_scalar(
        "select status from command_receipts where tenant_id = $1 and request_id = 'o02b-lost'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("accepted status");
    assert_eq!(accepted_status, "ACCEPTED");
    let unknown = repo
        .lookup_lost_command(
            tenant, "o02b-lost", "o02b-lost", "user-o02b", session_id, session_id, true, warehouse, sku, 1,
        )
        .await;
    assert!(unknown.expect_err("same session").to_string().contains("new session"));
    let revoked = repo
        .revoke_browser_session(tenant, "o02b-revoke", "o02b-revoke", session_id)
        .await
        .expect("revoke")
        .expect("admit revoke");
    assert!(matches!(revoked, SharedWrite::Stored(_)));
    let (reopened, next_session, _) = repo
        .open_browser_session(
            tenant, "o02b-relogin", "o02b-relogin", "user-o02b", "BEARER", false, false, "", "",
        )
        .await
        .expect("reopen")
        .expect("admit reopen");
    assert!(matches!(reopened, SharedWrite::Stored(_)));
    let looked = repo
        .lookup_lost_command(
            tenant, "o02b-lost", "o02b-lost", "user-o02b", session_id, next_session, true, warehouse, sku, 1,
        )
        .await
        .expect("lookup")
        .expect("admit lookup");
    assert!(matches!(looked, SharedWrite::Replay(_)));
    let still_accepted: String = sqlx::query_scalar(
        "select status from command_receipts where tenant_id = $1 and request_id = 'o02b-lost'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("still accepted");
    assert_eq!(still_accepted, "ACCEPTED");
    let finished = repo
        .lookup_lost_command(
            tenant, "o02b-lost", "o02b-lost", "user-o02b", session_id, next_session, false, warehouse, sku, 1,
        )
        .await
        .expect("finish")
        .expect("admit finish");
    assert!(matches!(finished, SharedWrite::Stored(_)));
    let again = repo
        .lookup_lost_command(
            tenant, "o02b-lost", "o02b-lost", "user-o02b", session_id, next_session, false, warehouse, sku, 1,
        )
        .await
        .expect("again")
        .expect("keep stored");
    assert!(matches!(again, SharedWrite::Replay(_)));
    let ledgers: i64 = sqlx::query_scalar(
        "select count(*) from inventory_ledgers where tenant_id = $1 and ref_id = 'o02b-lost' and reason_type = 'COMMAND_LOOKUP'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("ledgers");
    assert_eq!(ledgers, 1);
    let (status, version, completed_after): (String, i64, bool) = sqlx::query_as(
        r#"
        select r.status, o.version_no, o.completed_at > o.accepted_at
        from command_objects o
        join command_receipts r on r.tenant_id = o.tenant_id and r.request_id = o.request_id
        where o.tenant_id = $1 and o.request_id = 'o02b-lost' and o.line_no = 1
        "#,
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(pool)
    .await
    .expect("times");
    assert_eq!(status, "SUCCEEDED");
    assert_eq!(version, 2);
    assert!(completed_after);
    let found = repo.read_command(tenant, "o02b-lost").await.expect("read").expect("row");
    assert_eq!(found.2, "SUCCEEDED");
    assert!(!found.5);
}

