    assert!(matches!(planned, SharedWrite::Stored(_)));
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'o03b', 'O03B')")
        .bind(warehouse)
        .bind(uuid::Uuid::from(tenant))
        .execute(pool)
        .await
        .expect("o03b warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-O03B')")
