async fn company_setting_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("company-setting-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("company-setting-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let save = |request: &'static str, currency: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/company-settings"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "company_name": "Mill A05F",
                            "numbering_rule": "SO-{seq}",
                            "currency": currency,
                            "timezone": "Asia/Shanghai",
                            "qty_precision": 6,
                            "buy_enabled": true,
                            "make_enabled": true,
                            "sell_enabled": true,
                            "default_warehouse": "WH-A05F",
                            "effective_at": "2026-10-03T00:00:00+08:00",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(save("a05f-a", "CNY"), save("a05f-b", "USD"));
    let settings: i64 = sqlx::query_scalar(
        "select count(*) from company_settings where tenant_id = $1 and effective_at = '2026-10-03T00:00:00+08:00'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("settings");
    assert_eq!(settings, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('a05f-a','a05f-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let stored: (String, i32, String) = sqlx::query_as(
        "select currency, version_no, default_warehouse from company_settings where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stored");
    assert!(
        stored == ("CNY".to_string(), 1, "WH-A05F".to_string())
            || stored == ("USD".to_string(), 1, "WH-A05F".to_string()),
        "stored={stored:?}"
    );
    let documents: i64 = sqlx::query_scalar(
        "select count(*) from company_documents where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("documents");
    assert_eq!(documents, 0);
}

