async fn support_feedback_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("support-feedback-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("support-feedback-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let open = |request: &'static str, document: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/support-feedback"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "feedback_no": "FB-A08G",
                            "request_ref": "req-a08g",
                            "feature_id": "A08",
                            "document_no": document,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(open("a08g-a", "SO-A08G-A"), open("a08g-b", "SO-A08G-B"));
    let feedback: i64 = sqlx::query_scalar(
        "select count(*) from support_feedback where tenant_id = $1 and feedback_no = 'FB-A08G'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("feedback");
    assert_eq!(feedback, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('a08g-a','a08g-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let document: String = sqlx::query_scalar(
        "select document_no from support_feedback where tenant_id = $1 and feedback_no = 'FB-A08G'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("document");
    assert!(document == "SO-A08G-A" || document == "SO-A08G-B", "document={document}");
    let tickets: i64 = sqlx::query_scalar(
        "select count(*) from support_ops_tickets where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("tickets");
    assert_eq!(tickets, 0);
}

#[test]
fn support_handling_http_race_read_back() {
    std::thread::Builder::new()
        .name("support-handling-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(support_handling_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("support handling http thread");
}

async fn support_handling_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("support-handling-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("support-handling-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/support-feedback"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "a08h-open",
                    "feedback_no": "FB-A08H",
                    "request_ref": "req-a08h",
                    "feature_id": "A08",
                    "document_no": "SO-A08H",
                })
                .to_string(),
            ))
            .expect("open request"),
    )
    .await
    .expect("open oneshot");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let handle = |request: &'static str, result: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/support-feedback/FB-A08H/handling"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "scope": "TENANT",
                            "reason": "failed save",
                            "handler": "ops-a08h",
                            "result": result,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(handle("a08h-a", "HANDLED"), handle("a08h-b", "OPEN"));
    let tickets: i64 = sqlx::query_scalar(
        "select count(*) from support_ops_tickets where tenant_id = $1 and feedback_no = 'FB-A08H'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("tickets");
    assert_eq!(tickets, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('a08h-a','a08h-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let stored: String = sqlx::query_scalar(
        "select result_text from support_ops_tickets where tenant_id = $1 and feedback_no = 'FB-A08H'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stored");
    assert!(stored == "HANDLED" || stored == "OPEN", "stored={stored}");
    let feedback: i64 = sqlx::query_scalar(
        "select count(*) from support_feedback where tenant_id = $1 and feedback_no = 'FB-A08H'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("feedback");
    assert_eq!(feedback, 1);
}

