async fn query_complete_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("query-complete-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("query-complete-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/query-generations"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "u03k-open",
                    "scope": "orders-u03k",
                    "generation": 1,
                    "digest": "status=open",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open oneshot");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let open_body = http_body_util::BodyExt::collect(opened.into_body())
        .await
        .expect("open body")
        .to_bytes();
    let open_json: serde_json::Value = serde_json::from_slice(&open_body).expect("open json");
    let query_id = open_json["effect_id"].as_str().expect("query effect").to_string();
    let complete = |request: &'static str, result: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        let query_id = query_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/query-generations/complete"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "query_id": query_id,
                            "result": result,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(complete("u03k-a", "page-a"), complete("u03k-b", "page-b"));
    let applied: i64 = sqlx::query_scalar(
        "select count(*) from query_generations where tenant_id = $1 and applied = true",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("applied");
    assert_eq!(applied, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('u03k-a','u03k-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let opened: i64 = sqlx::query_scalar(
        "select count(*) from query_generations where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("opened");
    assert_eq!(opened, 1);
}

