async fn file_delivery_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("file-delivery-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("file-delivery-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let save = |request: &'static str, rows: i64| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/file-deliveries"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "file_no": "FILE-U07C",
                            "rows": rows,
                            "bound": 1000,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(save("u07c-a", 100), save("u07c-b", 100000));
    let deliveries: i64 = sqlx::query_scalar(
        "select count(*) from file_deliveries where tenant_id = $1 and file_no = 'FILE-U07C'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("deliveries");
    assert_eq!(deliveries, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('u07c-a','u07c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let (rows, decision): (i64, String) = sqlx::query_as(
        "select row_count, decision from file_deliveries where tenant_id = $1 and file_no = 'FILE-U07C'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("row");
    assert!(
        (rows == 100 && decision == "DIRECT") || (rows == 100000 && decision == "BACKEND_TASK"),
        "rows={rows} decision={decision}"
    );
    let winner = if rows == 100 { "u07c-a" } else { "u07c-b" };
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id = $2",
    )
    .bind(tenant)
    .bind(winner)
    .fetch_one(&pool)
    .await
    .expect("effect");
    assert_eq!(effect, decision);
    let cells: i64 = sqlx::query_scalar(
        "select count(*) from file_cells where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("cells");
    assert_eq!(cells, 0);
    let jobs: i64 = sqlx::query_scalar(
        "select count(*) from device_print_jobs where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("jobs");
    assert_eq!(jobs, 0);
}

