async fn item_identity_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("item-identity-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("item-identity-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/shared-items"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "d01d-item",
                    "item_code": "ITEM-D01D",
                    "name": "销钉",
                    "spec": "M6",
                    "category": "fastener",
                    "barcode": "6900004",
                    "buy": true,
                    "make": true,
                    "sell": true,
                })
                .to_string(),
            ))
            .expect("item request"),
    )
    .await
    .expect("item oneshot");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_body = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("item body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_body).expect("item json");
    let item_id = saved_json["effect_id"].as_str().expect("item effect").to_string();
    let bind = |request: &'static str, sku: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        let item_id = item_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/item-identities"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "item_id": item_id,
                            "product_code": "P-D01D",
                            "sku_code": sku,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(bind("d01d-a", "SKU-A"), bind("d01d-b", "SKU-B"));
    let products: i64 = sqlx::query_scalar(
        "select count(*) from item_products where tenant_id = $1 and item_id = $2 and product_code = 'P-D01D'",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&item_id).expect("item uuid"))
    .fetch_one(&pool)
    .await
    .expect("products");
    assert_eq!(products, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d01d-a','d01d-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let product_id: uuid::Uuid = sqlx::query_scalar(
        "select product_id from item_products where tenant_id = $1 and product_code = 'P-D01D'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("product");
    let sku_code: String = sqlx::query_scalar(
        "select sku_code from item_skus where tenant_id = $1 and product_id = $2",
    )
    .bind(tenant)
    .bind(product_id)
    .fetch_one(&pool)
    .await
    .expect("sku");
    assert!(sku_code == "SKU-A" || sku_code == "SKU-B", "sku={sku_code}");
    let winner = if sku_code == "SKU-A" { "d01d-a" } else { "d01d-b" };
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id = $2",
    )
    .bind(tenant)
    .bind(winner)
    .fetch_one(&pool)
    .await
    .expect("effect");
    let sku_id: uuid::Uuid = sqlx::query_scalar(
        "select sku_id from item_skus where tenant_id = $1 and product_id = $2",
    )
    .bind(tenant)
    .bind(product_id)
    .fetch_one(&pool)
    .await
    .expect("sku id");
    assert_eq!(effect, format!("{product_id}:{sku_id}"));
    let items: i64 = sqlx::query_scalar(
        "select count(*) from shared_items where tenant_id = $1 and item_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&item_id).expect("item uuid"))
    .fetch_one(&pool)
    .await
    .expect("items");
    assert_eq!(items, 1);
}

