async fn unit_conversion_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("unit-conversion-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("unit-conversion-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let save = |request: &'static str, aux: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/unit-conversions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "base_unit": "G",
                            "aux_unit": "KG",
                            "ratio_text": "1000",
                            "rounding_code": "HALF_UP",
                            "aux_text": aux,
                            "display_text": aux,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(save("d02a-a", "0.125"), save("d02a-b", "0.250"));
    let rows: i64 = sqlx::query_scalar(
        "select count(*) from unit_conversions where tenant_id = $1 and base_unit = 'G' and aux_unit = 'KG' and rounding_code = 'HALF_UP'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("rows");
    assert_eq!(rows, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d02a-a','d02a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let (aux_micros, base_micros): (i64, i64) = sqlx::query_as(
        "select aux_micros, base_micros from unit_conversions where tenant_id = $1 and base_unit = 'G' and aux_unit = 'KG'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("micros");
    assert!(
        (aux_micros == 125_000 && base_micros == 125_000_000)
            || (aux_micros == 250_000 && base_micros == 250_000_000),
        "aux={aux_micros} base={base_micros}"
    );
    let winner = if aux_micros == 125_000 { "d02a-a" } else { "d02a-b" };
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id = $2",
    )
    .bind(tenant)
    .bind(winner)
    .fetch_one(&pool)
    .await
    .expect("effect");
    assert_eq!(effect, base_micros.to_string());
    let samples: i64 = sqlx::query_scalar(
        "select count(*) from unit_qty_samples where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("samples");
    assert_eq!(samples, 0);
}

