async fn partner_merge_preview_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("partner-preview-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("partner-preview-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |path: &'static str, body: serde_json::Value| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/{path}"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (source_status, source_body) = post(
        "shared-partners",
        serde_json::json!({
            "request_id": "d03c-source",
            "name": "南厂",
            "customer": false,
            "supplier": true,
            "customer_no": "",
            "supplier_no": "S-D03C",
            "term_days": 10,
            "tax_no": "TAX-S",
        }),
    )
    .await;
    assert_eq!(source_status, axum::http::StatusCode::OK, "source={source_body}");
    let source_id = serde_json::from_str::<serde_json::Value>(&source_body)
        .expect("source json")["effect_id"]
        .as_str()
        .expect("source effect")
        .to_string();
    let (target_status, target_body) = post(
        "shared-partners",
        serde_json::json!({
            "request_id": "d03c-target",
            "name": "北厂",
            "customer": true,
            "supplier": true,
            "customer_no": "C-D03C",
            "supplier_no": "S-D03CT",
            "term_days": 30,
            "tax_no": "TAX-T",
        }),
    )
    .await;
    assert_eq!(target_status, axum::http::StatusCode::OK, "target={target_body}");
    let target_id = serde_json::from_str::<serde_json::Value>(&target_body)
        .expect("target json")["effect_id"]
        .as_str()
        .expect("target effect")
        .to_string();
    let (ref_status, ref_body) = post(
        "partner-refs",
        serde_json::json!({
            "request_id": "d03c-ref",
            "partner_id": source_id,
            "document_id": "PO-D03C",
            "document_date": "2026-09-15",
        }),
    )
    .await;
    assert_eq!(ref_status, axum::http::StatusCode::OK, "ref={ref_body}");
    let preview = |request: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        let source_id = source_id.clone();
        let target_id = target_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/partner-merge-previews"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "source_id": source_id,
                            "target_id": target_id,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(preview("d03c-a"), preview("d03c-b"));
    let previews: i64 = sqlx::query_scalar(
        "select count(*) from shared_partner_merge_previews where tenant_id = $1 and source_id = $2 and target_id = $3",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&source_id).expect("source uuid"))
    .bind(uuid::Uuid::parse_str(&target_id).expect("target uuid"))
    .fetch_one(&pool)
    .await
    .expect("previews");
    assert_eq!(previews, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d03c-a','d03c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let (preview_id, ref_count, decision): (uuid::Uuid, i64, String) = sqlx::query_as(
        "select preview_id, ref_count, decision from shared_partner_merge_previews where tenant_id = $1 and source_id = $2 and target_id = $3",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&source_id).expect("source uuid"))
    .bind(uuid::Uuid::parse_str(&target_id).expect("target uuid"))
    .fetch_one(&pool)
    .await
    .expect("preview row");
    assert_eq!(ref_count, 1);
    assert_eq!(decision, "PREVIEW");
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id in ('d03c-a','d03c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("effect");
    assert_eq!(effect, "1");
    let still_source: uuid::Uuid = sqlx::query_scalar(
        "select partner_id from shared_partner_refs where tenant_id = $1 and document_id = 'PO-D03C'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("still source");
    assert_eq!(still_source.to_string(), source_id);
    let source_status_text: String = sqlx::query_scalar(
        "select status from shared_partners where tenant_id = $1 and partner_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&source_id).expect("source uuid"))
    .fetch_one(&pool)
    .await
    .expect("source status");
    assert_eq!(source_status_text, "ACTIVE");
    let merges: i64 = sqlx::query_scalar(
        "select count(*) from shared_partner_merges where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("merges");
    assert_eq!(merges, 0);
    assert_ne!(preview_id.to_string(), target_id);
    let loser_count: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d03c-a','d03c-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both requests");
    assert_eq!(loser_count, 1, "first={first:?} second={second:?}");
}

