async fn location_move_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("location-move-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("location-move-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |path: &'static str, body: serde_json::Value| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/{path}"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (warehouse_status, warehouse_body) = post(
        "shared-locations",
        serde_json::json!({
            "request_id": "d04d-warehouse",
            "code": "WH-D04D",
            "purpose": "FINISHED",
            "is_default": true,
        }),
    )
    .await;
    assert_eq!(warehouse_status, axum::http::StatusCode::OK, "warehouse={warehouse_body}");
    let warehouse_id = serde_json::from_str::<serde_json::Value>(&warehouse_body)
        .expect("warehouse json")["effect_id"]
        .as_str()
        .expect("warehouse effect")
        .to_string();
    let (area_status, area_body) = post(
        "shared-locations",
        serde_json::json!({
            "request_id": "d04d-area",
            "parent_id": warehouse_id,
            "code": "A-D04D",
            "purpose": "RAW",
            "is_default": false,
        }),
    )
    .await;
    assert_eq!(area_status, axum::http::StatusCode::OK, "area={area_body}");
    let area_id = serde_json::from_str::<serde_json::Value>(&area_body)
        .expect("area json")["effect_id"]
        .as_str()
        .expect("area effect")
        .to_string();
    let (bin_status, bin_body) = post(
        "shared-locations",
        serde_json::json!({
            "request_id": "d04d-bin",
            "parent_id": area_id,
            "code": "B-D04D",
            "purpose": "WIP",
            "is_default": false,
        }),
    )
    .await;
    assert_eq!(bin_status, axum::http::StatusCode::OK, "bin={bin_body}");
    let bin_id = serde_json::from_str::<serde_json::Value>(&bin_body)
        .expect("bin json")["effect_id"]
        .as_str()
        .expect("bin effect")
        .to_string();
    let sku_id = uuid::Uuid::new_v4();
    let (stock_status, stock_body) = post(
        "location-stock",
        serde_json::json!({
            "request_id": "d04d-stock",
            "location_id": bin_id,
            "sku_id": sku_id,
            "on_hand": 1_250_000,
            "owner_code": "OWN",
        }),
    )
    .await;
    assert_eq!(stock_status, axum::http::StatusCode::OK, "stock={stock_body}");
    let move_to = |request: &'static str, parent: String| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        let bin_id = bin_id.clone();
        let sku = sku_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/location-moves"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "location_id": bin_id,
                            "parent_id": parent,
                            "sku_id": sku,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        move_to("d04d-a", warehouse_id.clone()),
        move_to("d04d-b", area_id.clone())
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d04d-a','d04d-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let parent: uuid::Uuid = sqlx::query_scalar(
        "select parent_id from shared_locations where tenant_id = $1 and location_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&bin_id).expect("bin uuid"))
    .fetch_one(&pool)
    .await
    .expect("parent");
    let winner = if parent.to_string() == warehouse_id {
        "d04d-a"
    } else if parent.to_string() == area_id {
        "d04d-b"
    } else {
        panic!("unexpected parent={parent}");
    };
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id = $2 and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .bind(winner)
    .fetch_one(&pool)
    .await
    .expect("effect");
    assert_eq!(effect, "KEPT");
    let (on_hand, owner): (i64, String) = sqlx::query_as(
        "select s.on_hand, o.owner_code from shared_location_stock s
         join shared_location_owners o
           on o.tenant_id = s.tenant_id and o.location_id = s.location_id and o.sku_id = s.sku_id
         where s.tenant_id = $1 and s.location_id = $2 and s.sku_id = $3",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&bin_id).expect("bin uuid"))
    .bind(sku_id)
    .fetch_one(&pool)
    .await
    .expect("stock row");
    assert_eq!(on_hand, 1_250_000);
    assert_eq!(owner, "OWN");
    let stock_rows: i64 = sqlx::query_scalar(
        "select count(*) from shared_location_stock where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stock rows");
    assert_eq!(stock_rows, 1);
    let transfers: i64 = sqlx::query_scalar(
        "select count(*) from shared_location_transfers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("transfers");
    assert_eq!(transfers, 0);
    let code: String = sqlx::query_scalar(
        "select code from shared_locations where tenant_id = $1 and location_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&bin_id).expect("bin uuid"))
    .fetch_one(&pool)
    .await
    .expect("code");
    assert_eq!(code, "B-D04D");
    let loser = if winner == "d04d-a" { "d04d-b" } else { "d04d-a" };
    let loser_receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = $2",
    )
    .bind(tenant)
    .bind(loser)
    .fetch_one(&pool)
    .await
    .expect("loser");
    assert_eq!(loser_receipts, 0, "loser={loser} first={first:?} second={second:?}");
}

