async fn shared_employee_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("shared-employee-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("shared-employee-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let save = |request: &'static str, user_id: &'static str, department: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/shared-employees"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "employee_code": "E-D05A",
                            "user_id": user_id,
                            "department": department,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        save("d05a-a", "user-a", "装配"),
        save("d05a-b", "user-b", "机加")
    );
    let employees: i64 = sqlx::query_scalar(
        "select count(*) from shared_employees where tenant_id = $1 and employee_code = 'E-D05A'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("employees");
    assert_eq!(employees, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d05a-a','d05a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let (employee_id, user_id, department, status): (uuid::Uuid, String, String, String) =
        sqlx::query_as(
            "select employee_id, user_id, department, status from shared_employees where tenant_id = $1 and employee_code = 'E-D05A'",
        )
        .bind(tenant)
        .fetch_one(&pool)
        .await
        .expect("employee");
    let winner = if user_id == "user-a" && department == "装配" {
        "d05a-a"
    } else if user_id == "user-b" && department == "机加" {
        "d05a-b"
    } else {
        panic!("unexpected employee user={user_id} department={department}");
    };
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id = $2 and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .bind(winner)
    .fetch_one(&pool)
    .await
    .expect("effect");
    assert_eq!(effect, employee_id.to_string());
    assert_eq!(status, "ACTIVE");
    assert_ne!(employee_id.to_string(), "E-D05A");
    assert_ne!(user_id, "E-D05A");
    let seats: i64 = sqlx::query_scalar(
        "select count(*) from member_seats where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("seats");
    assert_eq!(seats, 0);
    let loser = if winner == "d05a-a" { "d05a-b" } else { "d05a-a" };
    let loser_receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = $2",
    )
    .bind(tenant)
    .bind(loser)
    .fetch_one(&pool)
    .await
    .expect("loser");
    assert_eq!(loser_receipts, 0, "loser={loser} first={first:?} second={second:?}");
    let reports: i64 = sqlx::query_scalar(
        "select count(*) from shared_labor_reports where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("reports");
    assert_eq!(reports, 0);
}

