async fn opening_confirm_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("opening-confirm-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("opening-confirm-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let save = |request: &'static str, qty: i64, cost: i64, partner: i64| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/opening-confirms"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "cutoff_date": "2026-10-01",
                            "qty_micros": qty,
                            "cost_cent": cost,
                            "partner_cent": partner,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        save("d07a-a", 1_250_000, 800, 300),
        save("d07a-b", 2_000_000, 900, -400)
    );
    let documents: i64 = sqlx::query_scalar(
        "select count(*) from opening_documents where tenant_id = $1 and status = 'CONFIRMED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("documents");
    assert_eq!(documents, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d07a-a','d07a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let qty_rows: i64 = sqlx::query_scalar(
        "select count(*) from opening_qty_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("qty");
    assert_eq!(qty_rows, 1, "first={first:?} second={second:?}");
    let (cutoff, version_no): (String, i32) = sqlx::query_as(
        "select cutoff_date, version_no from opening_documents where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("document");
    assert_eq!(cutoff, "2026-10-01");
    assert_eq!(version_no, 1);
    let qty: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from opening_qty_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("qty sum");
    let cost: i64 = sqlx::query_scalar(
        "select coalesce(sum(amount_cent), 0)::bigint from opening_cost_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("cost sum");
    let partner: i64 = sqlx::query_scalar(
        "select coalesce(sum(amount_cent), 0)::bigint from partner_balances where tenant_id = $1 and source_type = 'OPENING'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("partner sum");
    let winner = if first.0 == axum::http::StatusCode::OK { "d07a-a" } else { "d07a-b" };
    if winner == "d07a-a" {
        assert_eq!((qty, cost, partner), (1_250_000, 800, 300));
    } else {
        assert_eq!((qty, cost, partner), (2_000_000, 900, -400));
    }
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id in ('d07a-a','d07a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("effect");
    let opening_id: uuid::Uuid = sqlx::query_scalar(
        "select opening_id from opening_documents where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("opening");
    assert_eq!(effect, opening_id.to_string());
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d07a-a','d07a-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

