async fn opening_correct_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("opening-correct-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("opening-correct-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let confirm = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/opening-confirms"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "d07d-confirm",
                    "cutoff_date": "2026-10-01",
                    "qty_micros": 2_000_000,
                    "cost_cent": 1000,
                    "partner_cent": 500,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(confirm.status(), axum::http::StatusCode::OK);
    let confirm_body = http_body_util::BodyExt::collect(confirm.into_body())
        .await
        .expect("body")
        .to_bytes();
    let opening_id = serde_json::from_slice::<serde_json::Value>(&confirm_body)
        .expect("confirm json")["effect_id"]
        .as_str()
        .expect("effect")
        .to_string();
    let save = |request: &'static str, qty: i64, cost: i64, partner: i64| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        let opening_id = opening_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/opening-corrections"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "opening_id": opening_id,
                            "qty_delta": qty,
                            "cost_delta": cost,
                            "partner_delta": partner,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        save("d07d-a", -200_000, -100, -50),
        save("d07d-b", -400_000, -200, -80)
    );
    let documents: i64 = sqlx::query_scalar(
        "select count(*) from opening_documents where tenant_id = $1 and opening_id = $2 and status = 'ADJUSTED'",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&opening_id).expect("opening uuid"))
    .fetch_one(&pool)
    .await
    .expect("documents");
    assert_eq!(documents, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d07d-a','d07d-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let qty_rows: i64 = sqlx::query_scalar(
        "select count(*) from opening_qty_ledgers where tenant_id = $1 and opening_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&opening_id).expect("opening uuid"))
    .fetch_one(&pool)
    .await
    .expect("qty rows");
    assert_eq!(qty_rows, 2, "first={first:?} second={second:?}");
    let original: i64 = sqlx::query_scalar(
        "select count(*) from opening_qty_ledgers where tenant_id = $1 and opening_id = $2 and delta_micros = 2000000",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&opening_id).expect("opening uuid"))
    .fetch_one(&pool)
    .await
    .expect("original");
    assert_eq!(original, 1, "first={first:?} second={second:?}");
    let qty: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from opening_qty_ledgers where tenant_id = $1 and opening_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&opening_id).expect("opening uuid"))
    .fetch_one(&pool)
    .await
    .expect("qty sum");
    let cost: i64 = sqlx::query_scalar(
        "select coalesce(sum(amount_cent), 0)::bigint from opening_cost_ledgers where tenant_id = $1 and opening_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&opening_id).expect("opening uuid"))
    .fetch_one(&pool)
    .await
    .expect("cost sum");
    let partner: i64 = sqlx::query_scalar(
        "select coalesce(sum(amount_cent), 0)::bigint from partner_balances where tenant_id = $1 and source_type = 'OPENING' and source_id = $2",
    )
    .bind(tenant)
    .bind(&opening_id)
    .fetch_one(&pool)
    .await
    .expect("partner sum");
    let winner = if first.0 == axum::http::StatusCode::OK { "d07d-a" } else { "d07d-b" };
    if winner == "d07d-a" {
        assert_eq!((qty, cost, partner), (1_800_000, 900, 450));
    } else {
        assert_eq!((qty, cost, partner), (1_600_000, 800, 420));
    }
    let version_no: i32 = sqlx::query_scalar(
        "select version_no from opening_documents where tenant_id = $1 and opening_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&opening_id).expect("opening uuid"))
    .fetch_one(&pool)
    .await
    .expect("version");
    assert_eq!(version_no, 2);
    let effect: String = sqlx::query_scalar(
        "select effect_id from command_receipts where tenant_id = $1 and request_id in ('d07d-a','d07d-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("effect");
    assert_eq!(effect, format!("{qty},{cost},{partner}"));
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d07d-a','d07d-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

#[test]
fn shared_attachment_http_race_read_back() {
    std::thread::Builder::new()
        .name("shared-attachment-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(shared_attachment_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("shared attachment http thread");
}

async fn shared_attachment_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("shared-attachment-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("shared-attachment-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let save = |request: &'static str, digest: &'static str, bytes: i64, actor: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/shared-attachments"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "object_id": "ITEM-D08A",
                            "file_name": "drawing.pdf",
                            "digest": digest,
                            "byte_count": bytes,
                            "actor_user_id": actor,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let body = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&body).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        save("d08a-a", "digest-a", 1024, "actor-a"),
        save("d08a-b", "digest-b", 2048, "actor-b")
    );
    assert_eq!(first.0, axum::http::StatusCode::OK, "first={first:?} second={second:?}");
    assert_eq!(second.0, axum::http::StatusCode::OK, "first={first:?} second={second:?}");
    let attachments: i64 = sqlx::query_scalar(
        "select count(*) from shared_attachments where tenant_id = $1 and object_id = 'ITEM-D08A' and file_name = 'drawing.pdf'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("attachments");
    assert_eq!(attachments, 2, "first={first:?} second={second:?}");
    let versions: Vec<i32> = sqlx::query_scalar(
        "select version_no from shared_attachments where tenant_id = $1 and object_id = 'ITEM-D08A' and file_name = 'drawing.pdf' order by version_no",
    )
    .bind(tenant)
    .fetch_all(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, vec![1, 2], "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('d08a-a','d08a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 2, "first={first:?} second={second:?}");
    let keys: Vec<(uuid::Uuid, String)> = sqlx::query_as(
        "select attachment_id, storage_key from shared_attachments where tenant_id = $1 and object_id = 'ITEM-D08A'",
    )
    .bind(tenant)
    .fetch_all(&pool)
    .await
    .expect("keys");
    assert_eq!(keys.len(), 2);
    for (attachment_id, storage_key) in &keys {
        assert_eq!(storage_key, &format!("{tenant}/ITEM-D08A/{attachment_id}"));
    }
    let grants: i64 = sqlx::query_scalar(
        "select count(*) from shared_attachment_grants where tenant_id = $1 and revoked = false",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("grants");
    assert_eq!(grants, 2, "first={first:?} second={second:?}");
    let cites: i64 = sqlx::query_scalar(
        "select count(*) from shared_attachment_cites where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("cites");
    assert_eq!(cites, 0);
    let same_version: i64 = sqlx::query_scalar(
        "select count(*) from (select version_no from shared_attachments where tenant_id = $1 and object_id = 'ITEM-D08A' and file_name = 'drawing.pdf' group by version_no having count(*) > 1) duplicated",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("same version");
    assert_eq!(same_version, 0, "first={first:?} second={second:?}");
}

