async fn count_confirm_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("count-confirm-http-tenant {tenant:?}");
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("count-confirm-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let posted = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/stock-ledgers"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "i03d-on-hand",
                    "warehouse_id": warehouse,
                    "location_id": location,
                    "sku_id": sku,
                    "batch_code": "B-I03D",
                    "quality_status": "GOOD",
                    "bucket": "ON_HAND",
                    "delta_micros": 1_000_000,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(posted.status(), axum::http::StatusCode::OK);
    let cutoff = "2026-10-03T23:59:59Z";
    let save = |request: &'static str, counted: i64| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/count-confirmations"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "warehouse_id": warehouse,
                            "location_id": location,
                            "sku_id": sku,
                            "batch_code": "B-I03D",
                            "cutoff_at": cutoff,
                            "counted_qty": counted,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(save("i03d-a", 900_000), save("i03d-b", 700_000));
    let sheets: i64 = sqlx::query_scalar(
        "select count(*) from shared_count_sheets where tenant_id = $1 and cutoff_at = $2",
    )
    .bind(tenant)
    .bind(cutoff)
    .fetch_one(&pool)
    .await
    .expect("sheets");
    assert_eq!(sheets, 1, "first={first:?} second={second:?}");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('i03d-a','i03d-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let adjustment: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from shared_stock_ledgers where tenant_id = $1 and sku_id = $2 and request_id in ('i03d-a','i03d-b')",
    )
    .bind(tenant)
    .bind(sku)
    .fetch_one(&pool)
    .await
    .expect("adjustment");
    let winner = if first.0 == axum::http::StatusCode::OK { "i03d-a" } else { "i03d-b" };
    if winner == "i03d-a" {
        assert_eq!(adjustment, -100_000, "first={first:?} second={second:?}");
    } else {
        assert_eq!(adjustment, -300_000, "first={first:?} second={second:?}");
    }
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('i03d-a','i03d-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

