async fn purchase_revision_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("purchase-revision-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("purchase-revision-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let order_id = uuid::Uuid::new_v4();
    let revise = |request: &'static str, due_date: &'static str, qty: i64| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/purchase-revisions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "po_id": order_id,
                            "supplier_code": "S-T01H",
                            "warehouse_code": "WH-T01H",
                            "action": "OPEN",
                            "lines": [{
                                "line_no": 1,
                                "item_code": "ITEM-T01H",
                                "qty_micros": qty,
                                "price_cent": 2000,
                                "tax_cent": 260,
                                "due_date": due_date,
                            }],
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        revise("t01h-a", "2026-10-15", 10_000_000),
        revise("t01h-b", "2026-10-20", 8_000_000)
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t01h-a','t01h-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let versions: i64 = sqlx::query_scalar(
        "select count(*) from shared_purchase_revisions where tenant_id = $1 and po_id = $2",
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, 1, "two first opens of one purchase store one snapshot: first={first:?} second={second:?}");
    let snapshot: (i32, String, i64, String) = sqlx::query_as(
        r#"
        select revision.version_no, revision.status, line.qty_micros, line.due_date
        from shared_purchase_revisions revision
        join shared_purchase_lines line
          on line.tenant_id = revision.tenant_id and line.revision_id = revision.revision_id
        where revision.tenant_id = $1 and revision.po_id = $2
        "#,
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("snapshot");
    assert_eq!(snapshot.0, 1, "the kept snapshot is version 1");
    assert_eq!(snapshot.1, "OPEN");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t01h-a','t01h-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
    let _ = snapshot;
}

