async fn purchase_close_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("purchase-close-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("purchase-close-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db.clone(), std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/purchase-revisions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t01i-open",
                    "supplier_code": "S-T01I",
                    "warehouse_code": "WH-T01I",
                    "action": "OPEN",
                    "lines": [{
                        "line_no": 1,
                        "item_code": "ITEM-T01I",
                        "qty_micros": 10_000_000,
                        "price_cent": 2000,
                        "tax_cent": 260,
                        "due_date": "2026-10-15",
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let order_id: uuid::Uuid = sqlx::query_scalar(
        "select po_id from shared_purchase_revisions where tenant_id = $1 and version_no = 1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("opened order");
    let received = SharedContractRepo::new(db.pool())
        .receive_purchase_line(TenantId(tenant), "t01i-rcv", "t01i-rcv", order_id, 1, 10_000_000)
        .await
        .expect("receive")
        .expect("admit receive");
    assert_eq!(received.1, 0, "the source line is fully received before close");
    let close = |request: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/purchase-closes"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "po_id": order_id,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(close("t01i-a"), close("t01i-b"));
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t01i-a','t01i-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let versions: (i64, i64) = sqlx::query_as(
        "select count(*), count(*) filter (where status = 'CLOSED') from shared_purchase_revisions where tenant_id = $1 and po_id = $2",
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, (2, 1), "the open snapshot stays and only one close is stored");
    let open_status: String = sqlx::query_scalar(
        "select status from shared_purchase_revisions where tenant_id = $1 and po_id = $2 and version_no = 1",
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("open status");
    assert_eq!(open_status, "OPEN", "closing must not overwrite the open snapshot");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t01i-a','t01i-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

