async fn purchase_return_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("purchase-return-http-tenant {tenant:?}");
    let supplier = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let actor = shared_contract_receipt_actor::actor(&pool, TenantId(tenant), warehouse)
        .await.expect("actual owned receipt actor");
    let jwt = std::sync::Arc::new(erp_api::JwtService::new("purchase-return-http-test".to_string()));
    let state = erp_api::AppState::new(db, std::sync::Arc::clone(&jwt));
    let app = erp_api::build_app(state);
    let token = shared_contract_receipt_actor::http_token(&app, &jwt, actor)
        .await.expect("actual receipt password login");
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/purchase-revisions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t02k-open",
                    "supplier_code": "S-T02K",
                    "warehouse_code": "WH-T02K",
                    "action": "OPEN",
                    "lines": [{
                        "line_no": 1,
                        "item_code": "ITEM-T02K",
                        "qty_micros": 10_000_000,
                        "price_cent": 1500,
                        "tax_cent": 195,
                        "due_date": "2026-10-18",
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let order_id: uuid::Uuid = sqlx::query_scalar(
        "select po_id from shared_purchase_revisions where tenant_id = $1 and version_no = 1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("opened order");
    let arrived = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/purchase-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t02k-arrive",
                    "supplier_id": supplier,
                    "warehouse_id": warehouse,
                    "po_id": order_id,
                    "line_no": 1,
                    "arrival_qty": 6_000_000,
                    "location_id": location,
                    "batch_code": "LOT-T02K",
                    "unit_cost_cent": 1500,
                    "items": [{
                        "sku_id": sku,
                        "qty": 6,
                        "price_cent": 1500,
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(arrived.status(), axum::http::StatusCode::OK);
    let quality_id: uuid::Uuid = sqlx::query_scalar(
        "select quality_id from shared_receipt_quality where tenant_id = $1 and po_id = $2",
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("quality");
    let released = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/purchase-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t02k-release",
                    "supplier_id": supplier,
                    "warehouse_id": warehouse,
                    "quality_id": quality_id,
                    "release_qty": 6_000_000,
                    "items": [{
                        "sku_id": sku,
                        "qty": 6,
                        "price_cent": 1500,
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(released.status(), axum::http::StatusCode::OK);
    let send_back = |request: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/purchase-orders"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "supplier_id": supplier,
                            "warehouse_id": warehouse,
                            "quality_id": quality_id,
                            "return_qty": 4_000_000,
                            "items": [{
                                "sku_id": sku,
                                "qty": 4,
                                "price_cent": 1500,
                            }],
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(send_back("t02k-a"), send_back("t02k-b"));
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t02k-a','t02k-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let receipt_id: uuid::Uuid = sqlx::query_scalar(
        "select receipt_id from shared_receipt_quality where tenant_id = $1 and quality_id = $2",
    )
    .bind(tenant)
    .bind(quality_id)
    .fetch_one(&pool)
    .await
    .expect("receipt");
    let returned: i64 = sqlx::query_scalar(
        "select coalesce(sum(qty_micros), 0)::bigint from shared_supplier_returns where tenant_id = $1 and receipt_id = $2",
    )
    .bind(tenant)
    .bind(receipt_id)
    .fetch_one(&pool)
    .await
    .expect("returned");
    assert_eq!(returned, 4_000_000, "the second return must not exceed the released quantity");
    let on_hand: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from shared_stock_ledgers where tenant_id = $1 and bucket = 'ON_HAND'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("on hand");
    assert_eq!(on_hand, 2_000_000, "usable stock must keep the unreturned remainder");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t02k-a','t02k-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

