async fn sales_delivery_plan_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("sales-delivery-plan-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("sales-delivery-plan-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            uuid::Uuid::new_v4().to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let order_id = uuid::Uuid::new_v4();
    let submitted = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/sales-revisions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t04a-open",
                    "so_id": order_id,
                    "customer_code": "C-T04A",
                    "action": "SUBMIT",
                    "lines": [{
                        "line_no": 1,
                        "item_code": "ITEM-T04A",
                        "qty_micros": 10_000_000,
                        "price_cent": 2500,
                        "discount_cent": 0,
                        "tax_cent": 325,
                        "due_date": "2026-10-22",
                        "address": "dock-4",
                        "source": "RESALE",
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(submitted.status(), axum::http::StatusCode::OK);
    let fulfilling = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/sales-revisions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t04a-fulfill",
                    "so_id": order_id,
                    "customer_code": "C-T04A",
                    "expected_version": 1,
                    "action": "FULFILL",
                    "lines": [{
                        "line_no": 1,
                        "item_code": "ITEM-T04A",
                        "qty_micros": 10_000_000,
                        "price_cent": 2500,
                        "discount_cent": 0,
                        "tax_cent": 325,
                        "due_date": "2026-10-22",
                        "address": "dock-4",
                        "source": "RESALE",
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("oneshot");
    assert_eq!(fulfilling.status(), axum::http::StatusCode::OK);
    let plan = |request: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/sales-orders/{order_id}/deliveries"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "line_no": 1,
                            "expected_version": 2,
                            "qty_micros": 6_000_000,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(plan("t04a-a"), plan("t04a-b"));
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t04a-a','t04a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let planned: i64 = sqlx::query_scalar(
        "select coalesce(sum(qty_micros), 0)::bigint from shared_sales_deliveries where tenant_id = $1 and so_id = $2",
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("planned");
    assert_eq!(planned, 6_000_000, "the second plan must not exceed the sales line");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t04a-a','t04a-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

