fn sales_return_cash_http_race_read_back() {
    std::thread::Builder::new()
        .name("sales-return-cash-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(sales_return_cash_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("sales return cash http thread");
}

