async fn document_action_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("document-action-http-tenant {tenant:?}");
    let document_id = uuid::Uuid::new_v4();
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("document-action-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, request: &'static str, action: &'static str, expected: Option<i32>| {
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/sales-orders/{document_id}/actions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": action,
                            "actor_user_id": actor,
                            "has_downstream": false,
                            "expected_version": expected,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let drafted = post(app.clone(), "t06a-draft", "DRAFT", None).await;
    assert_eq!(drafted.0, axum::http::StatusCode::OK, "{drafted:?}");
    let submitted = post(app.clone(), "t06a-submit", "SUBMIT", Some(1)).await;
    assert_eq!(submitted.0, axum::http::StatusCode::OK, "{submitted:?}");
    let (first, second) = tokio::join!(
        post(app.clone(), "t06a-a", "REVISE", Some(2)),
        post(app.clone(), "t06a-b", "REVISE", Some(2)),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t06a-a','t06a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let versions: (i64, i64) = sqlx::query_as(
        "select count(*), count(*) filter (where version_no = 3) from shared_document_actions where tenant_id = $1 and document_id = $2",
    )
    .bind(tenant)
    .bind(document_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, (3, 1), "one revise of version 2 stores one version 3");
    let stock_rows: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(stock_rows, 0, "document history must not write stock");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t06a-a','t06a-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

#[test]
fn document_print_http_race_read_back() {
    std::thread::Builder::new()
        .name("document-print-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(document_print_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("document print http thread");
}

