async fn document_reprint_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("document-reprint-http-tenant {tenant:?}");
    let document_id = uuid::Uuid::new_v4();
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("document-reprint-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let action = |app: axum::Router, request: &'static str, name: &'static str, expected: Option<i32>| {
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/sales-orders/{document_id}/actions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": name,
                            "actor_user_id": actor,
                            "has_downstream": false,
                            "expected_version": expected,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            assert_eq!(response.status(), axum::http::StatusCode::OK, "{request}");
        }
    };
    action(app.clone(), "t07b-draft", "DRAFT", None).await;
    action(app.clone(), "t07b-submit", "SUBMIT", Some(1)).await;
    let printed = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/print-jobs"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "job_type": "SALES",
                    "ref_type": "SALES",
                    "ref_id": document_id,
                    "request_id": "t07b-print",
                    "document_kind": "SALES",
                    "company_name": "易格",
                    "print_lines": [{
                        "line_no": 1,
                        "item_code": "ITEM-T07B",
                        "qty_micros": 2_000_000,
                        "amount_cent": 2_000,
                        "tax_cent": 260,
                        "discount_cent": 100
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("print");
    assert_eq!(printed.status(), axum::http::StatusCode::OK);
    let print_bytes = http_body_util::BodyExt::collect(printed.into_body())
        .await
        .expect("print body")
        .to_bytes();
    let print_json: serde_json::Value = serde_json::from_slice(&print_bytes).expect("print json");
    let print_id = print_json["print_id"].as_str().expect("print id").to_string();
    assert_eq!(print_json["total_cent"], 2_160);
    let reprint = |app: axum::Router, request: &'static str, reason: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let print_id = print_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/print-jobs"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "job_type": "SALES",
                            "ref_type": "SALES",
                            "ref_id": document_id,
                            "request_id": request,
                            "print_id": print_id,
                            "reason": reason,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        reprint(app.clone(), "t07b-a", "smear"),
        reprint(app.clone(), "t07b-b", "copy"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t07b-a','t07b-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let reprints: i64 = sqlx::query_scalar(
        "select count(*) from shared_document_reprints where tenant_id = $1 and print_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&print_id).expect("print uuid"))
    .fetch_one(&pool)
    .await
    .expect("reprints");
    assert_eq!(reprints, 1, "one snapshot stores one reprint");
    let frozen: (i32, i64, String) = sqlx::query_as(
        "select version_no, total_cent, company_name from shared_document_prints where tenant_id = $1 and print_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&print_id).expect("print uuid"))
    .fetch_one(&pool)
    .await
    .expect("frozen");
    assert_eq!(frozen, (2, 2_160, "易格".to_string()), "reprint must not rewrite the snapshot");
    let prints: i64 = sqlx::query_scalar(
        "select count(*) from shared_document_prints where tenant_id = $1 and document_id = $2",
    )
    .bind(tenant)
    .bind(document_id)
    .fetch_one(&pool)
    .await
    .expect("prints");
    assert_eq!(prints, 1, "reprint must not store a second print");
    let status: String = sqlx::query_scalar(
        "select status_after from shared_document_actions where tenant_id = $1 and document_id = $2 order by version_no desc limit 1",
    )
    .bind(tenant)
    .bind(document_id)
    .fetch_one(&pool)
    .await
    .expect("status");
    assert_eq!(status, "SUBMITTED", "reprint must not change the document status");
    let stock_rows: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(stock_rows, 0, "reprint must not move stock");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t07b-a','t07b-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

