async fn quote_convert_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("quote-convert-http-tenant {tenant:?}");
    let quote_id = uuid::Uuid::new_v4();
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("quote-convert-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/marketing/quotes"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t08b-open",
                    "quote_id": quote_id,
                    "partner_code": "C-T08B",
                    "currency": "CNY",
                    "item_code": "ITEM-T08B",
                    "qty_micros": 10_000_000,
                    "price_cent": 2_200,
                    "start_date": "2026-10-01",
                    "end_date": "2026-10-31",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let convert = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/marketing/quotes"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": "CONVERT",
                            "quote_id": quote_id,
                            "partner_code": "C-T08B",
                            "currency": "CNY",
                            "item_code": "ITEM-T08B",
                            "qty_micros": 6_000_000,
                            "price_cent": 9_999,
                            "expected_version": 1,
                            "today": "2026-10-15",
                            "start_date": "2026-10-01",
                            "end_date": "2026-10-31",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        convert(app.clone(), "t08b-a"),
        convert(app.clone(), "t08b-b"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t08b-a','t08b-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let converted: (i64, i64, i64) = sqlx::query_as(
        "select count(*), coalesce(sum(qty_micros), 0)::bigint, coalesce(max(price_cent), 0)::bigint from shared_quote_conversions where tenant_id = $1 and quote_id = $2",
    )
    .bind(tenant)
    .bind(quote_id)
    .fetch_one(&pool)
    .await
    .expect("converted");
    assert_eq!(converted, (1, 6_000_000, 2_200), "conversion freezes the saved price and does not double the quantity");
    let quoted: i64 = sqlx::query_scalar(
        "select price_cent from shared_quote_revisions where tenant_id = $1 and quote_id = $2 and version_no = 1",
    )
    .bind(tenant)
    .bind(quote_id)
    .fetch_one(&pool)
    .await
    .expect("quoted");
    assert_eq!(quoted, 2_200, "conversion must not rewrite the quote price");
    let stock_rows: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(stock_rows, 0, "converting a quote must not move stock");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t08b-a','t08b-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

#[test]
fn credit_hold_http_race_read_back() {
    std::thread::Builder::new()
        .name("credit-hold-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(credit_hold_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("credit hold http thread");
}

async fn credit_hold_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("credit-hold-http-tenant {tenant:?}");
    let sales_order_id = uuid::Uuid::new_v4();
    let actor = uuid::Uuid::new_v4();
    sqlx::query(
        "insert into sales_orders (sales_order_id, tenant_id, sales_order_no, source_type, receivable_amount_cent, status) values ($1,$2,'SO-T08C','TRADE',6000,'CONFIRMED')",
    )
    .bind(sales_order_id)
    .bind(tenant)
    .execute(&pool)
    .await
    .expect("confirmed sale");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("credit-hold-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let confirmed = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/sales-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t08c-ar",
                    "confirm_balance": true,
                    "so_id": sales_order_id,
                    "partner_code": "C-T08C",
                    "currency_code": "CNY",
                    "due_date": "2026-11-15",
                    "sales_order_no": "SO-T08C",
                    "source_type": "TRADE",
                    "items": [],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("confirm");
    assert_eq!(confirmed.status(), axum::http::StatusCode::OK);
    let hold = |app: axum::Router, request: &'static str, amount: i64| {
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/marketing/quotes"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": "HOLD",
                            "partner_code": "C-T08C",
                            "currency": "CNY",
                            "item_code": "ITEM-T08C",
                            "qty_micros": 1,
                            "price_cent": amount,
                            "limit_cent": 10_000,
                            "start_date": "2026-10-01",
                            "end_date": "2026-10-31",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        hold(app.clone(), "t08c-a", 3_000),
        hold(app.clone(), "t08c-b", 3_000),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t08c-a','t08c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let held: (i64, i64) = sqlx::query_as(
        "select count(*), coalesce(sum(amount_cent), 0)::bigint from shared_credit_holds where tenant_id = $1 and partner_code = 'C-T08C'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("held");
    assert_eq!(held, (1, 3_000), "two holds of the remaining credit store one hold");
    let open: i64 = sqlx::query_scalar(
        "select coalesce(sum(amount_cent - settled_cent), 0)::bigint from partner_balances where tenant_id = $1 and partner_code = 'C-T08C' and kind = 'AR'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("open");
    assert_eq!(open, 6_000, "the confirmed receivable stays open");
    let cash_rows: i64 = sqlx::query_scalar(
        "select count(*) from cash_entries where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("cash");
    assert_eq!(cash_rows, 0, "a credit hold must not create a payment");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t08c-a','t08c-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

