async fn consignment_receive_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("consignment-receive-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("consignment-receive-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let receive = |app: axum::Router, request: &'static str, owner: &'static str, qty: i64| {
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/trade/special-fulfillment"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": "CONSIGN",
                            "owner_code": owner,
                            "location_code": "BIN-1",
                            "item_code": "ITEM-T09B",
                            "qty_micros": qty,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        receive(app.clone(), "t09b-a", "OURS", 5_000_000),
        receive(app.clone(), "t09b-b", "OURS", 8_000_000),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t09b-a','t09b-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let ours: (i64, i64) = sqlx::query_as(
        "select count(*), coalesce(sum(qty_micros), 0)::bigint from shared_consignment_stock where tenant_id = $1 and owner_code = 'OURS' and location_code = 'BIN-1' and item_code = 'ITEM-T09B'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("ours");
    assert_eq!(ours.0, 1, "one owner at one location stores one stock row");
    assert!(ours.1 == 5_000_000 || ours.1 == 8_000_000);
    let other = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/trade/special-fulfillment"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t09b-sup",
                    "action": "CONSIGN",
                    "owner_code": "S-T09B",
                    "location_code": "BIN-1",
                    "item_code": "ITEM-T09B",
                    "qty_micros": 3_000_000,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("supplier");
    assert_eq!(other.status(), axum::http::StatusCode::OK);
    let supplier: i64 = sqlx::query_scalar(
        "select qty_micros from shared_consignment_stock where tenant_id = $1 and owner_code = 'S-T09B' and location_code = 'BIN-1' and item_code = 'ITEM-T09B'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("supplier");
    assert_eq!(supplier, 3_000_000, "another owner stays a separate row");
    let stock_rows: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(stock_rows, 0, "consignment receipt must not write our stock ledger");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t09b-a','t09b-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

#[test]
fn consignment_settle_http_race_read_back() {
    std::thread::Builder::new()
        .name("consignment-settle-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(consignment_settle_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("consignment settle http thread");
}

async fn consignment_settle_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("consignment-settle-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("consignment-settle-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let received = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/trade/special-fulfillment"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "t09c-recv",
                    "action": "CONSIGN",
                    "owner_code": "OURS",
                    "location_code": "BIN-1",
                    "item_code": "ITEM-T09C",
                    "qty_micros": 5_000_000,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("receive");
    assert_eq!(received.status(), axum::http::StatusCode::OK);
    let received_bytes = http_body_util::BodyExt::collect(received.into_body())
        .await
        .expect("receive body")
        .to_bytes();
    let received_json: serde_json::Value =
        serde_json::from_slice(&received_bytes).expect("receive json");
    let stock_id = received_json["stock_id"]
        .as_str()
        .expect("stock_id")
        .to_string();
    let settle = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let stock_id = stock_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/trade/special-fulfillment"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": "SETTLE",
                            "stock_id": stock_id,
                            "qty_micros": 3_000_000,
                            "fee_cent": 900,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        settle(app.clone(), "t09c-a"),
        settle(app.clone(), "t09c-b"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t09c-a','t09c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let settlement: (i64, i64, i64) = sqlx::query_as(
        "select count(*), coalesce(sum(sold_micros), 0)::bigint, coalesce(sum(fee_cent), 0)::bigint from shared_consignment_settlements where tenant_id = $1 and stock_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&stock_id).expect("stock uuid"))
    .fetch_one(&pool)
    .await
    .expect("settlement");
    assert_eq!(settlement.0, 1, "one overlapping sale stores one settlement");
    assert_eq!(settlement.1, 3_000_000, "sold quantity is the one stored sale");
    assert_eq!(settlement.2, 900, "fee stays on that settlement");
    let stock: (String, i64) = sqlx::query_as(
        "select owner_code, qty_micros from shared_consignment_stock where tenant_id = $1 and stock_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&stock_id).expect("stock uuid"))
    .fetch_one(&pool)
    .await
    .expect("stock row");
    assert_eq!(stock.0, "OURS", "settlement must not change the owner");
    assert_eq!(stock.1, 5_000_000, "settlement must not rewrite the received quantity");
    let stock_rows: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("ledger");
    assert_eq!(stock_rows, 0, "consignment settlement must not write our stock ledger");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t09c-a','t09c-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

