async fn bom_publish_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("bom-publish-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("bom-publish-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/manufacturing/bom-structures"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m02a-save",
                    "product_code": "FG-M02A",
                    "lines": [{
                        "parent": "FG-M02A",
                        "component": "RAW-A",
                        "qty_per": "0.125",
                        "unit_code": "KG",
                        "scrap_ppm": 20000,
                        "supply": "BUY",
                        "line_no": 1
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let bom_id = saved_json["bom_id"].as_str().expect("bom_id").to_string();
    let publish = |app: axum::Router, request: &'static str, start: &'static str, end: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let bom_id = bom_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/bom-versions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "series_code": "SER-M02A",
                            "bom_id": bom_id,
                            "start_date": start,
                            "end_date": end,
                            "make_default": true,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        publish(app.clone(), "m02a-a", "2026-10-01", "2026-10-31"),
        publish(app.clone(), "m02a-b", "2026-10-15", "2026-11-15"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m02a-a','m02a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let versions: (i64, i32, String, String) = sqlx::query_as(
        "select count(*), coalesce(max(version_no), 0), coalesce(min(status), ''), coalesce(min(start_date), '') from shared_mfg_bom_versions where tenant_id = $1 and series_code = 'SER-M02A'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions.0, 1, "one overlapping default stores one version");
    assert_eq!(versions.1, 1);
    assert_eq!(versions.2, "PUBLISHED");
    assert!(versions.3 == "2026-10-01" || versions.3 == "2026-10-15");
    let lines: (i64, String, i64) = sqlx::query_as(
        "select count(*), coalesce(min(component_code), ''), coalesce(min(qty_per_micros), 0)::bigint from shared_mfg_bom_version_lines where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("lines");
    assert_eq!(lines.0, 1, "the published snapshot keeps one line");
    assert_eq!(lines.1, "RAW-A");
    assert_eq!(lines.2, 125_000);
    let source: (String, i64) = sqlx::query_as(
        "select component_code, qty_per_micros from shared_mfg_bom_lines where tenant_id = $1 and bom_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&bom_id).expect("bom uuid"))
    .fetch_one(&pool)
    .await
    .expect("source");
    assert_eq!(source, ("RAW-A".to_string(), 125_000), "publish must not rewrite the source structure");
    let request_rows: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m02a-a','m02a-b')",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("both");
    assert_eq!(request_rows, 1, "first={first:?} second={second:?}");
}

