    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/manufacturing/bom-structures"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m02d-save",
                    "product_code": "FG-M02D",
                    "lines": [{
                        "parent": "FG-M02D",
                        "component": "RAW-D",
                        "qty_per": "0.125",
                        "unit_code": "KG",
                        "scrap_ppm": 20000,
                        "supply": "BUY",
                        "line_no": 1
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
