async fn route_page_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("route-page-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("route-page-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let mut steps = vec![serde_json::json!({
        "operation": "OP001",
        "sequence": 10,
        "predecessor": "",
        "work_center": "WC-A",
        "setup_minutes": 5,
        "minutes_per": 1,
        "inspection_required": false,
        "report_field": "QTY",
        "display_order": 100,
    })];
    for index in 2..=100 {
        let previous = format!("OP{:03}", index - 1);
        steps.push(serde_json::json!({
            "operation": format!("OP{index:03}"),
            "sequence": index * 10,
            "predecessor": previous,
            "work_center": "WC-A",
            "setup_minutes": 1,
            "minutes_per": 1,
            "inspection_required": index == 100,
            "report_field": "QTY",
            "display_order": 101 - index,
        }));
    }
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/manufacturing/operation-routes"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m03c-save",
                    "product_code": "FG-M03C",
                    "steps": steps,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let route_id = saved_json["route_id"].as_str().expect("route_id").to_string();
    let read = |app: axum::Router, offset: i64| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let route_id = route_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/operation-routes?route_id={route_id}&offset={offset}&limit=1"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
            (status, json)
        }
    };
    let (first, second) = tokio::join!(read(app.clone(), 40), read(app.clone(), 40));
    assert_eq!(first.0, axum::http::StatusCode::OK, "{first:?}");
    assert_eq!(second.0, axum::http::StatusCode::OK, "{second:?}");
    assert_eq!(first.1["step_count"], 100);
    assert_eq!(second.1["step_count"], 100);
    let row = &first.1["steps"][0];
    assert_eq!(row["operation"], "OP060");
    assert_eq!(row["sequence"], 600);
    assert_ne!(row["display_order"], row["sequence"]);
    assert_eq!(row["predecessor"], "OP059");
    let wide = tower::ServiceExt::oneshot(
        app,
        axum::http::Request::builder()
            .method("GET")
            .uri(format!(
                "/v1/tenants/{tenant}/manufacturing/operation-routes?route_id={route_id}&offset=0&limit=100"
            ))
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::empty())
            .expect("request"),
    )
    .await
    .expect("wide");
    assert_ne!(wide.status(), axum::http::StatusCode::OK);
    let stored: i64 = sqlx::query_scalar(
        "select count(*) from shared_operation_steps where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stored");
    assert_eq!(stored, 100, "page reads must not change the stored steps");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "page reads must not write receipts");
}

