async fn production_delivery_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("production-delivery-http-tenant {tenant:?}");
    let order_id = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("production-delivery-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, path: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(path)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
            (status, json, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let line = serde_json::json!({
        "line_no": 1,
        "item_code": "FG-M05C",
        "qty_micros": 10_000_000,
        "price_cent": 2500,
        "discount_cent": 0,
        "tax_cent": 325,
        "due_date": "2026-10-08",
        "address": "dock-5",
        "source": "MAKE",
    });
    let (opened, _, opened_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/sales-revisions"),
        serde_json::json!({
            "request_id": "m05c-open",
            "so_id": order_id,
            "customer_code": "C-M05C",
            "action": "SUBMIT",
            "lines": [line],
        }),
    )
    .await;
    assert_eq!(opened, axum::http::StatusCode::OK, "{opened_text}");
    let (fulfilled, _, fulfilled_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/sales-revisions"),
        serde_json::json!({
            "request_id": "m05c-go",
            "so_id": order_id,
            "customer_code": "C-M05C",
            "expected_version": 1,
            "action": "FULFILL",
            "lines": [line],
        }),
    )
    .await;
    assert_eq!(fulfilled, axum::http::StatusCode::OK, "{fulfilled_text}");
    let (saved_status, saved, saved_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/manufacturing/production-plans"),
        serde_json::json!({
            "request_id": "m05c-plan",
            "source_id": order_id,
            "line_no": 1,
            "item_code": "FG-M05C",
            "version_no": 1,
            "open_qty": 6_000_000,
            "buckets": [
                {"due_date":"2026-10-08","qty_micros":6_000_000,"source_kind":"MAKE"}
            ],
        }),
    )
    .await;
    assert_eq!(saved_status, axum::http::StatusCode::OK, "{saved_text}");
    let plan_id = saved["plan_id"].as_str().expect("plan_id").to_string();
    let (executed_status, _, executed_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/manufacturing/production-plans"),
        serde_json::json!({
            "request_id": "m05c-ex",
            "action": "EXECUTE",
            "plan_id": plan_id,
            "due_date": "2026-10-08",
            "qty_micros": 1_000_000,
        }),
    )
    .await;
    assert_eq!(executed_status, axum::http::StatusCode::OK, "{executed_text}");
    let (stocked, _, stocked_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/stock-ledgers"),
        serde_json::json!({
            "request_id": "m05c-stock",
            "warehouse_id": warehouse,
            "location_id": location,
            "sku_id": sku,
            "batch_code": "LOT-M05C",
            "quality_status": "GOOD",
            "bucket": "ON_HAND",
            "delta_micros": 10_000_000,
        }),
    )
    .await;
    assert_eq!(stocked, axum::http::StatusCode::OK, "{stocked_text}");
    let (reserved, _, reserved_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/stock-reservations"),
        serde_json::json!({
            "request_id": "m05c-reserve",
            "warehouse_id": warehouse,
            "location_id": location,
            "sku_id": sku,
            "batch_code": "LOT-M05C",
            "quality_status": "GOOD",
            "source_line": format!("{order_id}:1"),
            "qty_micros": 2_000_000,
        }),
    )
    .await;
    assert_eq!(reserved, axum::http::StatusCode::OK, "{reserved_text}");
    let (planned_status, planned, planned_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/sales-orders/{order_id}/deliveries"),
        serde_json::json!({
            "request_id": "m05c-ship",
            "line_no": 1,
            "expected_version": 2,
            "qty_micros": 2_000_000,
        }),
    )
    .await;
    assert_eq!(planned_status, axum::http::StatusCode::OK, "{planned_text}");
    let delivery_id = planned["delivery_id"].as_str().expect("delivery_id").to_string();
    for (request_id, action) in [("m05c-r", "RESERVE"), ("m05c-p", "PICK"), ("m05c-v", "REVIEW")] {
        let (status, _, text) = post(
            app.clone(),
            format!("/v1/tenants/{tenant}/sales-orders/{order_id}/deliveries"),
            serde_json::json!({
                "request_id": request_id,
                "line_no": 1,
                "expected_version": 2,
                "qty_micros": 2_000_000,
                "action": action,
                "delivery_id": delivery_id,
                "warehouse_id": warehouse,
                "location_id": location,
                "sku_id": sku,
                "batch_code": "LOT-M05C",
            }),
        )
        .await;
        assert_eq!(status, axum::http::StatusCode::OK, "{action} {text}");
    }
    let apply = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let plan_id = plan_id.clone();
        let delivery_id = delivery_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/production-plans"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "action": "DELIVER",
                            "plan_id": plan_id,
                            "due_date": "2026-10-08",
                            "delivery_id": delivery_id,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        apply(app.clone(), "m05c-a"),
        apply(app, "m05c-b"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m05c-a','m05c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let row: (i64, i64, i64) = sqlx::query_as(
        "select qty_micros, executed_micros, cancelled_micros from shared_production_buckets where tenant_id = $1 and due_date = '2026-10-08'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("bucket");
    assert_eq!(row.0, 6_000_000, "the remaining six stays planned");
    assert_eq!(row.1, 1_000_000, "executed quantity stays");
    assert_eq!(row.2, 2_000_000, "one reviewed delivery cancels only its own quantity");
    let deliveries: i64 = sqlx::query_scalar(
        "select count(*) from shared_plan_deliveries where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("deliveries");
    assert_eq!(deliveries, 1);
}

