async fn operation_totals_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("operation-totals-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm10e-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("operation-totals-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m10e-plan",
                    "work_order_no": "WO-M10E",
                    "product_code": "FG-M10E",
                    "order_qty": "4",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    let repo = SharedContractRepo::new(&pool);
    repo.transition_saved_work_order(TenantId(tenant_id), "m10e-rel", "m10e-rel", order_id, "release")
        .await
        .expect("status release")
        .expect("admit status release");
    let post = |app: axum::Router, body: serde_json::Value| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/reports"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).expect("json");
            (status, json)
        }
    };
    let original = post(
        app.clone(),
        serde_json::json!({
            "request_id": "m10e-cut",
            "operation_code": "CUT",
            "good_qty": "4",
            "rejected_qty": "1",
            "rework_qty": "0",
            "minutes": 30,
            "operator_id": "worker-m10e",
            "session_id": "session-m10e",
            "crew_code": "CREW-M10E",
            "started_at": "2026-10-02T09:00:00Z",
            "ended_at": "2026-10-02T09:30:00Z",
            "previous_good_qty": "5",
        }),
    )
    .await;
    assert_eq!(original.0, axum::http::StatusCode::OK);
    let report_id = original.1["effect_id"].as_str().expect("report").to_string();
    let reversed = post(
        app.clone(),
        serde_json::json!({
            "request_id": "m10e-rev",
            "operation_code": "CUT",
            "good_qty": "-4",
            "rejected_qty": "-1",
            "rework_qty": "0",
            "minutes": -30,
            "operator_id": "worker-m10e",
            "session_id": "session-m10e",
            "crew_code": "CREW-M10E",
            "started_at": "2026-10-02T09:00:00Z",
            "ended_at": "2026-10-02T09:30:00Z",
            "previous_good_qty": "5",
            "reverses_report_id": report_id,
        }),
    )
    .await;
    assert_eq!(reversed.0, axum::http::StatusCode::OK);
    let before: i64 = sqlx::query_scalar("select count(*) from command_receipts where tenant_id = $1")
        .bind(tenant_id)
        .fetch_one(&pool)
        .await
        .expect("receipts before");
    let read = |app: axum::Router| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/reports?operation_code=CUT"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (first, second) = tokio::join!(read(app.clone()), read(app));
    assert_eq!(first.0, axum::http::StatusCode::OK);
    assert_eq!(second.0, axum::http::StatusCode::OK);
    let first_json: serde_json::Value = serde_json::from_slice(&first.1).expect("first json");
    let second_json: serde_json::Value = serde_json::from_slice(&second.1).expect("second json");
    assert_eq!(first_json["good_micros"], 0);
    assert_eq!(first_json["rejected_micros"], 0);
    assert_eq!(first_json["minutes"], 0);
    assert_eq!(second_json["good_micros"], 0);
    assert_eq!(second_json["minutes"], 0);
    let after: i64 = sqlx::query_scalar("select count(*) from command_receipts where tenant_id = $1")
        .bind(tenant_id)
        .fetch_one(&pool)
        .await
        .expect("receipts after");
    assert_eq!(after, before, "a report totals read stores no receipt");
    let rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_reports where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("rows");
    assert_eq!(rows, 2, "the original report and its reversal both stay");
}

