async fn operation_successor_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("operation-successor-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm10d-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("operation-successor-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved_route = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/operation-routes"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m10d-route",
                    "product_code": "FG-M10D",
                    "steps": [
                        {"operation":"CUT","sequence":10,"predecessor":"","work_center":"WC-A","setup_minutes":5,"minutes_per":2,"inspection_required":false,"report_field":"QTY"},
                        {"operation":"WELD","sequence":20,"predecessor":"CUT","work_center":"WC-B","setup_minutes":3,"minutes_per":4,"inspection_required":false,"report_field":"QTY"}
                    ],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("route");
    assert_eq!(saved_route.status(), axum::http::StatusCode::OK);
    let route_bytes = http_body_util::BodyExt::collect(saved_route.into_body())
        .await
        .expect("route body")
        .to_bytes();
    let route_json: serde_json::Value = serde_json::from_slice(&route_bytes).expect("route json");
    let route_id = route_json["route_id"].as_str().expect("route id").to_string();
    let frozen = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/operation-routes"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m10d-snap",
                    "route_id": route_id,
                    "work_order_no": "WO-M10D",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("snapshot");
    assert_eq!(frozen.status(), axum::http::StatusCode::OK);
    let frozen_bytes = http_body_util::BodyExt::collect(frozen.into_body())
        .await
        .expect("snapshot body")
        .to_bytes();
    let frozen_json: serde_json::Value = serde_json::from_slice(&frozen_bytes).expect("snapshot json");
    let work_order_id = frozen_json["work_order_id"].as_str().expect("snapshot order").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    sqlx::query(
        "insert into mfg_work_orders(tenant_id, work_order_id, work_order_no, product_code, status, order_qty_micros) values ($1, $2, 'WO-M10D', 'FG-M10D', 'PLANNED', 4000000)",
    )
    .bind(tenant_id)
    .bind(order_id)
    .execute(&pool)
    .await
    .expect("order row for the frozen route");
    let repo = SharedContractRepo::new(&pool);
    let (released, released_status) = repo
        .transition_saved_work_order(TenantId(tenant_id), "m10d-rel", "m10d-rel", order_id, "release")
        .await
        .expect("status release")
        .expect("admit status release");
    assert!(matches!(released, SharedWrite::Stored(_)));
    assert_eq!(released_status.as_str(), "RELEASED");
    let cut = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/reports"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m10d-cut",
                    "operation_code": "CUT",
                    "good_qty": "4",
                    "rejected_qty": "1",
                    "rework_qty": "0",
                    "minutes": 30,
                    "operator_id": "worker-m10d",
                    "session_id": "session-m10d",
                    "crew_code": "CREW-M10D",
                    "started_at": "2026-10-02T09:00:00Z",
                    "ended_at": "2026-10-02T09:30:00Z",
                    "previous_good_qty": "99",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("cut");
    assert_eq!(cut.status(), axum::http::StatusCode::OK);
    let weld = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/reports"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "operation_code": "WELD",
                            "good_qty": "3",
                            "rejected_qty": "0",
                            "rework_qty": "0",
                            "minutes": 12,
                            "operator_id": "worker-m10d",
                            "session_id": "session-m10d",
                            "crew_code": "CREW-M10D",
                            "started_at": "2026-10-02T10:00:00Z",
                            "ended_at": "2026-10-02T10:12:00Z",
                            "previous_good_qty": "99",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(weld(app.clone(), "m10d-a"), weld(app, "m10d-b"));
    let stored = [&first, &second]
        .iter()
        .filter(|item| item.0 == axum::http::StatusCode::OK)
        .count();
    assert_eq!(stored, 1, "two successor reports store one: {first:?} {second:?}");
    let weld_rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_reports where tenant_id = $1 and work_order_id = $2 and operation_code = 'WELD'",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("weld rows");
    assert_eq!(weld_rows, 1);
    let weld_good: i64 = sqlx::query_scalar(
        "select coalesce(sum(good_micros), 0)::bigint from mfg_reports where tenant_id = $1 and work_order_id = $2 and operation_code = 'WELD'",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("weld good");
    assert_eq!(weld_good, 3_000_000);
    let cut_good: i64 = sqlx::query_scalar(
        "select coalesce(sum(good_micros), 0)::bigint from mfg_reports where tenant_id = $1 and work_order_id = $2 and operation_code = 'CUT'",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("cut good");
    assert_eq!(cut_good, 4_000_000);
}

