async fn issued_engineering_change_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("issued-change-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm15f-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'm15f', 'M15F')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-M15F')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("issued-change-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let bom = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/boms"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15f-bom",
                    "product_code": "FG-M15F",
                    "items": [{"parent": "FG-M15F", "component": "A", "qty_per": "1"}],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("bom");
    assert_eq!(bom.status(), axum::http::StatusCode::OK);
    let bom_bytes = http_body_util::BodyExt::collect(bom.into_body())
        .await
        .expect("bom body")
        .to_bytes();
    let bom_json: serde_json::Value = serde_json::from_slice(&bom_bytes).expect("bom json");
    let bom_id = bom_json["effect_id"].as_str().expect("bom").to_string();
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15f-plan",
                    "work_order_no": "WO-M15F",
                    "product_code": "FG-M15F",
                    "bom_id": bom_id,
                    "order_qty": "1",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    let repo = SharedContractRepo::new(&pool);
    repo.transition_saved_work_order(TenantId(tenant_id), "m15f-rel", "m15f-rel", order_id, "release")
        .await
        .expect("status release")
        .expect("admit status release");
    repo.post_inventory_inbound(TenantId(tenant_id), "m15f-in", "m15f-in", warehouse, sku, 1, Some("m15f".into()))
        .await
        .expect("inbound")
        .expect("admit inbound");
    let issued = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/materials"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15f-iss",
                    "kind": "ISSUE",
                    "qty": "1",
                    "warehouse_id": warehouse,
                    "sku_id": sku,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("issue");
    assert_eq!(issued.status(), axum::http::StatusCode::OK, "issued material");
    let rule = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/substitutes"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15f-sub",
                    "original_code": "A",
                    "replacement_code": "A2",
                    "ratio": "2",
                    "effective_from": "2026-10-01",
                    "effective_to": "2026-10-31",
                    "approver": "planner",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("rule");
    assert_eq!(rule.status(), axum::http::StatusCode::OK);
    let rule_bytes = http_body_util::BodyExt::collect(rule.into_body())
        .await
        .expect("rule body")
        .to_bytes();
    let rule_json: serde_json::Value = serde_json::from_slice(&rule_bytes).expect("rule json");
    let substitute_id = rule_json["effect_id"].as_str().expect("substitute").to_string();
    let apply = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        let substitute_id = substitute_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/engineering-changes"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "substitute_id": substitute_id,
                            "need_date": "2026-10-08",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(apply(app.clone(), "m15f-a"), apply(app, "m15f-b"));
    assert_eq!(first, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(second, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let issued_qty: i64 = sqlx::query_scalar(
        "select issued_micros from mfg_work_orders where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("issued");
    assert_eq!(issued_qty, 1_000_000);
    let changes: i64 = sqlx::query_scalar(
        "select count(*) from mfg_engineering_changes where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("changes");
    assert_eq!(changes, 0, "issued material blocks the change");
    let bom_line: String = sqlx::query_scalar(
        "select component_code from mfg_bom_items where tenant_id = $1 and bom_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&bom_id).expect("bom"))
    .fetch_one(&pool)
    .await
    .expect("bom");
    assert_eq!(bom_line, "A");
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m15f-a','m15f-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

