async fn quality_disposition_split_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("quality-split-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q02j-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'q02j', 'Q02J')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-Q02J')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("quality-split-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
            (status, json)
        }
    };
    let (saved_status, saved_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"),
        serde_json::json!({
            "request_id": "q02j-plan",
            "work_order_no": "WO-Q02J",
            "product_code": "FG-Q02J",
            "order_qty": "10",
        }),
    )
    .await;
    assert_eq!(saved_status, axum::http::StatusCode::OK);
    let work_order_id = saved_json["effect_id"].as_str().expect("order").to_string();
    let (hold_status, hold_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/holds"),
        serde_json::json!({
            "request_id": "q02j-hold",
            "work_order_id": work_order_id,
            "batch_code": "BATCH-Q02J",
            "qty": "10",
        }),
    )
    .await;
    assert_eq!(hold_status, axum::http::StatusCode::OK, "{hold_json}");
    let hold_id = hold_json["effect_id"].as_str().expect("hold").to_string();
    let dispose = |app: axum::Router, request: &'static str, kind: &'static str, qty: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let hold_id = hold_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/dispositions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "hold_id": hold_id,
                            "location_id": location,
                            "warehouse_id": warehouse,
                            "sku_id": sku,
                            "kind": kind,
                            "qty": qty,
                            "reason": "split",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let accepted = dispose(app.clone(), "q02j-good", "ACCEPT", "8").await;
    assert_eq!(accepted, axum::http::StatusCode::OK, "eight of ten accept");
    let (first, second) = tokio::join!(
        dispose(app.clone(), "q02j-a", "ISOLATE", "2"),
        dispose(app, "q02j-b", "ISOLATE", "2"),
    );
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two isolates of the remainder store one: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let rows: Vec<(String, i64, i64, String, i32)> = sqlx::query_as(
        r#"
        select kind, qty_micros, held_left_micros, quality_status, version_no
        from mfg_quality_dispositions
        where tenant_id = $1 and inspection_id = $2
        order by version_no
        "#,
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&hold_id).expect("hold id"))
    .fetch_all(&pool)
    .await
    .expect("dispositions");
    assert_eq!(rows.len(), 2);
    assert_eq!(rows[0].0, "ACCEPT");
    assert_eq!(rows[0].1, 8_000_000);
    assert_eq!(rows[0].2, 2_000_000);
    assert_eq!(rows[0].3, "GOOD");
    assert_eq!(rows[0].4, 1);
    assert_eq!(rows[1].0, "ISOLATE");
    assert_eq!(rows[1].1, 2_000_000);
    assert_eq!(rows[1].2, 0);
    assert_eq!(rows[1].3, "ISOLATED");
    assert_eq!(rows[1].4, 2);
    let pair: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('q02j-a','q02j-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("pair");
    assert_eq!(pair, 1);
    let ledgers: Vec<(String, i64)> = sqlx::query_as(
        r#"
        select reason_type, sum(delta_micros)::bigint
        from mfg_qty_ledgers
        where tenant_id = $1
        group by reason_type
        order by reason_type
        "#,
    )
    .bind(tenant_id)
    .fetch_all(&pool)
    .await
    .expect("ledgers");
    assert_eq!(ledgers, vec![("QC_AVAILABLE".to_string(), 8_000_000), ("QC_ISOLATED".to_string(), 2_000_000)]);
}

