async fn quality_disposition_return_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("quality-return-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q02n-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'q02n', 'Q02N')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-Q02N')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("quality-return-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
            (status, json)
        }
    };
    let (saved_status, saved_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"),
        serde_json::json!({
            "request_id": "q02n-plan",
            "work_order_no": "WO-Q02N",
            "product_code": "FG-Q02N",
            "order_qty": "2",
        }),
    )
    .await;
    assert_eq!(saved_status, axum::http::StatusCode::OK);
    let work_order_id = saved_json["effect_id"].as_str().expect("order").to_string();
    let (hold_status, hold_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/holds"),
        serde_json::json!({
            "request_id": "q02n-hold",
            "work_order_id": work_order_id,
            "batch_code": "BATCH-Q02N",
            "qty": "2",
        }),
    )
    .await;
    assert_eq!(hold_status, axum::http::StatusCode::OK, "{hold_json}");
    let hold_id = hold_json["effect_id"].as_str().expect("hold").to_string();
    let dispose = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let hold_id = hold_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/dispositions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "hold_id": hold_id,
                            "location_id": location,
                            "warehouse_id": warehouse,
                            "sku_id": sku,
                            "kind": "RETURN_SUPPLIER",
                            "qty": "2",
                            "reason": "supplier defect",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let missing = dispose(app.clone(), "q02n-none").await;
    assert_eq!(missing, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let missing_rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_quality_dispositions where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("missing disposition");
    assert_eq!(missing_rows, 0);
    sqlx::query(
        r#"
        insert into shared_stock_ledgers(
            tenant_id, ledger_id, warehouse_id, location_id, sku_id, batch_code,
            quality_status, bucket, delta_micros, source_line, request_id
        )
        values ($1, $2, $3, $4, $5, 'BATCH-Q02N', 'HOLD', 'ON_HAND', 2000000, 'q02n-hold', 'q02n-hold')
        "#,
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::new_v4())
    .bind(warehouse)
    .bind(location)
    .bind(sku)
    .execute(&pool)
    .await
    .expect("held stock");
    let (first, second) = tokio::join!(dispose(app.clone(), "q02n-a"), dispose(app, "q02n-b"));
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two returns of the remainder store one: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let stored: (i64, String, i64) = sqlx::query_as(
        r#"
        select count(*)::bigint, min(quality_status), min(held_left_micros)
        from mfg_quality_dispositions
        where tenant_id = $1 and inspection_id = $2
        "#,
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&hold_id).expect("hold id"))
    .fetch_one(&pool)
    .await
    .expect("disposition");
    assert_eq!(stored.0, 1);
    assert_eq!(stored.1, "RETURN");
    assert_eq!(stored.2, 0);
    let physical: i64 = sqlx::query_scalar(
        r#"
        select coalesce(sum(delta_micros), 0)::bigint
        from shared_stock_ledgers
        where tenant_id = $1 and batch_code = 'BATCH-Q02N' and bucket = 'ON_HAND'
        "#,
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("physical");
    assert_eq!(physical, 0);
    let pair: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('q02n-a','q02n-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("pair");
    assert_eq!(pair, 1);
    let none: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'q02n-none'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("none");
    assert_eq!(none, 0);
}

