async fn cost_period_close_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("cost-period-close-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'f04d-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("cost-period-close-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let missing = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cost-periods/closures"),
        serde_json::json!({"request_id": "f04d-none", "period_code": "2026-09-F04D"}),
    )
    .await;
    assert_eq!(missing.0, axum::http::StatusCode::UNPROCESSABLE_ENTITY, "{:?}", missing.1);
    for (request_id, bucket, amount, source) in [
        ("f04d-inv", "INVENTORY", 70_000_i64, "inv-f04d"),
        ("f04d-wip", "WIP", 4_000, "wip-f04d"),
        ("f04d-fg", "FINISHED", 49_000, "fg-f04d"),
        ("f04d-cogs", "COGS", 30_000, "cogs-f04d"),
    ] {
        let stored = post(
            app.clone(),
            format!("/v1/tenants/{tenant_id}/finance/cost-facts"),
            serde_json::json!({
                "request_id": request_id,
                "period_code": "2026-09-F04D",
                "bucket": bucket,
                "amount_cent": amount,
                "source_ref": source,
            }),
        )
        .await;
        assert_eq!(stored.0, axum::http::StatusCode::OK, "{request_id} {:?}", stored.1);
    }
    let reconciled = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cost-reconciliations"),
        serde_json::json!({
            "request_id": "f04d-recon",
            "period_code": "2026-09-F04D",
            "currency": "CNY",
            "cutoff_at": "2026-09-30",
            "books": [
                {"bucket": "INVENTORY", "book_cent": 70000},
                {"bucket": "WIP", "book_cent": 4000},
                {"bucket": "FINISHED", "book_cent": 50000},
                {"bucket": "COGS", "book_cent": 30000}
            ],
        }),
    )
    .await;
    assert_eq!(reconciled.0, axum::http::StatusCode::OK, "{:?}", reconciled.1);
    let close = |app: axum::Router, request_id: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/finance/cost-periods/closures"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request_id,
                            "period_code": "2026-09-F04D",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (first, second) = tokio::join!(close(app.clone(), "f04d-a"), close(app.clone(), "f04d-b"));
    let winners = [&first, &second]
        .into_iter()
        .filter(|result| result.0 == axum::http::StatusCode::OK)
        .count();
    assert_eq!(winners, 1, "two closes store one close: {first:?} {second:?}");
    let backdated = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cost-period-adjustments"),
        serde_json::json!({
            "request_id": "f04d-back",
            "period_code": "2026-09-F04D",
            "document_date": "2026-09-30",
            "amount_cent": 500,
            "reason": "late receipt",
        }),
    )
    .await;
    assert_eq!(backdated.0, axum::http::StatusCode::UNPROCESSABLE_ENTITY, "{:?}", backdated.1);
    let late = |app: axum::Router, request_id: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/finance/cost-period-adjustments"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request_id,
                            "period_code": "2026-09-F04D",
                            "document_date": "2026-10-02",
                            "amount_cent": 500,
                            "reason": "late receipt",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (late_a, late_b) = tokio::join!(late(app.clone(), "f04d-late"), late(app, "f04d-late"));
    let late_winners = [&late_a, &late_b]
        .into_iter()
        .filter(|result| result.0 == axum::http::StatusCode::OK)
        .count();
    assert_eq!(late_winners, 2, "the same late request replays: {late_a:?} {late_b:?}");
    let late_effects = [&late_a, &late_b]
        .into_iter()
        .map(|result| {
            serde_json::from_slice::<serde_json::Value>(&result.1)
                .expect("late body")["effect_id"]
                .as_str()
                .expect("effect")
                .to_string()
        })
        .collect::<Vec<_>>();
    assert_eq!(late_effects[0], late_effects[1], "replay keeps one adjustment");
    let status: String = sqlx::query_scalar(
        "select status from cost_periods where tenant_id = $1 and period_code = '2026-09-F04D'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("status");
    assert_eq!(status, "CLOSED");
    let fact: i64 = sqlx::query_scalar(
        "select amount_cent from shared_cost_facts where tenant_id = $1 and source_ref = 'fg-f04d'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("fact");
    assert_eq!(fact, 49_000);
    let difference: i64 = sqlx::query_scalar(
        "select difference_cent from cost_reconciliations where tenant_id = $1 and period_code = '2026-09-F04D' and bucket = 'FINISHED'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("difference");
    assert_eq!(difference, 1_000);
    let adjustments: i64 = sqlx::query_scalar(
        "select count(*) from cost_period_adjustments where tenant_id = $1 and period_code = '2026-09-F04D'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("adjustments");
    assert_eq!(adjustments, 1);
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('f04d-none', 'f04d-back')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

