async fn cited_cost_variance_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("cited-variance-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'f06a-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("cited-variance-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let work_order_id = uuid::Uuid::new_v4();
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let negative = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/standard-cost-snapshots"),
        serde_json::json!({
            "request_id": "f06a-neg",
            "work_order_id": work_order_id,
            "material_qty_micros": -1_000_000,
            "material_price_cent": 3_000,
            "labor_minutes": 60,
            "labor_rate_cent": 200,
            "overhead_rate_cent": 100,
        }),
    )
    .await;
    assert_eq!(negative.0, axum::http::StatusCode::BAD_REQUEST, "{:?}", negative.1);
    let snapshot = |app: axum::Router, request_id: &'static str, qty: i64| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/finance/standard-cost-snapshots"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request_id,
                            "work_order_id": work_order_id,
                            "material_qty_micros": qty,
                            "material_price_cent": 3_000,
                            "labor_minutes": 60,
                            "labor_rate_cent": 200,
                            "overhead_rate_cent": 100,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (first, second) = tokio::join!(
        snapshot(app.clone(), "f06a-std-a", 10_000_000),
        snapshot(app.clone(), "f06a-std-b", 10_000_000),
    );
    assert_eq!(first.0, axum::http::StatusCode::OK, "{:?}", first.1);
    assert_eq!(second.0, axum::http::StatusCode::OK, "{:?}", second.1);
    let versions: Vec<(i32, i64)> = sqlx::query_as(
        "select version_no, material_qty_micros from mfg_standard_cost_drivers where tenant_id = $1 and work_order_id = $2 order by version_no",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_all(&pool)
    .await
    .expect("versions");
    assert_eq!(versions.len(), 2);
    assert_eq!(versions[0].0, 1);
    assert_eq!(versions[0].1, 10_000_000);
    assert_eq!(versions[1].0, 2);
    assert_eq!(versions[1].1, 10_000_000);
    let standard_id: uuid::Uuid = sqlx::query_scalar(
        "select standard_id from mfg_standard_cost_drivers where tenant_id = $1 and work_order_id = $2 and version_no = 1",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("version 1");
    let missing = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cited-cost-variances"),
        serde_json::json!({
            "request_id": "f06a-missing",
            "standard_id": uuid::Uuid::new_v4(),
            "material_qty_micros": 5_000_000,
            "material_price_cent": 6_200,
            "labor_minutes": 50,
            "labor_rate_cent": 250,
            "overhead_cent": 6_500,
        }),
    )
    .await;
    assert_eq!(missing.0, axum::http::StatusCode::UNPROCESSABLE_ENTITY, "{:?}", missing.1);
    let variance = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cited-cost-variances"),
        serde_json::json!({
            "request_id": "f06a-var",
            "standard_id": standard_id,
            "material_qty_micros": 5_000_000,
            "material_price_cent": 6_200,
            "labor_minutes": 50,
            "labor_rate_cent": 250,
            "overhead_cent": 6_500,
        }),
    )
    .await;
    assert_eq!(variance.0, axum::http::StatusCode::OK, "{:?}", variance.1);
    let variance_json: serde_json::Value = serde_json::from_slice(&variance.1).expect("variance body");
    assert_eq!(variance_json["variance_cent"].as_i64(), Some(2_000));
    assert_eq!(variance_json["estimated"].as_bool(), Some(false));
    let again = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cited-cost-variances"),
        serde_json::json!({
            "request_id": "f06a-again",
            "standard_id": standard_id,
            "material_qty_micros": 8_000_000,
            "material_price_cent": 6_200,
            "labor_minutes": 50,
            "labor_rate_cent": 250,
            "overhead_cent": 6_500,
        }),
    )
    .await;
    assert_eq!(again.0, axum::http::StatusCode::UNPROCESSABLE_ENTITY, "{:?}", again.1);
    let second_standard = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/standard-cost-snapshots"),
        serde_json::json!({
            "request_id": "f06a-std2",
            "work_order_id": work_order_id,
            "material_qty_micros": 8_000_000,
            "material_price_cent": 3_000,
            "labor_minutes": 60,
            "labor_rate_cent": 200,
            "overhead_rate_cent": 100,
        }),
    )
    .await;
    assert_eq!(second_standard.0, axum::http::StatusCode::OK, "{:?}", second_standard.1);
    let second_json: serde_json::Value = serde_json::from_slice(&second_standard.1).expect("second body");
    assert_eq!(second_json["version_no"].as_i64(), Some(3));
    let second_id = second_json["effect_id"].as_str().expect("second id").to_string();
    let first_qty: i64 = sqlx::query_scalar(
        "select material_qty_micros from mfg_standard_cost_drivers where tenant_id = $1 and standard_id = $2",
    )
    .bind(tenant_id)
    .bind(standard_id)
    .fetch_one(&pool)
    .await
    .expect("version 1 qty");
    assert_eq!(first_qty, 10_000_000);
    let unknown = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cited-cost-variances"),
        serde_json::json!({
            "request_id": "f06a-unknown",
            "standard_id": second_id,
            "material_qty_micros": 5_000_000,
            "material_price_cent": 6_200,
            "labor_minutes": 50,
            "labor_rate_cent": 250,
        }),
    )
    .await;
    assert_eq!(unknown.0, axum::http::StatusCode::OK, "{:?}", unknown.1);
    let unknown_json: serde_json::Value = serde_json::from_slice(&unknown.1).expect("unknown body");
    assert_eq!(unknown_json["estimated"].as_bool(), Some(true));
    assert_ne!(unknown_json["variance_cent"].as_i64(), Some(2_000));
    let parts: Vec<(String, i64, i64, i64, bool)> = sqlx::query_as(
        "select kind, standard_cent, actual_cent, variance_cent, estimated from mfg_cost_variance_parts where tenant_id = $1 and standard_id = $2 order by kind",
    )
    .bind(tenant_id)
    .bind(standard_id)
    .fetch_all(&pool)
    .await
    .expect("parts");
    let part = |kind: &str| {
        parts
            .iter()
            .find(|row| row.0 == kind)
            .cloned()
            .unwrap_or_else(|| panic!("missing {kind}"))
    };
    assert_eq!(part("MATERIAL_PRICE"), ("MATERIAL_PRICE".to_string(), 30_000, 62_000, 32_000, false));
    assert_eq!(part("MATERIAL_USAGE"), ("MATERIAL_USAGE".to_string(), 62_000, 31_000, -31_000, false));
    assert_eq!(part("LABOR_RATE"), ("LABOR_RATE".to_string(), 12_000, 15_000, 3_000, false));
    assert_eq!(part("LABOR_EFFICIENCY"), ("LABOR_EFFICIENCY".to_string(), 15_000, 12_500, -2_500, false));
    assert_eq!(part("OVERHEAD"), ("OVERHEAD".to_string(), 6_000, 6_500, 500, false));
    assert_eq!(part("MATERIAL_PRICE").1 + part("LABOR_RATE").1 + part("OVERHEAD").1, 48_000);
    assert_eq!(part("MATERIAL_USAGE").2 + part("LABOR_EFFICIENCY").2 + part("OVERHEAD").2, 50_000);
    let variance_sum: i64 = parts.iter().map(|row| row.3).sum();
    assert_eq!(variance_sum, 2_000);
    let version_rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_standard_cost_drivers where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("version count");
    assert_eq!(version_rows, 3);
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('f06a-neg', 'f06a-missing', 'f06a-again')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

