async fn task_exception_action_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("task-action-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'r04e-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("task-action-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/tasks/exceptions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "r04e-save",
                    "kind": "TASK_FAILED",
                    "object_type": "WORK_ORDER",
                    "object_id": "wo-r04e",
                    "command_id": "cmd-r04e",
                    "query_generation": 1,
                    "error_text": "worker failed",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_body: serde_json::Value =
        serde_json::from_slice(&saved_bytes).expect("save json");
    let exception_id = saved_body["effect_id"]
        .as_str()
        .expect("exception id")
        .to_string();
    let stale = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/tasks/exceptions/{exception_id}/actions"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "r04e-stale",
                    "command_id": "cmd-r04e",
                    "query_generation": 2,
                    "action": "RETRY",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("stale");
    assert_eq!(stale.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let missing = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/tasks/exceptions/{}/actions",
                uuid::Uuid::nil()
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "r04e-missing",
                    "command_id": "cmd-r04e",
                    "query_generation": 1,
                    "action": "RETRY",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("missing");
    assert_eq!(missing.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let post = |app: axum::Router, request_id: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let exception = exception_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/tasks/exceptions/{exception}/actions"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request_id,
                            "command_id": "cmd-r04e",
                            "query_generation": 1,
                            "action": "RETRY",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (first, second) = tokio::join!(
        post(app.clone(), "r04e-a"),
        post(app.clone(), "r04e-b"),
    );
    let winners = [&first, &second]
        .iter()
        .filter(|item| item.0 == axum::http::StatusCode::OK)
        .count();
    assert_eq!(winners, 1, "first {:?} second {:?}", first.1, second.1);
    let row: (String, String, String) = sqlx::query_as(
        "select command_id, status, next_action from task_exceptions where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("exception");
    assert_eq!(row.0, "cmd-r04e");
    assert_eq!(row.1, "RETRIED");
    assert_eq!(row.2, "RETRY");
    let action: (String, String, i64) = sqlx::query_as(
        "select command_id, action, query_generation from task_exception_actions where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("action");
    assert_eq!(action.0, "cmd-r04e");
    assert_eq!(action.1, "RETRY");
    assert_eq!(action.2, 1);
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('r04e-stale', 'r04e-missing')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused receipts");
    assert_eq!(refused, 0);
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('r04e-a', 'r04e-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("action receipts");
    assert_eq!(receipts, 1);
}

