async fn saved_view_trend_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("saved-trend-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'r05f-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let october = uuid::Uuid::new_v4();
    let november = uuid::Uuid::new_v4();
    let outside = uuid::Uuid::new_v4();
    let draft = uuid::Uuid::new_v4();
    for (id, no, amount, date, status) in [
        (october, "so-r05f-oct", 12000_i64, "2026-10-06", "CONFIRMED"),
        (november, "so-r05f-nov", 8000, "2026-11-04", "CONFIRMED"),
        (outside, "so-r05f-out", 5000, "2026-12-02", "CONFIRMED"),
        (draft, "so-r05f-draft", 9000, "2026-10-20", "DRAFT"),
    ] {
        sqlx::query(
            "insert into sales_orders(sales_order_id, tenant_id, sales_order_no, source_type, total_amount_cent, document_date, status) values ($1,$2,$3,'MANUAL',$4,$5,$6)",
        )
        .bind(id)
        .bind(tenant_id)
        .bind(no)
        .bind(amount)
        .bind(date)
        .bind(status)
        .execute(&pool)
        .await
        .expect("sale");
        sqlx::query(
            "insert into sales_order_items(tenant_id, sales_order_id, sku_id, qty, price_cent, amount_cent) values ($1,$2,$3,$4,$5,$6)",
        )
        .bind(tenant_id)
        .bind(id)
        .bind(uuid::Uuid::new_v4())
        .bind(if id == october { 3 } else { 1 })
        .bind(amount)
        .bind(amount)
        .execute(&pool)
        .await
        .expect("sale item");
    }
    let jwt = erp_api::JwtService::new("saved-trend-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/reports/saved-views"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "r05f-save",
                    "report_scope": "operating",
                    "name": "month-sales-r05f",
                    "date_from": "2026-10-01",
                    "date_to": "2026-11-30",
                    "dimension": "document_date",
                    "measure": "amount_cent",
                    "chart_type": "line",
                    "formula": "sum(amount_cent)",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_body: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let view_id = saved_body["effect_id"].as_str().expect("view id").to_string();
    let page = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/reports/saved-views/{view_id}/trends"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "r05f-page",
                    "grain": "PAGE",
                    "caller_amount": 1,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("page grain");
    assert_eq!(page.status(), axum::http::StatusCode::BAD_REQUEST);
    let (left, right) = tokio::join!(
        tower::ServiceExt::oneshot(
            app.clone(),
            axum::http::Request::builder()
                .method("POST")
                .uri(format!(
                    "/v1/tenants/{tenant_id}/reports/saved-views/{view_id}/trends"
                ))
                .header("content-type", "application/json")
                .header("authorization", format!("Bearer {token}"))
                .body(axum::body::Body::from(
                    serde_json::json!({
                        "request_id": "r05f-a",
                        "grain": "MONTH",
                        "caller_amount": 999999,
                    })
                    .to_string(),
                ))
                .expect("request"),
        ),
        tower::ServiceExt::oneshot(
            app,
            axum::http::Request::builder()
                .method("POST")
                .uri(format!(
                    "/v1/tenants/{tenant_id}/reports/saved-views/{view_id}/trends"
                ))
                .header("content-type", "application/json")
                .header("authorization", format!("Bearer {token}"))
                .body(axum::body::Body::from(
                    serde_json::json!({
                        "request_id": "r05f-b",
                        "grain": "MONTH",
                        "caller_amount": 1,
                    })
                    .to_string(),
                ))
                .expect("request"),
        ),
    );
    let left = left.expect("left");
    let right = right.expect("right");
    let ok = [left.status(), right.status()]
        .iter()
        .filter(|status| **status == axum::http::StatusCode::OK)
        .count();
    assert_eq!(ok, 1);
    let winner = if left.status() == axum::http::StatusCode::OK {
        left
    } else {
        right
    };
    let winner_bytes = http_body_util::BodyExt::collect(winner.into_body())
        .await
        .expect("winner body")
        .to_bytes();
    let winner_body: serde_json::Value = serde_json::from_slice(&winner_bytes).expect("winner json");
    assert_eq!(winner_body["caller_amount_used"], false);
    assert_eq!(winner_body["grain"], "MONTH");
    assert_eq!(winner_body["bucket_count"], 2);
    let buckets: Vec<(String, String, String, i64, i64)> = sqlx::query_as(
        "select bucket, grain, measure, amount_cent, qty from saved_report_trend_buckets where tenant_id = $1 and view_id = $2 order by bucket",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&view_id).expect("view uuid"))
    .fetch_all(&pool)
    .await
    .expect("buckets");
    assert_eq!(buckets.len(), 2);
    assert_eq!(buckets[0].0, "2026-10");
    assert_eq!(buckets[1].0, "2026-11");
    assert!(buckets.iter().all(|row| row.1 == "MONTH" && row.2 == "amount_cent"));
    assert_eq!(buckets[0].3, 12000);
    assert_eq!(buckets[1].3, 8000);
    assert_eq!(buckets[0].4, 3);
    assert_eq!(buckets[1].4, 1);
    let amount_sum: i64 = buckets.iter().map(|row| row.3).sum();
    let qty_sum: i64 = buckets.iter().map(|row| row.4).sum();
    assert_eq!(amount_sum, 20000);
    assert_eq!(qty_sum, 4);
    let receipts: Vec<String> = sqlx::query_scalar(
        "select request_id from command_receipts where tenant_id = $1 and request_id like 'r05f-%' order by request_id",
    )
    .bind(tenant_id)
    .fetch_all(&pool)
    .await
    .expect("receipts");
    assert!(!receipts.iter().any(|id| id == "r05f-page"));
    let stored = receipts
        .iter()
        .filter(|id| *id == "r05f-a" || *id == "r05f-b")
        .count();
    assert_eq!(stored, 1);
}

