async fn cash_entry_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("cash-entry-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'f02s-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let customer = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    sqlx::query("insert into customers(customer_id, tenant_id, name) values ($1, $2, 'C-F02S')")
        .bind(customer)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("customer");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-F02S')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'WH-F02S', 'WH-F02S')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("cash-entry-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let sale = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/sales-orders"),
        serde_json::json!({
            "request_id": "f02s-sale",
            "sales_order_no": "SO-F02S",
            "source_type": "TRADE",
            "customer_id": customer,
            "partner_code": "CUST-F02S",
            "currency_code": "CNY",
            "items": [{
                "sku_id": sku,
                "qty": 1,
                "price_cent": 600,
                "warehouse_id": warehouse,
            }],
        }),
    )
    .await;
    assert_eq!(sale.0, axum::http::StatusCode::OK, "{:?}", sale.1);
    let sale_id = serde_json::from_slice::<serde_json::Value>(&sale.1).expect("sale")["sales_order_id"]
        .as_str()
        .expect("sale id")
        .to_string();
    let opened = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/document-balances"),
        serde_json::json!({
            "request_id": "f02s-open",
            "document_id": sale_id,
            "document_kind": "SALES",
            "due_date": "2026-10-31",
        }),
    )
    .await;
    assert_eq!(opened.0, axum::http::StatusCode::OK, "{:?}", opened.1);
    let balance_id = serde_json::from_slice::<serde_json::Value>(&opened.1).expect("open")["effect_id"]
        .as_str()
        .expect("balance")
        .to_string();
    let first_receipt = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/finance/cash-entries"),
        serde_json::json!({
            "request_id": "f02s-400",
            "direction": "RECEIPT",
            "partner_code": "CUST-F02S",
            "currency": "CNY",
            "account_code": "CASH",
            "amount_cent": 400,
            "balance_id": balance_id,
        }),
    )
    .await;
    assert_eq!(first_receipt.0, axum::http::StatusCode::OK, "{:?}", first_receipt.1);
    let collect = |app: axum::Router, request_id: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let balance = balance_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/finance/cash-entries"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request_id,
                            "direction": "RECEIPT",
                            "partner_code": "CUST-F02S",
                            "currency": "CNY",
                            "account_code": "CASH",
                            "amount_cent": 200,
                            "balance_id": balance,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (left, right) = tokio::join!(collect(app.clone(), "f02s-a"), collect(app, "f02s-b"));
    let winners = [&left, &right]
        .into_iter()
        .filter(|result| result.0 == axum::http::StatusCode::OK)
        .count();
    assert_eq!(winners, 1, "two receipts take one remainder: {left:?} {right:?}");
    let settled: i64 = sqlx::query_scalar(
        "select settled_cent from partner_balances where tenant_id = $1 and balance_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&balance_id).expect("balance uuid"))
    .fetch_one(&pool)
    .await
    .expect("settled");
    assert_eq!(settled, 600);
    let cash: i64 = sqlx::query_scalar(
        "select count(*) from cash_entries where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("cash");
    assert_eq!(cash, 2);
    let bank: bool = sqlx::query_scalar(
        "select bool_or(bank_executed) from cash_entries where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("bank");
    assert!(!bank);
}

