async fn sampling_trend_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("sampling-trend-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q04p-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("sampling-trend-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, body: serde_json::Value| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/sampling-decisions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let rule = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/quality/sampling-rules"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "q04p-rule",
                    "rule_code": "AQL-Q04P",
                    "rule_version": 1,
                    "sample_size": 20,
                    "accept_number": 1,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("rule");
    assert_eq!(rule.status(), axum::http::StatusCode::OK);
    for (request, period, defects) in [
        ("q04p-08", "2026-08", 0),
        ("q04p-09", "2026-09", 1),
        ("q04p-10", "2026-10", 2),
    ] {
        let saved = post(
            app.clone(),
            serde_json::json!({
                "request_id": request,
                "rule_code": "AQL-Q04P",
                "rule_version": 1,
                "period_code": period,
                "defects": defects,
            }),
        )
        .await;
        assert_eq!(saved, axum::http::StatusCode::OK, "{request}");
    }
    let read = |app: axum::Router, from_period: &'static str, to_period: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/quality/sampling-trends?rule_code=AQL-Q04P&from_period={from_period}&to_period={to_period}"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
            (status, json)
        }
    };
    let (empty_status, _) = read(app.clone(), "2026-01", "2026-02").await;
    assert_eq!(empty_status, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let (first_status, first) = read(app.clone(), "2026-09", "2026-10").await;
    let (second_status, second) = read(app, "2026-09", "2026-10").await;
    assert_eq!(first_status, axum::http::StatusCode::OK, "{first}");
    assert_eq!(second_status, axum::http::StatusCode::OK);
    assert_eq!(first, second);
    let periods: Vec<String> = first["items"]
        .as_array()
        .expect("items")
        .iter()
        .filter_map(|item| item["period_code"].as_str().map(str::to_string))
        .collect();
    assert_eq!(periods, vec!["2026-09".to_string(), "2026-10".to_string()]);
    assert_eq!(first["items"][0]["defect_ppm"], 50_000);
    assert_eq!(first["items"][0]["accepted"], true);
    assert_eq!(first["items"][1]["defect_ppm"], 100_000);
    assert_eq!(first["items"][1]["accepted"], false);
    let decisions: i64 = sqlx::query_scalar(
        "select count(*) from mfg_sampling_decisions where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("decisions");
    assert_eq!(decisions, 3);
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 4);
    let recalls: i64 = sqlx::query_scalar(
        "select count(*) from mfg_recalls where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("recalls");
    assert_eq!(recalls, 0);
    let august: i64 = sqlx::query_scalar(
        "select defect_ppm from mfg_sampling_decisions where tenant_id = $1 and period_code = '2026-08'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("august");
    assert_eq!(august, 0);
}

