async fn recall_notice_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("recall-notice-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q04n-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("recall-notice-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let rule = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/sampling-rules"),
        serde_json::json!({
            "request_id": "q04n-rule",
            "rule_code": "AQL-Q04N",
            "rule_version": 1,
            "sample_size": 20,
            "accept_number": 1,
        }),
    )
    .await;
    assert_eq!(rule.0, axum::http::StatusCode::OK);
    let consume = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/genealogy-edges"),
        serde_json::json!({
            "request_id": "q04n-use",
            "source_action": "CONSUME",
            "input_code": "RAW-Q04N",
            "output_code": "FG-Q04N",
            "qty": "1",
            "work_order_no": "WO-Q04N",
            "output_batch": "FG-Q04N",
        }),
    )
    .await;
    assert_eq!(consume.0, axum::http::StatusCode::OK);
    let shipped = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/genealogy-edges"),
        serde_json::json!({
            "request_id": "q04n-ship",
            "source_action": "DELIVER",
            "input_code": "FG-Q04N",
            "output_code": "FG-Q04N",
            "qty": "1",
            "work_order_no": "WO-Q04N",
            "output_batch": "FG-Q04N",
            "customer_code": "CUST-Q04N",
        }),
    )
    .await;
    assert_eq!(shipped.0, axum::http::StatusCode::OK);
    let (opened, open_body) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/recalls"),
        serde_json::json!({
            "request_id": "q04n-open",
            "input_batch": "RAW-Q04N",
            "rule_code": "AQL-Q04N",
            "rule_version": 1,
            "stock_qty": "2",
            "node_cap": 64,
        }),
    )
    .await;
    assert_eq!(opened, axum::http::StatusCode::OK);
    let open_json: serde_json::Value = serde_json::from_slice(&open_body).expect("open body");
    let recall_id = open_json["effect_id"].as_str().expect("recall id").to_string();
    let missing = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/recalls/{recall_id}/results"),
        serde_json::json!({
            "request_id": "q04n-none",
            "item_kind": "CUSTOMER",
            "item_code": "MISSING-Q04N",
            "field": "notice",
            "status": "DONE",
            "warehouse_id": warehouse,
            "location_id": location,
            "sku_id": sku,
        }),
    )
    .await;
    assert_eq!(missing.0, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let notice = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let recall = recall_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/recalls/{recall}/results"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "item_kind": "CUSTOMER",
                            "item_code": "CUST-Q04N",
                            "field": "notice",
                            "status": "DONE",
                            "warehouse_id": warehouse,
                            "location_id": location,
                            "sku_id": sku,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(notice(app.clone(), "q04n-a"), notice(app, "q04n-b"));
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two notices store one result: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let customer: (String, String) = sqlx::query_as(
        "select freeze_status, notice_status from mfg_recall_items where tenant_id = $1 and item_kind = 'CUSTOMER' and item_code = 'CUST-Q04N'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("customer");
    assert_eq!(customer.0, "PENDING");
    assert_eq!(customer.1, "DONE");
    let stock: (String, String) = sqlx::query_as(
        "select freeze_status, notice_status from mfg_recall_items where tenant_id = $1 and item_kind = 'STOCK'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(stock.0, "PENDING");
    assert_eq!(stock.1, "PENDING");
    let ledgers: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("ledgers");
    assert_eq!(ledgers, 0);
    let refused_receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'q04n-none'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("missing");
    assert_eq!(refused_receipts, 0);
    let winners: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('q04n-a', 'q04n-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("winner");
    assert_eq!(winners, 1);
}

