async fn sampling_decision_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("sampling-decision-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q04k-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("sampling-decision-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let saved = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/sampling-rules"),
        serde_json::json!({
            "request_id": "q04k-rule",
            "rule_code": "AQL-Q04K",
            "rule_version": 1,
            "sample_size": 20,
            "accept_number": 1,
        }),
    )
    .await;
    assert_eq!(saved, axum::http::StatusCode::OK);
    let missing = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/sampling-decisions"),
        serde_json::json!({
            "request_id": "q04k-none",
            "rule_code": "AQL-Q04K",
            "rule_version": 9,
            "period_code": "2026-09",
            "defects": 1,
        }),
    )
    .await;
    assert_eq!(missing, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let judge = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/sampling-decisions"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "rule_code": "AQL-Q04K",
                            "rule_version": 1,
                            "period_code": "2026-09",
                            "defects": 1,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(judge(app.clone(), "q04k-a"), judge(app.clone(), "q04k-b"));
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two first decisions store one: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let stored: (i64, i64, i64, bool, i64) = sqlx::query_as(
        r#"
        select count(*)::bigint, min(sample_size), min(accept_number), bool_and(accepted), min(defect_ppm)
        from mfg_sampling_decisions
        where tenant_id = $1 and rule_code = 'AQL-Q04K' and period_code = '2026-09'
        "#,
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("decision");
    assert_eq!(stored.0, 1);
    assert_eq!(stored.1, 20);
    assert_eq!(stored.2, 1);
    assert!(stored.3);
    assert_eq!(stored.4, 50_000);
    let none: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'q04k-none'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("missing rule");
    assert_eq!(none, 0);
    let winners: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('q04k-a', 'q04k-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("winner");
    assert_eq!(winners, 1);
    let rule_accept: i64 = sqlx::query_scalar(
        "select accept_number from shared_sampling_rules where tenant_id = $1 and rule_code = 'AQL-Q04K'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("rule");
    assert_eq!(rule_accept, 1);
}

