async fn sampling_rule_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("sampling-rule-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q04j-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("sampling-rule-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, request: &'static str, version: i32, accept: i64| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/sampling-rules"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "rule_code": "AQL-Q04J",
                            "rule_version": version,
                            "sample_size": 20,
                            "accept_number": accept,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let over = post(app.clone(), "q04j-over", 1, 21).await;
    assert_eq!(over, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let (first, second) = tokio::join!(
        post(app.clone(), "q04j-a", 1, 1),
        post(app.clone(), "q04j-b", 1, 1),
    );
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two first saves store one version: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let later = post(app.clone(), "q04j-v2", 2, 3).await;
    assert_eq!(later, axum::http::StatusCode::OK);
    let rows: Vec<(i32, i64, i64)> = sqlx::query_as(
        r#"
        select rule_version, sample_size, accept_number
        from shared_sampling_rules
        where tenant_id = $1 and rule_code = 'AQL-Q04J'
        order by rule_version
        "#,
    )
    .bind(tenant_id)
    .fetch_all(&pool)
    .await
    .expect("rules");
    assert_eq!(rows, vec![(1, 20, 1), (2, 20, 3)]);
    let over_receipt: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'q04j-over'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("over receipt");
    assert_eq!(over_receipt, 0);
    let decisions: i64 = sqlx::query_scalar(
        "select count(*) from mfg_sampling_decisions where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("decisions");
    assert_eq!(decisions, 0);
}

