async fn genealogy_delivery_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("genealogy-delivery-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q03f-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("genealogy-delivery-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, body: serde_json::Value| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/genealogy-edges"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let missing = post(
        app.clone(),
        serde_json::json!({
            "request_id": "q03f-none",
            "source_action": "DELIVER",
            "input_code": "SER-Q03F",
            "output_code": "FG-Q03F",
            "qty": "1",
            "work_order_no": "WO-Q03F",
            "output_batch": "BATCH-Q03F",
        }),
    )
    .await;
    assert_eq!(missing, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let deliver = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/genealogy-edges"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "source_action": "DELIVER",
                            "input_code": "SER-Q03F",
                            "output_code": "FG-Q03F",
                            "qty": "1",
                            "work_order_no": "WO-Q03F",
                            "output_batch": "BATCH-Q03F",
                            "customer_code": "CUST-Q03F",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(
        deliver(app.clone(), "q03f-a"),
        deliver(app.clone(), "q03f-b"),
    );
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two deliveries store one: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let returned = post(
        app.clone(),
        serde_json::json!({
            "request_id": "q03f-ret",
            "source_action": "RETURN",
            "input_code": "BATCH-Q03F",
            "output_code": "FG-Q03F",
            "qty": "1",
            "work_order_no": "WO-Q03F",
            "output_batch": "BATCH-Q03F",
            "customer_code": "CUST-Q03F",
        }),
    )
    .await;
    assert_eq!(returned, axum::http::StatusCode::OK);
    let reversed = post(
        app.clone(),
        serde_json::json!({
            "request_id": "q03f-rev",
            "source_action": "DELIVER_REVERSAL",
            "input_code": "SER-Q03F",
            "output_code": "FG-Q03F",
            "qty": "-1",
            "work_order_no": "WO-Q03F",
            "output_batch": "BATCH-Q03F",
            "customer_code": "CUST-Q03F",
        }),
    )
    .await;
    assert_eq!(reversed, axum::http::StatusCode::OK);
    let rows: Vec<(String, i64, String, bool)> = sqlx::query_as(
        r#"
        select source_action, qty_micros, customer_code, reversed
        from mfg_genealogy_edges
        where tenant_id = $1 and work_order_no = 'WO-Q03F'
        order by source_action
        "#,
    )
    .bind(tenant_id)
    .fetch_all(&pool)
    .await
    .expect("edges");
    assert_eq!(rows.len(), 3);
    assert!(rows.iter().any(|row| row.0 == "DELIVER" && row.1 == 1_000_000 && row.2 == "CUST-Q03F" && !row.3));
    assert!(rows.iter().any(|row| row.0 == "RETURN" && row.1 == 1_000_000 && row.2 == "CUST-Q03F" && !row.3));
    assert!(rows.iter().any(|row| row.0 == "DELIVER_REVERSAL" && row.1 == -1_000_000 && row.2 == "CUST-Q03F" && row.3));
    let none: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('q03f-none', 'q03f-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused receipts");
    assert_eq!(none, 0);
    let receipts: Vec<String> = sqlx::query_scalar(
        "select request_id from command_receipts where tenant_id = $1 order by request_id",
    )
    .bind(tenant_id)
    .fetch_all(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, vec!["q03f-a".to_string(), "q03f-ret".to_string(), "q03f-rev".to_string()]);
}

