async fn genealogy_edge_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("genealogy-edge-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q03e-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("genealogy-edge-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, body: serde_json::Value| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/genealogy-edges"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let planned = post(
        app.clone(),
        serde_json::json!({
            "request_id": "q03e-plan",
            "source_action": "PLANNED_BOM",
            "input_code": "RAW-Q03E",
            "output_code": "FG-Q03E",
            "qty": "1",
            "work_order_no": "WO-Q03E",
            "output_batch": "BATCH-Q03E",
        }),
    )
    .await;
    assert_eq!(planned, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let edge = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/genealogy-edges"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "source_action": "CONSUME",
                            "input_code": "SER-Q03E",
                            "output_code": "FG-Q03E",
                            "qty": "2",
                            "work_order_no": "WO-Q03E",
                            "output_batch": "BATCH-Q03E",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(edge(app.clone(), "q03e-a"), edge(app.clone(), "q03e-b"));
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two writes of one consume store one: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let stored: (i64, i64, bool) = sqlx::query_as(
        r#"
        select count(*)::bigint, min(qty_micros), bool_or(reversed)
        from mfg_genealogy_edges
        where tenant_id = $1 and work_order_no = 'WO-Q03E'
        "#,
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("edge");
    assert_eq!(stored.0, 1);
    assert_eq!(stored.1, 2_000_000);
    assert!(!stored.2);
    let planned_receipt: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'q03e-plan'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("planned receipt");
    assert_eq!(planned_receipt, 0);
    let read = |app: axum::Router, direction: &'static str, code: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/quality/genealogy-edges?direction={direction}&code={code}&limit=10&node_cap=64"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
            (status, json)
        }
    };
    let (forward_status, forward) = read(app.clone(), "input", "SER-Q03E").await;
    assert_eq!(forward_status, axum::http::StatusCode::OK, "{forward}");
    assert_eq!(forward["items"].as_array().map(Vec::len), Some(1));
    assert_eq!(forward["items"][0]["output_batch"], "BATCH-Q03E");
    assert_eq!(forward["items"][0]["qty_micros"], 2_000_000);
    assert_eq!(forward["incomplete"], false);
    let (reverse_status, reverse) = read(app, "output", "BATCH-Q03E").await;
    assert_eq!(reverse_status, axum::http::StatusCode::OK, "{reverse}");
    assert_eq!(reverse["items"].as_array().map(Vec::len), Some(1));
    assert_eq!(reverse["items"][0]["input_code"], "SER-Q03E");
    assert_eq!(reverse["items"][0]["edge_id"], forward["items"][0]["edge_id"]);
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1);
}

