async fn quality_release_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("quality-release-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'q01h-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'q01h', 'Q01H')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-Q01H')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("quality-release-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
            (status, json)
        }
    };
    let (saved_status, saved_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"),
        serde_json::json!({
            "request_id": "q01h-plan",
            "work_order_no": "WO-Q01H",
            "product_code": "FG-Q01H",
            "order_qty": "1",
        }),
    )
    .await;
    assert_eq!(saved_status, axum::http::StatusCode::OK);
    let work_order_id = saved_json["effect_id"].as_str().expect("order").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order id");
    SharedContractRepo::new(&pool)
        .transition_saved_work_order(TenantId(tenant_id), "q01h-rel", "q01h-rel", order_id, "release")
        .await
        .expect("status release")
        .expect("admit status release");
    let (report_status, report_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/reports"),
        serde_json::json!({
            "request_id": "q01h-rep",
            "operation_code": "CUT",
            "good_qty": "1",
            "rejected_qty": "0",
            "rework_qty": "0",
            "minutes": 10,
            "operator_id": "worker-q01h",
            "session_id": "session-q01h",
            "crew_code": "CREW-Q01H",
            "started_at": "2026-10-02T09:00:00Z",
            "ended_at": "2026-10-02T09:10:00Z",
            "previous_good_qty": "0",
        }),
    )
    .await;
    assert_eq!(report_status, axum::http::StatusCode::OK);
    let report_id = report_json["effect_id"].as_str().expect("report").to_string();
    let (template_status, template_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/inspection-templates"),
        serde_json::json!({
            "request_id": "q01h-tpl",
            "template_code": "TPL-Q01H",
            "kind": "FINAL",
            "lines": [{
                "item_code": "length",
                "required": true,
                "min_qty": "0",
                "max_qty": "2",
                "sample_count": 1,
            }],
        }),
    )
    .await;
    assert_eq!(template_status, axum::http::StatusCode::OK);
    let template_id = template_json["effect_id"].as_str().expect("template").to_string();
    let (freeze_status, freeze_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/inspection-freezes"),
        serde_json::json!({
            "request_id": "q01h-frz",
            "template_id": template_id,
            "source_kind": "WORK_ORDER",
            "source_id": work_order_id,
            "item_code": "FG-Q01H",
            "batch_code": "BATCH-Q01H",
        }),
    )
    .await;
    assert_eq!(freeze_status, axum::http::StatusCode::OK);
    let freeze_id = freeze_json["effect_id"].as_str().expect("freeze").to_string();
    let (reading_status, _) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/quality/inspection-freezes/{freeze_id}/readings"),
        serde_json::json!({
            "request_id": "q01h-read",
            "item_code": "length",
            "reading_qty": "1",
            "inspector": "inspector-q01h",
            "reviewer": "reviewer-q01h",
        }),
    )
    .await;
    assert_eq!(reading_status, axum::http::StatusCode::OK);
    let (held_status, held_json) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/receipts"),
        serde_json::json!({
            "request_id": "q01h-hold",
            "qty": "1",
            "status": "HOLD",
            "report_id": report_id,
            "batch_code": "BATCH-Q01H",
            "inspection_id": freeze_id,
            "warehouse_id": warehouse,
            "sku_id": sku,
        }),
    )
    .await;
    assert_eq!(held_status, axum::http::StatusCode::OK, "{held_json}");
    let receipt_id = held_json["effect_id"].as_str().expect("receipt").to_string();
    let release = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let receipt_id = receipt_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/quality/receipts/{receipt_id}/releases"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({ "request_id": request }).to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(release(app.clone(), "q01h-a"), release(app, "q01h-b"));
    eprintln!(
        "QA quality_source_direct case=review tenant={tenant_id} first_request=q01h-a first_status={} second_request=q01h-b second_status={}",
        first.as_u16(),
        second.as_u16()
    );
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two releases store one row: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let stored: (i64, String) = sqlx::query_as(
        "select count(*)::bigint, min(result) from mfg_quality_releases where tenant_id = $1 and receipt_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&receipt_id).expect("receipt id"))
    .fetch_one(&pool)
    .await
    .expect("release");
    assert_eq!(stored.0, 1);
    assert_eq!(stored.1, "RELEASED");
    let pair: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('q01h-a','q01h-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("pair");
    assert_eq!(pair, 1);
}

