async fn board_complete_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("board-complete-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm17g-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("board-complete-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, uri: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, bytes)
        }
    };
    let (saved_status, saved_bytes) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"),
        serde_json::json!({
            "request_id": "m17g-plan",
            "work_order_no": "WO-M17G",
            "product_code": "FG-M17G",
            "order_qty": "10",
        }),
    )
    .await;
    assert_eq!(saved_status, axum::http::StatusCode::OK);
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    let (queued_status, queued_bytes) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/board-refreshes"),
        serde_json::json!({ "request_id": "m17g-job" }),
    )
    .await;
    assert_eq!(queued_status, axum::http::StatusCode::OK);
    let queued_json: serde_json::Value = serde_json::from_slice(&queued_bytes).expect("queue json");
    let task_id = queued_json["effect_id"].as_str().expect("task").to_string();
    let (claim_status, _) = post(
        app.clone(),
        format!("/v1/tenants/{tenant_id}/manufacturing/board-refreshes/{task_id}/claims"),
        serde_json::json!({
            "request_id": "m17g-claim",
            "owner": "board-m17g",
            "lease_seconds": 60,
        }),
    )
    .await;
    assert_eq!(claim_status, axum::http::StatusCode::OK);
    let before: i64 = sqlx::query_scalar("select count(*) from command_receipts where tenant_id = $1")
        .bind(tenant_id)
        .fetch_one(&pool)
        .await
        .expect("before");
    let finish = |app: axum::Router| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let task = task_id.clone();
        let work_order_id = work_order_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/board-refreshes/{task}/completions"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "work_order_id": work_order_id,
                            "owner": "board-m17g",
                            "today": "2026-10-02",
                            "due_date": "2026-10-03",
                            "minutes_per_day": 60,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
            (status, json["snapshot_id"].as_str().map(str::to_string))
        }
    };
    let (first, second) = tokio::join!(finish(app.clone()), finish(app));
    let ok = [&first, &second]
        .into_iter()
        .filter(|(status, _)| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [&first, &second]
        .into_iter()
        .filter(|(status, _)| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two completions store one snapshot: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let snapshots: i64 = sqlx::query_scalar(
        "select count(*) from mfg_board_snapshots where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("snapshots");
    assert_eq!(snapshots, 1);
    let status: String = sqlx::query_scalar(
        "select status from durable_tasks where tenant_id = $1 and task_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&task_id).expect("task id"))
    .fetch_one(&pool)
    .await
    .expect("task");
    assert_eq!(status, "DONE");
    let after: i64 = sqlx::query_scalar("select count(*) from command_receipts where tenant_id = $1")
        .bind(tenant_id)
        .fetch_one(&pool)
        .await
        .expect("after");
    assert_eq!(after, before);
}

