async fn board_refresh_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("board-refresh-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm17e-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let jwt = erp_api::JwtService::new("board-refresh-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m17e-plan",
                    "work_order_no": "WO-M17E",
                    "product_code": "FG-M17E",
                    "order_qty": "10",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    let refresh = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/board-refreshes"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({ "request_id": request }).to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(refresh(app.clone(), "m17e-a"), refresh(app, "m17e-b"));
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two refreshes queue one task: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let tasks: (i64, String, String) = sqlx::query_as(
        r#"
        select count(*)::bigint, min(status), min(event_id)
        from durable_tasks
        where tenant_id = $1 and event_id = $2
        "#,
    )
    .bind(tenant_id)
    .bind(format!("board-refresh:{order_id}"))
    .fetch_one(&pool)
    .await
    .expect("task");
    assert_eq!(tasks.0, 1);
    assert_eq!(tasks.1, "QUEUED");
    assert_eq!(tasks.2, format!("board-refresh:{order_id}"));
    let snapshots: i64 = sqlx::query_scalar(
        "select count(*) from mfg_board_snapshots where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("snapshots");
    assert_eq!(snapshots, 0);
    let pair: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m17e-a','m17e-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("pair");
    assert_eq!(pair, 1);
}

