async fn backflush_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("backflush-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm16c-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'm16c', 'M16C')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-M16C')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("backflush-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m16c-plan",
                    "work_order_no": "WO-M16C",
                    "product_code": "FG-M16C",
                    "order_qty": "1",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    let repo = SharedContractRepo::new(&pool);
    repo.transition_saved_work_order(TenantId(tenant_id), "m16c-rel", "m16c-rel", order_id, "release")
        .await
        .expect("status release")
        .expect("admit status release");
    repo.post_inventory_inbound(
        TenantId(tenant_id),
        "m16c-in",
        "m16c-in",
        warehouse,
        sku,
        5,
        Some("m16c".into()),
    )
    .await
    .expect("inbound")
    .expect("admit inbound");
    let material = |app: axum::Router, request: &'static str, kind: &'static str, qty: &'static str, original: Option<String>| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        async move {
            let mut body = serde_json::json!({
                "request_id": request,
                "kind": kind,
                "qty": qty,
                "warehouse_id": warehouse,
                "sku_id": sku,
            });
            if let Some(original) = original {
                body["original_issue_id"] = serde_json::Value::String(original);
            }
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/materials"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            assert_eq!(response.status(), axum::http::StatusCode::OK, "{request}");
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).expect("json");
            json["move_id"].as_str().expect("move").to_string()
        }
    };
    let issue_id = material(app.clone(), "m16c-iss", "ISSUE", "5", None).await;
    let _hand = material(app.clone(), "m16c-hand", "CONSUME", "2", Some(issue_id)).await;
    let flush = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/backflushes"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "standard_qty": "5",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(flush(app.clone(), "m16c-a"), flush(app, "m16c-b"));
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two backflushes store one remainder: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let posted: (i64, i64) = sqlx::query_as(
        r#"
        select count(*)::bigint, coalesce(sum(qty_micros), 0)::bigint
        from mfg_material_moves
        where tenant_id = $1 and work_order_id = $2 and kind = 'CONSUME' and reason = 'BACKFLUSH'
        "#,
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("backflush");
    assert_eq!(posted.0, 1);
    assert_eq!(posted.1, 3_000_000);
    let consumed: i64 = sqlx::query_scalar(
        "select consumed_micros from mfg_work_orders where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("consumed");
    assert_eq!(consumed, 5_000_000);
    let pair: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m16c-a','m16c-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("pair");
    assert_eq!(pair, 1);
}

