async fn engineering_impact_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("engineering-impact-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm15i-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'm15i', 'M15I')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-M15I')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("engineering-impact-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let bom = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/boms"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15i-bom",
                    "product_code": "FG-M15I",
                    "items": [{"parent": "FG-M15I", "component": "A", "qty_per": "1"}],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("bom");
    assert_eq!(bom.status(), axum::http::StatusCode::OK);
    let bom_bytes = http_body_util::BodyExt::collect(bom.into_body())
        .await
        .expect("bom body")
        .to_bytes();
    let bom_json: serde_json::Value = serde_json::from_slice(&bom_bytes).expect("bom json");
    let bom_id = bom_json["effect_id"].as_str().expect("bom").to_string();
    let save_order = |app: axum::Router, request: &'static str, work_order_no: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let bom_id = bom_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/work-orders"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "work_order_no": work_order_no,
                            "product_code": "FG-M15I",
                            "bom_id": bom_id,
                            "order_qty": "1",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            assert_eq!(response.status(), axum::http::StatusCode::OK);
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).expect("json");
            json["effect_id"].as_str().expect("effect").to_string()
        }
    };
    let planned_id = save_order(app.clone(), "m15i-plan", "WO-M15I").await;
    let issued_id = save_order(app.clone(), "m15i-run", "WO-M15R").await;
    let repo = SharedContractRepo::new(&pool);
    repo.transition_saved_work_order(
        TenantId(tenant_id),
        "m15i-rel",
        "m15i-rel",
        uuid::Uuid::parse_str(&issued_id).expect("issued"),
        "release",
    )
    .await
    .expect("status release")
    .expect("admit status release");
    repo.post_inventory_inbound(
        TenantId(tenant_id),
        "m15i-in",
        "m15i-in",
        warehouse,
        sku,
        1,
        Some("m15i".into()),
    )
    .await
    .expect("inbound")
    .expect("admit inbound");
    let issued = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/manufacturing/work-orders/{issued_id}/materials"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15i-iss",
                    "kind": "ISSUE",
                    "qty": "1",
                    "warehouse_id": warehouse,
                    "sku_id": sku,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("issue");
    assert_eq!(issued.status(), axum::http::StatusCode::OK);
    let before: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("before");
    let read = |app: axum::Router| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/engineering-impacts?original_code=A"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            assert_eq!(response.status(), axum::http::StatusCode::OK);
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            serde_json::from_slice::<serde_json::Value>(&bytes).expect("json")
        }
    };
    let (first, second) = tokio::join!(read(app.clone()), read(app));
    assert_eq!(first, second);
    let orders = first["orders"].as_array().expect("orders");
    assert_eq!(orders.len(), 2);
    let planned = orders.iter().find(|row| row["work_order_no"] == "WO-M15I").expect("planned");
    let started = orders.iter().find(|row| row["work_order_no"] == "WO-M15R").expect("started");
    assert_eq!(planned["status"], "PLANNED");
    assert_eq!(planned["issued_micros"], 0);
    assert_eq!(started["status"], "RELEASED");
    assert_eq!(started["issued_micros"], 1_000_000);
    let after: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("after");
    assert_eq!(after, before, "a read stores no receipt");
    let changes: i64 = sqlx::query_scalar(
        "select count(*) from mfg_engineering_changes where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("changes");
    assert_eq!(changes, 0);
    let _ = planned_id;
}

#[test]
fn routing_change_http_race_read_back() {
    std::thread::Builder::new()
        .name("routing-change-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(routing_change_http_race_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("routing change http thread");
}

async fn routing_change_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("routing-change-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm15h-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("routing-change-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let routing = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/routings"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m15h-rte",
                    "product_code": "FG-M15H",
                    "steps": [{
                        "operation": "assemble",
                        "sequence": 10,
                        "work_center": "LINE-M15",
                        "minutes_per": 12,
                        "inspection_required": false,
                    }],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("routing");
    assert_eq!(routing.status(), axum::http::StatusCode::OK);
    let publish = |app: axum::Router, request: &'static str, minutes: i64, approver: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/routing-changes"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "product_code": "FG-M15H",
                            "approver": approver,
                            "steps": [{
                                "operation": "assemble",
                                "sequence": 10,
                                "work_center": "LINE-M15",
                                "minutes_per": minutes,
                                "inspection_required": false,
                            }],
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let blank = publish(app.clone(), "m15h-none", 18, "").await;
    assert_eq!(blank, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let (first, second) = tokio::join!(
        publish(app.clone(), "m15h-a", 18, "planner"),
        publish(app, "m15h-b", 18, "planner"),
    );
    let ok = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first, second]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two routing changes store one version: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let versions: i64 = sqlx::query_scalar(
        "select count(distinct version_no) from mfg_routing_versions where tenant_id = $1 and product_code = 'FG-M15H'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, 1);
    let new_minutes: i64 = sqlx::query_scalar(
        "select minutes_per from mfg_routing_versions where tenant_id = $1 and product_code = 'FG-M15H'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("new minutes");
    assert_eq!(new_minutes, 18);
    let old_minutes: i64 = sqlx::query_scalar(
        "select minutes_per from mfg_routings where tenant_id = $1 and product_code = 'FG-M15H' and version_no = 1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("old minutes");
    assert_eq!(old_minutes, 12);
    let diffs: (String, i64, i64) = sqlx::query_as(
        "select change_kind, old_minutes, new_minutes from mfg_routing_diffs where tenant_id = $1 and product_code = 'FG-M15H'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("diff");
    assert_eq!(diffs.0, "CHANGED");
    assert_eq!(diffs.1, 12);
    assert_eq!(diffs.2, 18);
    let none: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'm15h-none'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("blank");
    assert_eq!(none, 0);
    let pair: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m15h-a','m15h-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("pair");
    assert_eq!(pair, 1);
}

