async fn subcontract_supplier_material_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("subcontract-supplier-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm14g-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let supplier = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("subcontract-supplier-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m14g-plan",
                    "work_order_no": "WO-M14G",
                    "product_code": "FG-M14G",
                    "order_qty": "4",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/subcontracts"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m14g-open",
                    "work_order_id": work_order_id,
                    "supplier_id": supplier,
                    "component_code": "COMP-M14G",
                    "our_material": false,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let opened_bytes = http_body_util::BodyExt::collect(opened.into_body())
        .await
        .expect("open body")
        .to_bytes();
    let opened_json: serde_json::Value = serde_json::from_slice(&opened_bytes).expect("open json");
    let subcontract_id = opened_json["effect_id"].as_str().expect("subcontract").to_string();
    let issue = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let subcontract_id = subcontract_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/subcontracts/{subcontract_id}/moves"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "kind": "ISSUE",
                            "qty": "4",
                            "fee_cent": 0,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            response.status()
        }
    };
    let (first, second) = tokio::join!(issue(app.clone(), "m14g-a"), issue(app, "m14g-b"));
    assert_eq!(first, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(second, axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let subcontract = uuid::Uuid::parse_str(&subcontract_id).expect("subcontract id");
    let ours: bool = sqlx::query_scalar(
        "select our_material from mfg_subcontract_orders where tenant_id = $1 and subcontract_id = $2",
    )
    .bind(tenant_id)
    .bind(subcontract)
    .fetch_one(&pool)
    .await
    .expect("our material");
    assert!(!ours);
    let moves: i64 = sqlx::query_scalar(
        "select count(*) from mfg_subcontract_movements where tenant_id = $1 and subcontract_id = $2",
    )
    .bind(tenant_id)
    .bind(subcontract)
    .fetch_one(&pool)
    .await
    .expect("moves");
    assert_eq!(moves, 0, "supplier-owned material is not issued as our title");
    let stock: i64 = sqlx::query_scalar(
        "select count(*) from shared_stock_ledgers where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(stock, 0);
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m14g-a','m14g-b')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

