    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm14f-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    let supplier = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("subcontract-loss-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m14f-plan",
                    "work_order_no": "WO-M14F",
                    "product_code": "FG-M14F",
                    "order_qty": "10",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/subcontracts"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m14f-open",
                    "work_order_id": work_order_id,
                    "supplier_id": supplier,
                    "component_code": "COMP-M14F",
                    "our_material": true,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let opened_bytes = http_body_util::BodyExt::collect(opened.into_body())
        .await
        .expect("open body")
        .to_bytes();
    let opened_json: serde_json::Value = serde_json::from_slice(&opened_bytes).expect("open json");
    let subcontract_id = opened_json["effect_id"].as_str().expect("subcontract").to_string();
    let move_once = |app: axum::Router, request: &'static str, kind: &'static str, qty: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let subcontract_id = subcontract_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/subcontracts/{subcontract_id}/moves"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "kind": kind,
                            "qty": qty,
                            "fee_cent": 0,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let issued = move_once(app.clone(), "m14f-iss", "ISSUE", "10").await;
    assert_eq!(issued.0, axum::http::StatusCode::OK, "{issued:?}");
    let (first, second) = tokio::join!(
        move_once(app.clone(), "m14f-a", "LOSS", "6"),
        move_once(app, "m14f-b", "LOSS", "6"),
    );
    let ok = [first.0, second.0]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::OK)
        .count();
    let refused = [first.0, second.0]
        .into_iter()
        .filter(|status| *status == axum::http::StatusCode::UNPROCESSABLE_ENTITY)
        .count();
    assert_eq!(ok, 1, "two losses share one supplier balance: {first:?} {second:?}");
    assert_eq!(refused, 1, "{first:?} {second:?}");
    let subcontract = uuid::Uuid::parse_str(&subcontract_id).expect("subcontract id");
    let lost: i64 = sqlx::query_scalar(
        "select coalesce(sum(qty_micros), 0)::bigint from mfg_subcontract_movements where tenant_id = $1 and subcontract_id = $2 and kind = 'LOSS'",
    )
    .bind(tenant_id)
    .bind(subcontract)
    .fetch_one(&pool)
    .await
    .expect("lost");
    assert_eq!(lost, 6_000_000);
    let issued_qty: i64 = sqlx::query_scalar(
        "select coalesce(sum(qty_micros), 0)::bigint from mfg_subcontract_movements where tenant_id = $1 and subcontract_id = $2 and kind = 'ISSUE'",
    )
    .bind(tenant_id)
    .bind(subcontract)
    .fetch_one(&pool)
    .await
    .expect("issued");
    assert_eq!(issued_qty, 10_000_000);
