async fn production_receipt_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("production-receipt-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm11a-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'm11a', 'M11A')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-M11A')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("production-receipt-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m11a-plan",
                    "work_order_no": "WO-M11A",
                    "product_code": "FG-M11A",
                    "order_qty": "10",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = saved_json["effect_id"].as_str().expect("effect").to_string();
    let order_id = uuid::Uuid::parse_str(&work_order_id).expect("order");
    let repo = SharedContractRepo::new(&pool);
    let (released, released_status) = repo
        .transition_saved_work_order(TenantId(tenant_id), "m11a-rel", "m11a-rel", order_id, "release")
        .await
        .expect("status release")
        .expect("admit status release");
    assert!(matches!(released, SharedWrite::Stored(_)));
    assert_eq!(released_status.as_str(), "RELEASED");
    let reported = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/reports"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m11a-cut",
                    "operation_code": "CUT",
                    "good_qty": "10",
                    "rejected_qty": "0",
                    "rework_qty": "0",
                    "minutes": 20,
                    "operator_id": "worker-m11a",
                    "session_id": "session-m11a",
                    "crew_code": "CREW-M11A",
                    "started_at": "2026-10-02T09:00:00Z",
                    "ended_at": "2026-10-02T09:20:00Z",
                    "previous_good_qty": "10",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("report");
    assert_eq!(reported.status(), axum::http::StatusCode::OK);
    let reported_bytes = http_body_util::BodyExt::collect(reported.into_body())
        .await
        .expect("report body")
        .to_bytes();
    let reported_json: serde_json::Value = serde_json::from_slice(&reported_bytes).expect("report json");
    let report_id = reported_json["effect_id"].as_str().expect("report effect").to_string();
    let receive = |app: axum::Router, request: &'static str, inspection: String| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.clone();
        let report_id = report_id.clone();
        let warehouse = warehouse.to_string();
        let sku = sku.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/receipts"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "qty": "6",
                            "status": "RELEASED",
                            "report_id": report_id,
                            "batch_code": "BATCH-M11A",
                            "inspection_id": inspection,
                            "warehouse_id": warehouse,
                            "sku_id": sku,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        receive(app.clone(), "m11a-a", uuid::Uuid::new_v4().to_string()),
        receive(app, "m11a-b", uuid::Uuid::new_v4().to_string()),
    );
    let stored = [&first, &second]
        .iter()
        .filter(|item| item.0 == axum::http::StatusCode::OK)
        .count();
    assert_eq!(
        stored,
        1,
        "two receipts of 6 against reported good 10 store one: {first:?} {second:?}"
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from mfg_receipts where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("receipt rows");
    assert_eq!(receipts, 1);
    let received: i64 = sqlx::query_scalar(
        "select coalesce(sum(qty_micros), 0)::bigint from mfg_receipts where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("received");
    assert_eq!(received, 6_000_000);
    let available: i64 = sqlx::query_scalar(
        "select coalesce(sum(available_micros), 0)::bigint from mfg_receipts where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("available");
    assert_eq!(available, 6_000_000);
    let on_hand: i64 = sqlx::query_scalar(
        "select coalesce(on_hand_micros, 0)::bigint from inventory_balances where tenant_id = $1 and warehouse_id = $2 and sku_id = $3",
    )
    .bind(tenant_id)
    .bind(warehouse)
    .bind(sku)
    .fetch_one(&pool)
    .await
    .expect("on hand");
    assert_eq!(on_hand, 6_000_000);
    let command_receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m11a-a','m11a-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("command receipts");
    assert_eq!(command_receipts, 1);
    let report_good: i64 = sqlx::query_scalar(
        "select coalesce(sum(good_micros), 0)::bigint from mfg_reports where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("report good");
    assert_eq!(report_good, 10_000_000, "receipt must not rewrite the report");
}

