async fn material_supplement_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    let tenant = TenantId(tenant_id);
    eprintln!("material-supplement-http-tenant {tenant_id:?}");
    let repo = SharedContractRepo::new(&pool);
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm09d-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let lines = [erp_domain::manufacturing::BomLine {
        parent: "FG-M09D".into(),
        component: "RAW-M09D".into(),
        qty_per: qty_text("1"),
        unit_code: "EA".into(),
        scrap_ppm: 0,
        supply: "MAKE".into(),
        line_no: 10,
    }];
    let (_, bom_id) = repo
        .save_bom_structure(tenant, "m09d-bom", "m09d-bom", "FG-M09D", &lines)
        .await
        .expect("structure")
        .expect("admit structure");
    let (_, version_id, _) = repo
        .publish_bom_version(tenant, "m09d-ver", "m09d-ver", "FG-M09D", bom_id, "2026-10-01", "", true)
        .await
        .expect("version")
        .expect("admit version");
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'm09d', 'M09D')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-M09D')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    repo.post_inventory_inbound(tenant, "m09d-in", "m09d-in", warehouse, sku, 2, Some("m09d".into()))
        .await
        .expect("inbound")
        .expect("admit inbound");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("material-supplement-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m09d-plan",
                    "work_order_no": "WO-M09D",
                    "product_code": "FG-M09D",
                    "order_qty": "4",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = uuid::Uuid::parse_str(saved_json["effect_id"].as_str().expect("effect")).expect("order");
    let released = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/actions"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m09d-rel",
                    "action": "release",
                    "version_id": version_id,
                    "warehouse_id": warehouse,
                    "sku_id": sku,
                    "qty": "1",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("release");
    assert_eq!(released.status(), axum::http::StatusCode::OK);
    let issued = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/manufacturing/work-orders/{work_order_id}/materials"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m09d-issue",
                    "kind": "ISSUE",
                    "qty": "1",
                    "warehouse_id": warehouse,
                    "sku_id": sku,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("issue");
    assert_eq!(issued.status(), axum::http::StatusCode::OK);
    let supplement = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.to_string();
        let warehouse = warehouse.to_string();
        let sku = sku.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders/{work_order_id}/materials"
                    ))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "kind": "SUPPLEMENT",
                            "qty": "1",
                            "reason": "scrap replacement",
                            "warehouse_id": warehouse,
                            "sku_id": sku,
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(supplement(app.clone(), "m09d-a"), supplement(app, "m09d-b"));
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m09d-a','m09d-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let issued_now: i64 = sqlx::query_scalar(
        "select issued_micros from mfg_work_orders where tenant_id = $1 and work_order_id = $2",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("issued");
    assert_eq!(issued_now, 2_000_000);
    let supplements: i64 = sqlx::query_scalar(
        "select count(*) from mfg_material_moves where tenant_id = $1 and work_order_id = $2 and kind = 'SUPPLEMENT'",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("supplements");
    assert_eq!(supplements, 1);
    let on_hand: i64 = sqlx::query_scalar(
        "select on_hand_micros from inventory_balances where tenant_id = $1 and warehouse_id = $2 and sku_id = $3",
    )
    .bind(tenant_id)
    .bind(warehouse)
    .bind(sku)
    .fetch_one(&pool)
    .await
    .expect("stock");
    assert_eq!(on_hand, 0, "the same free stock is not supplemented twice");
}

