#[test]
fn access_audit_http_read_back() {
    std::thread::Builder::new()
        .name("access-audit-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(access_audit_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("access audit http thread");
}

async fn access_audit_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    let other_id = uuid::Uuid::new_v4();
    eprintln!("access-audit-http-tenant {tenant_id:?}");
    eprintln!("access-audit-http-other {other_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o05d-http'), ($2, 'o05d-other')")
        .bind(tenant_id)
        .bind(other_id)
        .execute(&pool)
        .await
        .expect("tenants");
    let actor = uuid::Uuid::new_v4();
    let other_actor = uuid::Uuid::new_v4();
    eprintln!("access-audit-http-actor {actor:?}");
    eprintln!("access-audit-http-other-actor {other_actor:?}");
    let jwt = erp_api::JwtService::new("access-audit-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let other_token = jwt
        .encode(&erp_api::Claims::bearer(
            other_actor.to_string(),
            other_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            false,
            now,
            now + 3600,
        ))
        .expect("other token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let warehouse = uuid::Uuid::new_v4();

    let blank = grant_access_http(&app, tenant_id, &token, "o05d-blank", "", warehouse).await;
    assert_eq!(blank.status(), axum::http::StatusCode::BAD_REQUEST);
    let platform_grant = grant_access_http(
        &app, tenant_id, &token, "o05d-platform-grant", "platform.ops", warehouse,
    )
    .await;
    assert_eq!(platform_grant.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let granted = grant_access_http(
        &app, tenant_id, &token, "o05d-grant", "stock.read", warehouse,
    )
    .await;
    assert_eq!(granted.status(), axum::http::StatusCode::OK);
    let granted_body = json_body(granted).await;
    assert_eq!(granted_body["actor_user_id"], actor.to_string());
    let object = register_object_http(&app, tenant_id, &token, "o05d-print", "PRINT", warehouse).await;
    assert_eq!(object.status(), axum::http::StatusCode::OK);
    let object_body = json_body(object).await;
    let object_id = object_body["object_id"].as_str().expect("object").to_string();
    eprintln!("access-audit-http-object {object_id}");
    let secret = act_access_http(
        &app, tenant_id, &token, "o05d-secret", "stock.read", &object_id, "password=hidden", false, 30, true,
    )
    .await;
    assert_eq!(secret.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let allowed = act_access_http(
        &app, tenant_id, &token, "o05d-allow", "stock.read", &object_id, "print stock", false, 30, true,
    )
    .await;
    assert_eq!(allowed.status(), axum::http::StatusCode::OK);
    let allowed_body = json_body(allowed).await;
    assert_eq!(allowed_body["allowed"], true);
    assert_eq!(allowed_body["actor_user_id"], actor.to_string());
    let platform = act_access_http(
        &app, tenant_id, &token, "o05d-ops", "platform.ops", &object_id, "ops", false, 30, true,
    )
    .await;
    assert_eq!(platform.status(), axum::http::StatusCode::OK);
    let platform_body = json_body(platform).await;
    assert_eq!(platform_body["allowed"], false);
    let crossed = act_access_http(
        &app, other_id, &other_token, "o05d-cross", "stock.read", &object_id, "other tenant", false, 30, true,
    )
    .await;
    assert_eq!(crossed.status(), axum::http::StatusCode::OK);
    let crossed_body = json_body(crossed).await;
    assert_eq!(crossed_body["allowed"], false);
    assert_eq!(crossed_body["actor_user_id"], other_actor.to_string());
    let objects: i64 = sqlx::query_scalar(
        "select count(*) from access_objects where object_id = $1",
    )
    .bind(uuid::Uuid::parse_str(&object_id).expect("object uuid"))
    .fetch_one(&pool)
    .await
    .expect("objects");
    assert_eq!(objects, 1, "cross tenant must not copy the object");
    let copied: i64 = sqlx::query_scalar(
        "select count(*) from access_objects where tenant_id = $1 and object_id = $2",
    )
    .bind(other_id)
    .bind(uuid::Uuid::parse_str(&object_id).expect("object uuid"))
    .fetch_one(&pool)
    .await
    .expect("copied");
    assert_eq!(copied, 0);
    let secrets: i64 = sqlx::query_scalar(
        "select count(*) from access_audits where tenant_id = $1 and (summary ilike '%password%' or summary ilike '%token%' or summary ilike '%secret%')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("secrets");
    assert_eq!(secrets, 0);
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o05d-blank','o05d-platform-grant','o05d-secret')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

