#[test]
fn versioned_document_http_read_back() {
    std::thread::Builder::new()
        .name("versioned-document-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(versioned_document_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("versioned document http thread");
}

async fn versioned_document_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("versioned-document-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o04d-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    eprintln!("versioned-document-http-actor {actor:?}");
    let jwt = erp_api::JwtService::new("versioned-document-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);

    let blank = open_document_http(&app, tenant_id, &token, "o04d-blank", "").await;
    assert_eq!(blank.status(), axum::http::StatusCode::BAD_REQUEST);
    let opened = open_document_http(&app, tenant_id, &token, "o04d-open", "draft-o04d").await;
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let opened_body = json_body(opened).await;
    let document_id = opened_body["document_id"].as_str().expect("document").to_string();
    eprintln!("versioned-document-http-document {document_id}");
    assert_eq!(opened_body["version_no"], 1);
    let missing = uuid::Uuid::new_v4();
    let absent = save_document_http(
        &app, tenant_id, &token, &missing.to_string(), "o04d-missing", 1, "missing-o04d",
    )
    .await;
    assert_eq!(absent.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let (desktop, web) = tokio::join!(
        save_document_http(&app, tenant_id, &token, &document_id, "o04d-desktop", 1, "desktop-o04d"),
        save_document_http(&app, tenant_id, &token, &document_id, "o04d-web", 1, "web-o04d"),
    );
    assert_eq!(desktop.status(), axum::http::StatusCode::OK);
    assert_eq!(web.status(), axum::http::StatusCode::OK);
    let desktop_body = json_body(desktop).await;
    let web_body = json_body(web).await;
    let winner = if desktop_body["conflict"] == false { &desktop_body } else { &web_body };
    let loser = if desktop_body["conflict"] == false { &web_body } else { &desktop_body };
    assert_eq!(winner["conflict"], false);
    assert_eq!(winner["version_no"], 2);
    assert_eq!(loser["conflict"], true);
    let stored: (i64, String) = sqlx::query_as(
        "select version_no, body_text from versioned_documents where tenant_id = $1 and document_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&document_id).expect("document uuid"))
    .fetch_one(&pool)
    .await
    .expect("stored");
    assert_eq!(stored.0, 2);
    let kept: String = sqlx::query_scalar(
        "select kept_input from version_conflicts where tenant_id = $1 and document_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&document_id).expect("document uuid"))
    .fetch_one(&pool)
    .await
    .expect("kept");
    assert_ne!(kept, stored.1);
    assert!(kept == "desktop-o04d" || kept == "web-o04d");
    assert!(stored.1 == "desktop-o04d" || stored.1 == "web-o04d");
    let docs: i64 = sqlx::query_scalar(
        "select count(*) from versioned_documents where tenant_id = $1 and document_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&document_id).expect("document uuid"))
    .fetch_one(&pool)
    .await
    .expect("docs");
    let conflicts: i64 = sqlx::query_scalar(
        "select count(*) from version_conflicts where tenant_id = $1 and document_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&document_id).expect("document uuid"))
    .fetch_one(&pool)
    .await
    .expect("conflicts");
    assert_eq!((docs, conflicts), (1, 1));
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o04d-blank','o04d-missing')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

async fn open_document_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    request_id: &str,
    body_text: &str,
) -> axum::http::Response<axum::body::Body> {
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/documents"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": request_id,
                    "body_text": body_text,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open document")
}

async fn save_document_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    document_id: &str,
    request_id: &str,
    expected_version: i64,
    body_text: &str,
) -> axum::http::Response<axum::body::Body> {
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/documents/{document_id}"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": request_id,
                    "expected_version": expected_version,
                    "body_text": body_text,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save document")
}

#[test]
fn health_signal_http_read_back() {
    std::thread::Builder::new()
        .name("health-signal-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(health_signal_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("health signal http thread");
}

async fn health_signal_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    let other_id = uuid::Uuid::new_v4();
    eprintln!("health-signal-http-tenant {tenant_id:?}");
    eprintln!("health-signal-http-other {other_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o08c-http'), ($2, 'o08c-other')")
        .bind(tenant_id)
        .bind(other_id)
        .execute(&pool)
        .await
        .expect("tenants");
    let actor = uuid::Uuid::new_v4();
    let other_actor = uuid::Uuid::new_v4();
    eprintln!("health-signal-http-actor {actor:?}");
    eprintln!("health-signal-http-other-actor {other_actor:?}");
    let jwt = erp_api::JwtService::new("health-signal-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            false,
            now,
            now + 3600,
        ))
        .expect("token");
    let other_token = jwt
        .encode(&erp_api::Claims::bearer(
            other_actor.to_string(),
            other_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            false,
            now,
            now + 3600,
        ))
        .expect("other token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let blank = record_health_http(
        &app, tenant_id, &token, "o08c-blank", "BACKLOG", 20, 5, 10, "", "resume consumer",
    )
    .await;
    assert_eq!(blank.status(), axum::http::StatusCode::BAD_REQUEST);
    let unknown = record_health_http(
        &app, tenant_id, &token, "o08c-kind", "CPU", 20, 5, 10, "cmd-o08c", "resume consumer",
    )
    .await;
    assert_eq!(unknown.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let no_action = record_health_http(
        &app, tenant_id, &token, "o08c-none", "BACKLOG", 20, 5, 10, "cmd-o08c-none", "",
    )
    .await;
    assert_eq!(no_action.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let process = record_health_http(
        &app, tenant_id, &token, "o08c-proc", "PROCESS", 1, 1, 0, "cmd-o08c-proc", "",
    )
    .await;
    assert_eq!(process.status(), axum::http::StatusCode::OK);
    let process_body = json_body(process).await;
    assert_eq!(process_body["signal_status"], "OK");
    assert_eq!(process_body["actor_user_id"], actor.to_string());
    let database_down = record_health_http(
        &app, tenant_id, &token, "o08c-db", "DATABASE", 0, 1, 30, "cmd-o08c-db", "restore database",
    )
    .await;
    assert_eq!(database_down.status(), axum::http::StatusCode::OK);
    let database_body = json_body(database_down).await;
    assert_eq!(database_body["signal_status"], "DOWN");
    let (left, right) = tokio::join!(
        record_health_http(
            &app, tenant_id, &token, "o08c-a", "BACKLOG", 20, 5, 10, "cmd-o08c-backlog", "resume consumer",
        ),
        record_health_http(
            &app, tenant_id, &token, "o08c-b", "BACKLOG", 20, 5, 10, "cmd-o08c-backlog", "resume consumer",
        ),
    );
    let statuses = [left.status(), right.status()];
    assert!(statuses.contains(&axum::http::StatusCode::OK));
    assert!(statuses.contains(&axum::http::StatusCode::UNPROCESSABLE_ENTITY));
    let winner = if left.status() == axum::http::StatusCode::OK {
        json_body(left).await
    } else {
        json_body(right).await
    };
    let signal_id = winner["signal_id"].as_str().expect("signal").to_string();
    let winner_request = winner["request_id"].as_str().expect("winner").to_string();
    eprintln!("health-signal-http-signal {signal_id}");
    eprintln!("health-signal-http-winner {winner_request}");
    assert_eq!(winner["signal_status"], "ALERT");
    assert_eq!(winner["actor_user_id"], actor.to_string());
    assert_eq!(winner["replay"], false);
    let replay = record_health_http(
        &app, tenant_id, &token, &winner_request, "BACKLOG", 20, 5, 10, "cmd-o08c-backlog", "resume consumer",
    )
    .await;
    assert_eq!(replay.status(), axum::http::StatusCode::OK);
    let replay_body = json_body(replay).await;
    assert_eq!(replay_body["replay"], true);
    assert_eq!(replay_body["signal_id"], signal_id);
    let other = record_health_http(
        &app, other_id, &other_token, "o08c-other", "BACKLOG", 20, 5, 10, "cmd-o08c-backlog", "resume consumer",
    )
    .await;
    assert_eq!(other.status(), axum::http::StatusCode::OK);
    let other_body = json_body(other).await;
    assert_ne!(other_body["signal_id"], signal_id);
    let stored: i64 = sqlx::query_scalar(
        "select count(*) from health_signals where tenant_id = $1 and command_id = 'cmd-o08c-backlog'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("signals");
    assert_eq!(stored, 1);
    let alert_owner: String = sqlx::query_scalar(
        "select owner_user_id from health_alerts where tenant_id = $1 and signal_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&signal_id).expect("signal uuid"))
    .fetch_one(&pool)
    .await
    .expect("owner");
    assert_eq!(alert_owner, actor.to_string());
    let process_alerts: i64 = sqlx::query_scalar(
        "select count(*) from health_alerts where tenant_id = $1 and signal_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(process_body["signal_id"].as_str().expect("process id")).expect("process uuid"))
    .fetch_one(&pool)
    .await
    .expect("process alerts");
    assert_eq!(process_alerts, 0);
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o08c-blank','o08c-kind','o08c-none')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
    let other_rows: i64 = sqlx::query_scalar(
        "select count(*) from health_signals where tenant_id = $1",
    )
    .bind(other_id)
    .fetch_one(&pool)
    .await
    .expect("other signals");
    assert_eq!(other_rows, 1);
}

async fn record_health_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    request_id: &str,
    kind: &str,
    value: i64,
    threshold: i64,
    duration_seconds: i64,
    command_id: &str,
    action_text: &str,
) -> axum::http::Response<axum::body::Body> {
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/health/signals"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": request_id,
                    "kind": kind,
                    "value": value,
                    "threshold": threshold,
                    "duration_seconds": duration_seconds,
                    "command_id": command_id,
                    "action_text": action_text,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("health signal")
}

#[test]
fn work_admission_http_read_back() {
    std::thread::Builder::new()
        .name("work-admission-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(work_admission_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("work admission http thread");
}

async fn work_admission_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    sqlx::query("update work_admissions set closed_at = now() where kind = 'HEAVY' and status in ('QUEUED','ACCEPTED') and closed_at is null")
        .execute(&pool)
        .await
        .expect("close stale heavy rows");
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("work-admission-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o03j-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    eprintln!("work-admission-http-actor {actor:?}");
    let jwt = erp_api::JwtService::new("work-admission-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);

    let blank = admit_work_http(&app, tenant_id, &token, "o03j-blank", "HEAVY", "", 30).await;
    assert_eq!(blank.status(), axum::http::StatusCode::BAD_REQUEST);
    let unknown = admit_work_http(&app, tenant_id, &token, "o03j-kind", "LIGHT", "cmd-o03j-kind", 30).await;
    assert_eq!(unknown.status(), axum::http::StatusCode::BAD_REQUEST);
    let (first, second) = tokio::join!(
        admit_work_http(&app, tenant_id, &token, "o03j-a", "HEAVY", "cmd-o03j-1", 30),
        admit_work_http(&app, tenant_id, &token, "o03j-b", "HEAVY", "cmd-o03j-2", 30),
    );
    assert_eq!(first.status(), axum::http::StatusCode::OK);
    assert_eq!(second.status(), axum::http::StatusCode::OK);
    let first_body = json_body(first).await;
    let second_body = json_body(second).await;
    assert_eq!(first_body["status"], "QUEUED");
    assert_eq!(second_body["status"], "QUEUED");
    let full = admit_work_http(&app, tenant_id, &token, "o03j-full", "HEAVY", "cmd-o03j-full", 30).await;
    assert_eq!(full.status(), axum::http::StatusCode::TOO_MANY_REQUESTS);
    let full_body = json_body(full).await;
    assert_eq!(full_body["status"], "429");
    assert_eq!(full_body["retry_after_seconds"], 30);
    assert_eq!(full_body["command_id"], "cmd-o03j-full");
    let order = admit_work_http(&app, tenant_id, &token, "o03j-order", "ORDER", "cmd-o03j-order", 30).await;
    assert_eq!(order.status(), axum::http::StatusCode::OK);
    let order_body = json_body(order).await;
    assert_eq!(order_body["status"], "ACCEPTED");
    let queued: i64 = sqlx::query_scalar(
        "select count(*) from work_admissions where tenant_id = $1 and kind = 'HEAVY' and status = 'QUEUED'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("queued");
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from work_admissions where tenant_id = $1 and command_id = 'cmd-o03j-full' and status = '429'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused row");
    let orders: i64 = sqlx::query_scalar(
        "select count(*) from work_admissions where tenant_id = $1 and kind = 'ORDER' and status = 'ACCEPTED'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("orders");
    assert_eq!((queued, refused, orders), (2, 1, 1));
    let missing: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o03j-blank','o03j-kind')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("missing receipts");
    assert_eq!(missing, 0);
}

async fn admit_work_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    request_id: &str,
    kind: &str,
    command_id: &str,
    retry_after_seconds: i64,
) -> axum::http::Response<axum::body::Body> {
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/work/admissions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": request_id,
                    "kind": kind,
                    "command_id": command_id,
                    "retry_after_seconds": retry_after_seconds,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("admission")
}

#[test]
fn durable_restore_http_read_back() {
    std::thread::Builder::new()
        .name("durable-restore-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(durable_restore_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("durable restore http thread");
}

async fn durable_restore_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("durable-restore-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o03i-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    eprintln!("durable-restore-http-actor {actor:?}");
    let jwt = erp_api::JwtService::new("durable-restore-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);

    let live = open_and_claim(&app, tenant_id, &token, "o03i-live", "evt-o03i-live", "eff-o03i-live").await;
    let early = restore_task_http(&app, tenant_id, &token, &live, "o03i-early").await;
    assert_eq!(early.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let missing = uuid::Uuid::new_v4();
    let absent = restore_task_http(&app, tenant_id, &token, &missing.to_string(), "o03i-missing").await;
    assert_eq!(absent.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);

    let dead_task = open_and_claim(&app, tenant_id, &token, "o03i-dead", "evt-o03i-dead", "eff-o03i-dead").await;
    eprintln!("durable-restore-http-dead {dead_task}");
    let expected = [1_i64, 2, 4, 8, 16];
    for attempt in 1..=5 {
        let failed = fail_task_http(
            &app,
            tenant_id,
            &token,
            &dead_task,
            &format!("o03i-dead-{attempt}"),
            "worker-a",
            true,
            true,
            "blip",
        )
        .await;
        assert_eq!(failed.status(), axum::http::StatusCode::OK, "attempt {attempt}");
        let body = json_body(failed).await;
        if attempt < 5 {
            assert_eq!(body["task_status"], "QUEUED");
            assert_eq!(body["retry_seconds"], expected[attempt - 1]);
            let reclaimed = claim_task_http(
                &app,
                tenant_id,
                &token,
                &dead_task,
                &format!("o03i-dead-claim-{attempt}"),
                "worker-a",
                30,
            )
            .await;
            assert_eq!(reclaimed.status(), axum::http::StatusCode::OK);
        } else {
            assert_eq!(body["task_status"], "DEAD");
        }
    }
    let (first, second) = tokio::join!(
        restore_task_http(&app, tenant_id, &token, &dead_task, "o03i-a"),
        restore_task_http(&app, tenant_id, &token, &dead_task, "o03i-b"),
    );
    let winner = [first, second]
        .into_iter()
        .find(|response| response.status() == axum::http::StatusCode::OK)
        .expect("one restore stored");
    let winner_body = json_body(winner).await;
    assert_eq!(winner_body["task_status"], "QUEUED");
    assert_eq!(winner_body["effect_id"], "eff-o03i-dead");
    assert_eq!(winner_body["replay"], false);
    let replay = restore_task_http(
        &app,
        tenant_id,
        &token,
        &dead_task,
        winner_body["request_id"].as_str().expect("winner"),
    )
    .await;
    assert_eq!(replay.status(), axum::http::StatusCode::OK);
    let replay_body = json_body(replay).await;
    assert_eq!(replay_body["replay"], true);
    assert_eq!(replay_body["effect_id"], "eff-o03i-dead");
    let row: (String, String, String, i32) = sqlx::query_as(
        "select status, event_id, effect_id, attempt_count from durable_tasks where tenant_id = $1 and task_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&dead_task).expect("dead uuid"))
    .fetch_one(&pool)
    .await
    .expect("restored row");
    assert_eq!(row.0, "QUEUED");
    assert_eq!(row.1, "evt-o03i-dead");
    assert_eq!(row.2, "eff-o03i-dead");
    assert_eq!(row.3, 5);
    let tasks: i64 = sqlx::query_scalar(
        "select count(*) from durable_tasks where tenant_id = $1 and effect_id = 'eff-o03i-dead'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("task count");
    assert_eq!(tasks, 1);
    let letter: String = sqlx::query_scalar(
        "select status from durable_task_letters where tenant_id = $1 and task_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&dead_task).expect("dead uuid"))
    .fetch_one(&pool)
    .await
    .expect("letter");
    assert_eq!(letter, "RESTORED");
    let refused: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o03i-early','o03i-missing')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(refused, 0);
}

async fn restore_task_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    task_id: &str,
    request_id: &str,
) -> axum::http::Response<axum::body::Body> {
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/tasks/{task_id}/restores"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({ "request_id": request_id }).to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("restore")
}

