async fn durable_cancel_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("durable-cancel-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o03h-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    eprintln!("durable-cancel-http-actor {actor:?}");
    let jwt = erp_api::JwtService::new("durable-cancel-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let tenant = TenantId::from(tenant_id);
    let repo = SharedContractRepo::new(&pool);

    let open_task = open_and_claim(&app, tenant_id, &token, "o03h-open", "evt-o03h-open", "eff-o03h-open").await;
    let other = cancel_task_http(&app, tenant_id, &token, &open_task, "o03h-other", "worker-b", false, None, None).await;
    assert_eq!(other.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let blank = cancel_task_http(&app, tenant_id, &token, &open_task, "o03h-blank", "", false, None, None).await;
    assert_eq!(blank.status(), axum::http::StatusCode::BAD_REQUEST);
    let cancelled = cancel_task_http(
        &app, tenant_id, &token, &open_task, "o03h-cancel", "worker-a", false, None, None,
    )
    .await;
    assert_eq!(cancelled.status(), axum::http::StatusCode::OK);
    let cancelled_body = json_body(cancelled).await;
    assert_eq!(cancelled_body["task_status"], "CANCELLED");
    assert_eq!(cancelled_body["cancel_success"], false);
    assert!(cancelled_body["reverse_move_id"].is_null());
    let open_status: String = sqlx::query_scalar(
        "select status from durable_tasks where tenant_id = $1 and task_id = $2",
    )
    .bind(tenant_id)
    .bind(uuid::Uuid::parse_str(&open_task).expect("open uuid"))
    .fetch_one(&pool)
    .await
    .expect("open status");
    assert_eq!(open_status, "CANCELLED");

    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'o03h', 'O03H')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-O03H')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    repo.post_inventory_inbound(tenant, "o03h-in", "o03h-in", warehouse, sku, 2, Some("o03h".into()))
        .await
        .expect("inbound")
        .expect("admit inbound");
    let planned = repo
        .save_work_order(
            tenant, "o03h-wo", "o03h-wo", "WO-O03H", "FG-O03H", None, ScaledQty::from_micros(2_000_000),
        )
        .await
        .expect("work order")
        .expect("admit work order");
    assert!(matches!(planned, SharedWrite::Stored(_)));
    let work_order_id = sqlx::query_scalar::<_, uuid::Uuid>(
        "select effect_id::uuid from command_receipts where tenant_id = $1 and request_id = 'o03h-wo'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("work order id");
    eprintln!("durable-cancel-http-order {work_order_id:?}");
    let posted_task = open_and_claim(&app, tenant_id, &token, "o03h-post", "evt-o03h-post", "eff-o03h-post").await;
    eprintln!("durable-cancel-http-posted {posted_task}");
    let posted_id = uuid::Uuid::parse_str(&posted_task).expect("posted uuid");
    repo.post_task_issue(
        tenant, "o03h-issue", "o03h-issue", posted_id, work_order_id, ScaledQty::from_micros(1_000_000),
    )
    .await
    .expect("issue")
    .expect("admit issue");
    let refused = cancel_task_http(
        &app, tenant_id, &token, &posted_task, "o03h-post-other", "worker-b", true, Some(work_order_id), Some("1.000000"),
    )
    .await;
    assert_eq!(refused.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let reversed = cancel_task_http(
        &app, tenant_id, &token, &posted_task, "o03h-reverse", "worker-a", true, Some(work_order_id), Some("1.000000"),
    )
    .await;
    assert_eq!(reversed.status(), axum::http::StatusCode::OK);
    let reversed_body = json_body(reversed).await;
    assert_eq!(reversed_body["task_status"], "REVERSE_REQUIRED");
    assert_eq!(reversed_body["cancel_success"], false);
    let reverse_move = reversed_body["reverse_move_id"].as_str().expect("reverse move").to_string();
    let posted_status: String = sqlx::query_scalar(
        "select status from durable_tasks where tenant_id = $1 and task_id = $2",
    )
    .bind(tenant_id)
    .bind(posted_id)
    .fetch_one(&pool)
    .await
    .expect("posted status");
    assert_eq!(posted_status, "REVERSE_REQUIRED");
    let issue_rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_material_moves where tenant_id = $1 and work_order_id = $2 and kind = 'ISSUE' and reason = 'eff-o03h-post'",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("issue rows");
    let return_rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_material_moves where tenant_id = $1 and work_order_id = $2 and kind = 'RETURN' and reason = 'reverse-eff-o03h-post'",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("return rows");
    assert_eq!((issue_rows, return_rows), (1, 1));
    let return_id: uuid::Uuid = sqlx::query_scalar(
        "select move_id from mfg_material_moves where tenant_id = $1 and work_order_id = $2 and kind = 'RETURN'",
    )
    .bind(tenant_id)
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("return id");
    assert_eq!(return_id.to_string(), reverse_move);
    let other_receipt: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o03h-other','o03h-blank','o03h-post-other')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("other receipts");
    assert_eq!(other_receipt, 0);
}

async fn cancel_task_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    task_id: &str,
    request_id: &str,
    owner: &str,
    posted: bool,
    work_order_id: Option<uuid::Uuid>,
    qty: Option<&str>,
) -> axum::http::Response<axum::body::Body> {
    let mut body = serde_json::json!({
        "request_id": request_id,
        "owner": owner,
        "posted": posted,
    });
    if let Some(work_order_id) = work_order_id {
        body["work_order_id"] = serde_json::json!(work_order_id);
    }
    if let Some(qty) = qty {
        body["qty"] = serde_json::json!(qty);
    }
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/tasks/{task_id}/cancellations"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(body.to_string()))
            .expect("request"),
    )
    .await
    .expect("cancel")
}

