    let actor = uuid::Uuid::new_v4();
    eprintln!("password-epoch-http-actor {actor:?}");
    let hash = "$argon2id$v=19$m=65536,t=3,p=4$e2sG+56d5ad9Zqhn3AyI0Q$+V/BdTqdWryDDwRw5r1Jz3knecMc7FwWB5FiPk5RDvw".to_string();
    sqlx::query("insert into users(user_id, tenant_id, email, password_hash, status) values ($1, $2, $3, $4, 'ACTIVE')")
        .bind(actor)
        .bind(tenant_id)
        .bind(format!("a03f-{actor}@example.test"))
        .bind(&hash)
        .execute(&pool)
        .await
        .expect("user");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'a03f', 'A03F')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-A03F')")
        .bind(sku)
        .bind(tenant_id)
