#[test]
fn command_restart_http_read_back() {
    std::thread::Builder::new()
        .name("command-restart-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(command_restart_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("command restart http thread");
}

async fn command_restart_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("command-restart-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o02g-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    eprintln!("command-restart-http-warehouse {warehouse:?}");
    eprintln!("command-restart-http-sku {sku:?}");
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'o02g', 'O02G')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-O02G')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    let actor = uuid::Uuid::new_v4();
    eprintln!("command-restart-http-actor {actor:?}");
    let secret = "command-restart-http-test".to_string();
    let jwt = erp_api::JwtService::new(secret.clone());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/browser-sessions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "o02g-session",
                    "mode": "BEARER",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("session");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let opened_body = json_body(opened).await;
    let old_session = opened_body["effect_id"].as_str().expect("session id").to_string();
    let accepted = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/commands"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "o02g-lost",
                    "object_type": "LEDGER",
                    "object_id": "ledger-o02g",
                    "version_no": 3,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open");
    assert_eq!(accepted.status(), axum::http::StatusCode::OK);
    let payload_hash: String = sqlx::query_scalar(
        "select payload_hash from command_receipts where tenant_id = $1 and request_id = 'o02g-lost'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("payload hash");
    let revoked = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/browser-sessions/{old_session}/revocations"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "o02g-revoke",
                    "mode": "BEARER",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("revoke");
    assert_eq!(revoked.status(), axum::http::StatusCode::OK);
    let relogin = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/browser-sessions"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "o02g-relogin",
                    "mode": "BEARER",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("relogin");
    assert_eq!(relogin.status(), axum::http::StatusCode::OK);
    let relogin_body = json_body(relogin).await;
    let new_session = relogin_body["effect_id"].as_str().expect("new session").to_string();
    eprintln!("command-restart-http-old-session {old_session}");
    eprintln!("command-restart-http-new-session {new_session}");
    let completed = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/commands/o02g-lost/lost-lookups"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "payload_hash": payload_hash,
                    "revoked_session_id": old_session,
                    "current_session_id": new_session,
                    "client_unknown": false,
                    "warehouse_id": warehouse,
                    "sku_id": sku,
                    "qty_units": 1,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("complete");
    assert_eq!(completed.status(), axum::http::StatusCode::OK);
    let completed_body = json_body(completed).await;
    let ledger_id = completed_body["effect_id"].as_str().expect("ledger").to_string();
    eprintln!("command-restart-http-ledger {ledger_id}");
    let receipts_before: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("receipts before");
    let ledgers_before: i64 = sqlx::query_scalar(
        "select count(*) from inventory_ledgers where tenant_id = $1 and ref_id = 'o02g-lost'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("ledgers before");
    assert_eq!(ledgers_before, 1);
    drop(app);
    drop(token);
    drop(completed_body);
    let restarted_jwt = erp_api::JwtService::new(secret);
    let restarted_token = restarted_jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("restarted token");
    let restarted_db = erp_repo::db::Db::connect_lazy(&url).expect("restarted db");
    let restarted = erp_api::build_app(erp_api::AppState::new(
        restarted_db,
        std::sync::Arc::new(restarted_jwt),
    ));
    let refused = tower::ServiceExt::oneshot(
        restarted.clone(),
        axum::http::Request::builder()
            .method("GET")
            .uri(format!(
                "/v1/tenants/{tenant_id}/commands/o02g-lost/restarts?restarted=false"
            ))
            .header("authorization", format!("Bearer {restarted_token}"))
            .body(axum::body::Body::empty())
            .expect("request"),
    )
    .await
    .expect("refused");
    assert_eq!(refused.status(), axum::http::StatusCode::BAD_REQUEST);
    let missing = tower::ServiceExt::oneshot(
        restarted.clone(),
        axum::http::Request::builder()
            .method("GET")
            .uri(format!(
                "/v1/tenants/{tenant_id}/commands/o02g-missing/restarts?restarted=true"
            ))
            .header("authorization", format!("Bearer {restarted_token}"))
            .body(axum::body::Body::empty())
            .expect("request"),
    )
    .await
    .expect("missing");
    assert_eq!(missing.status(), axum::http::StatusCode::NOT_FOUND);
    let found = tower::ServiceExt::oneshot(
        restarted,
        axum::http::Request::builder()
            .method("GET")
            .uri(format!(
                "/v1/tenants/{tenant_id}/commands/o02g-lost/restarts?restarted=true"
            ))
            .header("authorization", format!("Bearer {restarted_token}"))
            .body(axum::body::Body::empty())
            .expect("request"),
    )
    .await
    .expect("found");
    assert_eq!(found.status(), axum::http::StatusCode::OK);
    let found_body = json_body(found).await;
    assert_eq!(found_body["status"], "SUCCEEDED");
    assert_eq!(found_body["object_id"], "ledger-o02g");
    assert_eq!(found_body["effect_id"], ledger_id);
    assert_eq!(found_body["version_no"], 3);
    assert_eq!(found_body["line_status"], "SUCCEEDED");
    assert_eq!(found_body["executed"], false);
    assert_eq!(found_body["found_after_restart"], true);
    let receipts_after: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("receipts after");
    assert_eq!(receipts_after, receipts_before);
    let ledgers_after: i64 = sqlx::query_scalar(
        "select count(*) from inventory_ledgers where tenant_id = $1 and ref_id = 'o02g-lost'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("ledgers after");
    assert_eq!(ledgers_after, 1);
    let missing_receipt: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'o02g-missing'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("missing receipt");
    assert_eq!(missing_receipt, 0);
}

#[test]
fn window_close_http_read_back() {
    std::thread::Builder::new()
        .name("window-close-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(window_close_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("window close http thread");
}

async fn window_close_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    eprintln!("window-close-http-tenant {tenant_id:?}");
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'o02f-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let actor = uuid::Uuid::new_v4();
    eprintln!("window-close-http-actor {actor:?}");
    let jwt = erp_api::JwtService::new("window-close-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            vec!["MFG.PRODUCTION.WRITE".to_string()],
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let missing = close_window_http(&app, tenant_id, &token, "o02f-missing", "o02f-missing-close", true).await;
    assert_eq!(missing.status(), axum::http::StatusCode::UNPROCESSABLE_ENTITY);
    let opened = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/commands"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "o02f-lost",
                    "object_type": "LEDGER",
                    "object_id": "ledger-o02f",
                    "version_no": 2,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("open");
    assert_eq!(opened.status(), axum::http::StatusCode::OK);
    let (left, right) = tokio::join!(
        close_window_http(&app, tenant_id, &token, "o02f-lost", "o02f-close", true),
        close_window_http(&app, tenant_id, &token, "o02f-lost", "o02f-close", true),
    );
    assert_eq!(left.status(), axum::http::StatusCode::OK);
    assert_eq!(right.status(), axum::http::StatusCode::OK);
    let left_body = json_body(left).await;
    let right_body = json_body(right).await;
    assert_eq!(left_body["decision"], "LOOKUP");
    assert_eq!(right_body["decision"], "LOOKUP");
    assert_eq!(left_body["effect_id"], "ledger-o02f");
    assert_eq!(right_body["effect_id"], "ledger-o02f");
    assert_eq!(left_body["executed"], false);
    assert_eq!(right_body["executed"], false);
    assert!(left_body["replay"] != right_body["replay"]);
    let kept = close_window_http(&app, tenant_id, &token, "o02f-lost", "o02f-keep", false).await;
    assert_eq!(kept.status(), axum::http::StatusCode::OK);
    let kept_body = json_body(kept).await;
    assert_eq!(kept_body["decision"], "KEEP");
    assert_eq!(kept_body["effect_id"], "ledger-o02f");
    assert_eq!(kept_body["executed"], false);
    let clean = close_window_http(&app, tenant_id, &token, "o02f-clean", "o02f-clean-close", false).await;
    assert_eq!(clean.status(), axum::http::StatusCode::OK);
    let clean_body = json_body(clean).await;
    assert_eq!(clean_body["decision"], "CLOSE");
    assert_eq!(clean_body["effect_id"], "");
    assert_eq!(clean_body["executed"], false);
    let lookups: i64 = sqlx::query_scalar(
        "select count(*) from lost_response_lookups where tenant_id = $1 and request_id = 'o02f-lost'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("lookups");
    assert_eq!(lookups, 1);
    let stored_status: String = sqlx::query_scalar(
        "select stored_status from lost_response_lookups where tenant_id = $1 and request_id = 'o02f-lost'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("stored status");
    assert_eq!(stored_status, "ACCEPTED");
    let command_status: String = sqlx::query_scalar(
        "select status from command_receipts where tenant_id = $1 and request_id = 'o02f-lost'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("command status");
    assert_eq!(command_status, "ACCEPTED");
    let ledgers: i64 = sqlx::query_scalar(
        "select count(*) from inventory_ledgers where tenant_id = $1 and ref_id in ('o02f-lost','o02f-close','o02f-keep','o02f-missing','o02f-clean')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("ledgers");
    assert_eq!(ledgers, 0);
    let missing_receipt: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('o02f-missing','o02f-missing-close','o02f-clean','o02f-clean-close')",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("missing receipts");
    assert_eq!(missing_receipt, 0);
    let close_receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 'o02f-close'",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("close receipts");
    assert_eq!(close_receipts, 1);
}

async fn close_window_http(
    app: &axum::Router,
    tenant_id: uuid::Uuid,
    token: &str,
    command_request: &str,
    request_id: &str,
    client_unknown: bool,
) -> axum::http::Response<axum::body::Body> {
    tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!(
                "/v1/tenants/{tenant_id}/commands/{command_request}/window-closes"
            ))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": request_id,
                    "client_unknown": client_unknown,
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("window close")
}

async fn json_body(response: axum::http::Response<axum::body::Body>) -> serde_json::Value {
    let bytes = http_body_util::BodyExt::collect(response.into_body())
        .await
        .expect("body")
        .to_bytes();
    serde_json::from_slice(&bytes).expect("json")
}

