async fn work_order_release_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant_id = uuid::Uuid::new_v4();
    let tenant = TenantId(tenant_id);
    eprintln!("work-order-release-http-tenant {tenant_id:?}");
    let repo = SharedContractRepo::new(&pool);
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'm08b-http')")
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("tenant");
    let lines = [erp_domain::manufacturing::BomLine {
        parent: "FG-M08B".into(),
        component: "RAW-M08B".into(),
        qty_per: qty_text("1"),
        unit_code: "EA".into(),
        scrap_ppm: 0,
        supply: "MAKE".into(),
        line_no: 10,
    }];
    let (_, bom_id) = repo
        .save_bom_structure(tenant, "m08b-bom", "m08b-bom", "FG-M08B", &lines)
        .await
        .expect("structure")
        .expect("admit structure");
    let (_, version_id, version_no) = repo
        .publish_bom_version(tenant, "m08b-ver", "m08b-ver", "FG-M08B", bom_id, "2026-10-01", "", true)
        .await
        .expect("version")
        .expect("admit version");
    assert_eq!(version_no, 1);
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'm08b', 'M08B')")
        .bind(warehouse)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-M08B')")
        .bind(sku)
        .bind(tenant_id)
        .execute(&pool)
        .await
        .expect("sku");
    repo.post_inventory_inbound(tenant, "m08b-in", "m08b-in", warehouse, sku, 4, Some("m08b".into()))
        .await
        .expect("inbound")
        .expect("admit inbound");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("work-order-release-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant_id.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant_id}/manufacturing/work-orders"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m08b-plan",
                    "work_order_no": "WO-M08B",
                    "product_code": "FG-M08B",
                    "order_qty": "4",
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("save");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("save body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("save json");
    let work_order_id = uuid::Uuid::parse_str(saved_json["effect_id"].as_str().expect("effect")).expect("order id");
    let (released, reserved) = repo
        .release_work_order(tenant, "m08b-rel", "m08b-rel", work_order_id, version_id, warehouse, sku, 1_000_000)
        .await
        .expect("release")
        .expect("admit release");
    assert!(matches!(released, SharedWrite::Stored(_)));
    assert_eq!(reserved, 1_000_000);
    let (retired, _) = repo
        .retire_bom_version(tenant, "m08b-ret", "m08b-ret", version_id)
        .await
        .expect("retire")
        .expect("admit retire");
    assert!(matches!(retired, SharedWrite::Stored(_)));
    let read = |app: axum::Router| {
        let token = token.clone();
        let tenant = tenant_id.to_string();
        let work_order_id = work_order_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/work-orders?work_order_id={work_order_id}"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
            (status, json)
        }
    };
    let (first, second) = tokio::join!(read(app.clone()), read(app));
    assert_eq!(first.0, axum::http::StatusCode::OK, "{first:?}");
    assert_eq!(second.0, axum::http::StatusCode::OK, "{second:?}");
    assert_eq!(first.1["version_id"], version_id.to_string());
    assert_eq!(second.1["version_id"], version_id.to_string());
    assert_eq!(first.1["version_no"], 1);
    assert_eq!(first.1["reserved_micros"], 1_000_000);
    assert_eq!(first.1["release_status"], "RELEASED");
    assert_eq!(first.1["order_status"], "RELEASED");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant_id)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 6, "release reads must not write receipts");
}

