async fn mrp_center_calendar_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("mrp-center-calendar-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("mrp-center-calendar-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/manufacturing/work-centers"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m06b-cal",
                    "center_code": "LINE-M06B",
                    "machines": 1,
                    "days": [
                        {"day":"2026-10-07","rest":true,"shift_minutes":480},
                        {"day":"2026-10-06","rest":false,"shift_minutes":480},
                        {"day":"2026-10-05","rest":false,"shift_minutes":480}
                    ],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("calendar");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("calendar body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("calendar json");
    let center_id = saved_json["center_id"].as_str().expect("center_id").to_string();
    let trial = |app: axum::Router, request: &'static str, claimed_rest: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let center_id = center_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/mrp-buckets"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "warehouse": "WH-M06B",
                            "center_id": center_id,
                            "bom": [],
                            "stock": [
                                {"code":"A","on_hand":0,"allocated_elsewhere":0,"wip":0,"safety":0,"min_lot":0,"lot_multiple":0,"supply":"BUY","lead_days":1}
                            ],
                            "supply": [],
                            "demand": [
                                {"code":"A","qty_micros":1_000_000,"need_date":"2026-10-08","frozen":true}
                            ],
                            "rest_days": [claimed_rest],
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        trial(app.clone(), "m06b-a", "2026-10-06"),
        trial(app, "m06b-b", "2026-10-05"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m06b-a','m06b-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let release: String = sqlx::query_scalar(
        "select release_date from shared_mrp_suggestions where tenant_id = $1 and item_code = 'A'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("release");
    assert_eq!(release, "2026-10-06", "the saved rest day replaces both claimed rest days");
    let runs: i64 = sqlx::query_scalar(
        "select count(*) from shared_mrp_runs where tenant_id = $1 and center_id = $2",
    )
    .bind(tenant)
    .bind(uuid::Uuid::parse_str(&center_id).expect("center uuid"))
    .fetch_one(&pool)
    .await
    .expect("runs");
    assert_eq!(runs, 1);
    let rest: i64 = sqlx::query_scalar(
        "select shift_minutes from shared_work_calendar_days where tenant_id = $1 and day_code = '2026-10-07'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("rest");
    assert_eq!(rest, 0, "the saved rest day stays at zero shift");
}

