async fn mrp_sample_http_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("mrp-sample-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("mrp-sample-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let saved = tower::ServiceExt::oneshot(
        app.clone(),
        axum::http::Request::builder()
            .method("POST")
            .uri(format!("/v1/tenants/{tenant}/manufacturing/work-centers"))
            .header("content-type", "application/json")
            .header("authorization", format!("Bearer {token}"))
            .body(axum::body::Body::from(
                serde_json::json!({
                    "request_id": "m06c-cal",
                    "center_code": "LINE-M06C",
                    "machines": 1,
                    "days": [
                        {"day":"2026-10-05","rest":true,"shift_minutes":480},
                        {"day":"2026-10-06","rest":false,"shift_minutes":480},
                        {"day":"2026-10-07","rest":false,"shift_minutes":480}
                    ],
                })
                .to_string(),
            ))
            .expect("request"),
    )
    .await
    .expect("calendar");
    assert_eq!(saved.status(), axum::http::StatusCode::OK);
    let saved_bytes = http_body_util::BodyExt::collect(saved.into_body())
        .await
        .expect("calendar body")
        .to_bytes();
    let saved_json: serde_json::Value = serde_json::from_slice(&saved_bytes).expect("calendar json");
    let center_id = saved_json["center_id"].as_str().expect("center_id").to_string();
    let stock = |code: &str, on_hand: i64, allocated: i64, safety: i64, min_lot: i64, multiple: i64, supply: &str, lead: i32| {
        serde_json::json!({
            "code": code,
            "on_hand": on_hand,
            "allocated_elsewhere": allocated,
            "wip": 0,
            "safety": safety,
            "min_lot": min_lot,
            "lot_multiple": multiple,
            "supply": supply,
            "lead_days": lead,
        })
    };
    let body = serde_json::json!({
        "warehouse": "WH-M06C",
        "center_id": center_id,
        "bom": [
            {"parent":"P","component":"S","qty_per_micros":2_000_000},
            {"parent":"P","component":"A","qty_per_micros":3_000_000},
            {"parent":"S","component":"B","qty_per_micros":4_000_000}
        ],
        "stock": [
            stock("P", 0, 0, 0, 0, 0, "MAKE", 2),
            stock("S", 2_000_000, 0, 0, 0, 0, "MAKE", 1),
            stock("A", 12_000_000, 2_000_000, 2_000_000, 0, 0, "BUY", 3),
            stock("B", 10_000_000, 0, 2_000_000, 10_000_000, 6_000_000, "BUY", 3)
        ],
        "supply": [
            {"code":"A","qty_micros":5_000_000,"arrive_date":"2026-10-06","accepted":true},
            {"code":"B","qty_micros":8_000_000,"arrive_date":"2026-10-02","accepted":true},
            {"code":"B","qty_micros":10_000_000,"arrive_date":"2026-10-12","accepted":true}
        ],
        "demand": [
            {"code":"P","qty_micros":10_000_000,"need_date":"2026-10-08","frozen":true}
        ],
        "rest_days": ["2026-10-02"],
    });
    let trial = |app: axum::Router, request: &'static str| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let mut body = body.clone();
        body["request_id"] = serde_json::json!(request);
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/mrp-buckets"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        trial(app.clone(), "m06c-a"),
        trial(app, "m06c-b"),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m06c-a','m06c-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let rows: Vec<(String, i64, String)> = sqlx::query_as(
        "select item_code, net_micros, release_date from shared_mrp_suggestions where tenant_id = $1 order by item_code",
    )
    .bind(tenant)
    .fetch_all(&pool)
    .await
    .expect("suggestions");
    assert_eq!(rows.len(), 4, "S, A, and the shared B stay one row each");
    let mut by_code = std::collections::BTreeMap::new();
    for (code, net, release) in rows {
        by_code.insert(code, (net, release));
    }
    assert_eq!(by_code["S"].0, 18_000_000, "on-hand S is consumed before explosion");
    assert_eq!(by_code["A"].0, 17_000_000);
    assert_eq!(by_code["B"].0, 56_000_000, "shared B is aggregated before lot rounding");
    assert_eq!(by_code["A"].1, "2026-09-30");
    assert_eq!(by_code["P"].1, "2026-10-06");
    let suggested_b: i64 = sqlx::query_scalar(
        "select suggested_micros from shared_mrp_suggestions where tenant_id = $1 and item_code = 'B'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("suggested b");
    assert_eq!(suggested_b, 60_000_000, "B rounds to the lot multiple after aggregation");
    let runs: i64 = sqlx::query_scalar(
        "select count(*) from shared_mrp_runs where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("runs");
    assert_eq!(runs, 1);
}

#[test]
fn mrp_conversion_read_http_read_back() {
    std::thread::Builder::new()
        .name("mrp-conversion-read-http".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(mrp_conversion_read_http_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("mrp conversion read http thread");
}

async fn mrp_conversion_read_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("mrp-conversion-read-http-tenant {tenant:?}");
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("mrp-conversion-read-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, body: serde_json::Value| {
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/mrp-buckets"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
            (status, json)
        }
    };
    let saved = post(
        app.clone(),
        serde_json::json!({
            "request_id": "m07e-run",
            "warehouse": "WH-M07E",
            "bom": [],
            "stock": [
                {"code":"RAW-M07","on_hand":0,"allocated_elsewhere":0,"wip":0,"safety":0,"min_lot":0,"lot_multiple":0,"supply":"BUY","lead_days":1}
            ],
            "supply": [],
            "demand": [{"code":"RAW-M07","qty_micros":4_000_000,"need_date":"2026-10-12","frozen":true}],
            "rest_days": [],
        }),
    )
    .await;
    assert_eq!(saved.0, axum::http::StatusCode::OK, "{saved:?}");
    let run_id = saved.1["run_id"].as_str().expect("run_id").to_string();
    let converted = post(
        app.clone(),
        serde_json::json!({
            "request_id": "m07e-buy",
            "action": "CONVERT",
            "run_id": run_id,
            "item_code": "RAW-M07",
            "qty_micros": 2_000_000,
            "target_kind": "PURCHASE",
            "target_line": 1,
        }),
    )
    .await;
    assert_eq!(converted.0, axum::http::StatusCode::OK, "{converted:?}");
    let read = |app: axum::Router| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let run_id = run_id.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("GET")
                    .uri(format!(
                        "/v1/tenants/{tenant}/manufacturing/mrp-buckets?run_id={run_id}&item_code=RAW-M07&view=conversion"
                    ))
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::empty())
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
            (status, json)
        }
    };
    let (first, second) = tokio::join!(read(app.clone()), read(app));
    assert_eq!(first.0, axum::http::StatusCode::OK, "{first:?}");
    assert_eq!(second.0, axum::http::StatusCode::OK, "{second:?}");
    assert_eq!(first.1["converted_micros"], 2_000_000);
    assert_eq!(second.1["converted_micros"], 2_000_000);
    assert_eq!(first.1["net_micros"], 4_000_000);
    assert_eq!(first.1["accepted"], false);
    assert_eq!(first.1["status"], "SUCCEEDED");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 2, "conversion reads must not write receipts");
}

