async fn production_remainder_http_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    eprintln!("production-remainder-http-tenant {tenant:?}");
    let order_id = uuid::Uuid::new_v4();
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let actor = uuid::Uuid::new_v4();
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("production-remainder-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let token = jwt
        .encode(&erp_api::Claims::bearer(
            actor.to_string(),
            tenant.to_string(),
            Vec::new(),
            true,
            now,
            now + 3600,
        ))
        .expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let post = |app: axum::Router, path: String, body: serde_json::Value| {
        let token = token.clone();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(path)
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            let json: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_default();
            (status, json, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let line = serde_json::json!({
        "line_no": 1,
        "item_code": "FG-M05E",
        "qty_micros": 10_000_000,
        "price_cent": 2500,
        "discount_cent": 0,
        "tax_cent": 325,
        "due_date": "2026-10-08",
        "address": "dock-5",
        "source": "MAKE",
    });
    for (request_id, action, expected) in [
        ("m05e-open", "SUBMIT", serde_json::Value::Null),
        ("m05e-go", "FULFILL", serde_json::json!(1)),
    ] {
        let mut body = serde_json::json!({
            "request_id": request_id,
            "so_id": order_id,
            "customer_code": "C-M05E",
            "action": action,
            "lines": [line],
        });
        if !expected.is_null() {
            body["expected_version"] = expected;
        }
        let (status, _, text) = post(app.clone(), format!("/v1/tenants/{tenant}/sales-revisions"), body).await;
        assert_eq!(status, axum::http::StatusCode::OK, "{action} {text}");
    }
    let (stocked, _, stocked_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/stock-ledgers"),
        serde_json::json!({
            "request_id": "m05e-stock",
            "warehouse_id": warehouse,
            "location_id": location,
            "sku_id": sku,
            "batch_code": "LOT-M05E",
            "quality_status": "GOOD",
            "bucket": "ON_HAND",
            "delta_micros": 10_000_000,
        }),
    )
    .await;
    assert_eq!(stocked, axum::http::StatusCode::OK, "{stocked_text}");
    let (reserved, _, reserved_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/stock-reservations"),
        serde_json::json!({
            "request_id": "m05e-reserve",
            "warehouse_id": warehouse,
            "location_id": location,
            "sku_id": sku,
            "batch_code": "LOT-M05E",
            "quality_status": "GOOD",
            "source_line": format!("{order_id}:1"),
            "qty_micros": 4_000_000,
        }),
    )
    .await;
    assert_eq!(reserved, axum::http::StatusCode::OK, "{reserved_text}");
    let (planned_status, planned, planned_text) = post(
        app.clone(),
        format!("/v1/tenants/{tenant}/sales-orders/{order_id}/deliveries"),
        serde_json::json!({
            "request_id": "m05e-ship",
            "line_no": 1,
            "expected_version": 2,
            "qty_micros": 4_000_000,
        }),
    )
    .await;
    assert_eq!(planned_status, axum::http::StatusCode::OK, "{planned_text}");
    let delivery_id = planned["delivery_id"].as_str().expect("delivery_id").to_string();
    for (request_id, action) in [("m05e-r", "RESERVE"), ("m05e-p", "PICK"), ("m05e-v", "REVIEW")] {
        let (status, _, text) = post(
            app.clone(),
            format!("/v1/tenants/{tenant}/sales-orders/{order_id}/deliveries"),
            serde_json::json!({
                "request_id": request_id,
                "line_no": 1,
                "expected_version": 2,
                "qty_micros": 4_000_000,
                "action": action,
                "delivery_id": delivery_id,
                "warehouse_id": warehouse,
                "location_id": location,
                "sku_id": sku,
                "batch_code": "LOT-M05E",
            }),
        )
        .await;
        assert_eq!(status, axum::http::StatusCode::OK, "{action} {text}");
    }
    let save = |app: axum::Router, request: &'static str, claimed: i64| {
        let token = token.clone();
        let tenant = tenant.to_string();
        let order_id = order_id.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/manufacturing/production-plans"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "request_id": request,
                            "source_id": order_id,
                            "line_no": 1,
                            "item_code": "CLIENT-ITEM",
                            "version_no": 9,
                            "open_qty": claimed,
                            "buckets": [
                                {"due_date":"2026-10-08","qty_micros":6_000_000,"source_kind":"MAKE"}
                            ],
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(
        save(app.clone(), "m05e-a", 10_000_000),
        save(app, "m05e-b", 1_000_000),
    );
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m05e-a','m05e-b') and status = 'SUCCEEDED'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1, "first={first:?} second={second:?}");
    let row: (String, i32, i64) = sqlx::query_as(
        r#"
        select p.item_code, p.version_no, b.qty_micros
        from shared_production_plans p
        join shared_production_buckets b on b.tenant_id = p.tenant_id and b.plan_id = p.plan_id
        where p.tenant_id = $1 and p.source_id = $2
        "#,
    )
    .bind(tenant)
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("plan");
    assert_eq!(row.0, "FG-M05E", "the plan keeps the sales item, not the client item");
    assert_eq!(row.1, 2, "the plan keeps the fulfilling sales version");
    assert_eq!(row.2, 6_000_000, "a 10-piece order with 4 delivered keeps remaining 6");
    let plans: i64 = sqlx::query_scalar(
        "select count(*) from shared_production_plans where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("plans");
    assert_eq!(plans, 1);
}

