async fn free_seat_http_create_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let tenant = uuid::Uuid::new_v4();
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'Mill A02')")
        .bind(tenant)
        .execute(&pool)
        .await
        .expect("tenant");
    eprintln!("free-seat-http-tenant {tenant:?}");
    let db = erp_repo::db::Db::connect_lazy(&url).expect("lazy db");
    let jwt = erp_api::JwtService::new("free-seat-http-test".to_string());
    let now = chrono::Utc::now().timestamp() as usize;
    let claims = erp_api::Claims::bearer(
        uuid::Uuid::new_v4().to_string(),
        tenant.to_string(),
        vec!["SYS.USER.WRITE".to_string()],
        false,
        now,
        now + 3600,
    );
    let token = jwt.encode(&claims).expect("token");
    let state = erp_api::AppState::new(db, std::sync::Arc::new(jwt));
    let app = erp_api::build_app(state);
    let create = |email: &'static str| {
        let app = app.clone();
        let token = token.clone();
        let tenant = tenant.to_string();
        async move {
            let response = tower::ServiceExt::oneshot(
                app,
                axum::http::Request::builder()
                    .method("POST")
                    .uri(format!("/v1/tenants/{tenant}/users"))
                    .header("content-type", "application/json")
                    .header("authorization", format!("Bearer {token}"))
                    .body(axum::body::Body::from(
                        serde_json::json!({
                            "email": email,
                            "password": "seat-secret",
                            "status": "ACTIVE",
                        })
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("oneshot");
            let status = response.status();
            let bytes = http_body_util::BodyExt::collect(response.into_body())
                .await
                .expect("body")
                .to_bytes();
            (status, String::from_utf8_lossy(&bytes).into_owned())
        }
    };
    let (first, second) = tokio::join!(create("a02g-a@mill.example"), create("a02g-b@mill.example"));
    let active: i64 = sqlx::query_scalar(
        "select count(*) from users where tenant_id = $1 and status = 'ACTIVE'",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("active users");
    assert_eq!(active, 1, "first={first:?} second={second:?}");
    let stored: (String, String) = sqlx::query_as(
        "select email, status from users where tenant_id = $1",
    )
    .bind(tenant)
    .fetch_one(&pool)
    .await
    .expect("stored user");
    assert!(
        stored == ("a02g-a@mill.example".to_string(), "ACTIVE".to_string())
            || stored == ("a02g-b@mill.example".to_string(), "ACTIVE".to_string()),
        "stored={stored:?}"
    );
    let rows: i64 = sqlx::query_scalar("select count(*) from users where tenant_id = $1")
        .bind(tenant)
        .fetch_one(&pool)
        .await
        .expect("user rows");
    assert_eq!(rows, 1, "first={first:?} second={second:?}");
}

