    let tenant = TenantId(uuid::Uuid::new_v4());
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'x02d')")
        .bind(uuid::Uuid::from(tenant))
        .execute(&pool)
        .await
        .expect("tenant");
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'x02d', 'X02D')")
        .bind(warehouse)
        .bind(uuid::Uuid::from(tenant))
        .execute(&pool)
        .await
        .expect("warehouse");
