async fn process_formula_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into tenants(tenant_id, name) values ($1, 'x01d')")
        .bind(uuid::Uuid::from(tenant))
        .execute(&pool)
        .await
        .expect("tenant");
    sqlx::query("insert into warehouses(warehouse_id, tenant_id, name, code) values ($1, $2, 'x01d', 'X01D')")
        .bind(warehouse)
        .bind(uuid::Uuid::from(tenant))
        .execute(&pool)
        .await
        .expect("warehouse");
    sqlx::query("insert into skus(sku_id, tenant_id, sku_code) values ($1, $2, 'SKU-X01D')")
        .bind(sku)
        .bind(uuid::Uuid::from(tenant))
        .execute(&pool)
        .await
        .expect("sku");
    let opened = repo
        .save_work_order(tenant, "x01d-wo", "x01d-wo", "WO-X01D", "FG-X01D", None, ScaledQty::from_micros(1_000_000))
        .await
        .expect("work order")
        .expect("admit work order");
    let SharedWrite::Stored(opened) = opened else {
        panic!("work order was not stored");
    };
    let work_order_id = uuid::Uuid::parse_str(&opened.effect_id).expect("work order id");
    eprintln!("process-formula-tenant {tenant:?} {work_order_id}");
    let save = |request: &'static str, density: i64| {
        let repo = repo.clone();
        async move {
            repo.save_process_formula(
                tenant, request, request, work_order_id, "SOLVENT", 125_000, density, "mass-volume-v1",
            )
            .await
        }
    };
    let (_first, _second) = tokio::join!(save("x01d-a", 1_000_000), save("x01d-b", 2_000_000));
    let formulas: i64 = sqlx::query_scalar(
        "select count(*) from process_formulas where tenant_id = $1 and work_order_id = $2 and component_code = 'SOLVENT'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("formulas");
    assert_eq!(formulas, 1);
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('x01d-a','x01d-b') and status = 'SUCCEEDED'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1);
    let mass: i64 = sqlx::query_scalar(
        "select mass_micros from process_formulas where tenant_id = $1 and work_order_id = $2 and component_code = 'SOLVENT'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("mass");
    assert_eq!(mass, 125_000);
    let charges: i64 = sqlx::query_scalar(
        "select count(*) from process_charges where tenant_id = $1 and work_order_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("charges");
    assert_eq!(charges, 0);
}

