async fn cost_complete_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let warehouse = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    sqlx::query("insert into tenants(tenant_id,name) values($1,'QA-LEGACY-COST-CALLER')").bind(uuid::Uuid::from(tenant)).execute(&pool).await.expect("owned tenant");
    sqlx::query("insert into warehouses(tenant_id,warehouse_id,name,code) values($1,$2,'QA COST',$3)").bind(uuid::Uuid::from(tenant)).bind(warehouse).bind(warehouse.to_string()).execute(&pool).await.expect("owned warehouse");
    sqlx::query("insert into skus(tenant_id,sku_id,sku_code) values($1,$2,'ITEM-M12E')").bind(uuid::Uuid::from(tenant)).bind(sku).execute(&pool).await.expect("owned SKU");
    erp_repo::inventory::InventoryService::new(&pool).apply_precise(erp_repo::inventory_precision::InventoryPreciseDelta {
        key:erp_repo::inventory_precision::InventoryQuantityKey{tenant_id:tenant,warehouse_id:warehouse,sku_id:sku},on_hand:qty_text("10"),reserved:ScaledQty::ZERO,frozen:ScaledQty::ZERO,in_transit:ScaledQty::ZERO,reason_type:"QA_COST_CALLER_OPENING".into(),ref_type:None,ref_id:None,occurred_at:chrono::Utc::now(),
    }).await.expect("canonical owned opening");
    let order = repo
        .save_work_order(tenant, "m12e-wo", "m12e-wo", "WO-M12E", "FG-M12E", None, qty_text("10"))
        .await
        .expect("order")
        .expect("admit order");
    let SharedWrite::Stored(order) = order else {
        panic!("order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&order.effect_id).expect("order id");
    repo.transition_saved_work_order(tenant, "m12e-rel", "m12e-rel", work_order_id, "release")
        .await
        .expect("release")
        .expect("admit release");
    repo.post_cost_receipt(erp_repo::shared_contract::CostReceiptInput { tenant_id: tenant, request_id: "m12e-in", payload_hash: "m12e-in", item_code: "ITEM-M12E", qty_micros: 10_000_000, amount_cent: 3_000, period_code: "2026-11" })
        .await
        .expect("item cost")
        .expect("admit item cost");
    let movement=erp_repo::shared_contract::MaterialMoveInput{work_order_id,warehouse_id:warehouse,sku_id:sku,batch_id:None,original_issue_id:None,movement:MaterialMove{kind:MaterialMoveKind::Issue,qty:qty_text("10"),supplement_reason_required:false},reason:Some("QA typed cost issue")};
    let issued=repo.post_material_move(tenant,"m12e-iss","m12e-iss",movement).await.expect("issue").expect("admit issue");
    assert!(matches!(issued.effect,SharedWrite::Stored(_)));
    let issue_id=issued.move_id;
    repo.post_material_move(tenant,"use-m12e","use-m12e",erp_repo::shared_contract::MaterialMoveInput{original_issue_id:Some(issue_id),movement:MaterialMove{kind:MaterialMoveKind::Consume,qty:qty_text("10"),supplement_reason_required:false},reason:Some("QA typed cost consume"),..movement}).await.expect("consume").expect("admit consume");
    let report = OperationReport {
        operation: "assemble".into(),
        good: qty_text("10"),
        rejected: ScaledQty::ZERO,
        rework: ScaledQty::ZERO,
        minutes: 50,
        operator_id: "worker-m12e".into(),
        session_user_id: "login-m12e".into(),
        session_id: "session-m12e".into(),
        crew_code: "CREW-M12E".into(),
        started_at: "2026-10-02T10:00:00Z".into(),
        ended_at: "2026-10-02T10:50:00Z".into(),
        reverses_report_id: None,
    };
    repo.save_operation_report(tenant, "m12e-rpt", "m12e-rpt", work_order_id, qty_text("10"), &report)
        .await
        .expect("report")
        .expect("admit report");
    let day = erp_domain::manufacturing::CalendarDay {
        day: "2026-10-02".into(),
        rest: false,
        shift_minutes: 480,
    };
    let (center_write, center_id) = repo
        .save_work_center_calendar(tenant, "m12e-wc", "m12e-wc", "LINE-M12E", 1, &[day])
        .await
        .expect("center")
        .expect("admit center");
    assert!(matches!(center_write, SharedWrite::Stored(_)));
    repo.save_work_center_rate(tenant, "m12e-rate", "m12e-rate", center_id, 200, "2026-10-01", "", "2026-10-02")
        .await
        .expect("rate")
        .expect("admit rate");
    let (queued, task_id) = repo
        .enqueue_cost_batch(tenant, "m12e-job", "m12e-job", work_order_id)
        .await
        .expect("queue")
        .expect("admit queue");
    assert!(matches!(queued, SharedWrite::Stored(_)));
    repo.claim_durable_task(tenant, "m12e-claim", "m12e-claim", task_id, "worker-m12e", 60)
        .await
        .expect("claim")
        .expect("admit claim");
    eprintln!("cost-complete-tenant {tenant:?} order {work_order_id} task {task_id}");
    let finish = |request: &'static str| {
        let repo = repo.clone();
        async move {
            repo.complete_cost_batch(
                tenant,
                request,
                request,
                task_id,
                "worker-m12e",
                "ITEM-M12E",
                center_id,
                "2026-10-02",
                Some(10_000),
                qty_text("10"),
                ScaledQty::ZERO,
                ScaledQty::ZERO,
                1,
            )
            .await
        }
    };
    let (_first, _second) = tokio::join!(finish("m12e-a"), finish("m12e-b"));
    let runs: i64 = sqlx::query_scalar(
        "select count(*) from mfg_cost_runs where tenant_id = $1 and work_order_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("runs");
    assert_eq!(runs, 1);
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m12e-a','m12e-b') and status = 'SUCCEEDED'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("receipts");
    assert_eq!(receipts, 1);
    let status: String = sqlx::query_scalar(
        "select status from durable_tasks where tenant_id = $1 and task_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(task_id)
    .fetch_one(&pool)
    .await
    .expect("task");
    assert_eq!(status, "DONE");
}

