    sqlx::query("insert into warehouses(tenant_id,warehouse_id,name,code) values($1,$2,'QA LATE COST',$3)").bind(uuid::Uuid::from(tenant)).bind(warehouse).bind(warehouse.to_string()).execute(&pool).await.expect("owned warehouse");
