    erp_repo::inventory::InventoryService::new(&pool).apply_precise(erp_repo::inventory_precision::InventoryPreciseDelta {
        key:erp_repo::inventory_precision::InventoryQuantityKey{tenant_id:tenant,warehouse_id:warehouse,sku_id:sku},on_hand:qty_text("10"),reserved:ScaledQty::ZERO,frozen:ScaledQty::ZERO,in_transit:ScaledQty::ZERO,reason_type:"QA_LATE_COST_OPENING".into(),ref_type:None,ref_id:None,occurred_at:chrono::Utc::now(),
    }).await.expect("canonical owned opening");
