async fn report_reversal_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let planned = repo
        .save_work_order(tenant, "m10c-plan", "m10c-plan", "WO-M10C", "FG-M10C", None, qty_text("4"))
        .await
        .expect("plan")
        .expect("admit plan");
    let SharedWrite::Stored(planned) = planned else {
        panic!("order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&planned.effect_id).expect("order");
    repo.transition_saved_work_order(tenant, "m10c-rel", "m10c-rel", work_order_id, "release")
        .await
        .expect("release")
        .expect("admit release");
    let original = OperationReport {
        operation: "CUT".into(),
        good: qty_text("4"),
        rejected: qty_text("0"),
        rework: ScaledQty::ZERO,
        minutes: 30,
        operator_id: "worker-m10c".into(),
        session_user_id: "login-m10c".into(),
        session_id: "session-m10c".into(),
        crew_code: "CREW-M10C".into(),
        started_at: "2026-10-02T09:00:00Z".into(),
        ended_at: "2026-10-02T09:30:00Z".into(),
        reverses_report_id: None,
    };
    let (saved, _) = repo
        .save_operation_report(tenant, "m10c-cut", "m10c-cut", work_order_id, qty_text("0"), &original)
        .await
        .expect("report")
        .expect("admit report");
    let SharedWrite::Stored(saved) = saved else {
        panic!("report stores");
    };
    let report_id = uuid::Uuid::parse_str(&saved.effect_id).expect("report id");
    eprintln!("report-reversal-tenant {tenant:?} report {report_id} order {work_order_id}");
    let undo = |request: &'static str| {
        let repo = repo.clone();
        let effect = saved.effect_id.clone();
        let source = original.clone();
        async move {
            let reversal = OperationReport {
                good: ScaledQty::from_micros(-qty_text("4").as_micros()),
                minutes: -30,
                reverses_report_id: Some(effect),
                ..source
            };
            repo.save_operation_report(tenant, request, request, work_order_id, qty_text("0"), &reversal)
                .await
        }
    };
    let (first, second) = tokio::join!(undo("m10c-a"), undo("m10c-b"));
    let stored = [first, second]
        .into_iter()
        .filter(|item| matches!(item, Ok(Ok((SharedWrite::Stored(_), _)))))
        .count();
    assert_eq!(stored, 1, "two reversals of one report store one reversal");
    let rows: i64 = sqlx::query_scalar(
        "select count(*) from mfg_reports where tenant_id = $1 and work_order_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("rows");
    assert_eq!(rows, 2);
    let good: i64 = sqlx::query_scalar(
        "select coalesce(sum(good_micros), 0)::bigint from mfg_reports where tenant_id = $1 and work_order_id = $2 and operation_code = 'CUT'",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(work_order_id)
    .fetch_one(&pool)
    .await
    .expect("good");
    assert_eq!(good, 0);
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('m10c-a','m10c-b') and status = 'SUCCEEDED'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("reversal receipts");
    assert_eq!(receipts, 1);
    let kept: i64 = sqlx::query_scalar(
        "select count(*) from mfg_reports where tenant_id = $1 and report_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(report_id)
    .fetch_one(&pool)
    .await
    .expect("original kept");
    assert_eq!(kept, 1);
}

