async fn sales_advance_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let order_id = uuid::Uuid::new_v4();
    let line = erp_domain::trade::SalesLine {
        line_no: 1,
        item_code: "ITEM-T04D".into(),
        qty_micros: 10_000_000,
        price_cent: 1_800,
        discount_cent: 0,
        tax_cent: 234,
        due_date: "2026-10-22".into(),
        address: "Dock-4".into(),
        source: "RESALE".into(),
    };
    repo.save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "t04d-open", payload_hash: "t04d-open", so_id: Some(order_id), customer_code: "C-T04D", expected_version: None, action: "SUBMIT", lines: &[line.clone()] })
        .await
        .expect("submit")
        .expect("admit submit");
    repo.save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "t04d-go", payload_hash: "t04d-go", so_id: Some(order_id), customer_code: "C-T04D", expected_version: Some(1), action: "FULFILL", lines: &[line] })
        .await
        .expect("fulfill")
        .expect("admit fulfill");
    let (planned, delivery_id) = repo
        .plan_sales_delivery(erp_repo::shared_contract::SalesDeliveryPlanInput { tenant_id: tenant, request_id: "t04d-plan", payload_hash: "t04d-plan", so_id: order_id, line_no: 1, expected_version: 2, qty_micros: 6_000_000 })
        .await
        .expect("plan")
        .expect("admit plan");
    assert!(matches!(planned, SharedWrite::Stored(_)));
    eprintln!("sales-advance-tenant {tenant:?} delivery {delivery_id}");
    let advance = |request: &'static str| {
        let repo = repo.clone();
        async move {
            repo.advance_sales_delivery(erp_repo::shared_contract::SalesDeliveryAdvanceInput { tenant_id: tenant, request_id: request, payload_hash: request, delivery_id, action: "RESERVE", carrier_ref: "", warehouse_id: warehouse, location_id: location, sku_id: sku, batch_code: "LOT-T04D" })
            .await
        }
    };
    let (first, second) = tokio::join!(advance("t04d-a"), advance("t04d-b"));
    let stored = [first, second]
        .into_iter()
        .filter(|item| matches!(item, Ok(Ok((SharedWrite::Stored(_), _)))))
        .count();
    assert_eq!(stored, 1, "two reserves of one planned delivery store one stage");
    let stage: String = sqlx::query_scalar(
        "select stage from shared_sales_deliveries where tenant_id = $1 and delivery_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(delivery_id)
    .fetch_one(&pool)
    .await
    .expect("stage");
    assert_eq!(stage, "RESERVED");
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t04d-a','t04d-b') and status = 'SUCCEEDED'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("advance receipts");
    assert_eq!(receipts, 1);
    let on_hand: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from shared_stock_ledgers where tenant_id = $1 and bucket = 'ON_HAND'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("on hand");
    assert_eq!(on_hand, 0, "reserve does not deduct physical stock");
}

