async fn sales_revision_below_delivery_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let order_id = uuid::Uuid::new_v4();
    let line = erp_domain::trade::SalesLine {
        line_no: 1,
        item_code: "ITEM-T03D".into(),
        qty_micros: 10_000_000,
        price_cent: 3_000,
        discount_cent: 100,
        tax_cent: 390,
        due_date: "2026-10-20".into(),
        address: "Dock-1".into(),
        source: "RESALE".into(),
    };
    let (submitted, open_id, version) = repo
        .save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "t03d-open", payload_hash: "t03d-open", so_id: Some(order_id), customer_code: "C-T03D", expected_version: None, action: "SUBMIT", lines: &[line.clone()] })
        .await
        .expect("submit")
        .expect("admit submit");
    assert!(matches!(submitted, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let (fulfilling, _, fulfill_version) = repo
        .save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "t03d-go", payload_hash: "t03d-go", so_id: Some(order_id), customer_code: "C-T03D", expected_version: Some(1), action: "FULFILL", lines: &[line.clone()] })
        .await
        .expect("fulfill")
        .expect("admit fulfill");
    assert!(matches!(fulfilling, SharedWrite::Stored(_)));
    assert_eq!(fulfill_version, 2);
    let (planned, _) = repo
        .plan_sales_delivery(erp_repo::shared_contract::SalesDeliveryPlanInput { tenant_id: tenant, request_id: "t03d-plan", payload_hash: "t03d-plan", so_id: order_id, line_no: 1, expected_version: 2, qty_micros: 6_000_000 })
        .await
        .expect("plan")
        .expect("admit plan");
    assert!(matches!(planned, SharedWrite::Stored(_)));
    let below = erp_domain::trade::SalesLine { qty_micros: 5_000_000, ..line.clone() };
    let refused = repo
        .save_sales_revision(erp_repo::shared_contract::TradeSalesRevisionInput { tenant_id: tenant, request_id: "t03d-below", payload_hash: "t03d-below", so_id: Some(order_id), customer_code: "C-T03D", expected_version: Some(2), action: "REVISE", lines: &[below] })
        .await;
    assert!(refused.is_err(), "a revision cannot drop ordered quantity below delivered quantity");
    eprintln!("sales-below-tenant {tenant:?} order {order_id}");
    let versions: i64 = sqlx::query_scalar(
        "select count(*) from shared_sales_revisions where tenant_id = $1 and so_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, 2);
    let fulfill_qty: i64 = sqlx::query_scalar(
        "select qty_micros from shared_sales_lines where tenant_id = $1 and revision_id = $2 and line_no = 1",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(open_id)
    .fetch_one(&pool)
    .await
    .expect("open qty");
    assert_eq!(fulfill_qty, 10_000_000);
    let latest_qty: i64 = sqlx::query_scalar(
        "select l.qty_micros from shared_sales_lines l join shared_sales_revisions r on r.tenant_id = l.tenant_id and r.revision_id = l.revision_id where r.tenant_id = $1 and r.so_id = $2 order by r.version_no desc limit 1",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("latest qty");
    assert_eq!(latest_qty, 10_000_000);
    let lost: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 't03d-below'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("refused");
    assert_eq!(lost, 0);
    let demands: i64 = sqlx::query_scalar(
        "select count(*) from shared_sales_demands where tenant_id = $1 and so_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("demands");
    assert_eq!(demands, 0, "a resale line does not create a production demand");
}

