    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let order_id = uuid::Uuid::new_v4();
    let line = erp_domain::trade::PurchaseLine {
        line_no: 1,
        item_code: "ITEM-T02G".into(),
        qty_micros: 10_000_000,
        price_cent: 1_500,
        tax_cent: 195,
        due_date: "2026-10-18".into(),
    };
    repo.save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t02g-open", payload_hash: "t02g-open", po_id: Some(order_id), supplier_code: "S-T02G", warehouse_code: "WH-T02G", action: "OPEN", lines: &[line] })
        .await
        .expect("open")
        .expect("admit open");
    let (arrived, quality_id) = repo
        .arrive_purchase_receipt(tenant, "t02g-arr", "t02g-arr", order_id, 1, warehouse, location, sku, "LOT-T02G", 10_000_000, 1_500)
        .await
        .expect("arrive")
        .expect("admit arrive");
