async fn purchase_return_race_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let warehouse = uuid::Uuid::new_v4();
    let location = uuid::Uuid::new_v4();
    let sku = uuid::Uuid::new_v4();
    let order_id = uuid::Uuid::new_v4();
    let line = erp_domain::trade::PurchaseLine {
        line_no: 1,
        item_code: "ITEM-T02E".into(),
        qty_micros: 10_000_000,
        price_cent: 1_500,
        tax_cent: 195,
        due_date: "2026-10-18".into(),
    };
    repo.save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t02e-open", payload_hash: "t02e-open", po_id: Some(order_id), supplier_code: "S-T02E", warehouse_code: "WH-T02E", action: "OPEN", lines: &[line] })
        .await
        .expect("open")
        .expect("admit open");
    let (arrived, quality_id) = repo
        .arrive_purchase_receipt(tenant, "t02e-arr", "t02e-arr", order_id, 1, warehouse, location, sku, "LOT-T02E", 10_000_000, 1_500)
        .await
        .expect("arrive")
        .expect("admit arrive");
    assert!(matches!(arrived, SharedWrite::Stored(_)));
    let actor = shared_contract_receipt_actor::actor(&pool, tenant, warehouse).await.expect("actual receipt actor");
    let (released, held_left) = repo
        .release_purchase_receipt(tenant, "t02e-rel", "t02e-rel", quality_id, 6_000_000, actor)
        .await
        .expect("release")
        .expect("admit release");
    assert!(matches!(released, SharedWrite::Stored(_)));
    assert_eq!(held_left, 4_000_000);
    eprintln!("purchase-return-tenant {tenant:?} quality {quality_id}");
    let ret = |request: &'static str| {
        let repo = repo.clone();
        async move {
            repo.return_purchase_receipt(tenant, request, request, quality_id, 4_000_000, actor)
                .await
        }
    };
    let (first, second) = tokio::join!(ret("t02e-a"), ret("t02e-b"));
    let stored = [first, second]
        .into_iter()
        .filter(|item| matches!(item, Ok(Ok((SharedWrite::Stored(_), _)))))
        .count();
    assert_eq!(stored, 1, "two returns of one release store one reversal");
    let returned: (i64, i64) = sqlx::query_as(
        "select count(*), coalesce(sum(qty_micros), 0)::bigint from shared_supplier_returns where tenant_id = $1",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("returns");
    assert_eq!(returned, (1, 4_000_000));
    let receipts: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id in ('t02e-a','t02e-b') and status = 'SUCCEEDED'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("return receipts");
    assert_eq!(receipts, 1);
    let on_hand: i64 = sqlx::query_scalar(
        "select coalesce(sum(delta_micros), 0)::bigint from shared_stock_ledgers where tenant_id = $1 and bucket = 'ON_HAND'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("on hand");
    assert_eq!(on_hand, 2_000_000);
    let payable: i64 = sqlx::query_scalar(
        "select coalesce(sum(amount_cent), 0)::bigint from partner_balances where tenant_id = $1 and kind = 'AP'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("payable");
    assert_eq!(payable, 9_000 - 6_000);
}

