#[test]
fn purchase_revision_last_line_rollback_read_back() {
    std::thread::Builder::new()
        .name("purchase-rollback".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(purchase_revision_last_line_rollback_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("purchase rollback thread");
}

async fn purchase_revision_last_line_rollback_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let order_id = uuid::Uuid::new_v4();
    let open = erp_domain::trade::PurchaseLine {
        line_no: 1,
        item_code: "ITEM-T01G".into(),
        qty_micros: 1_000_000,
        price_cent: 100,
        tax_cent: 13,
        due_date: "2026-10-15".into(),
    };
    let (opened, open_id, version) = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t01g-open", payload_hash: "t01g-open", po_id: Some(order_id), supplier_code: "S-T01G", warehouse_code: "WH-T01G", action: "OPEN", lines: &[open] })
        .await
        .expect("open")
        .expect("admit open");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let mut lines = Vec::with_capacity(100);
    for line_no in 1..=99 {
        lines.push(erp_domain::trade::PurchaseLine {
            line_no,
            item_code: format!("ITEM-T01G-{line_no}"),
            qty_micros: 1_000_000,
            price_cent: 100,
            tax_cent: 13,
            due_date: "2026-10-20".into(),
        });
    }
    lines.push(erp_domain::trade::PurchaseLine {
        line_no: 99,
        item_code: "ITEM-T01G-DUP".into(),
        qty_micros: 1_000_000,
        price_cent: 100,
        tax_cent: 13,
        due_date: "2026-10-20".into(),
    });
    assert_eq!(lines.len(), 100);
    let refused = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t01g-bad", payload_hash: "t01g-bad", po_id: Some(order_id), supplier_code: "S-T01G", warehouse_code: "WH-T01G", action: "REVISE", lines: &lines })
        .await;
    assert!(refused.is_err(), "a repeated last line rejects the whole revision");
    eprintln!("purchase-rollback-tenant {tenant:?} order {order_id}");
    let versions: i64 = sqlx::query_scalar(
        "select count(*) from shared_purchase_revisions where tenant_id = $1 and po_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, 1);
    let stored_lines: i64 = sqlx::query_scalar(
        "select count(*) from shared_purchase_lines where tenant_id = $1 and revision_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(open_id)
    .fetch_one(&pool)
    .await
    .expect("open lines");
    assert_eq!(stored_lines, 1);
    let partial: i64 = sqlx::query_scalar(
        "select count(*) from shared_purchase_lines where tenant_id = $1 and item_code like 'ITEM-T01G-%'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("partial lines");
    assert_eq!(partial, 0);
    let lost: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 't01g-bad'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("refused receipt");
    assert_eq!(lost, 0);
    let purchases: i64 = sqlx::query_scalar("select count(*) from purchase_orders where tenant_id = $1")
        .bind(uuid::Uuid::from(tenant))
        .fetch_one(&pool)
        .await
        .expect("purchases");
    assert_eq!(purchases, 0);
}

#[test]
fn purchase_revision_below_receipt_read_back() {
    std::thread::Builder::new()
        .name("purchase-below".into())
        .stack_size(8 * 1024 * 1024)
        .spawn(|| {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("runtime");
            runtime.block_on(purchase_revision_below_receipt_read_back_body());
        })
        .expect("thread")
        .join()
        .expect("purchase below thread");
}

async fn purchase_revision_below_receipt_read_back_body() {
    let url = isolated_database_url().expect(
        "ERP_GRID_TEST_DATABASE_URL is required: database acceptance was NOT RUN, not PASS",
    );
    let options = protected_database_options(&url)
        .expect("refusing database access before verifying the isolated QA address");
    let pool = sqlx::postgres::PgPoolOptions::new()
        .max_connections(4)
        .connect_with(options)
        .await
        .expect("isolated database should connect");
    let (database, port): (String, i32) =
        sqlx::query_as("select current_database(), inet_server_port()")
            .fetch_one(&pool)
            .await
            .expect("database identity");
    assert_eq!(database, "erp_shared_contract_test");
    assert_eq!(port, 15438, "refusing any database that is not the isolated QA port");
    apply_contract_tables(&pool).await;
    let repo = SharedContractRepo::new(&pool);
    let tenant = TenantId(uuid::Uuid::new_v4());
    let order_id = uuid::Uuid::new_v4();
    let line = erp_domain::trade::PurchaseLine {
        line_no: 1,
        item_code: "ITEM-T01F".into(),
        qty_micros: 10_000_000,
        price_cent: 2_000,
        tax_cent: 260,
        due_date: "2026-10-15".into(),
    };
    let (opened, open_id, version) = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t01f-open", payload_hash: "t01f-open", po_id: Some(order_id), supplier_code: "S-T01F", warehouse_code: "WH-T01F", action: "OPEN", lines: &[line.clone()] })
        .await
        .expect("open")
        .expect("admit open");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let received = repo
        .receive_purchase_line(tenant, "t01f-rcv", "t01f-rcv", order_id, 1, 6_000_000)
        .await
        .expect("receive")
        .expect("admit receive");
    assert_eq!(received.1, 4_000_000);
    let below = erp_domain::trade::PurchaseLine { qty_micros: 5_000_000, ..line.clone() };
    let refused = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t01f-below", payload_hash: "t01f-below", po_id: Some(order_id), supplier_code: "S-T01F", warehouse_code: "WH-T01F", action: "REVISE", lines: &[below] })
        .await;
    assert!(refused.is_err(), "a revision cannot drop ordered quantity below accepted receipts");
    let kept = erp_domain::trade::PurchaseLine { due_date: "2026-10-20".into(), ..line };
    let (revised, revised_id, revised_version) = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "t01f-ok", payload_hash: "t01f-ok", po_id: Some(order_id), supplier_code: "S-T01F", warehouse_code: "WH-T01F", action: "REVISE", lines: &[kept] })
        .await
        .expect("revise")
        .expect("admit revise");
    assert!(matches!(revised, SharedWrite::Stored(_)));
    assert_eq!(revised_version, 2);
    eprintln!("purchase-below-tenant {tenant:?} order {order_id}");
    let versions: i64 = sqlx::query_scalar(
        "select count(*) from shared_purchase_revisions where tenant_id = $1 and po_id = $2",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(order_id)
    .fetch_one(&pool)
    .await
    .expect("versions");
    assert_eq!(versions, 2);
    let open_qty: i64 = sqlx::query_scalar(
        "select qty_micros from shared_purchase_lines where tenant_id = $1 and revision_id = $2 and line_no = 1",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(open_id)
    .fetch_one(&pool)
    .await
    .expect("open qty");
    let revised_qty: i64 = sqlx::query_scalar(
        "select qty_micros from shared_purchase_lines where tenant_id = $1 and revision_id = $2 and line_no = 1",
    )
    .bind(uuid::Uuid::from(tenant))
    .bind(revised_id)
    .fetch_one(&pool)
    .await
    .expect("revised qty");
    assert_eq!((open_qty, revised_qty), (10_000_000, 10_000_000));
    let lost: i64 = sqlx::query_scalar(
        "select count(*) from command_receipts where tenant_id = $1 and request_id = 't01f-below'",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("refused receipt");
    assert_eq!(lost, 0);
    let purchases: i64 = sqlx::query_scalar(
        "select count(*) from purchase_orders where tenant_id = $1",
    )
    .bind(uuid::Uuid::from(tenant))
    .fetch_one(&pool)
    .await
    .expect("purchases");
    assert_eq!(purchases, 0);
}

