async fn admit_paid_member_seats(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let free_raise = repo
        .save_paid_seat_plan(tenant, "seat-free", "seat-free", "FREE", 5)
        .await;
    assert!(free_raise.is_err(), "the free plan cannot raise its seat limit");
    let paid = repo
        .save_paid_seat_plan(tenant, "seat-paid", "seat-paid", "PAID", 5)
        .await
        .expect("paid plan")
        .expect("admit paid plan");
    assert!(matches!(paid, SharedWrite::Stored(_)));
    for index in 1..=6 {
        let invited = repo
            .invite_member(tenant, &format!("seat-inv-{index}"), &format!("seat-inv-{index}"), &format!("user-{index}"))
            .await
            .expect("invite")
            .expect("admit invite");
        assert!(matches!(invited, SharedWrite::Stored(_)));
    }
    for index in 1..=5 {
        let activated = repo
            .activate_member(tenant, &format!("seat-act-{index}"), &format!("seat-act-{index}"), &format!("user-{index}"))
            .await
            .expect("activate")
            .expect("admit activation");
        assert!(matches!(activated, SharedWrite::Stored(_)));
    }
    let sixth = repo.activate_member(tenant, "seat-act-6", "seat-act-6", "user-6").await;
    assert!(sixth.is_err(), "the sixth activation is over the paid limit of 5");
    let race_tenant = TenantId(uuid::Uuid::new_v4());
    repo.save_paid_seat_plan(race_tenant, "v01c-plan", "v01c-plan", "PAID", 5)
        .await
        .expect("race plan")
        .expect("admit race plan");
    for index in 1..=6 {
        repo.invite_member(
            race_tenant,
            &format!("v01c-inv-{index}"),
            &format!("v01c-inv-{index}"),
            &format!("user-v01c-{index}"),
        )
        .await
        .expect("race invite")
        .expect("admit race invite");
    }
    let one = repo.clone();
    let two = repo.clone();
    let three = repo.clone();
    let four = repo.clone();
    let five = repo.clone();
    let six = repo.clone();
    let (a1, a2, a3, a4, a5, a6) = tokio::join!(
        one.activate_member(race_tenant, "v01c-act-1", "v01c-act-1", "user-v01c-1"),
        two.activate_member(race_tenant, "v01c-act-2", "v01c-act-2", "user-v01c-2"),
        three.activate_member(race_tenant, "v01c-act-3", "v01c-act-3", "user-v01c-3"),
        four.activate_member(race_tenant, "v01c-act-4", "v01c-act-4", "user-v01c-4"),
        five.activate_member(race_tenant, "v01c-act-5", "v01c-act-5", "user-v01c-5"),
        six.activate_member(race_tenant, "v01c-act-6", "v01c-act-6", "user-v01c-6"),
    );
    let stored = [a1, a2, a3, a4, a5, a6]
        .into_iter()
        .filter(|result| matches!(result, Ok(Ok(SharedWrite::Stored(_)))))
        .count();
    assert_eq!(stored, 5, "six concurrent activations keep the paid limit of 5");
    let self_approval = repo
        .save_member_approval(tenant, "seat-self", "seat-self", "user-1", "user-1", "amount > 0", 1)
        .await;
    assert!(self_approval.is_err(), "a submitter cannot approve their own request");
    let approval = repo
        .save_member_approval(tenant, "seat-ok", "seat-ok", "user-1", "user-2", "amount > 0", 1)
        .await
        .expect("approval")
        .expect("admit approval");
    assert!(matches!(approval, SharedWrite::Stored(_)));
    let downgraded = repo
        .downgrade_paid_seats(tenant, "seat-down", "seat-down", "user-1")
        .await
        .expect("downgrade")
        .expect("admit downgrade");
    assert!(matches!(downgraded, SharedWrite::Stored(_)));
}

async fn save_scaled_trade_documents(
    repo: &SharedContractRepo<'_>,
    tenant: TenantId,
    customer: uuid::Uuid,
    sku: uuid::Uuid,
    warehouse: uuid::Uuid,
) {
    let (sale, micros, total) = repo
        .save_scaled_trade_sale(erp_repo::shared_contract::ScaledTradeSaleInput { tenant_id: tenant, request_id: "qty-sale", payload_hash: "qty-sale", customer_id: customer, sku_id: sku, warehouse_id: warehouse, qty_text: "0.125", unit_price_cent: 2_000, currency: "CNY", partner_code: "" })
        .await
        .expect("scaled sale")
        .expect("admit scaled sale");
    assert!(matches!(sale, SharedWrite::Stored(_)));
    assert_eq!(micros, 125_000);
    assert_eq!(total, 250);
    let replay = repo
        .save_scaled_trade_sale(erp_repo::shared_contract::ScaledTradeSaleInput { tenant_id: tenant, request_id: "qty-sale", payload_hash: "qty-sale", customer_id: customer, sku_id: sku, warehouse_id: warehouse, qty_text: "0.125", unit_price_cent: 2_000, currency: "CNY", partner_code: "" })
        .await
        .expect("scaled replay")
        .expect("same scaled sale");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!((replay.1, replay.2), (125_000, 250));
    let legacy = repo
        .save_scaled_trade_sale(erp_repo::shared_contract::ScaledTradeSaleInput { tenant_id: tenant, request_id: "qty-one", payload_hash: "qty-one", customer_id: customer, sku_id: sku, warehouse_id: warehouse, qty_text: "1", unit_price_cent: 2_000, currency: "CNY", partner_code: "" })
        .await
        .expect("legacy sale")
        .expect("admit legacy sale");
    assert_eq!(legacy.1, 1_000_000);
    assert_eq!(legacy.2, 2_000);
    let zero = repo
        .save_scaled_trade_sale(erp_repo::shared_contract::ScaledTradeSaleInput { tenant_id: tenant, request_id: "qty-zero", payload_hash: "qty-zero", customer_id: customer, sku_id: sku, warehouse_id: warehouse, qty_text: "0", unit_price_cent: 2_000, currency: "CNY", partner_code: "" })
        .await;
    assert!(zero.is_err(), "a zero quantity is refused");
}

async fn save_shared_item_master(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let empty = repo
        .save_shared_item(tenant, "item-empty", "item-empty", "ITEM-1", "Bolt", "M8", "fastener", "BC-1", false, false, false)
        .await;
    assert!(empty.is_err(), "an item without a role is refused");
    let (saved, item_id) = repo
        .save_shared_item(tenant, "item-1", "item-1", "ITEM-1", "Bolt", "M8", "fastener", "BC-1", true, true, true)
        .await
        .expect("item")
        .expect("admit item");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let replay = repo
        .save_shared_item(tenant, "item-1", "item-1", "ITEM-1", "Bolt", "M8", "fastener", "BC-1", true, true, true)
        .await
        .expect("item replay")
        .expect("same item");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, item_id);
    let duplicate = repo
        .save_shared_item(tenant, "item-dup", "item-dup", "ITEM-1", "Other", "M8", "fastener", "BC-2", true, false, false)
        .await;
    assert!(duplicate.is_err(), "the same code cannot be created twice");
    let referenced = repo
        .reference_shared_item(tenant, "item-ref", "item-ref", item_id, "po-1")
        .await
        .expect("reference")
        .expect("admit reference");
    assert!(matches!(referenced, SharedWrite::Stored(_)));
    let deleted = repo
        .retire_shared_item(tenant, "item-del", "item-del", item_id, "DELETE")
        .await;
    assert!(deleted.is_err(), "a referenced item cannot be deleted");
    let (disabled, decision) = repo
        .retire_shared_item(tenant, "item-off", "item-off", item_id, "DISABLE")
        .await
        .expect("disable")
        .expect("admit disable");
    assert!(matches!(disabled, SharedWrite::Stored(_)));
    assert_eq!(decision, "DISABLED");
    let other = TenantId(uuid::Uuid::new_v4());
    let other_item = repo
        .save_shared_item(other, "item-other", "item-other", "ITEM-1", "Other tenant", "M8", "fastener", "BC-1", false, false, true)
        .await
        .expect("other item")
        .expect("admit other item");
    assert!(matches!(other_item.0, SharedWrite::Stored(_)));
}

async fn save_shared_partner_master(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let none = repo
        .save_shared_partner(erp_repo::shared_contract::SharedPartnerInput { tenant_id: tenant, request_id: "partner-none", payload_hash: "partner-none", name: "North Mill", customer: false, supplier: false, customer_no: "", supplier_no: "", term_days: 30, tax_no: "TAX-1" })
        .await;
    assert!(none.is_err(), "a partner without a role is refused");
    let same_no = repo
        .save_shared_partner(erp_repo::shared_contract::SharedPartnerInput { tenant_id: tenant, request_id: "partner-same-no", payload_hash: "partner-same-no", name: "North Mill", customer: true, supplier: true, customer_no: "SAME", supplier_no: "SAME", term_days: 30, tax_no: "TAX-1" })
        .await;
    assert!(same_no.is_err(), "customer and supplier numbers must stay distinct");
    let (saved, partner_id) = repo
        .save_shared_partner(erp_repo::shared_contract::SharedPartnerInput { tenant_id: tenant, request_id: "partner-both", payload_hash: "partner-both", name: "North Mill", customer: true, supplier: true, customer_no: "C-1", supplier_no: "S-1", term_days: 30, tax_no: "TAX-1" })
        .await
        .expect("partner")
        .expect("admit partner");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    assert_ne!(partner_id.to_string(), "C-1");
    assert_ne!(partner_id.to_string(), "S-1");
    let replay = repo
        .save_shared_partner(erp_repo::shared_contract::SharedPartnerInput { tenant_id: tenant, request_id: "partner-both", payload_hash: "partner-both", name: "North Mill", customer: true, supplier: true, customer_no: "C-1", supplier_no: "S-1", term_days: 30, tax_no: "TAX-1" })
        .await
        .expect("partner replay")
        .expect("same partner");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, partner_id);
    let other = TenantId(uuid::Uuid::new_v4());
    let other_partner = repo
        .save_shared_partner(erp_repo::shared_contract::SharedPartnerInput { tenant_id: other, request_id: "partner-other", payload_hash: "partner-other", name: "North Mill", customer: true, supplier: false, customer_no: "C-1", supplier_no: "", term_days: 15, tax_no: "TAX-9" })
        .await
        .expect("other partner")
        .expect("admit other partner");
    assert!(matches!(other_partner.0, SharedWrite::Stored(_)));
    assert_ne!(other_partner.1, partner_id);
    let referenced = repo
        .reference_shared_partner(tenant, "partner-ref", "partner-ref", partner_id, "so-old", "2026-09-01")
        .await
        .expect("reference")
        .expect("admit reference");
    assert!(matches!(referenced, SharedWrite::Stored(_)));
    let revised = repo
        .revise_partner_term(tenant, "partner-term", "partner-term", partner_id, 45, "2026-10-01")
        .await
        .expect("term")
        .expect("admit term");
    assert!(matches!(revised, SharedWrite::Stored(_)));
    let (source_write, source_id) = repo
        .save_shared_partner(erp_repo::shared_contract::SharedPartnerInput { tenant_id: tenant, request_id: "partner-source", payload_hash: "partner-source", name: "South Mill", customer: false, supplier: true, customer_no: "", supplier_no: "S-2", term_days: 10, tax_no: "TAX-2" })
        .await
        .expect("source")
        .expect("admit source");
    assert!(matches!(source_write, SharedWrite::Stored(_)));
    let source_ref = repo
        .reference_shared_partner(tenant, "partner-source-ref", "partner-source-ref", source_id, "po-source", "2026-09-15")
        .await
        .expect("source reference")
        .expect("admit source reference");
    assert!(matches!(source_ref, SharedWrite::Stored(_)));
    let merged = repo
        .merge_shared_partners(tenant, "partner-merge", "partner-merge", source_id, partner_id)
        .await
        .expect("merge")
        .expect("admit merge");
    assert!(matches!(merged.0, SharedWrite::Stored(_)));
    assert_eq!(merged.1, 1);
    let self_merge = repo
        .merge_shared_partners(tenant, "partner-self", "partner-self", partner_id, partner_id)
        .await;
    assert!(self_merge.is_err(), "a partner cannot merge into itself");
    let stored = repo
        .read_shared_partner(tenant, partner_id, "so-old")
        .await
        .expect("read partner")
        .expect("partner row");
    assert_eq!(stored.0, true);
    assert_eq!(stored.1, true);
    assert_eq!(stored.2, "C-1");
    assert_eq!(stored.3, "S-1");
    assert_eq!(stored.4, 45);
    assert_eq!(stored.5, "TAX-1");
    assert_eq!(stored.6, "ACTIVE");
    assert_eq!(stored.7, Some(30));
    let source = repo
        .read_shared_partner(tenant, source_id, "po-source")
        .await
        .expect("read source")
        .expect("source row");
    assert_eq!(source.6, "MERGED");
    assert_eq!(source.3, "S-2");
    assert_eq!(source.7, None);
    let moved = repo
        .read_shared_partner(tenant, partner_id, "po-source")
        .await
        .expect("read moved")
        .expect("moved row");
    assert_eq!(moved.7, Some(10));
    assert_ne!(partner_id.to_string(), "S-2");
}

async fn save_shared_location_tree(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let empty = repo
        .save_shared_location(tenant, "loc-empty", "loc-empty", None, "WH-1", "", true)
        .await;
    assert!(empty.is_err(), "a location without a purpose is refused");
    let (warehouse, warehouse_id) = repo
        .save_shared_location(tenant, "loc-wh", "loc-wh", None, "WH-1", "FINISHED", true)
        .await
        .expect("warehouse")
        .expect("admit warehouse");
    assert!(matches!(warehouse, SharedWrite::Stored(_)));
    assert_ne!(warehouse_id.to_string(), "WH-1");
    let replay = repo
        .save_shared_location(tenant, "loc-wh", "loc-wh", None, "WH-1", "FINISHED", true)
        .await
        .expect("warehouse replay")
        .expect("same warehouse");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, warehouse_id);
    let (area, area_id) = repo
        .save_shared_location(tenant, "loc-area", "loc-area", Some(warehouse_id), "A-1", "RAW", false)
        .await
        .expect("area")
        .expect("admit area");
    assert!(matches!(area, SharedWrite::Stored(_)));
    let (bin, bin_id) = repo
        .save_shared_location(tenant, "loc-bin", "loc-bin", Some(area_id), "B-1", "HOLD", false)
        .await
        .expect("bin")
        .expect("admit bin");
    assert!(matches!(bin, SharedWrite::Stored(_)));
    let (other_bin, other_bin_id) = repo
        .save_shared_location(tenant, "loc-bin-2", "loc-bin-2", Some(area_id), "B-2", "WIP", false)
        .await
        .expect("second bin")
        .expect("admit second bin");
    assert!(matches!(other_bin, SharedWrite::Stored(_)));
    let (page, total) = repo.read_location_page(tenant, area_id, 0, 1).await.expect("page");
    assert_eq!(total, 2);
    assert_eq!(page.len(), 1);
    assert_eq!(page[0].1, "B-1");
    let (rest, rest_total) = repo.read_location_page(tenant, area_id, 1, 1).await.expect("rest");
    assert_eq!(rest_total, 2);
    assert_eq!(rest.len(), 1);
    assert_eq!(rest[0].1, "B-2");
    let referenced = repo
        .reference_shared_location(tenant, "loc-ref", "loc-ref", bin_id, "po-loc")
        .await
        .expect("reference")
        .expect("admit reference");
    assert!(matches!(referenced, SharedWrite::Stored(_)));
    let deleted = repo
        .retire_shared_location(tenant, "loc-del", "loc-del", bin_id, "DELETE")
        .await;
    assert!(deleted.is_err(), "a referenced location cannot be deleted");
    let (disabled, decision) = repo
        .retire_shared_location(tenant, "loc-off", "loc-off", bin_id, "DISABLE")
        .await
        .expect("disable")
        .expect("admit disable");
    assert!(matches!(disabled, SharedWrite::Stored(_)));
    assert_eq!(decision, "DISABLED");
    let cycle = repo
        .move_shared_location(tenant, "loc-cycle", "loc-cycle", warehouse_id, area_id)
        .await;
    assert!(cycle.is_err(), "a parent cannot move under its child");
    let moved = repo
        .move_shared_location(tenant, "loc-move", "loc-move", other_bin_id, warehouse_id)
        .await
        .expect("move")
        .expect("admit move");
    assert!(matches!(moved, SharedWrite::Stored(_)));
    let stored = repo.read_shared_location(tenant, other_bin_id).await.expect("read moved").expect("moved row");
    assert_eq!(stored.0, Some(warehouse_id));
    assert_eq!(stored.1, "B-2");
    assert_eq!(stored.2, "WIP");
    assert_eq!(stored.3, "ACTIVE");
    assert_eq!(stored.5, 0);
    let disabled_row = repo.read_shared_location(tenant, bin_id).await.expect("read bin").expect("bin row");
    assert_eq!(disabled_row.0, Some(area_id));
    assert_eq!(disabled_row.3, "DISABLED");
    assert_eq!(disabled_row.1, "B-1");
    let other = TenantId(uuid::Uuid::new_v4());
    let other_wh = repo
        .save_shared_location(other, "loc-other", "loc-other", None, "WH-1", "FINISHED", true)
        .await
        .expect("other warehouse")
        .expect("admit other warehouse");
    assert!(matches!(other_wh.0, SharedWrite::Stored(_)));
    assert_ne!(other_wh.1, warehouse_id);
}

async fn save_shared_employee_record(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let same = repo
        .save_shared_employee(tenant, "emp-same", "emp-same", "E-1", "E-1", "assembly")
        .await;
    assert!(same.is_err(), "an employee code cannot be used as the login user id");
    let (saved, employee_id) = repo
        .save_shared_employee(tenant, "emp-1", "emp-1", "E-1", "user-emp", "assembly")
        .await
        .expect("employee")
        .expect("admit employee");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    assert_ne!(employee_id.to_string(), "user-emp");
    assert_ne!(employee_id.to_string(), "E-1");
    let replay = repo
        .save_shared_employee(tenant, "emp-1", "emp-1", "E-1", "user-emp", "assembly")
        .await
        .expect("employee replay")
        .expect("same employee");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, employee_id);
    let bad_range = repo
        .assign_shared_employee(tenant, "emp-range", "emp-range", employee_id, "crew-1", "line-1", "2026-10-02", "2026-09-01")
        .await;
    assert!(bad_range.is_err(), "an assignment cannot end before it starts");
    let assigned = repo
        .assign_shared_employee(tenant, "emp-assign", "emp-assign", employee_id, "crew-1", "line-1", "2026-09-01", "")
        .await
        .expect("assignment")
        .expect("admit assignment");
    assert!(matches!(assigned, SharedWrite::Stored(_)));
    let same_person = repo
        .save_labor_report(tenant, "emp-self", "emp-self", employee_id, "user-report", "user-report", 30)
        .await;
    assert!(same_person.is_err(), "the reporter cannot certify the same report");
    let reported = repo
        .save_labor_report(tenant, "emp-labor", "emp-labor", employee_id, "user-report", "user-cert", 30)
        .await
        .expect("labor")
        .expect("admit labor");
    assert!(matches!(reported, SharedWrite::Stored(_)));
    let left = repo
        .leave_shared_employee(tenant, "emp-left", "emp-left", employee_id)
        .await
        .expect("leave")
        .expect("admit leave");
    assert!(matches!(left, SharedWrite::Stored(_)));
    let stored = repo
        .read_shared_employee(tenant, employee_id, "emp-labor")
        .await
        .expect("read employee")
        .expect("employee row");
    assert_eq!(stored.0, "E-1");
    assert_eq!(stored.1, "user-emp");
    assert_eq!(stored.2, "LEFT");
    assert_eq!(stored.3, 0);
    assert_eq!(stored.4, Some(("user-report".to_string(), "user-cert".to_string())));
    let other = TenantId(uuid::Uuid::new_v4());
    let other_employee = repo
        .save_shared_employee(other, "emp-other", "emp-other", "E-1", "user-other", "assembly")
        .await
        .expect("other employee")
        .expect("admit other employee");
    assert!(matches!(other_employee.0, SharedWrite::Stored(_)));
    assert_ne!(other_employee.1, employee_id);
}

async fn save_shared_import_job(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let existing = repo
        .save_shared_item(tenant, "imp-old", "imp-old", "OLD-1", "Kept Bolt", "M8", "fastener", "kg", true, false, true)
        .await
        .expect("existing item")
        .expect("admit existing item");
    assert!(matches!(existing.0, SharedWrite::Stored(_)));
    let rows = [
        (1_i32, "NEW-1", "New Bolt", "kg"),
        (2, "OLD-1", "Replaced Bolt", "kg"),
        (3, "", "Missing", "kg"),
        (4, "NEW-1", "Duplicate Bolt", "kg"),
    ];
    let borrowed: Vec<(i32, &str, &str, &str)> = rows.iter().map(|row| (row.0, row.1, row.2, row.3)).collect();
    let empty = repo
        .precheck_shared_import(tenant, "imp-empty", "imp-empty", "", "code=item_code", &borrowed)
        .await;
    assert!(empty.is_err(), "a precheck without a file digest is refused");
    let (prechecked, job_id, errors) = repo
        .precheck_shared_import(tenant, "imp-pre", "imp-pre", "digest-1", "code=item_code", &borrowed)
        .await
        .expect("precheck")
        .expect("admit precheck");
    assert!(matches!(prechecked, SharedWrite::Stored(_)));
    assert_eq!(errors, 2);
    let before = repo
        .read_shared_import(tenant, job_id, "OLD-1")
        .await
        .expect("read precheck")
        .expect("precheck row");
    assert_eq!(before.0, "PRECHECKED");
    assert_eq!(before.4.as_deref(), Some("Kept Bolt"));
    let mismatch = repo
        .confirm_shared_import(tenant, "imp-bad", "imp-bad", job_id, "digest-other", "SKIP")
        .await;
    assert!(mismatch.is_err(), "confirmation cannot use a different file digest");
    let (confirmed, imported, error_count, skipped) = repo
        .confirm_shared_import(tenant, "imp-ok", "imp-ok", job_id, "digest-1", "SKIP")
        .await
        .expect("confirm")
        .expect("admit confirm");
    assert!(matches!(confirmed, SharedWrite::Stored(_)));
    assert_eq!((imported, error_count, skipped), (1, 2, 1));
    let replay = repo
        .confirm_shared_import(tenant, "imp-ok", "imp-ok", job_id, "digest-1", "SKIP")
        .await
        .expect("confirm replay")
        .expect("same confirm");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!((replay.1, replay.2, replay.3), (1, 2, 1));
    let after = repo
        .read_shared_import(tenant, job_id, "OLD-1")
        .await
        .expect("read confirm")
        .expect("confirm row");
    assert_eq!(after.0, "CONFIRMED");
    assert_eq!((after.1, after.2, after.3), (1, 2, 1));
    assert_eq!(after.4.as_deref(), Some("Kept Bolt"));
    let created = repo
        .read_shared_import(tenant, job_id, "NEW-1")
        .await
        .expect("read new")
        .expect("new row");
    assert_eq!(created.4.as_deref(), Some("New Bolt"));
}

async fn confirm_opening_balance(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let invalid = repo
        .confirm_opening(tenant, "open-zero", "open-zero", "2026-10-01", 0, 1_000, 500)
        .await;
    assert!(invalid.is_err(), "a zero opening quantity is refused");
    let (saved, opening_id) = repo
        .confirm_opening(tenant, "open-1", "open-1", "2026-10-01", 1_000_000, 2_500, 800)
        .await
        .expect("opening")
        .expect("admit opening");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let replay = repo
        .confirm_opening(tenant, "open-1", "open-1", "2026-10-01", 1_000_000, 2_500, 800)
        .await
        .expect("opening replay")
        .expect("same opening");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, opening_id);
    let second = repo
        .confirm_opening(tenant, "open-2", "open-2", "2026-10-02", 1_000_000, 2_500, 800)
        .await;
    assert!(second.is_err(), "a second opening confirmation does not add another posting");
    let posted = repo.read_opening(tenant, opening_id).await.expect("read opening").expect("opening row");
    assert_eq!(posted.0, "CONFIRMED");
    assert_eq!(posted.1, 1);
    assert_eq!((posted.2, posted.3, posted.4), (1_000_000, 2_500, 800));
    let corrected = repo
        .correct_opening(tenant, "open-adj", "open-adj", opening_id, -250_000, -500, -200)
        .await
        .expect("correction")
        .expect("admit correction");
    assert!(matches!(corrected, SharedWrite::Stored(_)));
    let after = repo.read_opening(tenant, opening_id).await.expect("read correction").expect("corrected row");
    assert_eq!(after.0, "ADJUSTED");
    assert_eq!(after.1, 2);
    assert_eq!((after.2, after.3, after.4), (750_000, 2_000, 600));
}

async fn save_shared_attachment_version(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let too_large = repo
        .save_shared_attachment(
            tenant, "file-big", "file-big", "ITEM-1", "drawing.pdf", "digest-a", 10 * 1024 * 1024 + 1, "user-1",
        )
        .await;
    assert!(too_large.is_err(), "a file above 10 MiB is refused");
    let (saved, attachment_id, version_no) = repo
        .save_shared_attachment(tenant, "file-1", "file-1", "ITEM-1", "drawing.pdf", "digest-a", 1_024, "user-1")
        .await
        .expect("attachment")
        .expect("admit attachment");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    assert_eq!(version_no, 1);
    let (next, next_id, next_version) = repo
        .save_shared_attachment(tenant, "file-2", "file-2", "ITEM-1", "drawing.pdf", "digest-b", 2_048, "user-1")
        .await
        .expect("next version")
        .expect("admit next version");
    assert!(matches!(next, SharedWrite::Stored(_)));
    assert_ne!(next_id, attachment_id);
    assert_eq!(next_version, 2);
    let script = repo
        .save_custom_field(tenant, "field-script", "field-script", "ITEM-1", "note", "TEXT", "<script>")
        .await;
    assert!(script.is_err(), "a script custom field is refused");
    let field = repo
        .save_custom_field(tenant, "field-1", "field-1", "ITEM-1", "note", "TEXT", "heat treated")
        .await
        .expect("field")
        .expect("admit field");
    assert!(matches!(field, SharedWrite::Stored(_)));
    let stored = repo
        .read_shared_attachment(tenant, attachment_id, "user-1")
        .await
        .expect("read attachment")
        .expect("attachment row");
    assert_eq!(stored.0, "ITEM-1");
    assert_eq!(stored.1, 1);
    assert_eq!(stored.2, 1_024);
    assert_eq!(stored.3, "digest-a");
    assert!(stored.4.contains(&uuid::Uuid::from(tenant).to_string()));
    assert!(stored.5);
    let revoked = repo
        .revoke_attachment_download(tenant, "file-revoke", "file-revoke", attachment_id, "user-1")
        .await
        .expect("revoke")
        .expect("admit revoke");
    assert!(matches!(revoked, SharedWrite::Stored(_)));
    let after = repo
        .read_shared_attachment(tenant, attachment_id, "user-1")
        .await
        .expect("read revoked")
        .expect("revoked row");
    assert!(!after.5);
    let other = TenantId(uuid::Uuid::new_v4());
    let foreign = repo
        .read_shared_attachment(other, attachment_id, "user-1")
        .await
        .expect("other tenant read");
    assert!(foreign.is_none(), "another tenant cannot read the storage key");
}

async fn append_stock_ledger_rows(
    repo: &SharedContractRepo<'_>,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let location = uuid::Uuid::new_v4();
    let zero = repo
        .append_stock_ledger(tenant, "stk-zero", "stk-zero", warehouse, location, sku, "B-1", "GOOD", "ON_HAND", 0)
        .await;
    assert!(zero.is_err(), "a zero stock delta is refused");
    let (posted, ledger_id) = repo
        .append_stock_ledger(
            tenant, "stk-in", "stk-in", warehouse, location, sku, "B-1", "GOOD", "ON_HAND", 1_000_000,
        )
        .await
        .expect("stock")
        .expect("admit stock");
    assert!(matches!(posted, SharedWrite::Stored(_)));
    let replay = repo
        .append_stock_ledger(
            tenant, "stk-in", "stk-in", warehouse, location, sku, "B-1", "GOOD", "ON_HAND", 1_000_000,
        )
        .await
        .expect("stock replay")
        .expect("same stock");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, ledger_id);
    let reserved = repo
        .append_stock_ledger(
            tenant, "stk-res", "stk-res", warehouse, location, sku, "B-1", "GOOD", "RESERVED", 250_000,
        )
        .await
        .expect("reserve")
        .expect("admit reserve");
    assert!(matches!(reserved.0, SharedWrite::Stored(_)));
    let transit = repo
        .append_stock_ledger(
            tenant, "stk-transit", "stk-transit", warehouse, location, sku, "B-1", "GOOD", "IN_TRANSIT", 500_000,
        )
        .await
        .expect("transit")
        .expect("admit transit");
    assert!(matches!(transit.0, SharedWrite::Stored(_)));
    let wip = repo
        .append_stock_ledger(
            tenant, "stk-wip", "stk-wip", warehouse, location, sku, "B-1", "GOOD", "WIP", 125_000,
        )
        .await
        .expect("wip")
        .expect("admit wip");
    assert!(matches!(wip.0, SharedWrite::Stored(_)));
    let rebuilt = repo
        .read_stock_ledger(tenant, warehouse, location, sku, "B-1", "GOOD")
        .await
        .expect("rebuild");
    assert_eq!(rebuilt, (1_000_000, 250_000, 0, 750_000, 500_000, 125_000));
    let other = repo
        .read_stock_ledger(tenant, warehouse, location, sku, "B-2", "GOOD")
        .await
        .expect("other batch");
    assert_eq!(other, (0, 0, 0, 0, 0, 0));
}

async fn reserve_and_consume_stock(
    repo: &SharedContractRepo<'_>,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let location = uuid::Uuid::new_v4();
    let posted = repo
        .append_stock_ledger(
            tenant, "mov-in", "mov-in", warehouse, location, sku, "B-9", "GOOD", "ON_HAND", 1_000_000,
        )
        .await
        .expect("inbound")
        .expect("admit inbound");
    assert!(matches!(posted.0, SharedWrite::Stored(_)));
    let short = repo
        .reserve_stock_line(
            tenant, "mov-short", "mov-short", warehouse, location, sku, "B-9", "GOOD", "line-1", 2_000_000,
        )
        .await;
    assert!(short.is_err(), "a reservation above available stock is refused");
    let (reserved, reserve_id) = repo
        .reserve_stock_line(
            tenant, "mov-res", "mov-res", warehouse, location, sku, "B-9", "GOOD", "line-1", 400_000,
        )
        .await
        .expect("reserve")
        .expect("admit reserve");
    assert!(matches!(reserved, SharedWrite::Stored(_)));
    let replay = repo
        .reserve_stock_line(
            tenant, "mov-res", "mov-res", warehouse, location, sku, "B-9", "GOOD", "line-1", 400_000,
        )
        .await
        .expect("reserve replay")
        .expect("same reserve");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, reserve_id);
    let released = repo
        .release_stock_line(
            tenant, "mov-rel", "mov-rel", warehouse, location, sku, "B-9", "GOOD", "line-1", 100_000,
        )
        .await
        .expect("release")
        .expect("admit release");
    assert!(matches!(released.0, SharedWrite::Stored(_)));
    let over = repo
        .consume_stock_line(
            tenant, "mov-over", "mov-over", warehouse, location, sku, "B-9", "GOOD", "line-1", 400_000,
        )
        .await;
    assert!(over.is_err(), "consume cannot exceed the open reservation");
    let consumed = repo
        .consume_stock_line(
            tenant, "mov-use", "mov-use", warehouse, location, sku, "B-9", "GOOD", "line-1", 300_000,
        )
        .await
        .expect("consume")
        .expect("admit consume");
    assert!(matches!(consumed.0, SharedWrite::Stored(_)));
    let rebuilt = repo
        .read_stock_ledger(tenant, warehouse, location, sku, "B-9", "GOOD")
        .await
        .expect("rebuild");
    assert_eq!(rebuilt, (700_000, 0, 0, 700_000, 0, 0));
}

async fn issue_and_count_stock(
    repo: &SharedContractRepo<'_>,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let location = uuid::Uuid::new_v4();
    let destination = uuid::Uuid::new_v4();
    let posted = repo
        .append_stock_ledger(
            tenant, "xfer-seed", "xfer-seed", warehouse, location, sku, "B-7", "GOOD", "ON_HAND", 1_000_000,
        )
        .await
        .expect("seed")
        .expect("admit seed");
    assert!(matches!(posted.0, SharedWrite::Stored(_)));
    let (issued, transfer_id) = repo
        .issue_transfer(
            tenant, "xfer-issue", "xfer-issue", warehouse, destination, location, sku, "B-7", 600_000,
        )
        .await
        .expect("issue")
        .expect("admit issue");
    assert!(matches!(issued, SharedWrite::Stored(_)));
    let first = repo
        .receive_transfer(
            tenant, "xfer-recv-1", "xfer-recv-1", transfer_id, destination, location, sku, "B-7", 400_000,
        )
        .await
        .expect("first receive")
        .expect("admit first receive");
    assert!(matches!(first, SharedWrite::Stored(_)));
    let replay = repo
        .receive_transfer(
            tenant, "xfer-recv-1", "xfer-recv-1", transfer_id, destination, location, sku, "B-7", 400_000,
        )
        .await
        .expect("receive replay")
        .expect("same receive");
    assert!(matches!(replay, SharedWrite::Replay(_)));
    let over = repo
        .receive_transfer(
            tenant, "xfer-over", "xfer-over", transfer_id, destination, location, sku, "B-7", 300_000,
        )
        .await;
    assert!(over.is_err(), "a receive cannot exceed the open transfer");
    let lost = repo
        .lose_transfer(
            tenant, "xfer-loss", "xfer-loss", transfer_id, destination, location, sku, "B-7", 200_000,
        )
        .await
        .expect("loss")
        .expect("admit loss");
    assert!(matches!(lost, SharedWrite::Stored(_)));
    let balance = repo.read_transfer(tenant, transfer_id).await.expect("read transfer").expect("transfer row");
    assert_eq!(balance, (600_000, 400_000, 0, 200_000));
    let book = repo
        .read_stock_ledger(tenant, warehouse, location, sku, "B-7", "GOOD")
        .await
        .expect("book before sale");
    let cutoff = chrono::Utc::now().to_rfc3339();
    let sale = repo
        .append_stock_ledger(
            tenant, "xfer-sale", "xfer-sale", warehouse, location, sku, "B-7", "GOOD", "ON_HAND", -100_000,
        )
        .await
        .expect("sale")
        .expect("admit sale");
    assert!(matches!(sale.0, SharedWrite::Stored(_)));
    let counted_qty = book.0 - 100_000;
    let (counted, delta) = repo
        .confirm_count_adjustment(
            tenant, "xfer-count", "xfer-count", warehouse, location, sku, "B-7", &cutoff, counted_qty,
        )
        .await
        .expect("count")
        .expect("admit count");
    assert!(matches!(counted, SharedWrite::Stored(_)));
    assert_eq!(delta, counted_qty - book.0);
    let source = repo
        .read_stock_ledger(tenant, warehouse, location, sku, "B-7", "GOOD")
        .await
        .expect("source");
    assert_eq!(source.0, book.0 - 100_000 + delta);
}

async fn trace_batch_and_serial(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let (saved, batch_id) = repo
        .save_shared_batch(tenant, "bat-in", "bat-in", "ITEM-B", "LOT-IN", "2026-09-01", "2026-10-01", true, "GOOD")
        .await
        .expect("input batch")
        .expect("admit input batch");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let replay = repo
        .save_shared_batch(tenant, "bat-in", "bat-in", "ITEM-B", "LOT-IN", "2026-09-01", "2026-10-01", true, "GOOD")
        .await
        .expect("batch replay")
        .expect("same batch");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, batch_id);
    let duplicate = repo
        .save_shared_batch(tenant, "bat-dup", "bat-dup", "ITEM-B", "LOT-IN", "2026-09-01", "2026-12-01", true, "GOOD")
        .await;
    assert!(duplicate.is_err(), "the same item cannot reuse a batch code");
    let (output, _) = repo
        .save_shared_batch(tenant, "bat-out", "bat-out", "ITEM-C", "LOT-OUT", "2026-09-02", "2026-12-01", false, "GOOD")
        .await
        .expect("output batch")
        .expect("admit output batch");
    assert!(matches!(output, SharedWrite::Stored(_)));
    let other = TenantId(uuid::Uuid::new_v4());
    let (other_batch, _) = repo
        .save_shared_batch(other, "bat-other", "bat-other", "ITEM-B", "LOT-IN", "2026-09-01", "2026-12-01", false, "GOOD")
        .await
        .expect("other tenant batch")
        .expect("admit other batch");
    assert!(matches!(other_batch, SharedWrite::Stored(_)));
    let fraction = repo
        .issue_shared_batch(tenant, "bat-frac", "bat-frac", "ITEM-B", "LOT-IN", "2026-09-15", 500_000)
        .await;
    assert!(fraction.is_err(), "a serialized batch cannot be split into a fraction");
    let (serial, serial_id) = repo
        .assign_shared_serial(tenant, "ser-1", "ser-1", "ITEM-B", "LOT-IN", "SN-1")
        .await
        .expect("serial")
        .expect("admit serial");
    assert!(matches!(serial, SharedWrite::Stored(_)));
    let repeated = repo
        .assign_shared_serial(tenant, "ser-dup", "ser-dup", "ITEM-B", "LOT-IN", "SN-1")
        .await;
    assert!(repeated.is_err(), "one serial cannot be assigned twice");
    let issued = repo
        .issue_shared_batch(tenant, "bat-issue", "bat-issue", "ITEM-B", "LOT-IN", "2026-09-15", 1_000_000)
        .await
        .expect("issue open batch")
        .expect("admit issue");
    assert!(matches!(issued, SharedWrite::Stored(_)));
    let expired = repo
        .issue_shared_batch(tenant, "bat-exp", "bat-exp", "ITEM-B", "LOT-IN", "2026-10-02", 1_000_000)
        .await;
    assert!(expired.is_err(), "an expired batch cannot be issued");
    let frozen = repo
        .freeze_shared_batch(tenant, "bat-freeze", "bat-freeze", "ITEM-C", "LOT-OUT")
        .await
        .expect("freeze")
        .expect("admit freeze");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    let frozen_issue = repo
        .issue_shared_batch(tenant, "bat-frozen", "bat-frozen", "ITEM-C", "LOT-OUT", "2026-09-15", 1_000_000)
        .await;
    assert!(frozen_issue.is_err(), "a frozen batch cannot be issued");
    let planned = repo
        .record_batch_use(tenant, "bat-plan", "bat-plan", "LOT-IN", "LOT-OUT", 1_000_000, "PLANNED_BOM")
        .await;
    assert!(planned.is_err(), "a planned BOM is not an actual batch use");
    let (used, _) = repo
        .record_batch_use(tenant, "bat-use", "bat-use", "LOT-IN", "LOT-OUT", 1_000_000, "WO-1")
        .await
        .expect("actual use")
        .expect("admit use");
    assert!(matches!(used, SharedWrite::Stored(_)));
    let forward = repo.trace_batch_use(tenant, "forward", "LOT-IN").await.expect("forward");
    let backward = repo.trace_batch_use(tenant, "backward", "LOT-OUT").await.expect("backward");
    assert_eq!(forward.len(), 1);
    assert_eq!(backward, forward);
    assert_eq!(forward[0].3, "WO-1");
    let stored = repo.read_shared_batch(tenant, "ITEM-B", "LOT-IN").await.expect("read batch").expect("batch");
    assert_eq!(stored.0, batch_id);
    assert_eq!(serial_id.is_nil(), false);
}

async fn post_moving_average_cost(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let (receipt, amount, estimated) = repo
        .post_cost_receipt(erp_repo::shared_contract::CostReceiptInput { tenant_id: tenant, request_id: "mav-in", payload_hash: "mav-in", item_code: "ITEM-COST", qty_micros: 50_000_000, amount_cent: 100_000, period_code: "2026-10" })
        .await
        .expect("receipt")
        .expect("admit receipt");
    assert!(matches!(receipt, SharedWrite::Stored(_)));
    assert_eq!((amount, estimated), (100_000, false));
    let replay = repo
        .post_cost_receipt(erp_repo::shared_contract::CostReceiptInput { tenant_id: tenant, request_id: "mav-in", payload_hash: "mav-in", item_code: "ITEM-COST", qty_micros: 50_000_000, amount_cent: 100_000, period_code: "2026-10" })
        .await
        .expect("receipt replay")
        .expect("same receipt");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    let fraction = repo
        .post_cost_receipt(erp_repo::shared_contract::CostReceiptInput { tenant_id: tenant, request_id: "mav-frac", payload_hash: "mav-frac", item_code: "ITEM-COST", qty_micros: 500_000, amount_cent: 1_250, period_code: "2026-10" })
        .await
        .expect("fraction")
        .expect("admit fraction");
    assert!(matches!(fraction.0, SharedWrite::Stored(_)));
    let (issue, issue_amount, issue_estimated) = repo
        .post_cost_issue(erp_repo::shared_contract::CostIssueInput { tenant_id: tenant, request_id: "mav-out", payload_hash: "mav-out", item_code: "ITEM-COST", qty_micros: 20_000_000, period_code: "2026-10" })
        .await
        .expect("issue")
        .expect("admit issue");
    assert!(matches!(issue, SharedWrite::Stored(_)));
    assert!(!issue_estimated);
    let before_return = issue_amount;
    let returned = repo
        .post_cost_return(erp_repo::shared_contract::CostReturnCommand { tenant_id: tenant, request_id: "mav-back", payload_hash: "mav-back", item_code: "ITEM-COST", issue_request: "mav-out", return_qty: 5_000_000, period_code: "2026-10" })
        .await
        .expect("return")
        .expect("admit return");
    assert!(matches!(returned.0, SharedWrite::Stored(_)));
    // A quarter return uses the cumulative rounded issue cost. Integer division drops the cent remainder.
    let expected_return = erp_domain::trade::cumulative_return_cost(erp_domain::trade::CostReturnInput {
        original_qty: 20_000_000,
        original_cent: before_return,
        returned_qty: 0,
        returned_cent: 0,
        new_qty: 5_000_000,
    })
    .expect("quarter return of the stored issue");
    assert_eq!(returned.1, expected_return);
    assert!(expected_return >= before_return / 4);
    let late = repo
        .post_cost_adjustment(erp_repo::shared_contract::CostAdjustmentInput { tenant_id: tenant, request_id: "mav-late", payload_hash: "mav-late", item_code: "ITEM-COST", amount_cent: 3_000, period_code: "2026-10" })
        .await
        .expect("late fee")
        .expect("admit late fee");
    assert!(matches!(late.0, SharedWrite::Stored(_)));
    let over = repo
        .post_cost_return(erp_repo::shared_contract::CostReturnCommand { tenant_id: tenant, request_id: "mav-over", payload_hash: "mav-over", item_code: "ITEM-COST", issue_request: "mav-out", return_qty: 21_000_000, period_code: "2026-10" })
        .await;
    assert!(over.is_err(), "a return cannot exceed the original issue");
    let closed = repo
        .close_item_cost_period(tenant, "mav-close", "mav-close", "2026-10")
        .await
        .expect("close")
        .expect("admit close");
    assert!(matches!(closed, SharedWrite::Stored(_)));
    let inside = repo
        .post_cost_receipt(erp_repo::shared_contract::CostReceiptInput { tenant_id: tenant, request_id: "mav-closed", payload_hash: "mav-closed", item_code: "ITEM-COST", qty_micros: 1_000_000, amount_cent: 2_000, period_code: "2026-10" })
        .await;
    assert!(inside.is_err(), "a closed period refuses a new receipt");
    let position = repo.read_item_cost(tenant, "ITEM-COST").await.expect("read cost");
    assert!(position.0 > 0);
    assert!(!position.3);
}

async fn record_scan_and_print(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let (scan, scan_id, status) = repo
        .record_scan(tenant, "scan-item", "scan-item", "ITEM-B", "ITEM", "user-1")
        .await
        .expect("scan")
        .expect("admit scan");
    assert!(matches!(scan, SharedWrite::Stored(_)));
    assert_eq!(status, "VERIFIED");
    let replay = repo
        .record_scan(tenant, "scan-item", "scan-item", "ITEM-B", "ITEM", "user-1")
        .await
        .expect("scan replay")
        .expect("same scan");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, scan_id);
    let unknown = repo.record_scan(tenant, "scan-bad", "scan-bad", "??", "UNKNOWN", "user-1").await;
    assert!(unknown.is_err(), "an unrecognized scan kind is refused");
    let rendered = repo
        .record_print_event(tenant, "prn-render", "prn-render", "job-1", "RENDERED", 1, "", "USER", "user-1")
        .await
        .expect("rendered")
        .expect("admit rendered");
    assert!(matches!(rendered.0, SharedWrite::Stored(_)));
    let accepted = repo
        .record_print_event(tenant, "prn-accept", "prn-accept", "job-1", "ACCEPTED", 1, "", "AGENT", "agent-1")
        .await
        .expect("accepted")
        .expect("admit accepted");
    assert!(accepted.2, "an agent identity is not a business seat");
    let missing = repo
        .record_print_event(tenant, "prn-paper", "prn-paper", "job-1", "FAILED", 1, "out of paper", "USER", "user-1")
        .await
        .expect("paper out")
        .expect("admit paper out");
    assert!(matches!(missing.0, SharedWrite::Stored(_)));
    let reprint = repo
        .record_print_event(tenant, "prn-again", "prn-again", "job-1", "CONFIRMED", 2, "smear", "USER", "user-1")
        .await
        .expect("reprint")
        .expect("admit reprint");
    assert!(matches!(reprint.0, SharedWrite::Stored(_)));
    let bare = repo
        .record_print_event(tenant, "prn-bare", "prn-bare", "job-1", "CONFIRMED", 2, "", "USER", "user-1")
        .await;
    assert!(bare.is_err(), "a reprint needs a reason");
    let unknown_state = repo
        .record_print_event(tenant, "prn-unk", "prn-unk", "job-1", "UNKNOWN", 1, "", "USER", "user-1")
        .await
        .expect("unknown")
        .expect("admit unknown");
    assert!(matches!(unknown_state.0, SharedWrite::Stored(_)));
    let queued = repo
        .record_print_event(tenant, "prn-queue", "prn-queue", "job-1", "QUEUED", 1, "", "USER", "user-1")
        .await;
    assert!(queued.is_err(), "queued is not a print confirmation state");
    let events = repo.read_print_events(tenant, "job-1").await.expect("read events");
    assert_eq!(events.len(), 5);
    assert_eq!(events[3].1, "CONFIRMED");
    assert_eq!(events[3].3, "smear");
    assert_eq!(events[4].1, "UNKNOWN");
}

async fn raise_inventory_alerts(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let (opened, alert_id, notified) = repo
        .raise_inventory_alert(
            tenant, "alt-low", "alt-low", "LOW_STOCK", "ITEM-B", "2026-10-01T00:00:00Z", "below safety", 4, 10,
        )
        .await
        .expect("low stock")
        .expect("admit low stock");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    assert!(notified);
    let repeat = repo
        .raise_inventory_alert(
            tenant, "alt-low-2", "alt-low-2", "LOW_STOCK", "ITEM-B", "2026-10-01T00:00:00Z", "below safety", 3, 10,
        )
        .await;
    assert!(repeat.is_err(), "the same open state does not notify again");
    let cleared = repo
        .raise_inventory_alert(
            tenant, "alt-clear", "alt-clear", "LOW_STOCK", "ITEM-B", "2026-10-01T01:00:00Z", "restocked", 12, 10,
        )
        .await
        .expect("clear")
        .expect("admit clear");
    assert!(cleared.2, "a state change notifies once");
    let shortage = repo
        .raise_inventory_alert(
            tenant, "alt-short", "alt-short", "SHORTAGE", "ITEM-C", "2026-10-01T00:00:00Z", "make shortage", 0, 1,
        )
        .await
        .expect("shortage")
        .expect("admit shortage");
    assert!(matches!(shortage.0, SharedWrite::Stored(_)));
    let empty = repo
        .raise_inventory_alert(tenant, "alt-empty", "alt-empty", "LOW_STOCK", "ITEM-B", "", "missing cutoff", 1, 2)
        .await;
    assert!(empty.is_err(), "an alert needs a cutoff");
    let handled = repo
        .handle_inventory_alert(tenant, "alt-handle", "alt-handle", alert_id, "buyer reviewed")
        .await
        .expect("handle")
        .expect("admit handle");
    assert!(matches!(handled, SharedWrite::Stored(_)));
    let stored = repo.read_inventory_alert(tenant, alert_id).await.expect("read alert").expect("alert");
    assert_eq!(stored.0, "LOW_STOCK");
    assert_eq!(stored.3, "HANDLED");
    assert_eq!((stored.6.as_str(), stored.7.as_str()), ("", ""));
    let suggestion = repo.read_inventory_alert(tenant, shortage.1).await.expect("read shortage").expect("shortage");
    assert_eq!(suggestion.3, "SUGGEST_ONLY");
    assert_eq!((suggestion.6.as_str(), suggestion.7.as_str()), ("", ""));
}

async fn suggest_and_issue_lots(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let lots = vec![
        erp_domain::trade::AllocationLot {
            batch_code: "LOT-B".into(), location_code: "A-1".into(), available: 400_000,
            sort_date: "2026-10-01".into(), stock_version: 3, frozen: false, expired: false,
        },
        erp_domain::trade::AllocationLot {
            batch_code: "LOT-A".into(), location_code: "A-2".into(), available: 400_000,
            sort_date: "2026-10-01".into(), stock_version: 3, frozen: false, expired: false,
        },
        erp_domain::trade::AllocationLot {
            batch_code: "LOT-F".into(), location_code: "A-3".into(), available: 1_000_000,
            sort_date: "2026-09-01".into(), stock_version: 1, frozen: true, expired: false,
        },
        erp_domain::trade::AllocationLot {
            batch_code: "LOT-X".into(), location_code: "A-4".into(), available: 1_000_000,
            sort_date: "2026-09-01".into(), stock_version: 1, frozen: false, expired: true,
        },
    ];
    let (saved, ids) = repo
        .save_allocation_suggestion(tenant, "alloc-1", "alloc-1", "FEFO", "pick-1", 600_000, &lots)
        .await
        .expect("suggest")
        .expect("admit suggestion");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let replay = repo
        .save_allocation_suggestion(tenant, "alloc-1", "alloc-1", "FIFO", "pick-1", 600_000, &lots)
        .await
        .expect("replay")
        .expect("same suggestion");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    let stored = repo.read_allocation_suggestions(tenant, "pick-1").await.expect("read suggestions");
    assert_eq!(stored.len(), ids.len());
    assert_eq!(stored[0].1, "LOT-A");
    assert_eq!(stored[1].1, "LOT-B");
    assert_eq!(stored[0].3 + stored[1].3, 600_000);
    assert!(stored[0].5.contains("LOT-F frozen"));
    assert!(stored[0].5.contains("LOT-X expired"));
    let stale = repo
        .issue_allocation_suggestion(tenant, "alloc-stale", "alloc-stale", stored[0].0, 4, stored[0].3)
        .await;
    assert!(stale.is_err(), "a changed stock version cannot be issued from the old suggestion");
    let issued = repo
        .issue_allocation_suggestion(tenant, "alloc-issue", "alloc-issue", stored[0].0, stored[0].4, stored[0].3)
        .await
        .expect("issue")
        .expect("admit issue");
    assert!(matches!(issued.0, SharedWrite::Stored(_)));
    let over = repo
        .issue_allocation_suggestion(tenant, "alloc-over", "alloc-over", stored[1].0, stored[1].4, stored[1].3 - 1)
        .await;
    assert!(over.is_err(), "an issue cannot exceed the current available quantity");
}

async fn revise_purchase_order(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let line = || erp_domain::trade::PurchaseLine {
        line_no: 1,
        item_code: "ITEM-B".into(),
        qty_micros: 20_000_000,
        price_cent: 2_000,
        tax_cent: 260,
        due_date: "2026-10-15".into(),
    };
    let (opened, _revision_id, version) = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "po-open", payload_hash: "po-open", po_id: None, supplier_code: "S-1", warehouse_code: "WH-1", action: "OPEN", lines: &[line()] })
        .await
        .expect("open")
        .expect("admit open");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let order_id = uuid::Uuid::new_v4();
    let (opened, _, version) = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "po-1", payload_hash: "po-1", po_id: Some(order_id), supplier_code: "S-1", warehouse_code: "WH-1", action: "OPEN", lines: &[line()] })
        .await
        .expect("open order")
        .expect("admit order");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let revised_line = erp_domain::trade::PurchaseLine { due_date: "2026-10-20".into(), ..line() };
    let (revised, revised_id, revised_version) = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "po-rev", payload_hash: "po-rev", po_id: Some(order_id), supplier_code: "S-1", warehouse_code: "WH-1", action: "REVISE", lines: &[revised_line] })
        .await
        .expect("revise")
        .expect("admit revise");
    assert!(matches!(revised, SharedWrite::Stored(_)));
    assert_eq!(revised_version, 2);
    assert_ne!(revised_id, _revision_id);
    let first = repo
        .receive_purchase_line(tenant, "po-rcv-1", "po-rcv-1", order_id, 1, 8_000_000)
        .await
        .expect("first receipt")
        .expect("admit first receipt");
    assert_eq!(first.1, 12_000_000);
    let second = repo
        .receive_purchase_line(tenant, "po-rcv-2", "po-rcv-2", order_id, 1, 8_000_000)
        .await
        .expect("second receipt")
        .expect("admit second receipt");
    assert_eq!(second.1, 4_000_000);
    let over = repo
        .receive_purchase_line(tenant, "po-over", "po-over", order_id, 1, 5_000_000)
        .await;
    assert!(over.is_err(), "a receipt cannot exceed the source line");
    let closed = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "po-close", payload_hash: "po-close", po_id: Some(order_id), supplier_code: "S-1", warehouse_code: "WH-1", action: "CLOSE", lines: &[erp_domain::trade::PurchaseLine { due_date: "2026-10-20".into(), ..line() }] })
        .await
        .expect("close")
        .expect("admit close");
    assert_eq!(closed.2, 3);
    let after = repo
        .save_purchase_revision(erp_repo::shared_contract::TradePurchaseRevisionInput { tenant_id: tenant, request_id: "po-after", payload_hash: "po-after", po_id: Some(order_id), supplier_code: "S-1", warehouse_code: "WH-1", action: "REVISE", lines: &[line()] })
        .await;
    assert!(after.is_err(), "a closed order cannot be revised");
    let latest = repo.read_purchase_revision(tenant, order_id, 1).await.expect("read").expect("latest");
    assert_eq!(latest.1, 3);
    assert_eq!(latest.2, "CLOSED");
    assert_eq!(latest.3, "2026-10-20");
    assert_eq!(latest.5, 4_000_000);
}

async fn convert_quote_and_hold_credit(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let quote_id = uuid::Uuid::new_v4();
    let (opened, _, version) = repo
        .save_quote_revision(erp_repo::shared_contract::TradeQuoteRevisionInput { tenant_id: tenant, request_id: "qt-1", payload_hash: "qt-1", quote_id: Some(quote_id), partner_code: "C-QT", currency: "CNY", item_code: "ITEM-QT", qty_micros: 10_000_000, price_cent: 2_000, start_date: "2026-10-01", end_date: "2026-10-31" })
        .await
        .expect("quote")
        .expect("admit quote");
    assert!(matches!(opened, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let (revised, _, revised_version) = repo
        .save_quote_revision(erp_repo::shared_contract::TradeQuoteRevisionInput { tenant_id: tenant, request_id: "qt-2", payload_hash: "qt-2", quote_id: Some(quote_id), partner_code: "C-QT", currency: "CNY", item_code: "ITEM-QT", qty_micros: 10_000_000, price_cent: 2_200, start_date: "2026-10-01", end_date: "2026-10-31" })
        .await
        .expect("revise")
        .expect("admit revise");
    assert!(matches!(revised, SharedWrite::Stored(_)));
    assert_eq!(revised_version, 2);
    let expired = repo
        .convert_quote(erp_repo::shared_contract::TradeQuoteConversionInput { tenant_id: tenant, request_id: "qt-exp", payload_hash: "qt-exp", quote_id, expected_version: 2, today: "2026-11-02", qty_micros: 1_000_000 })
        .await;
    assert!(expired.is_err(), "an expired price cannot be converted");
    let stale = repo
        .convert_quote(erp_repo::shared_contract::TradeQuoteConversionInput { tenant_id: tenant, request_id: "qt-stale", payload_hash: "qt-stale", quote_id, expected_version: 1, today: "2026-10-15", qty_micros: 1_000_000 })
        .await;
    assert!(stale.is_err(), "conversion cannot use an old quote version");
    let (converted, _, price) = repo
        .convert_quote(erp_repo::shared_contract::TradeQuoteConversionInput { tenant_id: tenant, request_id: "qt-part", payload_hash: "qt-part", quote_id, expected_version: 2, today: "2026-10-15", qty_micros: 4_000_000 })
        .await
        .expect("convert")
        .expect("admit convert");
    assert!(matches!(converted, SharedWrite::Stored(_)));
    assert_eq!(price, 2_200);
    let over = repo
        .convert_quote(erp_repo::shared_contract::TradeQuoteConversionInput { tenant_id: tenant, request_id: "qt-over", payload_hash: "qt-over", quote_id, expected_version: 2, today: "2026-10-15", qty_micros: 7_000_000 })
        .await;
    assert!(over.is_err(), "conversion cannot exceed the quoted quantity");
    repo.save_partner_balance(erp_repo::shared_contract::PartnerBalanceInput { tenant_id: tenant, request_id: "qt-ar", payload_hash: "qt-ar", kind: erp_domain::trade::PartnerBalanceKind::Receivable, partner_code: "C-QT", currency: "CNY", source_type: "SALE", source_id: "so-qt", source_status: "CONFIRMED", amount_cent: 6_000, due_date: Some("2026-11-15") })
    .await
    .expect("open ar")
    .expect("admit ar");
    let (held, _, left) = repo
        .hold_credit(tenant, "qt-hold", "qt-hold", "C-QT", 10_000, 3_000)
        .await
        .expect("hold")
        .expect("admit hold");
    assert!(matches!(held, SharedWrite::Stored(_)));
    assert_eq!(left, 1_000);
    let blocked = repo.hold_credit(tenant, "qt-block", "qt-block", "C-QT", 10_000, 2_000).await;
    assert!(blocked.is_err(), "a second hold cannot exceed the remaining credit");
    let (suggested, suggestion_id) = repo
        .save_purchase_suggestion(tenant, "qt-sug", "qt-sug", "ITEM-QT", 1_000_000)
        .await
        .expect("suggest")
        .expect("admit suggestion");
    assert!(matches!(suggested, SharedWrite::Stored(_)));
    let duplicate = repo
        .save_purchase_suggestion(tenant, "qt-sug2", "qt-sug2", "ITEM-QT", 1_000_000)
        .await;
    assert!(duplicate.is_err(), "the same item suggestion is not written twice");
    let _ = suggestion_id;
    let state = repo.read_quote_state(tenant, quote_id, "C-QT", "ITEM-QT").await.expect("read");
    assert_eq!(state.0, 2);
    assert_eq!(state.1, 2_200);
    assert_eq!(state.2, "CNY");
    assert_eq!(state.3, 4_000_000);
    assert_eq!(state.4, 1_000);
    assert!(!state.5, "a suggestion is not a payment");
}

async fn fulfill_dropship_consignment_and_kit(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let bare = repo
        .record_dropship(tenant, "own-bare", "own-bare", "", "C-DS", "CUST-DOCK", "ITEM-DS", 1_000_000, "WB-DS")
        .await;
    assert!(bare.is_err(), "dropship needs a supplier that is not the customer");
    let (shipped, dropship_id) = repo
        .record_dropship(tenant, "own-ds", "own-ds", "S-DS", "C-DS", "CUST-DOCK", "ITEM-DS", 2_000_000, "WB-DS")
        .await
        .expect("dropship")
        .expect("admit dropship");
    assert!(matches!(shipped, SharedWrite::Stored(_)));
    let replay = repo
        .record_dropship(tenant, "own-ds", "own-ds", "S-DS", "C-DS", "CUST-DOCK", "ITEM-DS", 2_000_000, "WB-DS")
        .await
        .expect("replay")
        .expect("same dropship");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, dropship_id);
    let (ours, our_stock) = repo
        .receive_consignment(tenant, "own-ours", "own-ours", "OURS", "BIN-1", "ITEM-CON", 5_000_000)
        .await
        .expect("our stock")
        .expect("admit our stock");
    assert!(matches!(ours, SharedWrite::Stored(_)));
    let (supplier, _) = repo
        .receive_consignment(tenant, "own-sup", "own-sup", "S-OWN", "BIN-1", "ITEM-CON", 8_000_000)
        .await
        .expect("supplier stock")
        .expect("admit supplier stock");
    assert!(matches!(supplier, SharedWrite::Stored(_)));
    let mixed = repo
        .settle_consignment(tenant, "own-mix", "own-mix", our_stock, 6_000_000, 900)
        .await;
    assert!(mixed.is_err(), "a sale cannot use another owner's quantity at the same location");
    let (settled, _, fee) = repo
        .settle_consignment(tenant, "own-set", "own-set", our_stock, 2_000_000, 900)
        .await
        .expect("settle")
        .expect("admit settlement");
    assert!(matches!(settled, SharedWrite::Stored(_)));
    assert_eq!(fee, 900);
    let over = repo.settle_consignment(tenant, "own-over", "own-over", our_stock, 4_000_000, 100).await;
    assert!(over.is_err(), "settlement cannot exceed that owner's remaining quantity");
    let parts = [
        erp_domain::trade::KitPart { item_code: "PART-A".into(), qty_per_micros: 2_000_000 },
        erp_domain::trade::KitPart { item_code: "PART-B".into(), qty_per_micros: 3_000_000 },
    ];
    let duplicate = repo.save_trade_kit(tenant, "own-dup", "own-dup", "KIT-1", &parts).await;
    let (saved, kit_id) = duplicate.expect("kit").expect("admit kit");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let again = repo.save_trade_kit(tenant, "own-kit2", "own-kit2", "KIT-1", &parts).await;
    assert!(again.is_err(), "the same kit code is not a second kit");
    let (expanded, expand_id, rows) = repo
        .expand_trade_kit(tenant, "own-exp", "own-exp", kit_id, 2)
        .await
        .expect("expand")
        .expect("admit expand");
    assert!(matches!(expanded, SharedWrite::Stored(_)));
    assert_eq!(rows, 2);
    let same = repo
        .expand_trade_kit(tenant, "own-exp", "own-exp", kit_id, 2)
        .await
        .expect("expand replay")
        .expect("same expand");
    assert!(matches!(same.0, SharedWrite::Replay(_)));
    assert_eq!(same.1, expand_id);
    let state = repo
        .read_special_fulfillment(tenant, dropship_id, "BIN-1", "ITEM-CON", expand_id)
        .await
        .expect("read");
    assert!(!state.0, "dropship does not invent our inbound");
    assert_eq!(state.1, 3_000_000);
    assert_eq!(state.2, 8_000_000);
    assert_eq!(state.3, 2);
    assert!(!state.4, "a trade kit expand is not production");
}

async fn save_multilevel_bom(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let kg = |parent: &str, component: &str, qty: &str, scrap: i64, supply: &str, line: i32| {
        erp_domain::manufacturing::BomLine {
            parent: parent.into(),
            component: component.into(),
            qty_per: erp_domain::quantity::parse_qty(qty).expect("qty"),
            unit_code: "KG".into(),
            scrap_ppm: scrap,
            supply: supply.into(),
            line_no: line,
        }
    };
    let cycle = [
        kg("FG", "SUB", "1", 0, "MAKE", 1),
        kg("SUB", "FG", "1", 0, "MAKE", 1),
    ];
    let refused = repo.save_bom_structure(tenant, "bom-cyc", "bom-cyc", "FG", &cycle).await;
    assert!(refused.is_err(), "a cycle is refused before publish");
    let overflow = [kg("FG", "RAW", "0.125", 1_000_001, "BUY", 1)];
    let bad_scrap = repo.save_bom_structure(tenant, "bom-scrap", "bom-scrap", "FG", &overflow).await;
    assert!(bad_scrap.is_err(), "scrap above 100 percent is refused");
    let lines = [
        kg("FG", "SUB", "1", 0, "MAKE", 20),
        kg("SUB", "MID", "1", 0, "MAKE", 10),
        kg("MID", "RAW", "0.125", 20_000, "BUY", 30),
    ];
    let (saved, bom_id) = repo
        .save_bom_structure(tenant, "bom-3", "bom-3", "FG", &lines)
        .await
        .expect("bom")
        .expect("admit bom");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let replay = repo
        .save_bom_structure(tenant, "bom-3", "bom-3", "FG", &lines)
        .await
        .expect("replay")
        .expect("same bom");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, bom_id);
    let (exploded, explode_id, rows) = repo
        .explode_bom_structure(tenant, "bom-exp", "bom-exp", bom_id, 1_000_000)
        .await
        .expect("explode")
        .expect("admit explode");
    assert!(matches!(exploded, SharedWrite::Stored(_)));
    assert_eq!(rows, 3);
    let raw = repo.read_bom_explode(tenant, explode_id, "RAW").await.expect("raw");
    assert_eq!(raw.0, 127_500, "0.125 times 2 percent scrap is 0.1275");
    assert_eq!(raw.1, "KG");
    assert_eq!(raw.2, 30);
    assert_eq!(raw.3, 3);
    let same = repo
        .explode_bom_structure(tenant, "bom-exp", "bom-exp", bom_id, 1_000_000)
        .await
        .expect("explode replay")
        .expect("same explode");
    assert!(matches!(same.0, SharedWrite::Replay(_)));
    assert_eq!(same.1, explode_id);
}

async fn publish_bom_and_keep_work_order(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let line = |parent: &str, component: &str, qty: i64, line_no: i32| erp_domain::manufacturing::BomLine {
        parent: parent.into(),
        component: component.into(),
        qty_per: erp_domain::quantity::ScaledQty::from_micros(qty),
        unit_code: "KG".into(),
        scrap_ppm: 0,
        supply: "BUY".into(),
        line_no,
    };
    let first = [line("FG", "RAW-1", 100_000, 1)];
    let (saved, bom_id) = repo
        .save_bom_structure(tenant, "ver-draft", "ver-draft", "FG", &first)
        .await
        .expect("draft")
        .expect("admit draft");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let (published, version_id, version_no) = repo
        .publish_bom_version(tenant, "ver-pub", "ver-pub", "FG-SERIES", bom_id, "2026-10-01", "2026-10-15", true)
        .await
        .expect("publish")
        .expect("admit publish");
    assert!(matches!(published, SharedWrite::Stored(_)));
    assert_eq!(version_no, 1);
    let overlap = repo
        .publish_bom_version(tenant, "ver-over", "ver-over", "FG-SERIES", bom_id, "2026-10-10", "2026-10-20", true)
        .await;
    assert!(overlap.is_err(), "default ranges cannot overlap");
    let second = [line("FG", "RAW-2", 250_000, 1)];
    let (_, bom_two) = repo
        .save_bom_structure(tenant, "ver-draft2", "ver-draft2", "FG", &second)
        .await
        .expect("second draft")
        .expect("admit second");
    let (later, version_two, version_two_no) = repo
        .publish_bom_version(tenant, "ver-pub2", "ver-pub2", "FG-SERIES", bom_two, "2026-10-16", "", true)
        .await
        .expect("later")
        .expect("admit later");
    assert!(matches!(later, SharedWrite::Stored(_)));
    assert_eq!(version_two_no, 2);
    assert_ne!(version_two, version_id);
    let (frozen, work_order_id, frozen_version) = repo
        .snapshot_work_order_bom(tenant, "ver-wo", "ver-wo", "FG-SERIES", "2026-10-08", "WO-VER")
        .await
        .expect("snapshot")
        .expect("admit snapshot");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    assert_eq!(frozen_version, 1);
    let (retired, kept) = repo
        .retire_bom_version(tenant, "ver-ret", "ver-ret", version_id)
        .await
        .expect("retire")
        .expect("admit retire");
    assert!(matches!(retired, SharedWrite::Stored(_)));
    assert_eq!(kept, 1);
    let row = repo.read_work_order_bom(tenant, work_order_id, "RAW-1").await.expect("frozen row");
    assert_eq!(row.0, 1);
    assert_eq!(row.1, 100_000);
    assert_eq!(row.2, "PUBLISHED");
    let (copied, copy_id) = repo
        .copy_bom_version(tenant, "ver-copy", "ver-copy", version_id)
        .await
        .expect("copy")
        .expect("admit copy");
    assert!(matches!(copied, SharedWrite::Stored(_)));
    assert_ne!(copy_id, bom_id);
    let missing = repo
        .snapshot_work_order_bom(tenant, "ver-miss", "ver-miss", "FG-SERIES", "2026-09-01", "WO-MISS")
        .await;
    assert!(missing.is_err(), "a date outside every published range is refused");
}

async fn freeze_operation_route(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let step = |operation: &str, sequence: i32, predecessor: &str, setup: i64| erp_domain::manufacturing::OperationStep {
        operation: operation.into(),
        sequence,
        predecessor: predecessor.into(),
        work_center: "LINE-1".into(),
        setup_minutes: setup,
        minutes_per: 6,
        inspection_required: operation == "PACK",
        report_field: "good_qty".into(),
        display_order: sequence + 1_000,
    };
    let cycle = [step("CUT", 10, "PACK", 5), step("WELD", 20, "CUT", 4), step("PACK", 30, "WELD", 3)];
    let refused = repo.save_operation_route(tenant, "rte-cyc", "rte-cyc", "FG-RTE", &cycle).await;
    assert!(refused.is_err(), "a predecessor cycle is refused");
    let skip = [step("CUT", 10, "", 5), step("PACK", 30, "MISSING", 3)];
    let missing = repo.save_operation_route(tenant, "rte-skip", "rte-skip", "FG-RTE", &skip).await;
    assert!(missing.is_err(), "a missing predecessor is refused");
    let first = [step("CUT", 10, "", 5), step("WELD", 20, "CUT", 4), step("PACK", 30, "WELD", 3)];
    let (saved, route_id, version) = repo
        .save_operation_route(tenant, "rte-1", "rte-1", "FG-RTE", &first)
        .await
        .expect("route")
        .expect("admit route");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let (frozen, work_order_id, frozen_version) = repo
        .snapshot_work_order_route(tenant, "rte-wo", "rte-wo", route_id, "WO-RTE")
        .await
        .expect("snapshot")
        .expect("admit snapshot");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    assert_eq!(frozen_version, 1);
    let revised = [step("CUT", 10, "", 9), step("WELD", 20, "CUT", 4), step("PACK", 30, "WELD", 3)];
    let (later, later_id, later_version) = repo
        .save_operation_route(tenant, "rte-2", "rte-2", "FG-RTE", &revised)
        .await
        .expect("revise")
        .expect("admit revise");
    assert!(matches!(later, SharedWrite::Stored(_)));
    assert_eq!(later_version, 2);
    assert_ne!(later_id, route_id);
    let rows = repo.read_work_order_route(tenant, work_order_id).await.expect("frozen route");
    assert_eq!(rows.len(), 3);
    assert_eq!(rows[0], ("CUT".into(), 10, "".into(), 5));
    assert_eq!(rows[1], ("PACK".into(), 30, "WELD".into(), 3));
    assert_eq!(rows[2], ("WELD".into(), 20, "CUT".into(), 4));
}

async fn schedule_work_center_load(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let days = [
        erp_domain::manufacturing::CalendarDay { day: "2026-10-03".into(), rest: true, shift_minutes: 480 },
        erp_domain::manufacturing::CalendarDay { day: "2026-10-05".into(), rest: false, shift_minutes: 480 },
    ];
    let (saved, center_id) = repo
        .save_work_center_calendar(tenant, "wc-cal", "wc-cal", "LINE-A", 2, &days)
        .await
        .expect("calendar")
        .expect("admit calendar");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let (loaded, load_id, overload) = repo
        .record_work_center_load(tenant, "wc-load", "wc-load", center_id, 60, 1_020)
        .await
        .expect("load")
        .expect("admit load");
    assert!(matches!(loaded, SharedWrite::Stored(_)));
    assert_eq!(overload, 120, "18 hours on 16 hours of capacity overloads by 2 hours");
    let replay = repo
        .record_work_center_load(tenant, "wc-load", "wc-load", center_id, 60, 1_020)
        .await
        .expect("replay")
        .expect("same load");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, load_id);
    let (rate, _, version) = repo
        .save_work_center_rate(tenant, "wc-rate", "wc-rate", center_id, 800, "2026-10-01", "2026-10-31", "2026-10-05")
        .await
        .expect("rate")
        .expect("admit rate");
    assert!(matches!(rate, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let (later, _, later_version) = repo
        .save_work_center_rate(tenant, "wc-rate2", "wc-rate2", center_id, 900, "2026-11-01", "", "2026-11-02")
        .await
        .expect("later rate")
        .expect("admit later");
    assert!(matches!(later, SharedWrite::Stored(_)));
    assert_eq!(later_version, 2);
    let expired = repo
        .save_work_center_rate(tenant, "wc-old", "wc-old", center_id, 700, "2026-09-01", "2026-09-30", "2026-10-05")
        .await;
    assert!(expired.is_err(), "a rate outside its dates is refused");
    let row = repo.read_work_center_load(tenant, load_id).await.expect("read load");
    assert_eq!(row.0, 960);
    assert_eq!(row.1, 1_080);
    assert_eq!(row.2, 120);
    assert!(!row.3, "manual load is not automatic scheduling");
    assert_eq!(row.4, 2);
}

async fn plan_dated_demand(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let source_id = uuid::Uuid::new_v4();
    let buckets = [
        erp_domain::manufacturing::PlanBucket {
            due_date: "2026-10-08".into(),
            qty: erp_domain::quantity::ScaledQty::from_micros(6_000_000),
            source_kind: "MAKE".into(),
        },
        erp_domain::manufacturing::PlanBucket {
            due_date: "2026-10-20".into(),
            qty: erp_domain::quantity::ScaledQty::from_micros(4_000_000),
            source_kind: "BUY".into(),
        },
    ];
    let (saved, plan_id) = repo
        .save_production_plan(tenant, "mps-1", "mps-1", source_id, 1, "FG-MPS", 2, 10_000_000, &buckets)
        .await
        .expect("plan")
        .expect("admit plan");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let duplicate = repo
        .save_production_plan(tenant, "mps-dup", "mps-dup", source_id, 1, "FG-MPS", 2, 10_000_000, &buckets)
        .await;
    assert!(duplicate.is_err(), "the same source line is not imported twice");
    let (executed, qty) = repo
        .execute_plan_bucket(tenant, "mps-ex", "mps-ex", plan_id, "2026-10-08", 2_000_000)
        .await
        .expect("execute")
        .expect("admit execute");
    assert!(matches!(executed, SharedWrite::Stored(_)));
    assert_eq!(qty, 2_000_000);
    let (cancelled, left) = repo
        .cancel_plan_bucket(tenant, "mps-can", "mps-can", plan_id, "2026-10-08", 3_000_000)
        .await
        .expect("cancel")
        .expect("admit cancel");
    assert!(matches!(cancelled, SharedWrite::Stored(_)));
    assert_eq!(left, 3_000_000);
    let over = repo
        .cancel_plan_bucket(tenant, "mps-over", "mps-over", plan_id, "2026-10-08", 2_000_000)
        .await;
    assert!(over.is_err(), "cancel cannot erase executed quantity");
    let (frozen, status) = repo
        .freeze_production_plan(tenant, "mps-fr", "mps-fr", plan_id)
        .await
        .expect("freeze")
        .expect("admit freeze");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    assert_eq!(status, "FROZEN");
    let after = repo
        .cancel_plan_bucket(tenant, "mps-after", "mps-after", plan_id, "2026-10-08", 1_000_000)
        .await;
    assert!(after.is_err(), "a frozen plan is not rewritten");
    let make = repo.read_production_bucket(tenant, plan_id, "2026-10-08").await.expect("make bucket");
    assert_eq!(make.0, 6_000_000);
    assert_eq!(make.1, 2_000_000);
    assert_eq!(make.2, 3_000_000);
    assert!(make.3);
    assert_eq!(make.4, "FROZEN");
    let buy = repo.read_production_bucket(tenant, plan_id, "2026-10-20").await.expect("buy bucket");
    assert_eq!(buy.0, 0, "a resale bucket is not a production demand");
    assert!(!buy.3);
}

async fn plan_authorized_bucket_mrp(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let qty = qty_text;
    let bom = vec![
        BomItem { parent: "P".into(), component: "S".into(), qty_per: qty("2") },
        BomItem { parent: "P".into(), component: "A".into(), qty_per: qty("3") },
        BomItem { parent: "S".into(), component: "B".into(), qty_per: qty("4") },
    ];
    let stock = |code: &str, on_hand: &str, allocated: &str, safety: &str, min_lot: &str, multiple: &str, supply: &str, lead: i32| {
        erp_domain::manufacturing::BucketStock {
            code: code.into(),
            warehouse: "WH-1".into(),
            on_hand: qty(on_hand),
            allocated_elsewhere: qty(allocated),
            wip: erp_domain::quantity::ScaledQty::ZERO,
            safety: qty(safety),
            min_lot: qty(min_lot),
            lot_multiple: qty(multiple),
            supply: supply.into(),
            lead_days: lead,
        }
    };
    let rows = vec![
        stock("P", "0", "0", "0", "0", "0", "MAKE", 2),
        stock("S", "2", "0", "0", "0", "0", "MAKE", 1),
        stock("A", "12", "2", "2", "0", "0", "BUY", 3),
        stock("B", "10", "0", "2", "10", "6", "BUY", 3),
    ];
    let supply = vec![
        erp_domain::manufacturing::BucketSupply { code: "A".into(), warehouse: "WH-1".into(), qty: qty("5"), arrive_date: "2026-10-06".into(), accepted: true },
        erp_domain::manufacturing::BucketSupply { code: "B".into(), warehouse: "WH-1".into(), qty: qty("8"), arrive_date: "2026-10-05".into(), accepted: true },
        erp_domain::manufacturing::BucketSupply { code: "B".into(), warehouse: "WH-1".into(), qty: qty("10"), arrive_date: "2026-10-12".into(), accepted: true },
    ];
    let demand = vec![erp_domain::manufacturing::BucketDemand {
        code: "P".into(),
        qty: qty("10"),
        need_date: "2026-10-08".into(),
        warehouse: "WH-1".into(),
        frozen: true,
    }];
    let (saved, run_id) = repo
        .save_bucket_mrp(tenant, "mrp6-1", "mrp6-1", "WH-1", &bom, &rows, &supply, &demand, &[])
        .await
        .expect("bucket")
        .expect("admit bucket");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let replay = repo
        .save_bucket_mrp(tenant, "mrp6-1", "mrp6-1", "WH-1", &bom, &rows, &supply, &demand, &[])
        .await
        .expect("replay")
        .expect("same bucket");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, run_id);
    let open = vec![erp_domain::manufacturing::BucketDemand {
        code: "P".into(),
        qty: qty("10"),
        need_date: "2026-10-08".into(),
        warehouse: "WH-1".into(),
        frozen: false,
    }];
    let unfrozen = repo
        .save_bucket_mrp(tenant, "mrp6-open", "mrp6-open", "WH-1", &bom, &rows, &supply, &open, &[])
        .await;
    assert!(unfrozen.is_err(), "an unfrozen demand is not planned");
    let other = rows
        .iter()
        .map(|row| erp_domain::manufacturing::BucketStock { warehouse: "WH-2".into(), ..row.clone() })
        .collect::<Vec<_>>();
    let outside = repo
        .save_bucket_mrp(tenant, "mrp6-wh", "mrp6-wh", "WH-1", &bom, &other, &supply, &demand, &[])
        .await;
    assert!(outside.is_err(), "stock outside the authorized warehouse is refused");
    let suggested = vec![erp_domain::manufacturing::BucketSupply {
        code: "B".into(),
        warehouse: "WH-1".into(),
        qty: qty("10"),
        arrive_date: "2026-10-01".into(),
        accepted: false,
    }];
    let pending = repo
        .save_bucket_mrp(tenant, "mrp6-pend", "mrp6-pend", "WH-1", &bom, &rows, &suggested, &demand, &[])
        .await;
    assert!(pending.is_err(), "an unaccepted suggestion is not supply");
    let parent = repo.read_bucket_suggestion(tenant, run_id, "P").await.expect("parent");
    assert_eq!(parent.0, 10_000_000);
    assert_eq!(parent.1, 10_000_000);
    assert_eq!(parent.3, "MAKE");
    assert_eq!(parent.4, "2026-10-06");
    assert!(!parent.5, "a suggestion is not accepted by planning");
    assert_eq!(parent.6, "WH-1");
    let semi = repo.read_bucket_suggestion(tenant, run_id, "S").await.expect("semi");
    assert_eq!(semi.1, 18_000_000);
    assert_eq!(semi.3, "MAKE");
    // Parent starts 2026-10-06. One lead day skips the weekend and releases on 2026-10-05.
    assert_eq!(semi.4, "2026-10-05");
    let material_a = repo.read_bucket_suggestion(tenant, run_id, "A").await.expect("a");
    assert_eq!(material_a.0, 30_000_000);
    assert_eq!(material_a.1, 17_000_000);
    assert_eq!(material_a.3, "BUY");
    assert_eq!(material_a.4, "2026-10-01");
    let material_b = repo.read_bucket_suggestion(tenant, run_id, "B").await.expect("b");
    assert_eq!(material_b.0, 72_000_000);
    assert_eq!(material_b.1, 56_000_000);
    assert_eq!(material_b.2, 60_000_000, "the net shortage rounds up to the lot multiple");
    assert_eq!(material_b.3, "BUY");
    assert_eq!(material_b.4, "2026-09-30");
    assert_ne!(parent.4, material_a.4, "production and purchase dates stay independent");
}

async fn convert_mrp_suggestion_in_parts(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let qty = qty_text;
    let bom = vec![BomItem { parent: "FG".into(), component: "RAW".into(), qty_per: qty("1") }];
    let stock = vec![erp_domain::manufacturing::BucketStock {
        code: "RAW".into(),
        warehouse: "WH-C".into(),
        on_hand: qty("0"),
        allocated_elsewhere: erp_domain::quantity::ScaledQty::ZERO,
        wip: erp_domain::quantity::ScaledQty::ZERO,
        safety: erp_domain::quantity::ScaledQty::ZERO,
        min_lot: erp_domain::quantity::ScaledQty::ZERO,
        lot_multiple: erp_domain::quantity::ScaledQty::ZERO,
        supply: "BUY".into(),
        lead_days: 1,
    }];
    let demand = vec![erp_domain::manufacturing::BucketDemand {
        code: "RAW".into(),
        qty: qty("4"),
        need_date: "2026-10-09".into(),
        warehouse: "WH-C".into(),
        frozen: true,
    }];
    let (saved, run_id) = repo
        .save_bucket_mrp(tenant, "cvt-run", "cvt-run", "WH-C", &bom, &stock, &[], &demand, &[])
        .await
        .expect("run")
        .expect("admit run");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let (first, target_a, total, accepted, kit) = repo
        .convert_mrp_suggestion(tenant, "cvt-a", "cvt-a", run_id, "RAW", 2_000_000, "PURCHASE", 1)
        .await
        .expect("first half")
        .expect("admit first");
    assert!(matches!(first, SharedWrite::Stored(_)));
    assert_eq!(total, 2_000_000);
    assert!(!accepted, "half of a suggestion is not fully accepted");
    assert!(!kit, "a shortage is not a complete kit");
    let (second, target_b, total, accepted, kit) = repo
        .convert_mrp_suggestion(tenant, "cvt-b", "cvt-b", run_id, "RAW", 2_000_000, "PURCHASE", 2)
        .await
        .expect("second half")
        .expect("admit second");
    assert!(matches!(second, SharedWrite::Stored(_)));
    assert_ne!(target_b, target_a);
    assert_eq!(total, 4_000_000);
    assert!(accepted, "both halves accept the suggestion");
    assert!(!kit, "accepting a shortage suggestion does not show a complete kit");
    let replay = repo
        .convert_mrp_suggestion(tenant, "cvt-a", "cvt-a", run_id, "RAW", 2_000_000, "PURCHASE", 1)
        .await
        .expect("replay")
        .expect("same conversion");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, target_a);
    let over = repo
        .convert_mrp_suggestion(tenant, "cvt-over", "cvt-over", run_id, "RAW", 1_000_000, "PURCHASE", 3)
        .await;
    assert!(over.is_err(), "conversion cannot exceed the suggestion");
    let wrong = repo
        .convert_mrp_suggestion(tenant, "cvt-kind", "cvt-kind", run_id, "RAW", 1_000_000, "PRODUCTION", 1)
        .await;
    assert!(wrong.is_err(), "a purchase suggestion is not a production order");
    let (expired, status) = repo
        .expire_mrp_run(tenant, "cvt-exp", "cvt-exp", run_id)
        .await
        .expect("expire")
        .expect("admit expire");
    assert!(matches!(expired, SharedWrite::Stored(_)));
    assert_eq!(status, "EXPIRED");
    let late = repo
        .convert_mrp_suggestion(tenant, "cvt-late", "cvt-late", run_id, "RAW", 1_000_000, "PURCHASE", 4)
        .await;
    assert!(late.is_err(), "an expired plan is not converted");
    let row = repo.read_plan_conversion(tenant, run_id, "RAW").await.expect("read conversion");
    assert_eq!(row.0, 4_000_000);
    assert_eq!(row.1, 4_000_000);
    assert!(row.2, "both halves mark the suggestion accepted");
    assert_eq!(row.3, "EXPIRED");
    assert!(row.1 > 0, "the remaining shortage is still visible and is not a complete kit");
}

async fn cancel_mrp_run_keeps_conversion(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let qty = qty_text;
    let stock = vec![erp_domain::manufacturing::BucketStock {
        code: "PART".into(),
        warehouse: "WH-X".into(),
        on_hand: qty("0"),
        allocated_elsewhere: erp_domain::quantity::ScaledQty::ZERO,
        wip: erp_domain::quantity::ScaledQty::ZERO,
        safety: erp_domain::quantity::ScaledQty::ZERO,
        min_lot: erp_domain::quantity::ScaledQty::ZERO,
        lot_multiple: erp_domain::quantity::ScaledQty::ZERO,
        supply: "BUY".into(),
        lead_days: 1,
    }];
    let demand = vec![erp_domain::manufacturing::BucketDemand {
        code: "PART".into(),
        qty: qty("3"),
        need_date: "2026-10-15".into(),
        warehouse: "WH-X".into(),
        frozen: true,
    }];
    let (saved, run_id) = repo
        .save_bucket_mrp(tenant, "can-run", "can-run", "WH-X", &[], &stock, &[], &demand, &[])
        .await
        .expect("run")
        .expect("admit run");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    let (converted, target_id, total, accepted, kit) = repo
        .convert_mrp_suggestion(tenant, "can-a", "can-a", run_id, "PART", 1_000_000, "PURCHASE", 1)
        .await
        .expect("convert")
        .expect("admit convert");
    assert!(matches!(converted, SharedWrite::Stored(_)));
    assert_eq!(total, 1_000_000);
    assert!(!accepted);
    assert!(!kit);
    let (cancelled, status, kept) = repo
        .cancel_mrp_run(tenant, "can-stop", "can-stop", run_id)
        .await
        .expect("cancel")
        .expect("admit cancel");
    assert!(matches!(cancelled, SharedWrite::Stored(_)));
    assert_eq!(status, "CANCELLED");
    assert_eq!(kept, 1_000_000, "cancel keeps the conversion already stored");
    let replay = repo
        .cancel_mrp_run(tenant, "can-stop", "can-stop", run_id)
        .await
        .expect("replay")
        .expect("same cancel");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.2, 1_000_000);
    let after = repo
        .convert_mrp_suggestion(tenant, "can-late", "can-late", run_id, "PART", 1_000_000, "PURCHASE", 2)
        .await;
    assert!(after.is_err(), "a cancelled run accepts nothing more");
    let expired = repo.expire_mrp_run(tenant, "can-exp", "can-exp", run_id).await;
    assert!(expired.is_err(), "a cancelled run is not rewritten as expired");
    let row = repo.read_plan_conversion(tenant, run_id, "PART").await.expect("read");
    assert_eq!(row.0, 1_000_000);
    assert_eq!(row.3, "CANCELLED");
    let _ = target_id;
}

async fn release_work_order_and_reserve(
    repo: &SharedContractRepo<'_>,
    pool: &sqlx::PgPool,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let lines = [erp_domain::manufacturing::BomLine {
        parent: "FG-WO".into(),
        component: "RAW-WO".into(),
        qty_per: qty_text("1"),
        unit_code: "EA".into(),
        scrap_ppm: 0,
        supply: "MAKE".into(),
        line_no: 10,
    }];
    let (structure, bom_id) = repo
        .save_bom_structure(tenant, "wo8-bom", "wo8-bom", "FG-WO", &lines)
        .await
        .expect("structure")
        .expect("admit structure");
    assert!(matches!(structure, SharedWrite::Stored(_)));
    let (published, version_id, version_no) = repo
        .publish_bom_version(tenant, "wo8-ver", "wo8-ver", "FG-WO", bom_id, "2026-10-01", "", true)
        .await
        .expect("version")
        .expect("admit version");
    assert!(matches!(published, SharedWrite::Stored(_)));
    assert_eq!(version_no, 1);
    let seeded = repo
        .post_inventory_inbound(tenant, "wo8-in", "wo8-in", warehouse, sku, 3, Some("wo8".into()))
        .await
        .expect("seed")
        .expect("admit seed");
    assert!(matches!(seeded, SharedWrite::Stored(_)));
    let before = repo.read_qty_balance(tenant, warehouse, sku).await.expect("before");
    let planned = repo
        .save_work_order(tenant, "wo8-plan", "wo8-plan", "WO-8", "FG-WO", None, qty_text("3"))
        .await
        .expect("plan")
        .expect("admit plan");
    let SharedWrite::Stored(planned) = planned else {
        panic!("first order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&planned.effect_id).expect("order id");
    let missing = repo
        .release_work_order(tenant, "wo8-none", "wo8-none", work_order_id, uuid::Uuid::new_v4(), warehouse, sku, 1_000_000)
        .await;
    assert!(missing.is_err(), "a missing bom version is not released");
    let (released, reserved) = repo
        .release_work_order(tenant, "wo8-rel", "wo8-rel", work_order_id, version_id, warehouse, sku, 3_000_000)
        .await
        .expect("release")
        .expect("admit release");
    assert!(matches!(released, SharedWrite::Stored(_)));
    assert_eq!(reserved, 3_000_000);
    let replay = repo
        .release_work_order(tenant, "wo8-rel", "wo8-rel", work_order_id, version_id, warehouse, sku, 3_000_000)
        .await
        .expect("replay")
        .expect("same release");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, 3_000_000);
    let again = repo
        .save_work_order(tenant, "wo8-plan2", "wo8-plan2", "WO-8B", "FG-WO", None, qty_text("2"))
        .await
        .expect("second")
        .expect("admit second");
    let SharedWrite::Stored(again) = again else {
        panic!("second order stores");
    };
    let second_id = uuid::Uuid::parse_str(&again.effect_id).expect("second id");
    let compete = repo
        .release_work_order(tenant, "wo8-comp", "wo8-comp", second_id, version_id, warehouse, sku, 100_000_000)
        .await;
    assert!(compete.is_err(), "two orders cannot reserve more than available stock");
    let (retired, _) = repo
        .retire_bom_version(tenant, "wo8-ret", "wo8-ret", version_id)
        .await
        .expect("retire")
        .expect("admit retire");
    assert!(matches!(retired, SharedWrite::Stored(_)));
    let row = repo.read_work_order_release(tenant, work_order_id).await.expect("read release");
    assert_eq!(row.0, version_id);
    assert_eq!(row.1, 1);
    assert_eq!(row.2, 3_000_000);
    assert_eq!(row.3, "RELEASED");
    assert_eq!(row.4, "RELEASED");
    let balance = repo.read_qty_balance(tenant, warehouse, sku).await.expect("balance");
    assert_eq!(balance.0, before.0);
    assert_eq!(balance.1, before.1 + 3_000_000);
    let (issued, _) = repo
        .save_material_move(
            tenant,
            "wo8-issue",
            "wo8-issue",
            work_order_id,
            erp_domain::manufacturing::MaterialMove {
                kind: erp_domain::manufacturing::MaterialMoveKind::Issue,
                qty: qty_text("1"),
                supplement_reason_required: false,
            },
            None,
            Some(warehouse),
            Some(sku),
        )
        .await
        .expect("issue")
        .expect("admit issue");
    assert!(matches!(issued, SharedWrite::Stored(_)));
    let removed = repo
        .transition_saved_work_order(tenant, "wo8-del", "wo8-del", work_order_id, "cancel")
        .await;
    assert!(removed.is_err(), "an order with issued material is not deleted");
    let still = repo.read_work_order_release(tenant, work_order_id).await.expect("still there");
    assert_eq!(still.2, 3_000_000);
}

async fn issue_return_and_consume_material(
    repo: &SharedContractRepo<'_>,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let planned = repo
        .save_work_order(tenant, "mat9-plan", "mat9-plan", "WO-9", "FG-9", None, qty_text("1"))
        .await
        .expect("plan")
        .expect("admit plan");
    let SharedWrite::Stored(planned) = planned else {
        panic!("order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&planned.effect_id).expect("order");
    repo.transition_saved_work_order(tenant, "mat9-rel", "mat9-rel", work_order_id, "release")
        .await
        .expect("release")
        .expect("admit release");
    let location = uuid::Uuid::new_v4();
    let bare = repo
        .issue_work_order_material(tenant, "mat9-sup", "mat9-sup", work_order_id, warehouse, location, sku, "B-9", 125_000, "SUPPLEMENT", "")
        .await;
    assert!(bare.is_err(), "a supplement needs a reason");
    let (issued, issue_id) = repo
        .issue_work_order_material(tenant, "mat9-iss", "mat9-iss", work_order_id, warehouse, location, sku, "B-9", 125_000, "ISSUE", "")
        .await
        .expect("issue")
        .expect("admit issue");
    assert!(matches!(issued, SharedWrite::Stored(_)));
    let replay = repo
        .issue_work_order_material(tenant, "mat9-iss", "mat9-iss", work_order_id, warehouse, location, sku, "B-9", 125_000, "ISSUE", "")
        .await
        .expect("replay")
        .expect("same issue");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, issue_id);
    let (returned, return_id, left) = repo
        .return_work_order_material(tenant, "mat9-ret", "mat9-ret", issue_id, 25_000)
        .await
        .expect("return")
        .expect("admit return");
    assert!(matches!(returned, SharedWrite::Stored(_)));
    assert_eq!(left, 100_000);
    let over = repo.return_work_order_material(tenant, "mat9-over", "mat9-over", issue_id, 200_000).await;
    assert!(over.is_err(), "a return cannot exceed the cited issue");
    let (consumed, shop) = repo
        .consume_work_order_material(tenant, "use-9", "use-9", issue_id, 50_000)
        .await
        .expect("consume")
        .expect("admit consume");
    assert!(matches!(consumed, SharedWrite::Stored(_)));
    assert_eq!(shop, 50_000);
    let row = repo.read_material_issue(tenant, issue_id).await.expect("read issue");
    assert_eq!(row.0, 125_000);
    assert_eq!(row.1, 25_000);
    assert_eq!(row.2, 50_000, "shop stock is issue minus return minus consume");
    assert_eq!(row.3, -100_000, "consume does not restore warehouse stock");
    let _ = return_id;
}

async fn report_later_operation_from_frozen_route(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let step = |operation: &str, sequence: i32, predecessor: &str| erp_domain::manufacturing::OperationStep {
        operation: operation.into(),
        sequence,
        predecessor: predecessor.into(),
        work_center: "LINE-10".into(),
        setup_minutes: 1,
        minutes_per: 2,
        inspection_required: false,
        report_field: "good_qty".into(),
        display_order: sequence + 1_000,
    };
    let route = [step("CUT", 10, ""), step("WELD", 20, "CUT")];
    let (saved, route_id, version) = repo
        .save_operation_route(tenant, "rpt10-rte", "rpt10-rte", "FG-RPT10", &route)
        .await
        .expect("route")
        .expect("admit route");
    assert!(matches!(saved, SharedWrite::Stored(_)));
    assert_eq!(version, 1);
    let planned = repo
        .save_work_order(tenant, "rpt10-wo", "rpt10-wo", "WO-RPT10", "FG-RPT10", None, qty_text("10"))
        .await
        .expect("order")
        .expect("admit order");
    let SharedWrite::Stored(planned) = planned else {
        panic!("order stores");
    };
    let work_order_id = uuid::Uuid::parse_str(&planned.effect_id).expect("order id");
    let (frozen, frozen_version) = repo
        .snapshot_named_work_order_route(tenant, "rpt10-snap", "rpt10-snap", route_id, work_order_id)
        .await
        .expect("snapshot")
        .expect("admit snapshot");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    assert_eq!(frozen_version, 1);
    let report = |operation: &str, good: &str, rejected: &str, minutes: i64| OperationReport {
        operation: operation.into(),
        good: qty_text(good),
        rejected: qty_text(rejected),
        rework: ScaledQty::ZERO,
        minutes,
        operator_id: "worker-10".into(),
        session_user_id: "login-10".into(),
        session_id: "session-10".into(),
        crew_code: "CREW-10".into(),
        started_at: "2026-10-02T08:00:00Z".into(),
        ended_at: "2026-10-02T08:30:00Z".into(),
        reverses_report_id: None,
    };
    let impersonated = OperationReport {
        operator_id: "login-10".into(),
        ..report("CUT", "4", "1", 30)
    };
    assert!(
        repo.save_operation_report(tenant, "rpt10-same", "rpt10-same", work_order_id, qty_text("99"), &impersonated)
            .await
            .expect_err("operator cannot be the login")
            .to_string()
            .contains("operator")
    );
    let negative = OperationReport { minutes: -1, ..report("CUT", "4", "1", 30) };
    assert!(
        repo.save_operation_report(tenant, "rpt10-neg", "rpt10-neg", work_order_id, qty_text("99"), &negative)
            .await
            .expect_err("negative minutes")
            .to_string()
            .contains("InvalidText")
    );
    let (cut, _) = repo
        .save_operation_report(tenant, "rpt10-cut", "rpt10-cut", work_order_id, qty_text("99"), &report("CUT", "4", "1", 30))
        .await
        .expect("cut")
        .expect("admit cut");
    let SharedWrite::Stored(cut) = cut else {
        panic!("cut stores");
    };
    let replay = repo
        .save_operation_report(tenant, "rpt10-cut", "rpt10-cut", work_order_id, qty_text("99"), &report("CUT", "4", "1", 30))
        .await
        .expect("cut replay")
        .expect("same cut");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    let invented = repo
        .save_operation_report(tenant, "rpt10-invent", "rpt10-invent", work_order_id, qty_text("99"), &report("WELD", "5", "0", 10))
        .await;
    assert!(invented.is_err(), "a later operation cannot use a caller ceiling above the prior good output");
    let (weld, _) = repo
        .save_operation_report(tenant, "rpt10-weld", "rpt10-weld", work_order_id, qty_text("99"), &report("WELD", "3", "1", 12))
        .await
        .expect("weld")
        .expect("admit weld");
    assert!(matches!(weld, SharedWrite::Stored(_)));
    let reversal = OperationReport {
        good: ScaledQty::from_micros(-qty_text("4").as_micros()),
        rejected: ScaledQty::from_micros(-qty_text("1").as_micros()),
        minutes: -30,
        reverses_report_id: Some(cut.effect_id.clone()),
        ..report("CUT", "4", "1", 30)
    };
    let (reversed, _) = repo
        .save_operation_report(tenant, "rpt10-rev", "rpt10-rev", work_order_id, qty_text("99"), &reversal)
        .await
        .expect("reversal")
        .expect("admit reversal");
    assert!(matches!(reversed, SharedWrite::Stored(_)));
    let after = repo
        .save_operation_report(tenant, "rpt10-after", "rpt10-after", work_order_id, qty_text("99"), &report("WELD", "1", "0", 4))
        .await;
    assert!(after.is_err(), "reversing the prior good output blocks a later report");
    assert_eq!(repo.count_operation_reports(tenant, work_order_id).await.expect("kept"), 3);
}

async fn receive_semi_and_reissue_to_parent(
    repo: &SharedContractRepo<'_>,
    tenant: TenantId,
    warehouse: uuid::Uuid,
    sku: uuid::Uuid,
) {
    let location = uuid::Uuid::new_v4();
    let semi = repo
        .save_work_order(tenant, "rcv11-s", "rcv11-s", "WO-S11", "S", None, qty_text("10"))
        .await
        .expect("semi")
        .expect("admit semi");
    let SharedWrite::Stored(semi) = semi else {
        panic!("semi stores");
    };
    let semi_id = uuid::Uuid::parse_str(&semi.effect_id).expect("semi id");
    repo.transition_saved_work_order(tenant, "rcv11-srel", "rcv11-srel", semi_id, "release")
        .await
        .expect("semi release")
        .expect("admit");
    let report = OperationReport {
        operation: "make-s".into(),
        good: qty_text("10"),
        rejected: ScaledQty::ZERO,
        rework: ScaledQty::ZERO,
        minutes: 20,
        operator_id: "worker-11".into(),
        session_user_id: "login-11".into(),
        session_id: "session-11".into(),
        crew_code: "CREW-11".into(),
        started_at: "2026-10-02T09:00:00Z".into(),
        ended_at: "2026-10-02T09:20:00Z".into(),
        reverses_report_id: None,
    };
    let (saved_report, _) = repo
        .save_operation_report(tenant, "rcv11-rpt", "rcv11-rpt", semi_id, qty_text("10"), &report)
        .await
        .expect("report")
        .expect("admit report");
    let SharedWrite::Stored(saved_report) = saved_report else {
        panic!("report stores");
    };
    let report_id = uuid::Uuid::parse_str(&saved_report.effect_id).expect("report id");
    let inspection = uuid::Uuid::new_v4();
    let (held, received, available) = repo
        .save_production_receipt(tenant, "rcv11-hold", "rcv11-hold", semi_id, qty_text("6"), ReceiptStatus::Hold, report_id, "BATCH-S11", inspection, warehouse, sku)
        .await
        .expect("hold")
        .expect("admit hold");
    let SharedWrite::Stored(held) = held else {
        panic!("hold stores");
    };
    assert_eq!((received, available), (qty_text("6").as_micros(), 0));
    let held_id = uuid::Uuid::parse_str(&held.effect_id).expect("held");
    let parent = repo
        .save_work_order(tenant, "rcv11-p", "rcv11-p", "WO-P11", "P", None, qty_text("2"))
        .await
        .expect("parent")
        .expect("admit parent");
    let SharedWrite::Stored(parent) = parent else {
        panic!("parent stores");
    };
    let parent_id = uuid::Uuid::parse_str(&parent.effect_id).expect("parent id");
    repo.transition_saved_work_order(tenant, "rcv11-prel", "rcv11-prel", parent_id, "release")
        .await
        .expect("parent release")
        .expect("admit");
    let blocked = repo
        .reissue_semi_finished(tenant, "rcv11-held", "rcv11-held", parent_id, held_id, qty_text("2"), warehouse, location, sku, "BATCH-S11")
        .await;
    assert!(blocked.is_err(), "held semi cannot be issued into the parent");
    let (_, available_after) = repo
        .release_production_receipt(tenant, "rcv11-rel", "rcv11-rel", held_id)
        .await
        .expect("release")
        .expect("admit release");
    assert_eq!(available_after, qty_text("6").as_micros());
    let (issued, left) = repo
        .reissue_semi_finished(tenant, "rcv11-use", "rcv11-use", parent_id, held_id, qty_text("2"), warehouse, location, sku, "BATCH-S11")
        .await
        .expect("reissue")
        .expect("admit reissue");
    assert!(matches!(issued, SharedWrite::Stored(_)));
    assert_eq!(left, qty_text("4").as_micros());
    let replay = repo
        .reissue_semi_finished(tenant, "rcv11-use", "rcv11-use", parent_id, held_id, qty_text("2"), warehouse, location, sku, "BATCH-S11")
        .await
        .expect("replay")
        .expect("same reissue");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, qty_text("4").as_micros());
    let over = repo
        .reissue_semi_finished(tenant, "rcv11-over", "rcv11-over", parent_id, held_id, qty_text("5"), warehouse, location, sku, "BATCH-S11")
        .await;
    assert!(over.is_err(), "reissue cannot exceed the released remainder");
    let (direct, _, direct_available) = repo
        .save_production_receipt(tenant, "rcv11-4", "rcv11-4", semi_id, qty_text("4"), ReceiptStatus::Released, report_id, "BATCH-S11B", uuid::Uuid::new_v4(), warehouse, sku)
        .await
        .expect("direct")
        .expect("admit direct");
    assert!(matches!(direct, SharedWrite::Stored(_)));
    assert_eq!(direct_available, qty_text("8").as_micros());
    let again = repo
        .save_production_receipt(tenant, "rcv11-again", "rcv11-again", semi_id, qty_text("1"), ReceiptStatus::Released, report_id, "BATCH-S11C", uuid::Uuid::new_v4(), warehouse, sku)
        .await;
    assert!(again.is_err(), "receipts cannot exceed reported good");
    repo.mark_work_order_complete_flag(tenant, semi_id, qty_text("1.500")).await.expect("seed wip");
    let kept = repo.mark_work_order_complete_flag(tenant, semi_id, ScaledQty::ZERO).await.expect("flag");
    assert_eq!(kept, qty_text("1.500").as_micros(), "a completion flag does not zero stored wip");
}

