async fn trace_mixed_batches(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let planned = repo
        .save_genealogy_edge(
            tenant,
            "trace-plan",
            "trace-plan",
            "PLANNED_BOM",
            "RAW-MIX",
            "FG-A",
            qty_text("1"),
            "WO-TRACE",
            "FG-A",
            "",
        )
        .await;
    assert!(planned.expect_err("planned bom").to_string().contains("planned BOM"));

    let consume = repo
        .save_genealogy_edge(
            tenant,
            "trace-consume",
            "trace-consume",
            "CONSUME",
            "RAW-MIX",
            "FG-A",
            qty_text("6"),
            "WO-TRACE",
            "FG-A",
            "",
        )
        .await
        .expect("consume")
        .expect("admit consume");
    assert!(matches!(consume.0, SharedWrite::Stored(_)));
    let consume_replay = repo
        .save_genealogy_edge(
            tenant,
            "trace-consume",
            "trace-consume",
            "CONSUME",
            "RAW-MIX",
            "FG-A",
            qty_text("6"),
            "WO-TRACE",
            "FG-A",
            "",
        )
        .await
        .expect("consume replay")
        .expect("same consume");
    assert!(matches!(consume_replay.0, SharedWrite::Replay(_)));
    assert_eq!(consume_replay.1, consume.1);

    let split = repo
        .save_genealogy_edge(
            tenant,
            "trace-split",
            "trace-split",
            "OUTPUT",
            "RAW-MIX",
            "FG-B",
            qty_text("4"),
            "WO-TRACE",
            "FG-B",
            "",
        )
        .await
        .expect("split output")
        .expect("admit split");
    assert!(matches!(split.0, SharedWrite::Stored(_)));

    for (request, action, batch, customer, qty) in [
        ("trace-c1", "DELIVER", "FG-A", "CUST-1", "2"),
        ("trace-c2", "DELIVER", "FG-A", "CUST-2", "1"),
        ("trace-c3", "DELIVER", "FG-B", "CUST-3", "3"),
    ] {
        let saved = repo
            .save_genealogy_edge(
                tenant,
                request,
                request,
                action,
                "RAW-MIX",
                batch,
                qty_text(qty),
                "WO-TRACE",
                batch,
                customer,
            )
            .await
            .expect(request)
            .expect("admit delivery");
        assert!(matches!(saved.0, SharedWrite::Stored(_)));
    }
    let returned = repo
        .save_genealogy_edge(
            tenant,
            "trace-return",
            "trace-return",
            "RETURN",
            "FG-A",
            "FG-A",
            qty_text("1"),
            "WO-TRACE",
            "FG-A",
            "CUST-1",
        )
        .await
        .expect("return")
        .expect("admit return");
    assert!(matches!(returned.0, SharedWrite::Stored(_)));
    let reversed = repo
        .save_genealogy_edge(
            tenant,
            "trace-reverse",
            "trace-reverse",
            "DELIVER_REVERSAL",
            "RAW-MIX",
            "FG-B",
            ScaledQty::from_micros(-qty_text("1").as_micros()),
            "WO-TRACE",
            "FG-B",
            "CUST-3",
        )
        .await
        .expect("reversal")
        .expect("admit reversal");
    assert!(matches!(reversed.0, SharedWrite::Stored(_)));
    let missing_customer = repo
        .save_genealogy_edge(
            tenant,
            "trace-nocust",
            "trace-nocust",
            "DELIVER",
            "RAW-MIX",
            "FG-A",
            qty_text("1"),
            "WO-TRACE",
            "FG-A",
            "",
        )
        .await;
    assert!(missing_customer.expect_err("customer").to_string().contains("customer"));

    let (page, next, incomplete, total) = repo
        .read_genealogy_page(tenant, "input", "RAW-MIX", None, 2)
        .await
        .expect("forward page");
    assert_eq!(total, 7);
    assert!(incomplete);
    assert_eq!(next, Some(2));
    assert_eq!(page.len(), 2);
    let (rest, done, complete, rest_total) = repo
        .read_genealogy_page(tenant, "input", "RAW-MIX", next, 10)
        .await
        .expect("forward rest");
    assert!(!complete);
    assert!(done.is_none());
    assert_eq!(rest_total, 7);
    assert_eq!(page.len() + rest.len(), 7);
    let customers: Vec<&str> = page
        .iter()
        .chain(rest.iter())
        .map(|edge| edge.customer.as_str())
        .filter(|customer| !customer.is_empty())
        .collect();
    assert!(customers.contains(&"CUST-1"));
    assert!(customers.contains(&"CUST-2"));
    assert!(customers.contains(&"CUST-3"));

    let (backward, _, backward_incomplete, backward_total) = repo
        .read_genealogy_page(tenant, "output", "FG-A", None, 10)
        .await
        .expect("backward page");
    assert!(!backward_incomplete);
    assert_eq!(backward_total, 4);
    assert!(backward.iter().any(|edge| edge.source_action == "CONSUME" && edge.input_code == "RAW-MIX"));
    assert!(backward.iter().any(|edge| edge.source_action == "RETURN" && edge.customer == "CUST-1"));
    assert!(backward.iter().all(|edge| edge.source_action != "PLANNED_BOM"));
}

async fn recall_confirmed_scope(repo: &SharedContractRepo<'_>, tenant: TenantId) {
    let accepted = repo
        .save_sampling_decision(tenant, "sample-pass", "sample-pass", "AQL-1", 1, "2026-09", 20, 1, 1)
        .await
        .expect("sample pass")
        .expect("admit sample");
    assert!(matches!(accepted.0, SharedWrite::Stored(_)));
    assert!(accepted.1);
    assert_eq!(accepted.2, 50_000);
    let rejected = repo
        .save_sampling_decision(tenant, "sample-fail", "sample-fail", "AQL-1", 1, "2026-10", 20, 2, 1)
        .await
        .expect("sample fail")
        .expect("admit failed sample");
    assert!(!rejected.1);
    assert_eq!(rejected.2, 100_000);
    let sample_replay = repo
        .save_sampling_decision(tenant, "sample-fail", "sample-fail", "AQL-1", 1, "2026-10", 20, 2, 1)
        .await
        .expect("sample replay")
        .expect("same sample");
    assert!(matches!(sample_replay.0, SharedWrite::Replay(_)));
    let over = repo
        .save_sampling_decision(tenant, "sample-over", "sample-over", "AQL-1", 1, "2026-11", 20, 21, 1)
        .await;
    assert!(over.expect_err("defects").to_string().contains("sampling rejected"));

    let opened = repo
        .save_recall(tenant, "recall-open", "recall-open", "RAW-MIX", "AQL-1", 1, qty_text("3"))
        .await
        .expect("recall")
        .expect("admit recall");
    assert!(matches!(opened.0, SharedWrite::Stored(_)));
    assert_eq!(opened.2, 6);
    let recall_id = opened.1;
    let replay = repo
        .save_recall(tenant, "recall-open", "recall-open", "RAW-MIX", "AQL-1", 1, qty_text("3"))
        .await
        .expect("recall replay")
        .expect("same recall");
    assert!(matches!(replay.0, SharedWrite::Replay(_)));
    assert_eq!(replay.1, recall_id);
    let empty = repo
        .save_recall(tenant, "recall-empty", "recall-empty", "RAW-NONE", "AQL-1", 1, qty_text("1"))
        .await;
    assert!(empty.expect_err("empty scope").to_string().contains("confirmed trace"));

    let frozen = repo
        .save_recall_result(tenant, "recall-freeze", "recall-freeze", recall_id, "STOCK", "RAW-MIX", "freeze", "DONE")
        .await
        .expect("freeze")
        .expect("admit freeze");
    assert!(matches!(frozen, SharedWrite::Stored(_)));
    let notice_failed = repo
        .save_recall_result(tenant, "recall-notice-fail", "recall-notice-fail", recall_id, "CUSTOMER", "CUST-2", "notice", "FAILED")
        .await
        .expect("notice fail")
        .expect("admit notice failure");
    assert!(matches!(notice_failed, SharedWrite::Stored(_)));
    let recovered = repo
        .save_recall_result(tenant, "recall-notice-ok", "recall-notice-ok", recall_id, "CUSTOMER", "CUST-2", "notice", "DONE")
        .await
        .expect("notice recover")
        .expect("admit notice recovery");
    assert!(matches!(recovered, SharedWrite::Stored(_)));
    let missing = repo
        .save_recall_result(tenant, "recall-missing", "recall-missing", recall_id, "CUSTOMER", "CUST-9", "notice", "DONE")
        .await;
    assert!(missing.expect_err("missing item").to_string().contains("not found"));
}

